/* ---------- Asie : pays et régions encore peu servis ---------- */
const D56 = [
{ id:'or-lam', c:'as', lat:19.883, lon:102.140, base:6, prep:40, cook:90, diff:2, tags:['beef','slow','comfort'],
  art:{v:'pot',bg:'#28331f',plate:'#f0e4c8',style:'stew',food:['#4f6f3a','#8f5a3a','#7fae5a','#e8dcb8'],garnish:'#7fae6a'},
  n:{fr:'Or lam',en:'Or lam'},
  p:{fr:'Xieng Khouang, Laos',en:'Xiangkhouang, Laos'},
  d:{fr:"Un ragoût de buffle et de légumes au bois de sakhan, qui engourdit la langue comme le poivre du Sichuan. On plonge un bâton de sakhan dans la marmite et on le retire : il ne se mange pas, il parfume.",
     en:"A buffalo and vegetable stew with sakhan wood, which numbs the tongue like Sichuan pepper. A stick of sakhan goes into the pot and comes back out: it is not eaten, it flavours."},
  i:[['beef_chuck',800,'g'],['sakhan_wood',2,'pc'],['eggplant',400,'g'],['long_beans',300,'g'],['wood_ear_mushrooms',100,'g'],['lemongrass',3,'pc'],['shallot',6,'pc'],['dill',2,'bunch'],['bird_eye_chili',4,'pc'],['fish_sauce',4,'tbsp'],['glutinous_rice',500,'g'],['spring_onion',5,'pc'],['salt',null,'']],
  s:{fr:["Grillez la viande sur la braise avant de la mettre en marmite : c'est cette fumée qui distingue l'or lam d'un simple ragoût.","Écrasez le bois de sakhan au maillet pour libérer sa sève, et plongez-le dans un litre d'eau bouillante.","Ajoutez la viande, la citronnelle écrasée et l'échalote, et laissez mijoter 1 heure.","Retirez le bois de sakhan avant qu'il ne domine tout, puis ajoutez les aubergines et les haricots longs.","Terminez par les champignons noirs, l'aneth et le piment. Servez avec du riz gluant, à la main."],
     en:["Grill the meat over coals before it goes in the pot: that smoke is what separates or lam from an ordinary stew.","Bruise the sakhan wood with a mallet to release its sap, and drop it into a litre of boiling water.","Add the meat, bruised lemongrass and shallot, and simmer for 1 hour.","Take the sakhan out before it dominates everything, then add the aubergines and long beans.","Finish with the wood ear mushrooms, dill and chilli. Serve with sticky rice, eaten by hand."]} },

{ id:'amok-trey', c:'as', lat:13.412, lon:103.867, base:4, prep:40, cook:35, diff:3, tags:['sea','festive','comfort'],
  art:{v:'leaf',bg:'#28331f',plate:'#f4ecd8',style:'fish',food:['#e8c46a','#f0e8d0','#7fae5a','#e0b45a'],garnish:'#6fbf8f'},
  n:{fr:'Amok trey',en:'Amok trey'},
  p:{fr:'Siem Reap, Cambodge',en:'Siem Reap, Cambodia'},
  d:{fr:"Une mousse de poisson à la pâte kroeung et au lait de coco, cuite à la vapeur dans une coupe de feuille de bananier. Elle doit prendre comme un flan : si elle reste liquide, c'est qu'on a manqué d'œuf ou de patience.",
     en:"A fish mousse with kroeung paste and coconut milk, steamed in a banana leaf cup. It must set like a custard: if it stays runny, either the egg or the patience was short."},
  i:[['white_fish',700,'g'],['coconut_milk',500,'ml'],['egg',2,'pc'],['lemongrass',4,'pc'],['galangal',40,'g'],['turmeric',2,'tsp'],['kaffir_lime_leaves',8,'pc'],['shallot',6,'pc'],['garlic',6,'clove'],['shrimp_paste',1,'tbsp'],['palm_sugar',2,'tbsp'],['fish_sauce',3,'tbsp'],['noni_leaves',12,'pc'],['banana_leaf',8,'pc'],['red_pepper',1,'pc'],['salt',null,'']],
  s:{fr:["Pilez au mortier citronnelle, galanga, curcuma, feuilles de combava, échalote, ail et pâte de crevette : c'est le kroeung, et il demande vingt minutes de bras.","Taillez le poisson en lamelles fines et travaillez-le avec le kroeung dans un saladier, en tournant toujours dans le même sens.","Incorporez le lait de coco cuillère par cuillère, puis les œufs battus : l'appareil doit épaissir et devenir soyeux.","Confectionnez des coupes de feuille de bananier assouplie à la flamme, agrafées aux angles.","Tapissez-les de feuilles de noni, garnissez et cuisez 25 minutes à la vapeur douce. Décorez de crème de coco et de poivron."],
     en:["Pound lemongrass, galangal, turmeric, kaffir lime leaves, shallot, garlic and shrimp paste in a mortar: this is kroeung, and it takes twenty minutes of arm work.","Slice the fish thinly and work it with the kroeung in a bowl, always stirring the same way.","Add the coconut milk a spoonful at a time, then the beaten eggs: the mixture should thicken and turn silky.","Make cups from banana leaf softened over a flame, pinned at the corners.","Line them with noni leaves, fill and steam gently for 25 minutes. Decorate with coconut cream and pepper."]} },

{ id:'banh-xeo', c:'as', lat:10.762, lon:106.660, base:4, prep:40, cook:30, diff:2, tags:['sea','fry','street'],
  art:{v:'plate',bg:'#33301f',plate:'#f4ecd8',style:'flat',food:['#e8c46a','#f0a878','#7fae5a','#f0e8d0'],garnish:'#6fbf8f'},
  n:{fr:'Bánh xèo',en:'Bánh xèo'},
  p:{fr:'Hô-Chi-Minh-Ville, Viêt Nam',en:'Ho Chi Minh City, Vietnam'},
  d:{fr:"Une crêpe de riz au curcuma, croustillante, garnie de crevettes et de germes de soja. Le nom imite le bruit de la pâte qui touche la poêle brûlante : xèo, le grésillement, est la seule mesure de la bonne température.",
     en:"A crisp turmeric rice pancake filled with prawns and bean sprouts. The name imitates the sound of batter hitting the scorching pan: xèo, the sizzle, is the only measure of the right heat."},
  i:[['rice_flour',300,'g'],['coconut_milk',400,'ml'],['turmeric',2,'tsp'],['spring_onion',6,'pc'],['shrimp',400,'g'],['pork_belly',300,'g'],['bean_sprouts',400,'g'],['mung_beans',100,'g'],['peanut_oil',200,'ml'],['lettuce',1,'pc'],['mint',1,'bunch'],['fish_sauce',60,'ml'],['lime',3,'pc'],['garlic',4,'clove'],['bird_eye_chili',2,'pc'],['sugar',3,'tbsp'],['salt',null,'']],
  s:{fr:["Mêlez la farine de riz, le lait de coco, le curcuma, l'eau et l'oignon vert, et laissez reposer 2 heures.","La pâte doit être aussi liquide que du lait : plus épaisse, la crêpe sera molle au lieu de croustiller.","Faites cuire les haricots mungo à la vapeur et faites revenir le porc en lamelles avec les crevettes.","Chauffez une poêle jusqu'à ce qu'une goutte d'eau y danse, huilez et versez une louche fine en tournant la poêle.","Garnissez une moitié, couvrez 2 minutes, puis découvrez pour que le bord croustille. Pliez et mangez roulé dans une feuille de salade, trempé dans le nuoc cham."],
     en:["Mix the rice flour, coconut milk, turmeric, water and spring onion, and rest for 2 hours.","The batter must be as thin as milk: any thicker and the pancake goes soft instead of crisp.","Steam the mung beans and fry the sliced pork with the prawns.","Heat a pan until a drop of water dances on it, oil it and pour in a thin ladleful, swirling.","Fill one half, cover for 2 minutes, then uncover so the edge crisps. Fold, and eat rolled in a lettuce leaf, dipped in nuoc cham."]} },

{ id:'gudeg', c:'as', lat:-7.797, lon:110.371, base:6, prep:45, cook:300, diff:3, tags:['veg','slow','comfort'],
  art:{v:'pot',bg:'#2b2419',plate:'#f0e4c8',style:'stew',food:['#8f5a3a','#6f4a2a','#e0b45a','#e8dcb8'],garnish:'#7fae6a'},
  n:{fr:'Gudeg',en:'Gudeg'},
  p:{fr:'Yogyakarta, Java, Indonésie',en:'Yogyakarta, Java, Indonesia'},
  d:{fr:"Du jaque vert mijoté cinq heures dans le lait de coco et le sucre de palme, avec des feuilles de teck qui le teintent d'acajou. Yogyakarta s'appelle la ville du gudeg ; on le mange au petit-déjeuner comme au dîner.",
     en:"Green jackfruit stewed five hours in coconut milk and palm sugar, with teak leaves that stain it mahogany. Yogyakarta calls itself the gudeg city; it is eaten at breakfast as at dinner."},
  i:[['green_jackfruit',1.5,'kg'],['coconut_milk',1.5,'l'],['palm_sugar',200,'g'],['teak_leaves',6,'pc'],['shallot',12,'pc'],['garlic',10,'clove'],['candlenut',8,'pc'],['coriander_seeds',2,'tbsp'],['galangal',60,'g'],['bay_leaf',4,'pc'],['egg',6,'pc'],['chicken',800,'g'],['pork_crackling',150,'g'],['long_grain_rice',500,'g'],['salt',null,'']],
  s:{fr:["Faites bouillir le jaque vert 20 minutes et jetez cette eau : c'est ce qui ôte son latex.","Pilez échalote, ail, noix de bancoul, coriandre et galanga en une pâte fine.","Tapissez le fond de la marmite de feuilles de teck — elles donnent la couleur, sans quoi le gudeg reste pâle.","Rangez le jaque, les œufs durs et le poulet, versez la pâte, le lait de coco et le sucre de palme.","Laissez mijoter 5 heures à feu très doux sans remuer, jusqu'à évaporation presque totale. Servez avec riz et grattons."],
     en:["Boil the green jackfruit for 20 minutes and discard that water: it removes the latex.","Pound the shallot, garlic, candlenuts, coriander and galangal into a fine paste.","Line the base of the pot with teak leaves — they give the colour, without which gudeg stays pale.","Pack in the jackfruit, hard-boiled eggs and chicken, and pour over the paste, coconut milk and palm sugar.","Simmer for 5 hours over very low heat without stirring, until almost dry. Serve with rice and cracklings."]} },

{ id:'ayam-betutu', c:'as', lat:-8.409, lon:115.188, base:6, prep:60, cook:240, diff:3, tags:['poultry','slow','festive'],
  art:{v:'leaf',bg:'#33291f',plate:'#f4ecd8',style:'stew',food:['#e0913a','#c9402c','#8f5a3a','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Ayam betutu',en:'Ayam betutu'},
  p:{fr:'Gianyar, Bali, Indonésie',en:'Gianyar, Bali, Indonesia'},
  d:{fr:"Un poulet entier farci de pâte d'épices, enveloppé d'écorce de bananier et cuit quatre heures sous la braise. Le betutu se commande la veille dans les warungs de Gianyar : personne ne le prépare à la demande.",
     en:"A whole chicken stuffed with spice paste, wrapped in banana bark and cooked four hours under embers. Betutu is ordered a day ahead in the warungs of Gianyar: nobody makes it to order."},
  i:[['chicken',1.8,'kg'],['shallot',15,'pc'],['garlic',12,'clove'],['turmeric',60,'g'],['ginger',60,'g'],['galangal',60,'g'],['candlenut',10,'pc'],['bird_eye_chili',12,'pc'],['lemongrass',4,'pc'],['shrimp_paste',1,'tbsp'],['coriander_seeds',2,'tbsp'],['cassava_leaves',400,'g'],['banana_leaf',10,'pc'],['peanut_oil',120,'ml'],['salt',null,'']],
  s:{fr:["Pilez tous les aromates en une pâte épaisse — le base genep balinais — et faites-la revenir 20 minutes à l'huile.","Frottez le poulet dedans et dehors, en insistant sous la peau, et laissez mariner 6 heures.","Farcissez-le de feuilles de manioc blanchies mêlées à un tiers de la pâte, et cousez l'ouverture.","Enveloppez-le de plusieurs épaisseurs de feuilles de bananier assouplies à la flamme, et liez fermement.","Enfouissez sous la braise ou cuisez 4 heures à 150 °C : la chair doit se détacher de l'os d'elle-même."],
     en:["Pound all the aromatics into a thick paste — the Balinese base genep — and fry it in oil for 20 minutes.","Rub the chicken inside and out, working under the skin, and marinate for 6 hours.","Stuff it with blanched cassava leaves mixed with a third of the paste, and sew the opening.","Wrap it in several thicknesses of flame-softened banana leaf, and tie it firmly.","Bury under embers or cook for 4 hours at 150°C: the flesh should leave the bone by itself."]} },

{ id:'nasi-kandar', c:'as', lat:5.417, lon:100.335, base:6, prep:45, cook:90, diff:2, tags:['rice','poultry','street'],
  art:{v:'plate',bg:'#33291f',plate:'#f4ecd8',style:'rice',food:['#f0e8d0','#c9402c','#e0913a','#8f5a3a'],garnish:'#7fae6a'},
  n:{fr:'Nasi kandar',en:'Nasi kandar'},
  p:{fr:'Butterworth, Penang, Malaisie',en:'Butterworth, Penang, Malaysia'},
  d:{fr:"Du riz nature noyé sous plusieurs currys mélangés d'un coup de louche. Kandar désigne la palanche des porteurs tamouls qui vendaient ce riz de porte en porte ; le mélange des sauces s'appelle banjir, l'inondation.",
     en:"Plain rice drowned under several curries poured together in one ladle. Kandar was the pole of the Tamil hawkers who sold this rice door to door; the mixing of sauces is called banjir, the flood."},
  i:[['long_grain_rice',600,'g'],['chicken',1,'kg'],['okra',300,'g'],['eggplant',300,'g'],['curry_powder',4,'tbsp'],['coconut_milk',400,'ml'],['onion',4,'pc'],['garlic',10,'clove'],['ginger',50,'g'],['curry_leaves',20,'pc'],['cinnamon',2,'pc'],['star_anise',3,'pc'],['dried_chili',8,'pc'],['tamarind_paste',3,'tbsp'],['egg',6,'pc'],['peanut_oil',150,'ml'],['salt',null,'']],
  s:{fr:["Faites cuire le riz nature, sans épices : c'est la toile blanche sur laquelle tout va se mélanger.","Préparez un curry de poulet au lait de coco, épicé aux bâtons de cannelle et à la badiane.","Préparez un second curry, de gombos et d'aubergines au tamarin, plus acide et plus liquide.","Faites frire des œufs durs jusqu'à ce que la peau se craquelle, et gardez le curry de poisson à part.","Servez le riz et versez les sauces les unes sur les autres : le banjir n'est pas un accident, c'est le principe."],
     en:["Cook the rice plain, without spices: it is the white canvas on which everything will mix.","Make a chicken curry with coconut milk, spiced with cinnamon sticks and star anise.","Make a second curry, of okra and aubergine with tamarind, sharper and thinner.","Fry hard-boiled eggs until the skins crack, and keep a fish curry alongside.","Serve the rice and pour the sauces one over another: the banjir is not an accident, it is the point."]} },

{ id:'kaeng-som', c:'as', lat:8.070, lon:98.912, base:4, prep:25, cook:30, diff:2, tags:['sea','soup','spicy'],
  art:{v:'bowl',bg:'#33251c',plate:'#f4ecd8',style:'soup',food:['#e0913a','#c9402c','#7fae5a','#f0e8d0'],garnish:'#6fbf8f'},
  n:{fr:'Kaeng som du Sud',en:'Southern kaeng som'},
  p:{fr:'Krabi, Thaïlande',en:'Krabi, Thailand'},
  d:{fr:"Un curry aigre et jaune, sans lait de coco, d'une force que le nord de la Thaïlande juge déraisonnable. Le tamarin et le curcuma en font tout le corps ; le piment y est présent en quantité qui surprend même les habitués.",
     en:"A sour yellow curry, without coconut milk, of a strength northern Thailand considers unreasonable. Tamarind and turmeric give it body; the chilli is present in quantities that startle even regulars."},
  i:[['white_fish',600,'g'],['shrimp',200,'g'],['tamarind_paste',5,'tbsp'],['turmeric',40,'g'],['dried_chili',10,'pc'],['shallot',6,'pc'],['shrimp_paste',1,'tbsp'],['palm_sugar',2,'tbsp'],['fish_sauce',4,'tbsp'],['green_papaya',300,'g'],['long_beans',200,'g'],['pineapple',200,'g'],['long_grain_rice',400,'g'],['salt',null,'']],
  s:{fr:["Pochez un morceau de poisson et pilez-le au mortier avec les piments, l'échalote, le curcuma frais et la pâte de crevette.","Cette pâte au poisson est la particularité du Sud : elle donne au bouillon un corps que le curry du centre n'a pas.","Délayez-la dans un litre d'eau bouillante et laissez frémir 10 minutes.","Assaisonnez au tamarin, à la sauce poisson et au sucre de palme : le goût doit être franchement acide en premier.","Ajoutez les légumes par ordre de fermeté, puis le poisson et les crevettes pour 5 minutes seulement."],
     en:["Poach a piece of the fish and pound it in a mortar with the chillies, shallot, fresh turmeric and shrimp paste.","This fish-based paste is the southern signature: it gives the broth a body the central curry lacks.","Slake it in a litre of boiling water and simmer for 10 minutes.","Season with tamarind, fish sauce and palm sugar: the first taste should be frankly sour.","Add the vegetables in order of firmness, then the fish and prawns for 5 minutes only."]} },

{ id:'sinigang-na-baboy', c:'as', lat:14.676, lon:121.044, base:6, prep:25, cook:90, diff:1, tags:['pork','soup','comfort'],
  art:{v:'bowl',bg:'#28331f',plate:'#f4ecd8',style:'soup',food:['#f0e8d0','#7fae5a','#8f5a3a','#c9402c'],garnish:'#6fbf8f'},
  n:{fr:'Sinigang na baboy',en:'Sinigang na baboy'},
  p:{fr:'Quezon City, Philippines',en:'Quezon City, Philippines'},
  d:{fr:"Une soupe de porc acidulée au tamarin vert, avec des légumes et des feuilles de kangkong. L'acidité peut venir du tamarin, de la goyave ou de la mangue verte : chaque famille défend son acide et méprise les autres.",
     en:"A pork soup soured with green tamarind, with vegetables and kangkong leaves. The sourness may come from tamarind, guava or green mango: each family defends its acid and scorns the others."},
  i:[['pork_ribs',1,'kg'],['tamarind_paste',5,'tbsp'],['daikon',300,'g'],['long_beans',200,'g'],['eggplant',300,'g'],['water_spinach',400,'g'],['ripe_tomato',300,'g'],['onion',2,'pc'],['taro_root',300,'g'],['green_chili',4,'pc'],['fish_sauce',4,'tbsp'],['long_grain_rice',500,'g'],['salt',null,'']],
  s:{fr:["Blanchissez le travers 10 minutes et jetez cette eau : le bouillon doit rester clair.","Remettez-le dans deux litres d'eau avec l'oignon et la tomate, et laissez frémir 1 heure en écumant.","Ajoutez le taro en cubes : il se défait et épaissit naturellement le bouillon, ce qui est recherché.","Incorporez le tamarin et goûtez : la soupe doit faire saliver, sans piquer le fond de la gorge.","Ajoutez les légumes par ordre de fermeté, le kangkong en tout dernier, et servez avec du riz et de la sauce poisson."],
     en:["Blanch the ribs for 10 minutes and discard that water: the broth must stay clear.","Return them to two litres of water with the onion and tomato, and simmer for 1 hour, skimming.","Add the diced taro: it breaks down and thickens the broth naturally, which is the point.","Stir in the tamarind and taste: the soup should make you salivate, without catching the throat.","Add the vegetables in order of firmness, the water spinach last of all, and serve with rice and fish sauce."]} },

{ id:'la-paz-batchoy', c:'as', lat:10.720, lon:122.562, base:4, prep:30, cook:180, diff:2, tags:['noodles','pork','comfort'],
  art:{v:'bowl',bg:'#33251c',plate:'#f2e8d0',style:'noodle',food:['#8f6a4a','#f0e8d0','#c9754a','#e0b45a'],garnish:'#7fae6a'},
  n:{fr:'La Paz batchoy',en:'La Paz batchoy'},
  p:{fr:'Iloilo, Panay, Philippines',en:'Iloilo, Panay, Philippines'},
  d:{fr:"Une soupe de nouilles au bouillon d'os et d'abats, couronnée de chicharron écrasé. Le marché de La Paz revendique son invention dans les années 1930 ; le bouillon y mijote depuis l'ouverture jusqu'à la fermeture.",
     en:"A noodle soup in a bone and offal broth, crowned with crushed chicharrón. La Paz market claims its invention in the 1930s; the broth there simmers from opening to closing."},
  i:[['pork_bones',1,'kg'],['beef_bones',500,'g'],['pork_liver',200,'g'],['pork_kidney',150,'g'],['pork_belly',300,'g'],['wheat_noodles',400,'g'],['shrimp_paste',1,'tbsp'],['garlic',12,'clove'],['onion',2,'pc'],['ginger',40,'g'],['pork_crackling',150,'g'],['spring_onion',6,'pc'],['egg',4,'pc'],['soy_sauce',3,'tbsp'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Faites un bouillon d'os de porc et de bœuf, 3 heures à frémissement, en écumant sans relâche.","Faites dégorger le rognon 2 heures à l'eau vinaigrée, puis pochez-le et taillez-le en fines lamelles.","Faites de même avec le foie, en le pochant à peine : trop cuit, il devient granuleux.","Relevez le bouillon d'une cuillerée de pâte de crevette et de sauce soja, sans le rendre salé.","Dressez les nouilles, les abats, le porc, un œuf poché, et couronnez d'ail frit et de chicharron écrasé au dernier moment."],
     en:["Make a broth from pork and beef bones, 3 hours at a simmer, skimming relentlessly.","Soak the kidney for 2 hours in vinegared water, then poach it and slice it thinly.","Do the same with the liver, poaching it barely: overcooked it turns grainy.","Season the broth with a spoonful of shrimp paste and soy sauce, without making it salty.","Assemble the noodles, offal, pork and a poached egg, and crown with fried garlic and crushed chicharrón at the last moment."]} },

{ id:'bun-cha-ca', c:'as', lat:12.239, lon:109.196, base:4, prep:35, cook:40, diff:2, tags:['sea','noodles','fresh'],
  art:{v:'bowl',bg:'#26384a',plate:'#f2e8d0',style:'noodle',food:['#f0e8d0','#e8c46a','#7fae5a','#f4f0e6'],garnish:'#6fbf8f'},
  n:{fr:'Bún chả cá',en:'Bún chả cá'},
  p:{fr:'Nha Trang, Viêt Nam',en:'Nha Trang, Vietnam'},
  d:{fr:"Un bouillon clair de poisson avec des galettes de chair pilée, frites puis pochées. Le poisson est pilé au mortier jusqu'à devenir élastique : c'est ce rebond sous la dent, et non le goût, qui juge la galette.",
     en:"A clear fish broth with cakes of pounded flesh, fried then poached. The fish is pounded until springy: it is that bounce under the tooth, not the taste, that judges the cake."},
  i:[['mackerel',700,'g'],['rice_vermicelli',400,'g'],['fish_broth',1.5,'l'],['dill',1,'bunch'],['spring_onion',6,'pc'],['garlic',6,'clove'],['fish_sauce',60,'ml'],['pineapple',150,'g'],['ripe_tomato',200,'g'],['bean_sprouts',200,'g'],['thai_basil',1,'bunch'],['lime',3,'pc'],['bird_eye_chili',2,'pc'],['frying_oil',400,'ml'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Levez les filets, retirez la peau et pilez la chair au mortier avec ail, sucre, sauce poisson et beaucoup de poivre.","Pilez 15 minutes : la pâte doit devenir collante et rebondir quand on la jette contre la paroi.","Incorporez l'aneth et l'oignon vert ciselés, formez des galettes plates et faites-les frire 3 minutes par face.","Faites un bouillon clair avec les têtes et arêtes, l'ananas et la tomate, et filtrez-le soigneusement.","Pochez les galettes 5 minutes dans ce bouillon et servez sur les vermicelles, avec germes, herbes et citron vert."],
     en:["Fillet the fish, skin it and pound the flesh in a mortar with garlic, sugar, fish sauce and plenty of pepper.","Pound for 15 minutes: the paste should turn sticky and bounce when thrown against the side.","Fold in chopped dill and spring onion, shape flat cakes and fry them 3 minutes a side.","Make a clear broth from the heads and bones with pineapple and tomato, and strain it carefully.","Poach the cakes for 5 minutes in that broth and serve over vermicelli, with sprouts, herbs and lime."]} },

{ id:'lu-rou-fan', c:'as', lat:25.033, lon:121.565, base:4, prep:20, cook:90, diff:1, tags:['pork','rice','comfort'],
  art:{v:'bowl',bg:'#33251c',plate:'#f4ecd8',style:'rice',food:['#f4f0e6','#6f4a2a','#8f5a3a','#e0b45a'],garnish:'#7fae6a'},
  n:{fr:'Lu rou fan',en:'Lu rou fan'},
  p:{fr:'Taipei, Taïwan',en:'Taipei, Taiwan'},
  d:{fr:"Du porc gras haché mijoté à la sauce soja et au vin de riz, versé sur du riz blanc. Taïwan le tient pour son plat national ; le nord et le sud se disputent sur la taille du hachis, à un millimètre près.",
     en:"Fatty minced pork stewed in soy sauce and rice wine, spooned over white rice. Taiwan calls it the national dish; north and south argue over the size of the dice, to the millimetre."},
  i:[['pork_belly',700,'g'],['shallot',10,'pc'],['soy_sauce',120,'ml'],['dark_soy_sauce',2,'tbsp'],['rice_wine',100,'ml'],['rock_sugar',40,'g'],['five_spice',1,'tsp'],['star_anise',2,'pc'],['garlic',6,'clove'],['white_pepper',1,'tsp'],['egg',4,'pc'],['pickled_mustard_greens',150,'g'],['long_grain_rice',500,'g'],['peanut_oil',60,'ml']],
  s:{fr:["Taillez la poitrine au couteau en dés de 5 mm, gras compris : c'est le gras qui fait la texture, l'ôter revient à faire autre chose.","Faites frire les échalotes émincées dans l'huile jusqu'au brun doré, puis retirez-les et gardez l'huile.","Faites rendre le porc à sec dans un wok jusqu'à ce qu'il colore et que la graisse se libère.","Ajoutez l'ail, les échalotes frites, les deux sauces soja, le vin de riz, le sucre candi et les épices.","Mouillez d'eau à hauteur et laissez mijoter 1 h 15 à découvert : la sauce doit devenir sirupeuse et enrober chaque dé."],
     en:["Cut the belly by knife into 5 mm dice, fat included: the fat makes the texture, and removing it makes another dish.","Fry the sliced shallots in oil to a deep gold, then lift them out and keep the oil.","Render the pork dry in a wok until it colours and the fat runs.","Add the garlic, fried shallots, both soy sauces, rice wine, rock sugar and spices.","Cover with water and simmer uncovered for 1¼ hours: the sauce should turn syrupy and coat every dice."]} },

{ id:'o-a-tsian', c:'as', lat:22.997, lon:120.213, base:2, prep:15, cook:10, diff:2, tags:['sea','street','fast'],
  art:{v:'plate',bg:'#33251c',plate:'#f4ecd8',style:'flat',food:['#f0e8d0','#c9402c','#7fae5a','#e8dcc0'],garnish:'#6fbf8f'},
  n:{fr:'Omelette aux huîtres',en:'Oyster omelette'},
  p:{fr:'Tainan, Taïwan',en:'Tainan, Taiwan'},
  d:{fr:"Une omelette liée à la fécule de patate douce, translucide et élastique, aux petites huîtres. La fécule est ce qui compte : sans elle, ce n'est qu'une omelette aux huîtres, et les marchés de nuit ne pardonneraient pas.",
     en:"An omelette bound with sweet potato starch, translucent and elastic, with small oysters. The starch is what matters: without it, it is merely an oyster omelette, and the night markets would not forgive."},
  i:[['oysters',200,'g'],['sweet_potato_starch',60,'g'],['egg',3,'pc'],['water_spinach',150,'g'],['peanut_oil',60,'ml'],['ketchup',3,'tbsp'],['miso_paste',1,'tbsp'],['sugar',1,'tbsp'],['cornstarch',1,'tsp'],['garlic',2,'clove'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Délayez la fécule de patate douce dans le double d'eau froide et laissez reposer : elle doit rester liquide et laiteuse.","Préparez la sauce en faisant épaissir ketchup, miso, sucre et un peu d'eau avec la fécule de maïs.","Chauffez le wok très fort, huilez, et faites sauter les huîtres 30 secondes.","Versez la pâte de fécule dessus : elle devient aussitôt translucide et gélatineuse. Ne remuez pas.","Cassez les œufs par-dessus, ajoutez les feuilles vertes, retournez d'un coup et servez nappé de sauce rouge."],
     en:["Slake the sweet potato starch in twice its volume of cold water and let it stand: it should stay thin and milky.","Make the sauce by thickening ketchup, miso, sugar and a little water with the cornstarch.","Heat the wok fiercely, oil it, and toss the oysters for 30 seconds.","Pour the starch batter over them: it turns translucent and gelatinous at once. Do not stir.","Break the eggs over the top, add the greens, flip in one movement and serve under the red sauce."]} },

{ id:'thenthuk', c:'as', lat:27.717, lon:85.360, base:4, prep:40, cook:30, diff:2, tags:['noodles','soup','comfort'],
  art:{v:'bowl',bg:'#33291f',plate:'#f4ecd8',style:'noodle',food:['#f0e8d0','#8f5a3a','#7fae5a','#e8dcc0'],garnish:'#7fae6a'},
  n:{fr:'Thenthuk',en:'Thenthuk'},
  p:{fr:'Bodnath, Katmandou, Népal',en:'Boudhanath, Kathmandu, Nepal'},
  d:{fr:"Une soupe de pâte déchirée à la main dans le bouillon, avec du mouton et des légumes. Then veut dire tirer, thuk soupe : les morceaux sont irréguliers par principe, et un rouleau à pâtisserie serait un contresens.",
     en:"A soup of dough torn by hand straight into the broth, with mutton and vegetables. Then means to pull, thuk soup: the pieces are irregular on principle, and a rolling pin would miss the point."},
  i:[['flour',400,'g'],['water',200,'ml'],['mutton_shoulder',500,'g'],['onion',2,'pc'],['tomato',300,'g'],['daikon',200,'g'],['spinach',200,'g'],['carrot',2,'pc'],['garlic',6,'clove'],['ginger',40,'g'],['soy_sauce',3,'tbsp'],['cilantro',1,'bunch'],['spring_onion',4,'pc'],['peanut_oil',60,'ml'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Pétrissez la farine, l'eau et le sel en une pâte ferme, et laissez-la reposer une heure sous un linge humide.","Faites revenir le mouton en dés avec l'oignon, l'ail, le gingembre et la tomate, puis mouillez de deux litres d'eau.","Laissez mijoter 40 minutes, ajoutez le radis et la carotte.","Étalez la pâte en bandes de 3 cm, huilez-les, puis étirez et déchirez des morceaux directement au-dessus du bouillon frémissant.","Ils remontent en 3 minutes quand ils sont cuits. Ajoutez les épinards et les herbes, et servez brûlant."],
     en:["Knead the flour, water and salt into a firm dough, and rest it for an hour under a damp cloth.","Fry the diced mutton with the onion, garlic, ginger and tomato, then add two litres of water.","Simmer for 40 minutes, then add the daikon and carrot.","Roll the dough into 3 cm strips, oil them, then stretch and tear pieces straight over the simmering broth.","They rise within 3 minutes when cooked. Add the spinach and herbs, and serve scalding."]} },

{ id:'biryani-sindhi', c:'as', lat:25.396, lon:68.377, base:8, prep:60, cook:90, diff:3, tags:['rice','poultry','festive'],
  art:{v:'plate',bg:'#33291f',plate:'#f4ecd8',style:'rice',food:['#e0b45a','#c9402c','#f0e8d0','#8f5a3a'],garnish:'#7fae6a'},
  n:{fr:'Biryani sindhi',en:'Sindhi biryani'},
  p:{fr:'Hyderabad, Sind, Pakistan',en:'Hyderabad, Sindh, Pakistan'},
  d:{fr:"Un biryani aux pommes de terre, aux pruneaux et au yaourt, plus acide et plus épicé que ses cousins. Le Sind y met de la prune séchée : ce contrepoint sucré-acide surprend et devient vite indispensable.",
     en:"A biryani with potatoes, prunes and yogurt, sharper and hotter than its cousins. Sindh adds dried plum: that sweet-sour counterpoint surprises, then quickly becomes indispensable."},
  i:[['chicken',1.5,'kg'],['basmati_rice',800,'g'],['plain_yogurt',400,'g'],['onion',5,'pc'],['potato',500,'g'],['prunes',150,'g'],['ripe_tomato',400,'g'],['ginger_garlic_paste',4,'tbsp'],['green_chili',6,'pc'],['biryani_masala',4,'tbsp'],['saffron',1,'pinch'],['mint',2,'bunch'],['cilantro',1,'bunch'],['ghee',200,'g'],['lemon',2,'pc'],['salt',null,'']],
  s:{fr:["Faites frire les oignons émincés jusqu'au brun foncé et réservez-en la moitié : ils parfument et colorent.","Faites mariner le poulet 3 heures dans le yaourt, la pâte gingembre-ail, le masala et la moitié des oignons frits.","Faites cuire la marinade 30 minutes avec la tomate et les pommes de terre, jusqu'à ce que l'huile se sépare.","Précuisez le riz trempé 6 minutes à grande eau salée avec des épices entières, et égouttez-le aux trois quarts cuit.","Montez en couches viande, pruneaux, riz, herbes, oignons frits et safran ; scellez et laissez 25 minutes à feu très doux."],
     en:["Fry the sliced onions to a deep brown and set half aside: they perfume and colour.","Marinate the chicken for 3 hours in the yogurt, ginger-garlic paste, masala and half the fried onions.","Cook the marinade for 30 minutes with the tomato and potatoes, until the oil separates.","Par-boil the soaked rice for 6 minutes in salted water with whole spices, and drain it three-quarters cooked.","Layer meat, prunes, rice, herbs, fried onions and saffron; seal and leave 25 minutes over very low heat."]} },

{ id:'kuku-sabzi', c:'as', lat:32.660, lon:51.680, base:6, prep:40, cook:45, diff:2, tags:['veg','festive','bake'],
  art:{v:'plate',bg:'#28331f',plate:'#f4ecd8',style:'cake',food:['#2f4f2a','#4f6f3a','#e0b45a','#f0e8d0'],garnish:'#6fbf8f'},
  n:{fr:'Kuku sabzi',en:'Kuku sabzi'},
  p:{fr:'Ispahan, Iran',en:'Isfahan, Iran'},
  d:{fr:"Une omelette si verte d'herbes qu'on y voit à peine l'œuf, servie à Norouz. Le vert est la couleur du renouveau : on la mange au premier jour du printemps pour que l'année soit fertile.",
     en:"An omelette so green with herbs that the egg barely shows, served at Nowruz. Green is the colour of renewal: eaten on the first day of spring so the year will be fertile."},
  i:[['parsley',3,'bunch'],['cilantro',2,'bunch'],['dill',2,'bunch'],['chives',2,'bunch'],['fenugreek_leaves',1,'bunch'],['egg',8,'pc'],['walnuts',100,'g'],['barberries',60,'g'],['turmeric',1,'tsp'],['baking_powder',1,'tsp'],['flour',2,'tbsp'],['butter',80,'g'],['peanut_oil',80,'ml'],['plain_yogurt',300,'g'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Lavez les herbes, essorez-les à fond et hachez-les très finement : il faut un volume énorme, presque deux litres tassés.","Épongez-les dans un linge : la moindre humidité rendrait le kuku mou au centre.","Battez les œufs sans les faire mousser, ajoutez la farine, la levure, le curcuma et le sel.","Incorporez les herbes, les noix concassées et les épines-vinettes : l'appareil doit être plus vert que jaune.","Versez dans une poêle beurrée et cuisez 20 minutes à couvert, à feu doux, puis retournez pour 15 minutes. Servez tiède avec du yaourt."],
     en:["Wash the herbs, spin them thoroughly dry and chop them very finely: you need an enormous volume, nearly two packed litres.","Blot them in a cloth: the least moisture would leave the kuku soft in the middle.","Beat the eggs without aerating them, add the flour, baking powder, turmeric and salt.","Fold in the herbs, crushed walnuts and barberries: the mixture should be more green than yellow.","Pour into a buttered pan and cook covered for 20 minutes over low heat, then flip for 15 more. Serve warm with yogurt."]} },

{ id:'khash', c:'as', lat:40.177, lon:44.512, base:6, prep:30, cook:480, diff:2, tags:['beef','slow','breakfast'],
  art:{v:'bowl',bg:'#2c3440',plate:'#f4f0e6',style:'soup',food:['#f4f0e6','#f0e8d0','#e8dcc0','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Khash',en:'Khash'},
  p:{fr:'Guimri, Arménie',en:'Gyumri, Armenia'},
  d:{fr:"Un bouillon de pieds de bœuf cuit toute la nuit, mangé à l'aube avec de l'ail cru et du lavash. On le sert de décembre à mars, avant le lever du jour, et l'usage veut qu'on boive de la vodka avec, jamais du vin.",
     en:"A cow's-foot broth cooked all night and eaten at dawn with raw garlic and lavash. Served from December to March, before sunrise, and custom requires vodka with it, never wine."},
  i:[['beef_trotters',3,'kg'],['beef_tripe',500,'g'],['garlic',20,'clove'],['lavash',6,'pc'],['radish',2,'bunch'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Faites tremper les pieds 24 heures à l'eau froide courante, en changeant l'eau six fois : c'est ce qui ôte l'odeur.","Grattez-les soigneusement et blanchissez-les 15 minutes ; jetez cette eau.","Remettez-les dans une grande marmite d'eau claire, sans sel, sans légume, sans aucune épice.","Laissez frémir 7 à 8 heures en écumant : le bouillon doit devenir laiteux et prendre en gelée à froid.","Servez brûlant, non salé. Chacun ajoute à sa guise sel, ail pilé et lavash émietté dans son bol."],
     en:["Soak the trotters for 24 hours under cold running water, changing it six times: this removes the smell.","Scrape them thoroughly and blanch them for 15 minutes; discard that water.","Return them to a large pot of clean water, without salt, vegetable or any spice.","Simmer for 7 to 8 hours, skimming: the broth should turn milky and set to a jelly when cold.","Serve scalding and unsalted. Each diner adds salt, pounded garlic and crumbled lavash to their own bowl."]} },

{ id:'shah-plov', c:'as', lat:40.376, lon:49.849, base:8, prep:60, cook:90, diff:3, tags:['rice','lamb','festive'],
  art:{v:'plate',bg:'#33291f',plate:'#f4ecd8',style:'rice',food:['#e8c46a','#f4f0e6','#8f5a3a','#c9402c'],garnish:'#7fae6a'},
  n:{fr:'Chah plov',en:'Shah plov'},
  p:{fr:'Chéki, Azerbaïdjan',en:'Sheki, Azerbaijan'},
  d:{fr:"Un riz au safran et à l'agneau enfermé dans une couronne de pain lavash, doré au four comme une couronne. On l'apporte entier à table et on l'ouvre devant les convives : le pain croustillant est la moitié du plat.",
     en:"Saffron rice and lamb sealed in a crown of lavash bread, baked golden like a crown. It comes whole to the table and is opened in front of the guests: the crisp bread is half the dish."},
  i:[['basmati_rice',800,'g'],['lamb_shoulder',800,'g'],['lavash',6,'pc'],['ghee',250,'g'],['saffron',1,'tsp'],['dried_apricots',100,'g'],['chestnuts',200,'g'],['raisins',100,'g'],['onion',3,'pc'],['barberries',60,'g'],['cinnamon',1,'tsp'],['egg_yolk',2,'pc'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Rincez le riz sept fois et faites-le tremper 2 heures dans l'eau salée : c'est ce qui donne des grains longs et détachés.","Précuisez-le 6 minutes à grande eau et égouttez-le à moitié cuit.","Faites revenir l'agneau en dés avec l'oignon, les abricots, les châtaignes et les raisins, 30 minutes.","Chemisez une cocotte beurrée de lavash badigeonné de ghee et de jaune d'œuf, en laissant largement dépasser les bords.","Remplissez de riz et de viande en couches, rabattez le pain, et enfournez 50 minutes à 180 °C. Démoulez d'un geste et coupez comme un gâteau."],
     en:["Rinse the rice seven times and soak it for 2 hours in salted water: this gives long, separate grains.","Par-boil it for 6 minutes in plenty of water and drain it half cooked.","Fry the diced lamb with the onion, apricots, chestnuts and raisins for 30 minutes.","Line a buttered pot with lavash brushed with ghee and egg yolk, leaving the edges hanging well over.","Fill with layers of rice and meat, fold the bread over, and bake for 50 minutes at 180°C. Turn out in one movement and cut like a cake."]} },

{ id:'soup-curry-sapporo', c:'as', lat:43.062, lon:141.354, base:4, prep:40, cook:90, diff:2, tags:['poultry','soup','spicy'],
  art:{v:'bowl',bg:'#33251c',plate:'#f0e4c8',style:'soup',food:['#c9532c','#e0913a','#7fae5a','#e8dcb8'],garnish:'#7fae6a'},
  n:{fr:'Soup curry de Sapporo',en:'Sapporo soup curry'},
  p:{fr:'Sapporo, Hokkaidō, Japon',en:'Sapporo, Hokkaidō, Japan'},
  d:{fr:"Un curry liquide et épicé où baignent une cuisse de poulet et des légumes entiers, servi avec du riz à part. Inventé à Sapporo dans les années 1970, il est l'exact opposé du curry japonais épais : la sauce se boit à la cuillère, et les légumes se dressent hors du bol.",
     en:"A thin, spiced curry in which a chicken leg and whole vegetables sit, with rice served separately. Invented in Sapporo in the 1970s, it is the exact opposite of thick Japanese curry: the broth is spooned, and the vegetables stand proud of the bowl."},
  i:[['chicken_legs',4,'pc'],['chicken_broth',1.2,'l'],['onion',2,'pc'],['ripe_tomato',300,'g'],['carrot',2,'pc'],['potato',400,'g'],['eggplant',1,'pc'],['green_pepper',1,'pc'],['curry_powder',3,'tbsp'],['cumin',1,'tbsp'],['ginger',30,'g'],['garlic',5,'clove'],['sunflower_oil',60,'ml'],['long_grain_rice',300,'g'],['salt',null,'']],
  s:{fr:["Faites confire l'oignon très finement émincé 40 minutes à feu doux, jusqu'à ce qu'il soit brun et fondu : c'est le fond du bouillon.","Ajoutez l'ail et le gingembre râpés, puis les épices hors du feu — jetées dans une huile bouillante, elles brûlent en trois secondes.","Ajoutez la tomate râpée, laissez réduire, puis mouillez du bouillon et laissez frémir 40 minutes.","Ne liez surtout pas : le soup curry doit rester liquide comme un consommé, et la moindre farine en ferait un curry ordinaire.","Faites frire les légumes entiers séparément pour qu'ils gardent leur forme, et disposez-les debout dans le bol avec la cuisse. Riz à part."],
     en:["Confit the very finely sliced onion for 40 minutes over low heat, until brown and melting: it is the base of the broth.","Add the grated garlic and ginger, then the spices off the heat — thrown into hot oil they burn in three seconds.","Add the grated tomato, reduce, then moisten with the broth and simmer 40 minutes.","On no account thicken it: a soup curry must stay as thin as consommé, and the least flour would make it an ordinary curry.","Fry the vegetables whole and separately so they hold their shape, and stand them up in the bowl with the leg. Rice on the side."]} },

{ id:'ishikari-nabe', c:'as', lat:43.171, lon:141.354, base:4, prep:30, cook:30, diff:2, tags:['sea','soup','comfort'],
  art:{v:'pot',bg:'#26485c',plate:'#f0e4c8',style:'soup',food:['#e0a8a0','#f4f0e6','#7fae5a','#e8c46a'],garnish:'#6fbf8f'},
  n:{fr:'Ishikari nabe',en:'Ishikari nabe'},
  p:{fr:'Ishikari, Hokkaidō, Japon',en:'Ishikari, Hokkaidō, Japan'},
  d:{fr:"Une marmite de saumon et de légumes au miso, mijotée à table sur un réchaud. Elle vient de l'embouchure de l'Ishikari, où les pêcheurs faisaient cuire les parures de saumon invendables ; on y met la tête et la peau, qui donnent la gélatine, et non les beaux pavés.",
     en:"A pot of salmon and vegetables in miso, simmered at the table over a burner. It comes from the mouth of the Ishikari, where fishermen cooked the unsellable trimmings; head and skin go in, for the gelatine, rather than the handsome fillets."},
  i:[['salmon',600,'g'],['miso_paste',80,'g'],['napa_cabbage',400,'g'],['daikon',300,'g'],['carrot',1,'pc'],['tofu',200,'g'],['shiitake_mushrooms',150,'g'],['kombu',15,'g'],['spring_onion',4,'pc'],['sake',60,'ml'],['butter',30,'g'],['water',1.2,'l'],['salt',null,'']],
  s:{fr:["Faites tremper le kombu une heure à l'eau froide et retirez-le dès que l'eau frémit : bouilli, il devient visqueux et amer.","Ébouillantez les morceaux de saumon dix secondes puis rincez-les à l'eau froide — ce geste ôte l'écume et l'odeur, et clarifie le bouillon.","Rangez les légumes debout dans la marmite, les plus longs à cuire au fond, et posez le saumon dessus.","Délayez le miso dans une louche de bouillon chaud avant de l'incorporer, et ne le faites jamais bouillir : au-delà de 80 °C il perd son parfum.","Terminez d'une noix de beurre, signature de Hokkaidō, et servez la marmite au centre de la table, sur son réchaud."],
     en:["Soak the kombu an hour in cold water and lift it out as soon as the water trembles: boiled, it turns slimy and bitter.","Blanch the salmon pieces for ten seconds then rinse them cold — this removes scum and odour, and clears the broth.","Stand the vegetables upright in the pot, the slowest to cook at the bottom, and set the salmon on top.","Slake the miso in a ladle of hot broth before stirring it in, and never let it boil: above 80°C it loses its scent.","Finish with a knob of butter, the Hokkaidō signature, and set the pot in the middle of the table over its burner."]} },

{ id:'kaisendon', c:'as', lat:43.196, lon:140.994, base:2, prep:40, cook:20, diff:2, tags:['sea','fresh','rice'],
  art:{v:'bowl',bg:'#26485c',plate:'#f4f0e6',style:'rice',food:['#e07a6a','#f4f0e6','#e8c46a','#7fae5a'],garnish:'#6fbf8f'},
  n:{fr:'Kaisendon',en:'Kaisendon'},
  p:{fr:'Otaru, Hokkaidō, Japon',en:'Otaru, Hokkaidō, Japan'},
  d:{fr:"Un bol de riz vinaigré couvert de poisson cru, d'oursin et d'œufs de saumon. Il se mange au marché du port dès sept heures du matin ; contrairement au sushi, le poisson n'est pas travaillé mais simplement tranché, ce qui exige une fraîcheur que seul un port permet.",
     en:"A bowl of vinegared rice covered with raw fish, sea urchin and salmon roe. It is eaten at the harbour market from seven in the morning; unlike sushi the fish is not worked but simply sliced, which demands a freshness only a port allows."},
  i:[['sushi_rice',300,'g'],['tuna',150,'g'],['salmon',150,'g'],['scallops',100,'g'],['sea_urchin',80,'g'],['salmon_roe',80,'g'],['rice_vinegar',50,'ml'],['sugar',1,'tbsp'],['nori',1,'sheet'],['wasabi',1,'tbsp'],['soy_sauce',60,'ml'],['shiso',6,'pc'],['salt',null,'']],
  s:{fr:["Assaisonnez le riz encore chaud au vinaigre sucré en le coupant à la spatule, jamais en le remuant, et éventez-le pour le faire briller.","Laissez-le tiédir à température du corps : un riz glacé anesthésie le poisson, un riz brûlant le cuit.","Tranchez chaque poisson selon son grain : le thon en travers des fibres, le saumon en biais et plus fin, le pétoncle en deux dans l'épaisseur.","Essuyez la lame entre chaque poisson pour ne pas transporter le goût de l'un sur l'autre.","Dressez sans superposer, en laissant voir le riz par endroits, et posez l'oursin et les œufs en dernier — ils s'écrasent sous tout le reste."],
     en:["Season the still-warm rice with sweetened vinegar, cutting it in with a spatula and never stirring, and fan it to make it shine.","Let it cool to body temperature: ice-cold rice numbs the fish, scalding rice cooks it.","Slice each fish according to its grain: tuna across the fibres, salmon on the bias and thinner, scallop split through its thickness.","Wipe the blade between each fish so as not to carry the taste of one onto another.","Arrange without overlapping, leaving the rice visible in places, and set the sea urchin and roe last — they crush under anything else."]} },

{ id:'gyutan-sendai', c:'as', lat:38.268, lon:140.869, base:4, prep:40, cook:15, diff:3, tags:['beef','grill','comfort'],
  art:{v:'plate',bg:'#2b2419',plate:'#f4f0e6',style:'grill',food:['#e0a8a0','#8f5a3a','#f4f0e6','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Gyūtan de Sendai',en:'Sendai gyūtan'},
  p:{fr:'Sendai, Tōhoku, Japon',en:'Sendai, Tōhoku, Japan'},
  d:{fr:"Des tranches de langue de bœuf salées puis grillées au charbon, servies avec du riz d'orge et une soupe de queue de bœuf. Un cuisinier de Sendai les mit à sa carte en 1948 : les Américains occupants ne mangeaient ni la langue ni la queue, et il récupérait les deux.",
     en:"Slices of beef tongue salted then charcoal-grilled, served with barley rice and oxtail soup. A Sendai cook put them on his menu in 1948: the occupying Americans ate neither tongue nor tail, and he took both."},
  i:[['beef_tongue',600,'g'],['coarse_salt',20,'g'],['sake',40,'ml'],['long_grain_rice',250,'g'],['barley',80,'g'],['oxtail',400,'g'],['spring_onion',4,'pc'],['lemon',1,'pc'],['black_peppercorns',1,'tbsp'],['pickled_beets',100,'g'],['salt',null,'']],
  s:{fr:["Pelez la langue crue en la fendant à la pointe : à ce stade la peau se retire au couteau, alors qu'après cuisson elle s'arrache.","Taillez-la en tranches de 6 mm en travers, et incisez chaque tranche en croisillons peu profonds des deux côtés.","Ces incisions ne sont pas décoratives : elles empêchent la tranche de se contracter en boule sur la braise.","Salez au sel sec et laissez reposer 48 heures au froid : ce salage long attendrit la langue, qui est un muscle très ferme.","Grillez sur des braises vives 90 secondes par face, pas davantage. Servez avec du riz d'orge, une soupe de queue et du citron."],
     en:["Peel the tongue raw by slitting it with a point: at this stage the skin comes away with a knife, whereas after cooking it must be torn.","Cut it into 6 mm slices across, and score each slice in a shallow lattice on both sides.","Those cuts are not decorative: they stop the slice curling into a ball over the coals.","Dry-salt it and rest 48 hours in the cold: that long cure tenderises the tongue, which is a very firm muscle.","Grill over fierce coals 90 seconds a side, no longer. Serve with barley rice, oxtail soup and lemon."]} },

{ id:'wanko-soba', c:'as', lat:39.702, lon:141.155, base:4, prep:70, cook:5, diff:3, tags:['noodles','festive','fast'],
  art:{v:'bowl',bg:'#33291f',plate:'#f4f0e6',style:'noodle',food:['#8f6a4a','#f4f0e6','#7fae5a','#e8dcb8'],garnish:'#7fae6a'},
  n:{fr:'Wanko soba',en:'Wanko soba'},
  p:{fr:'Morioka, Iwate, Japon',en:'Morioka, Iwate, Japan'},
  d:{fr:"De minuscules portions de nouilles de sarrasin servies dans de petits bols qu'un serveur remplit sans arrêt. On ne s'arrête qu'en refermant le couvercle, et l'usage veut qu'on compte : quinze bols valent une portion normale, et les habitués dépassent la centaine.",
     en:"Tiny portions of buckwheat noodles served in small bowls that a server refills without pause. You stop only by closing the lid, and custom demands you count: fifteen bowls make one normal portion, and regulars pass a hundred."},
  i:[['buckwheat_flour',300,'g'],['flour',100,'g'],['water',180,'ml'],['dashi_stock',600,'ml'],['soy_sauce',80,'ml'],['mirin',60,'ml'],['spring_onion',4,'pc'],['nori',1,'sheet'],['sesame_seeds',2,'tbsp'],['wasabi',1,'tbsp'],['tuna',80,'g'],['salt',null,'']],
  s:{fr:["Pétrissez la farine de sarrasin et de froment à l'eau tiède en travaillant vite : la pâte de sarrasin sèche et se fendille en quelques minutes.","Elle ne contient presque pas de gluten et ne se pétrit pas comme une pâte à pain : on la rassemble en pressant, sans jamais l'étirer.","Abaissez à 1,5 mm, pliez la feuille en accordéon et coupez au couteau des nouilles de la même largeur que leur épaisseur.","Cuisez-les 90 secondes seulement dans une grande eau bouillante, puis rincez-les à l'eau glacée pour arrêter la cuisson et ôter l'amidon.","Servez par petites poignées dans un bouillon de dashi et de soja, avec les garnitures à part. Les bols se remplissent aussitôt vidés."],
     en:["Knead the buckwheat and wheat flours with warm water, working fast: buckwheat dough dries and cracks within minutes.","It has almost no gluten and is not kneaded like bread dough: you press it together, never stretching it.","Roll to 1.5 mm, fold the sheet like a concertina and cut noodles the same width as their thickness.","Cook them 90 seconds only in plenty of boiling water, then rinse in iced water to stop the cooking and wash off the starch.","Serve in small handfuls in a dashi and soy broth, with the garnishes apart. The bowls are refilled the moment they are empty."]} },

{ id:'kiritanpo', c:'as', lat:39.720, lon:140.103, base:4, prep:50, cook:40, diff:2, tags:['poultry','rice','comfort'],
  art:{v:'pot',bg:'#33291f',plate:'#f0e4c8',style:'soup',food:['#f4f0e6','#e8dcb8','#7fae5a','#c9924a'],garnish:'#7fae6a'},
  n:{fr:'Kiritanpo',en:'Kiritanpo'},
  p:{fr:'Akita, Tōhoku, Japon',en:'Akita, Tōhoku, Japan'},
  d:{fr:"Du riz écrasé et moulé autour d'un bâton de cèdre, grillé puis mijoté dans un bouillon de poulet. Les bûcherons d'Akita emportaient ainsi leur riz en forêt, le faisant griller sur le feu ; le nom vient de la forme, qui rappelle un tampon de lance coupé.",
     en:"Rice mashed and moulded around a cedar stick, grilled then simmered in chicken broth. Akita woodsmen carried their rice into the forest this way and grilled it over the fire; the name comes from the shape, like a cut spear-tip wrapping."},
  i:[['sushi_rice',400,'g'],['chicken',500,'g'],['chicken_broth',1.2,'l'],['burdock',150,'g'],['maitake_mushrooms',200,'g'],['spring_onion',6,'pc'],['soy_sauce',60,'ml'],['sake',40,'ml'],['mirin',30,'ml'],['parsley',2,'tbsp'],['salt',null,'']],
  s:{fr:["Cuisez le riz plus humide qu'à l'ordinaire, puis écrasez-le au pilon jusqu'à ce que la moitié des grains soit brisée — pas tous, sinon c'est une pâte.","Moulez-le encore chaud autour de bâtons de bois, en couche d'un centimètre, en mouillant vos mains d'eau salée.","Grillez au-dessus des braises en tournant, jusqu'à ce que la surface soit dorée et sèche : c'est cette croûte qui empêchera le riz de se déliter dans le bouillon.","Retirez les bâtons en tournant, coupez en tronçons de 5 cm et ajoutez-les au bouillon dans les cinq dernières minutes.","Au-delà, ils se défont. Servez avec le poulet, la bardane taillée en copeaux et les champignons maitake."],
     en:["Cook the rice wetter than usual, then pound it until half the grains are broken — not all, or it becomes a paste.","Mould it while still hot around wooden sticks in a one-centimetre layer, wetting your hands in salted water.","Grill over coals, turning, until the surface is golden and dry: that crust is what will stop the rice falling apart in the broth.","Twist out the sticks, cut into 5 cm lengths and add them to the broth for the last five minutes only.","Beyond that they collapse. Serve with the chicken, burdock shaved into slivers and maitake mushrooms."]} },

{ id:'ika-no-shiokara', c:'as', lat:38.500, lon:141.300, base:8, prep:60, cook:0, diff:3, tags:['sea','slow','fresh'],
  art:{v:'bowl',bg:'#26384a',plate:'#f4f0e6',style:'other',food:['#8f6a4a','#e0a8a0','#f4f0e6','#7fae5a'],garnish:'#6fbf8f'},
  n:{fr:'Ika no shiokara',en:'Ika no shiokara'},
  p:{fr:'Ishinomaki, Tōhoku, Japon',en:'Ishinomaki, Tōhoku, Japan'},
  d:{fr:"Des lanières de calmar cru fermentées dans leurs propres viscères salés, mangées à la pointe des baguettes avec du saké. La fermentation se fait par les enzymes du foie du calmar : c'est un procédé de conservation d'avant le froid, et le goût en est puissamment iodé.",
     en:"Strips of raw squid fermented in their own salted viscera, eaten on the tips of chopsticks with sake. The fermentation is driven by enzymes from the squid's liver: a preservation method from before refrigeration, and the taste is powerfully briny."},
  i:[['squid',600,'g'],['coarse_salt',60,'g'],['sake',60,'ml'],['mirin',20,'ml'],['ginger',20,'g'],['spring_onion',3,'pc'],['long_grain_rice',300,'g']],
  s:{fr:["Videz les calmars en gardant intacte la poche de foie, brun-orange : c'est elle qui fermente le plat, et une poche crevée le gâche.","Salez le foie seul et laissez-le dégorger 24 heures au froid, puis passez-le au tamis pour n'en garder que la crème.","Pelez les corps, taillez-les en lanières de 5 mm et salez-les séparément deux heures, puis épongez-les.","Mêlez foie et calmar avec le saké et le mirin, et laissez fermenter de trois à sept jours à 8 °C, en remuant chaque jour.","Le mélange doit sentir la mer et non l'ammoniac : à la moindre odeur piquante, il faut le jeter. Servez très froid, en très petite quantité."],
     en:["Gut the squid keeping the brown-orange liver sac intact: it drives the fermentation, and a burst sac ruins the dish.","Salt the liver alone and let it drain 24 hours in the cold, then sieve it to keep only the cream.","Skin the bodies, cut them into 5 mm strips and salt them separately for two hours, then blot them.","Mix liver and squid with the sake and mirin, and ferment three to seven days at 8°C, stirring daily.","The mixture must smell of the sea and not of ammonia: at the least sharp odour it must be thrown away. Serve very cold, in very small quantities."]} },

{ id:'tempura', c:'as', lat:35.671, lon:139.766, base:4, prep:40, cook:20, diff:3, tags:['sea','fry','festive'],
  art:{v:'plate',bg:'#33291f',plate:'#f4f0e6',style:'other',food:['#f2dfa8','#e8c46a','#f4f0e6','#7fae5a'],garnish:'#6fbf8f'},
  n:{fr:'Tempura',en:'Tempura'},
  p:{fr:'Tokyo, Japon',en:'Tokyo, Japan'},
  d:{fr:"Des crevettes et des légumes enrobés d'une pâte à peine mêlée et frits, à la croûte pâle et dentelée. Les Portugais l'apportèrent au XVIᵉ siècle avec leurs beignets des quatre-temps — tempora — mais les Japonais en ont fait le contraire d'une panure : la pâte doit être presque invisible.",
     en:"Prawns and vegetables in a barely mixed batter, fried to a pale, lacy crust. The Portuguese brought it in the 16th century with their ember-days fritters — tempora — but the Japanese made it the opposite of a coating: the batter must be nearly invisible."},
  i:[['shrimp',12,'pc'],['eggplant',1,'pc'],['sweet_potato',200,'g'],['shiitake_mushrooms',8,'pc'],['green_pepper',2,'pc'],['flour',200,'g'],['egg',1,'pc'],['ice',200,'g'],['sunflower_oil',1.5,'l'],['dashi_stock',300,'ml'],['soy_sauce',60,'ml'],['mirin',60,'ml'],['daikon',150,'g'],['salt',null,'']],
  s:{fr:["Entaillez le ventre des crevettes en trois endroits et étirez-les : sans cela, elles se recroquevillent en anneau dans l'huile.","Battez l'œuf dans l'eau glacée avec des glaçons, puis versez la farine d'un coup et mêlez à peine, en huit ou dix coups de baguettes.","La pâte doit rester grumeleuse et pleine de farine sèche : trop mélangée, elle développe du gluten et donne une croûte épaisse et molle.","Gardez le bol sur un lit de glace pendant toute la friture — une pâte qui se réchauffe perd sa légèreté en deux minutes.","Frites à 180 °C, deux ou trois pièces à la fois. Servez avec un bouillon de dashi et de soja et du daikon râpé."],
     en:["Score the belly of the prawns in three places and stretch them: without this they curl into rings in the oil.","Beat the egg into iced water with ice cubes, then tip in the flour all at once and mix barely, eight or ten strokes with chopsticks.","The batter must stay lumpy and full of dry flour: overmixed, it develops gluten and gives a thick, soft crust.","Keep the bowl on a bed of ice throughout the frying — a batter that warms loses its lightness within two minutes.","Fry at 180°C, two or three pieces at a time. Serve with a dashi and soy broth and grated daikon."]} },

{ id:'monjayaki', c:'as', lat:35.664, lon:139.783, base:2, prep:25, cook:15, diff:2, tags:['street','comfort','fast'],
  art:{v:'plate',bg:'#33291f',plate:'#f4ecd8',style:'flat',food:['#c9924a','#e0b45a','#7fae5a','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Monjayaki',en:'Monjayaki'},
  p:{fr:'Tsukishima, Tokyo, Japon',en:'Tsukishima, Tokyo, Japan'},
  d:{fr:"Une pâte très liquide cuite à la plaque jusqu'à devenir collante, raclée à petites spatules directement sur le fer. À la différence de l'okonomiyaki, elle ne prend jamais : elle reste semi-liquide et se mange par petites quantités, brûlante, à même la plaque.",
     en:"A very thin batter cooked on the griddle until sticky, scraped up with small spatulas straight off the iron. Unlike okonomiyaki it never sets: it stays semi-liquid and is eaten in small amounts, scalding, directly from the plate."},
  i:[['flour',60,'g'],['dashi_stock',400,'ml'],['green_cabbage',300,'g'],['worcestershire',2,'tbsp'],['shrimp',100,'g'],['spring_onion',3,'pc'],['bonito_flakes',10,'g'],['pickled_ginger',30,'g'],['mochi',60,'g'],['sunflower_oil',20,'ml'],['salt',null,'']],
  s:{fr:["Délayez la farine dans le dashi froid jusqu'à obtenir un liquide à peine plus épais que de l'eau : c'est là toute la différence avec l'okonomiyaki.","Filtrez-le : un seul grumeau reste dur au milieu d'une pâte qui, elle, ne prendra jamais.","Faites d'abord revenir le chou émincé et les garnitures sur la plaque huilée, puis rassemblez-les en couronne, avec un trou au centre.","Versez le liquide dans le trou et laissez-le bouillonner une minute avant de rompre la digue et de tout mêler.","Raclez et écrasez sans arrêt avec deux petites spatules pendant cinq minutes, jusqu'à ce que la pâte accroche. Mangez directement de la plaque, par petites raclées."],
     en:["Whisk the flour into cold dashi to a liquid barely thicker than water: that is the whole difference from okonomiyaki.","Strain it: a single lump stays hard in the middle of a batter that itself will never set.","First fry the shredded cabbage and the fillings on the oiled griddle, then gather them into a ring with a hole in the centre.","Pour the liquid into the hole and let it bubble for a minute before breaking the dam and mixing everything.","Scrape and press constantly with two small spatulas for five minutes, until the batter catches. Eat straight off the griddle, in small scrapes."]} },

{ id:'chanko-nabe', c:'as', lat:35.697, lon:139.793, base:6, prep:40, cook:45, diff:2, tags:['poultry','soup','comfort'],
  art:{v:'pot',bg:'#33291f',plate:'#f0e4c8',style:'soup',food:['#f4f0e6','#7fae5a','#e8dcb8','#c9924a'],garnish:'#7fae6a'},
  n:{fr:'Chanko nabe',en:'Chanko nabe'},
  p:{fr:'Ryōgoku, Tokyo, Japon',en:'Ryōgoku, Tokyo, Japan'},
  d:{fr:"La marmite des lutteurs de sumo, chargée de poulet, de boulettes, de tofu et de légumes. On y met du poulet et non du bœuf pour une raison superstitieuse : le poulet se tient sur deux pattes, comme un lutteur debout, alors qu'une bête à quatre pattes touche le sol des mains.",
     en:"The sumo wrestlers' pot, loaded with chicken, meatballs, tofu and vegetables. Chicken goes in rather than beef for a superstitious reason: a chicken stands on two legs, like a wrestler on his feet, whereas a four-legged animal touches the ground with its hands."},
  i:[['chicken',600,'g'],['ground_chicken',300,'g'],['tofu',300,'g'],['napa_cabbage',500,'g'],['shiitake_mushrooms',200,'g'],['daikon',300,'g'],['spring_onion',5,'pc'],['dashi_stock',1.5,'l'],['miso_paste',60,'g'],['sake',80,'ml'],['ginger',30,'g'],['soy_sauce',60,'ml'],['salt',null,'']],
  s:{fr:["Faites un bouillon de carcasse de poulet et de dashi, et écumez-le sans relâche pendant le premier quart d'heure.","Formez des boulettes de poulet haché avec le gingembre râpé et un peu de miso, et pochez-les d'abord : elles parfument tout le bouillon.","Rangez les ingrédients par secteurs et non mêlés : chacun cuit à son rythme et se prélève quand il est prêt.","Ajoutez le chou en dernier, en le tassant : il rend beaucoup d'eau et rallongerait le bouillon si on le mettait au début.","Mangez au fur et à mesure, en rajoutant des ingrédients dans le bouillon qui se concentre. Finissez par des nouilles udon dans ce qui reste."],
     en:["Make a broth from chicken carcass and dashi, and skim it relentlessly for the first fifteen minutes.","Shape minced chicken balls with grated ginger and a little miso, and poach them first: they scent the whole broth.","Arrange the ingredients in sectors rather than mixed: each cooks at its own pace and is lifted out when ready.","Add the cabbage last, packing it down: it releases a great deal of water and would thin the broth if added at the start.","Eat as you go, adding more ingredients to the broth as it concentrates. Finish with udon noodles in what remains."]} },

{ id:'miso-katsu', c:'as', lat:35.181, lon:136.907, base:4, prep:30, cook:25, diff:2, tags:['pork','fry','comfort'],
  art:{v:'plate',bg:'#33291f',plate:'#f4ecd8',style:'flat',food:['#6f4a2a','#c9924a','#f4f0e6','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Miso katsu',en:'Miso katsu'},
  p:{fr:'Nagoya, Chūbu, Japon',en:'Nagoya, Chūbu, Japan'},
  d:{fr:"Une côtelette de porc panée nappée d'une sauce épaisse au miso rouge de Nagoya. Le hatchō miso, fermenté deux ans en fût sous des pierres empilées, est presque noir et bien plus salé que le miso blanc : il ne s'emploie qu'en petite quantité, coupé de sucre et de dashi.",
     en:"A breaded pork cutlet under a thick sauce of Nagoya red miso. Hatchō miso, fermented two years in barrels under stacked stones, is almost black and far saltier than white miso: it is used sparingly, cut with sugar and dashi."},
  i:[['pork_loin',600,'g'],['flour',80,'g'],['egg',2,'pc'],['panko',200,'g'],['sunflower_oil',1,'l'],['miso_paste',80,'g'],['sugar',60,'g'],['mirin',60,'ml'],['dashi_stock',150,'ml'],['sake',30,'ml'],['green_cabbage',300,'g'],['sesame_seeds',1,'tbsp'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Entaillez le gras de la côtelette tous les deux centimètres pour qu'elle ne se recroqueville pas, et aplatissez-la légèrement.","Panez à la farine, à l'œuf puis au panko, en pressant à peine : le panko doit rester en flocons dressés, non écrasés.","Frites 6 minutes à 170 °C, feu doux et long — un porc pané à feu vif brunit avant que le centre soit cuit.","Faites la sauce en délayant le miso rouge dans le dashi chaud avec le sucre, le mirin et le saké, et laissez réduire 10 minutes.","Elle doit napper la cuillère et rester brillante : trop réduite, elle devient amère. Nappez au dernier moment, sur un katsu tranché."],
     en:["Score the fat of the cutlet every two centimetres so it does not curl, and flatten it slightly.","Coat in flour, egg then panko, pressing barely: the panko must stay in standing flakes, not crushed.","Fry 6 minutes at 170°C, low and long — breaded pork over fierce heat browns before the centre cooks.","Make the sauce by slaking red miso in hot dashi with the sugar, mirin and sake, and reduce for 10 minutes.","It must coat the spoon and stay glossy: over-reduced it turns bitter. Pour it at the last moment, over a sliced katsu."]} },

{ id:'hoto-nabe', c:'as', lat:35.664, lon:138.568, base:4, prep:60, cook:40, diff:2, tags:['noodles','soup','comfort'],
  art:{v:'pot',bg:'#33291f',plate:'#f0e4c8',style:'noodle',food:['#e8c46a','#f2dfa8','#7fae5a','#c9924a'],garnish:'#7fae6a'},
  n:{fr:'Hōtō',en:'Hōtō'},
  p:{fr:'Kōfu, Yamanashi, Japon',en:'Kōfu, Yamanashi, Japan'},
  d:{fr:"De larges nouilles plates mijotées directement dans une soupe de miso à la courge, sans être bouillies à part. C'est précisément ce qui la distingue de l'udon : l'amidon des nouilles épaissit le bouillon, et le plat serait manqué si on les rinçait avant.",
     en:"Wide flat noodles simmered directly in a miso and pumpkin soup, never boiled separately. That is exactly what sets it apart from udon: the noodle starch thickens the broth, and rinsing them first would ruin the dish."},
  i:[['flour',300,'g'],['water',140,'ml'],['pumpkin',400,'g'],['daikon',200,'g'],['carrot',1,'pc'],['shiitake_mushrooms',150,'g'],['taro_root',200,'g'],['miso_paste',80,'g'],['dashi_stock',1.5,'l'],['spring_onion',4,'pc'],['pork_belly',150,'g'],['salt',null,'']],
  s:{fr:["Pétrissez la farine et l'eau salée 10 minutes en une pâte ferme et laissez-la reposer 30 minutes sous un linge.","Abaissez-la à 3 mm et coupez des lanières larges d'un centimètre et demi : le hōtō est bien plus large et plus épais qu'un udon.","Ne les rincez surtout pas et ne les précuisez pas : c'est leur farine qui liera la soupe, et c'est toute la recette.","Faites cuire la courge, le daikon et le taro dans le dashi 20 minutes, jusqu'à ce que la courge commence à se défaire.","Jetez les nouilles crues dedans et laissez frémir 15 minutes, puis délayez le miso hors du feu. La soupe doit être épaisse et jaune."],
     en:["Knead the flour and salted water for 10 minutes into a firm dough and rest it 30 minutes under a cloth.","Roll it to 3 mm and cut strips a centimetre and a half wide: hōtō is far wider and thicker than udon.","On no account rinse them or precook them: their flour is what will thicken the soup, and that is the whole recipe.","Cook the pumpkin, daikon and taro in the dashi for 20 minutes, until the pumpkin begins to collapse.","Drop the raw noodles in and simmer 15 minutes, then slake the miso off the heat. The soup should be thick and yellow."]} },

{ id:'kishimen', c:'as', lat:35.170, lon:136.882, base:4, prep:70, cook:15, diff:2, tags:['noodles','fast','comfort'],
  art:{v:'bowl',bg:'#33291f',plate:'#f0e4c8',style:'noodle',food:['#f4f0e6','#8f6a4a','#7fae5a','#e8dcb8'],garnish:'#7fae6a'},
  n:{fr:'Kishimen',en:'Kishimen'},
  p:{fr:'Nagoya, Chūbu, Japon',en:'Nagoya, Chūbu, Japan'},
  d:{fr:"Des nouilles de blé plates comme des rubans, servies dans un bouillon clair de dashi. Elles sont si fines qu'elles cuisent en trois minutes contre douze pour un udon ; on les vend sur les quais de la gare de Nagoya, où elles se mangent debout entre deux trains.",
     en:"Wheat noodles as flat as ribbons, served in a clear dashi broth. They are so thin they cook in three minutes against twelve for udon; they are sold on the platforms of Nagoya station, eaten standing between two trains."},
  i:[['flour',300,'g'],['water',140,'ml'],['dashi_stock',1,'l'],['soy_sauce',60,'ml'],['mirin',40,'ml'],['spring_onion',4,'pc'],['bonito_flakes',15,'g'],['spinach',150,'g'],['abura_age',2,'pc'],['salt',null,'']],
  s:{fr:["Pétrissez une pâte ferme, puis piétinez-la enveloppée dans un sac, comme au Japon : le pied développe le gluten sans échauffer la pâte.","Laissez-la reposer 2 heures : sans repos, elle se rétracte et ne descend jamais à l'épaisseur voulue.","Abaissez à 1,5 mm — bien plus fin qu'un udon — et coupez des rubans de 8 mm de large.","Cuisez-les 3 minutes dans une grande eau bouillante et rincez-les à l'eau froide pour ôter l'amidon, puis réchauffez-les dans le bouillon.","Le bouillon de Nagoya est clair et se fait au soja léger : un bouillon foncé masquerait le goût de blé de la nouille, qui est tout le sujet."],
     en:["Knead a firm dough, then tread it wrapped in a bag, as in Japan: the foot develops the gluten without warming the dough.","Rest it 2 hours: without rest it shrinks back and never reaches the required thinness.","Roll to 1.5 mm — far thinner than udon — and cut 8 mm ribbons.","Cook them 3 minutes in plenty of boiling water and rinse cold to remove the starch, then reheat them in the broth.","Nagoya broth is clear and made with light soy: a dark broth would mask the wheat flavour of the noodle, which is the whole point."]} },

{ id:'kitsune-udon', c:'as', lat:34.694, lon:135.502, base:4, prep:40, cook:20, diff:2, tags:['noodles','comfort','fast'],
  art:{v:'bowl',bg:'#33291f',plate:'#f0e4c8',style:'noodle',food:['#f4f0e6','#c9924a','#7fae5a','#e8dcb8'],garnish:'#7fae6a'},
  n:{fr:'Kitsune udon',en:'Kitsune udon'},
  p:{fr:'Osaka, Kansai, Japon',en:'Osaka, Kansai, Japan'},
  d:{fr:"Des udon dans un bouillon clair, couronnés d'une feuille de tofu frit mijotée dans un sirop de soja. Le nom veut dire renard : la légende dit qu'Inari, divinité des moissons, se déplace avec des renards, et que ceux-ci raffolent du tofu frit qu'on lui offre aux sanctuaires.",
     en:"Udon in a clear broth, crowned with a sheet of fried tofu simmered in soy syrup. The name means fox: legend has Inari, the harvest deity, travelling with foxes, and foxes are said to love the fried tofu left at her shrines."},
  i:[['udon_noodles',400,'g'],['abura_age',4,'pc'],['dashi_stock',1.2,'l'],['soy_sauce',80,'ml'],['mirin',60,'ml'],['sugar',3,'tbsp'],['spring_onion',4,'pc'],['kombu',15,'g'],['bonito_flakes',20,'g'],['shichimi',1,'tsp'],['salt',null,'']],
  s:{fr:["Ébouillantez les feuilles de tofu frit trente secondes et pressez-les entre deux assiettes : ce dégraissage est indispensable, sinon le bouillon devient huileux.","Faites-les mijoter 15 minutes dans un sirop de dashi, de soja, de mirin et de sucre, jusqu'à ce qu'elles l'aient entièrement bu.","Laissez-les refroidir dans leur sirop : elles absorbent encore en refroidissant, et c'est là qu'elles prennent leur goût sucré-salé.","Faites un dashi de kombu et de bonite, et assaisonnez-le au soja clair du Kansai — le bouillon d'Osaka est presque transparent, contrairement à celui de Tokyo.","Cuisez les udon, rincez-les, réchauffez-les dans le bouillon et posez la feuille de tofu dessus, entière et non coupée."],
     en:["Blanch the fried tofu sheets for thirty seconds and press them between two plates: this degreasing is essential, or the broth turns oily.","Simmer them 15 minutes in a syrup of dashi, soy, mirin and sugar, until they have drunk it entirely.","Let them cool in that syrup: they keep absorbing as they cool, and that is when they take their sweet-salt flavour.","Make a kombu and bonito dashi, and season it with light Kansai soy — Osaka broth is nearly transparent, unlike Tokyo's.","Cook the udon, rinse them, reheat them in the broth and lay the tofu sheet on top, whole and uncut."]} },

{ id:'yudofu', c:'as', lat:35.012, lon:135.678, base:4, prep:20, cook:15, diff:1, tags:['veg','comfort','fresh'],
  art:{v:'pot',bg:'#2c3440',plate:'#f4f0e6',style:'other',food:['#f4f0e6','#f0e8d0','#7fae5a','#e8dcb8'],garnish:'#6fbf8f'},
  n:{fr:'Yudōfu',en:'Yudōfu'},
  p:{fr:'Nanzen-ji, Kyoto, Kansai, Japon',en:'Nanzen-ji, Kyoto, Kansai, Japan'},
  d:{fr:"Du tofu chauffé dans une eau de kombu à peine frémissante, trempé dans une sauce au soja. C'est la cuisine des temples zen de Kyoto : rien n'est ajouté au tofu, et l'exercice consiste précisément à ne rien faire — le chauffer trop le rend spongieux et criblé de trous.",
     en:"Tofu warmed in barely trembling kombu water and dipped in a soy sauce. It is the cooking of Kyoto's Zen temples: nothing is added to the tofu, and the exercise is precisely to do nothing — overheated, it turns spongy and riddled with holes."},
  i:[['tofu',600,'g'],['kombu',20,'g'],['water',1.5,'l'],['soy_sauce',80,'ml'],['mirin',40,'ml'],['bonito_flakes',15,'g'],['spring_onion',4,'pc'],['ginger',20,'g'],['daikon',150,'g'],['shichimi',1,'tsp']],
  s:{fr:["Employez un tofu de Kyoto, ferme mais soyeux, fait à l'eau de source : c'est le seul ingrédient du plat et rien ne masquera sa qualité.","Faites tremper le kombu une heure à l'eau froide dans le poêlon de terre, et ne le retirez pas — ici il reste au fond pendant tout le repas.","Coupez le tofu en cubes de 5 cm et posez-les délicatement dans l'eau froide, avant de chauffer.","Montez très lentement jusqu'à 70 °C et maintenez : l'eau ne doit jamais frémir, seulement fumer. À ébullition, le tofu se troue et durcit.","Prélevez les cubes à l'écumoire dès qu'ils remontent, et trempez-les dans une sauce de soja, mirin et bonite, avec du gingembre râpé."],
     en:["Use a Kyoto tofu, firm but silky, made with spring water: it is the only ingredient in the dish and nothing will hide its quality.","Soak the kombu an hour in cold water in the earthenware pot, and do not remove it — here it stays in the bottom throughout the meal.","Cut the tofu into 5 cm cubes and lower them gently into the cold water, before heating.","Bring it very slowly to 70°C and hold: the water must never tremble, only steam. At a boil, tofu holes and toughens.","Lift the cubes out with a skimmer as they rise, and dip them in a sauce of soy, mirin and bonito, with grated ginger."]} },

{ id:'kaiseki-ryori', c:'as', lat:35.004, lon:135.768, base:4, prep:240, cook:60, diff:3, tags:['fresh','festive','sunday'],
  art:{v:'board',bg:'#2c3440',plate:'#f4f0e6',style:'other',food:['#7fae5a','#f4f0e6','#e07a6a','#e8c46a'],garnish:'#6fbf8f'},
  n:{fr:'Kaiseki ryōri',en:'Kaiseki ryōri'},
  p:{fr:'Kyoto, Kansai, Japon',en:'Kyoto, Kansai, Japan'},
  d:{fr:"Un repas en une dizaine de services suivant un ordre fixe de techniques : cru, grillé, mijoté, vapeur, frit. Il descend du repas léger servi avant la cérémonie du thé ; sa règle première est saisonnière — un ingrédient hors de sa quinzaine ne peut pas y figurer.",
     en:"A meal of some ten courses following a fixed order of techniques: raw, grilled, simmered, steamed, fried. It descends from the light meal served before the tea ceremony; its first rule is seasonal — an ingredient outside its fortnight cannot appear."},
  i:[['sea_bream',300,'g'],['tofu',200,'g'],['dashi_stock',1,'l'],['bamboo_shoots',200,'g'],['shiitake_mushrooms',150,'g'],['sushi_rice',300,'g'],['miso_paste',60,'g'],['sake',80,'ml'],['mirin',60,'ml'],['soy_sauce',60,'ml'],['yuzu',2,'pc'],['shiso',8,'pc'],['sesame_seeds',2,'tbsp'],['salt',null,'']],
  s:{fr:["Choisissez chaque ingrédient dans sa quinzaine de perfection : le kaiseki ne connaît pas de recette fixe, seulement un calendrier.","Préparez un dashi de première extraction — kombu retiré à 60 °C, bonite infusée trente secondes — et n'en faites jamais bouillir une goutte.","Servez dans l'ordre des techniques : sakizuke cru, wanmono en bouillon clair, yakimono grillé, takiawase mijoté, agemono frit.","Chaque service tient en trois ou quatre bouchées et se présente dans une pièce différente, choisie pour la saison et la couleur de l'aliment.","Terminez par le riz, la soupe de miso et les pickles servis ensemble : c'est le signal de la fin, et rien ne se sert après."],
     en:["Choose every ingredient within its fortnight of perfection: kaiseki has no fixed recipe, only a calendar.","Make a first-extraction dashi — kombu lifted out at 60°C, bonito infused thirty seconds — and never let a drop of it boil.","Serve in the order of techniques: raw sakizuke, wanmono in clear broth, grilled yakimono, simmered takiawase, fried agemono.","Each course is three or four mouthfuls and comes in a different vessel, chosen for the season and the colour of the food.","Finish with rice, miso soup and pickles served together: that is the signal of the end, and nothing follows."]} },

{ id:'hiroshima-tsukemen', c:'as', lat:34.385, lon:132.455, base:4, prep:40, cook:20, diff:2, tags:['noodles','spicy','fast'],
  art:{v:'bowl',bg:'#33251c',plate:'#f0e4c8',style:'noodle',food:['#c9402c','#f4f0e6','#7fae5a','#e8dcb8'],garnish:'#6fbf8f'},
  n:{fr:'Tsukemen de Hiroshima',en:'Hiroshima tsukemen'},
  p:{fr:'Hiroshima, Chūgoku, Japon',en:'Hiroshima, Chūgoku, Japan'},
  d:{fr:"Des nouilles froides trempées dans une sauce pimentée, avec du chou et du concombre crus. Contrairement au tsukemen de Tokyo, servi avec un bouillon brûlant, celui de Hiroshima se mange entièrement froid : la sauce est acide, très pimentée, et se commande par niveaux de force.",
     en:"Cold noodles dipped in a chilli sauce, with raw cabbage and cucumber. Unlike Tokyo tsukemen, served with a scalding broth, the Hiroshima version is eaten entirely cold: the sauce is sour, fiercely hot, and ordered by strength level."},
  i:[['ramen_noodles',400,'g'],['soy_sauce',100,'ml'],['rice_vinegar',60,'ml'],['sesame_oil',30,'ml'],['chili_oil',40,'ml'],['gochugaru',2,'tbsp'],['garlic',3,'clove'],['sugar',2,'tbsp'],['green_cabbage',300,'g'],['cucumber',1,'pc'],['spring_onion',4,'pc'],['sesame_seeds',2,'tbsp'],['egg',4,'pc'],['salt',null,'']],
  s:{fr:["Préparez la sauce la veille : soja, vinaigre, sucre, ail râpé, huile de sésame et piment coréen, laissés reposer une nuit au froid.","Le piment doit infuser et non être ajouté au dernier moment : une sauce faite le jour même est agressive et déséquilibrée.","Cuisez les nouilles, rincez-les longuement à l'eau glacée et égouttez-les à fond — l'eau résiduelle diluerait la sauce.","Émincez le chou et le concombre très finement et laissez-les dix minutes dans l'eau glacée pour qu'ils croquent.","Servez les nouilles, les légumes et la sauce dans trois récipients séparés. On trempe bouchée par bouchée, et la sauce ne se verse jamais sur les nouilles."],
     en:["Make the sauce the day before: soy, vinegar, sugar, grated garlic, sesame oil and Korean chilli, rested overnight in the cold.","The chilli must infuse rather than be added at the last moment: a same-day sauce is aggressive and unbalanced.","Cook the noodles, rinse them at length in iced water and drain thoroughly — residual water would thin the sauce.","Shred the cabbage and cucumber very finely and leave them ten minutes in iced water so they snap.","Serve noodles, vegetables and sauce in three separate vessels. You dip mouthful by mouthful, and the sauce is never poured over the noodles."]} },

{ id:'kaki-no-dotenabe', c:'as', lat:34.397, lon:132.459, base:4, prep:40, cook:25, diff:2, tags:['sea','soup','comfort'],
  art:{v:'pot',bg:'#26485c',plate:'#f0e4c8',style:'soup',food:['#e8dcc0','#8f6a4a','#7fae5a','#f4f0e6'],garnish:'#6fbf8f'},
  n:{fr:'Dote-nabe aux huîtres',en:'Oyster dote-nabe'},
  p:{fr:'Hiroshima, Chūgoku, Japon',en:'Hiroshima, Chūgoku, Japan'},
  d:{fr:"Des huîtres mijotées dans une marmite dont on a tapissé le bord d'un bourrelet de miso. Dote veut dire digue : le miso est étalé en muraille sur la paroi intérieure, et l'on en fait tomber peu à peu dans le bouillon pour régler l'assaisonnement en cours de repas.",
     en:"Oysters simmered in a pot whose rim has been lined with a wall of miso. Dote means dyke: the miso is smeared as a bank around the inner wall, and pushed into the broth little by little to adjust the seasoning as the meal goes on."},
  i:[['oysters',600,'g'],['miso_paste',120,'g'],['tofu',200,'g'],['napa_cabbage',400,'g'],['spring_onion',5,'pc'],['shiitake_mushrooms',150,'g'],['dashi_stock',800,'ml'],['mirin',60,'ml'],['sake',60,'ml'],['sugar',2,'tbsp'],['ginger',20,'g'],['salt',null,'']],
  s:{fr:["Lavez les huîtres décoquillées dans une eau salée additionnée de fécule, qui capte le sable sans les abîmer, puis rincez et épongez.","Mêlez le miso au sucre, au mirin et au saké pour obtenir une pâte souple, et étalez-la en bourrelet sur la paroi intérieure de la marmite, au-dessus du niveau du liquide.","Versez le dashi et rangez les légumes, sans que le liquide n'atteigne le miso.","Portez à frémissement et faites tomber une petite quantité de miso dans le bouillon avec les baguettes : on assaisonne progressivement, à la demande.","Ajoutez les huîtres en dernier et comptez trois minutes : au-delà, elles se rétractent et durcissent irrémédiablement."],
     en:["Wash the shucked oysters in salted water with a little starch, which traps the grit without damaging them, then rinse and blot.","Mix the miso with the sugar, mirin and sake to a supple paste, and smear it as a bank around the inner wall of the pot, above the liquid line.","Pour in the dashi and arrange the vegetables, without the liquid reaching the miso.","Bring to a tremble and push a little miso into the broth with chopsticks: the seasoning is adjusted gradually, on demand.","Add the oysters last and count three minutes: beyond that they shrink and toughen beyond recovery."]} },

{ id:'miyajima-manju', c:'as', lat:34.296, lon:132.320, base:12, prep:60, cook:20, diff:2, tags:['sweet','street','bake'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'cake',food:['#e0b45a','#4f3a2a','#f2dfa8','#f0e8d0'],garnish:'#c9754a'},
  n:{fr:'Momiji manjū',en:'Momiji manjū'},
  p:{fr:'Miyajima, Chūgoku, Japon',en:'Miyajima, Chūgoku, Japan'},
  d:{fr:"De petits gâteaux en forme de feuille d'érable, fourrés de pâte de haricot rouge. Ils furent créés vers 1906 pour les pèlerins du sanctuaire d'Itsukushima ; la forme rappelle les érables de la vallée de Momijidani, et l'île en vend plusieurs millions par an.",
     en:"Small maple-leaf-shaped cakes filled with red bean paste. They were created around 1906 for pilgrims to the Itsukushima shrine; the shape recalls the maples of the Momijidani valley, and the island sells several million a year."},
  i:[['flour',250,'g'],['egg',3,'pc'],['sugar',150,'g'],['honey',60,'g'],['baking_powder',1,'tsp'],['whole_milk',80,'ml'],['red_bean_paste',300,'g'],['butter',30,'g'],['salt',null,'']],
  s:{fr:["Fouettez les œufs et le sucre 8 minutes jusqu'au ruban, puis ajoutez le miel tiède, le lait et la farine tamisée avec la levure.","Laissez reposer la pâte 1 heure au froid : elle doit s'assouplir, et une pâte reposée coule mieux dans les alvéoles du moule.","Chauffez le moule à feu doux et beurrez-le au pinceau à chaque fournée, sans exception.","Emplissez chaque alvéole à moitié, posez une boule de pâte de haricot au centre et recouvrez du reste de pâte.","Fermez le moule et cuisez 3 minutes par face, en le retournant une fois. Les gâteaux doivent rester pâles et moelleux, jamais dorés comme un biscuit."],
     en:["Whisk the eggs and sugar for 8 minutes to the ribbon, then add the warm honey, milk and flour sifted with the baking powder.","Rest the batter an hour in the cold: it must relax, and a rested batter flows better into the mould's cavities.","Heat the mould over low heat and brush it with butter for every batch, without exception.","Fill each cavity halfway, set a ball of bean paste in the centre and cover with the remaining batter.","Close the mould and cook 3 minutes a side, turning once. The cakes must stay pale and soft, never browned like a biscuit."]} },

{ id:'sanuki-udon', c:'as', lat:34.343, lon:134.047, base:4, prep:180, cook:15, diff:3, tags:['noodles','fast','comfort'],
  art:{v:'bowl',bg:'#33291f',plate:'#f0e4c8',style:'noodle',food:['#f4f0e6','#e8dcb8','#7fae5a','#c9924a'],garnish:'#7fae6a'},
  n:{fr:'Sanuki udon',en:'Sanuki udon'},
  p:{fr:'Takamatsu, Kagawa, Shikoku, Japon',en:'Takamatsu, Kagawa, Shikoku, Japan'},
  d:{fr:"Des udon épais et carrés, célèbres pour leur mâche élastique, servis avec très peu d'assaisonnement. Kagawa en consomme trois fois plus que la moyenne japonaise et compte huit cents boutiques pour un million d'habitants ; la pâte s'y pétrit au pied, enveloppée dans un sac.",
     en:"Thick, square-sectioned udon famous for their elastic chew, served with very little dressing. Kagawa eats three times the Japanese average and has eight hundred shops for a million people; the dough there is kneaded underfoot, wrapped in a bag."},
  i:[['flour',500,'g'],['water',230,'ml'],['coarse_salt',25,'g'],['dashi_stock',800,'ml'],['soy_sauce',60,'ml'],['mirin',40,'ml'],['spring_onion',4,'pc'],['ginger',20,'g'],['egg',4,'pc'],['bonito_flakes',15,'g']],
  s:{fr:["Dissolvez le sel dans l'eau avant de l'ajouter : la proportion de sel varie selon la saison, plus forte l'hiver, et c'est elle qui règle l'élasticité.","Pétrissez, puis enveloppez la pâte dans un sac et piétinez-la vingt minutes en la repliant : le pied développe le gluten sans échauffer la pâte comme le ferait la main.","Laissez reposer 3 heures à couvert, puis piétinez de nouveau brièvement avant d'abaisser.","Abaissez à 3 mm et coupez des nouilles de 3 mm de large : la section doit être carrée, c'est la signature du sanuki.","Cuisez 12 minutes dans une très grande eau non salée, rincez à l'eau froide en frottant, et servez avec un simple dashi, un œuf cru ou du gingembre râpé."],
     en:["Dissolve the salt in the water before adding it: the proportion varies with the season, higher in winter, and it governs the elasticity.","Knead, then wrap the dough in a bag and tread it for twenty minutes, folding as you go: the foot develops gluten without warming the dough as a hand would.","Rest 3 hours covered, then tread it again briefly before rolling.","Roll to 3 mm and cut noodles 3 mm wide: the section must be square, the sanuki signature.","Cook 12 minutes in a great deal of unsalted water, rinse cold while rubbing, and serve with a plain dashi, a raw egg or grated ginger."]} },

{ id:'katsuo-no-tataki', c:'as', lat:33.560, lon:133.531, base:4, prep:30, cook:10, diff:3, tags:['sea','grill','fresh'],
  art:{v:'board',bg:'#26485c',plate:'#f4f0e6',style:'fish',food:['#8f2a2a','#3a3a2a','#7fae5a','#f4f0e6'],garnish:'#6fbf8f'},
  n:{fr:'Katsuo no tataki',en:'Katsuo no tataki'},
  p:{fr:'Kōchi, Shikoku, Japon',en:'Kōchi, Shikoku, Japan'},
  d:{fr:"Une longe de bonite saisie quelques secondes sur une flamme de paille de riz, crue au centre, tranchée épaisse. La paille brûle très vite et très chaud : elle saisit la surface sans cuire la chair, et laisse un goût de fumée que le charbon ne donne pas.",
     en:"A loin of bonito seared for seconds over a rice-straw flame, raw at the centre, cut in thick slices. Straw burns very fast and very hot: it seizes the surface without cooking the flesh, and leaves a smokiness charcoal does not give."},
  i:[['bonito',600,'g'],['coarse_salt',2,'tbsp'],['garlic',4,'clove'],['ginger',30,'g'],['spring_onion',6,'pc'],['shiso',10,'pc'],['ponzu',80,'ml'],['soy_sauce',40,'ml'],['yuzu',2,'pc'],['myoga',3,'pc']],
  s:{fr:["Levez les filets et gardez la peau : c'est elle qui prend la flamme et protège la chair pendant l'opération.","Salez généreusement la surface et laissez dix minutes — le sel forme une croûte qui aide à la saisie.","Embrochez la longe sur des baguettes en éventail et passez-la à la flamme de paille, dix secondes par face, en tournant sans arrêt.","Plongez-la immédiatement dans l'eau glacée pour stopper net la cuisson, puis épongez-la à fond : sans ce choc, la chaleur continue vers le centre.","Tranchez épais, à un centimètre, et servez avec beaucoup d'ail cru en lamelles, du gingembre, de l'oignon vert et du ponzu."],
     en:["Fillet the fish keeping the skin: it takes the flame and shields the flesh during the operation.","Salt the surface generously and leave it ten minutes — the salt forms a crust that helps the searing.","Skewer the loin on a fan of chopsticks and pass it through the straw flame, ten seconds a side, turning constantly.","Plunge it immediately into iced water to stop the cooking dead, then blot it thoroughly: without that shock the heat travels on toward the centre.","Cut thick slices, a centimetre, and serve with plenty of raw sliced garlic, ginger, spring onion and ponzu."]} },

{ id:'tokushima-ramen', c:'as', lat:34.070, lon:134.555, base:4, prep:60, cook:180, diff:3, tags:['noodles','pork','comfort'],
  art:{v:'bowl',bg:'#33291f',plate:'#f0e4c8',style:'noodle',food:['#6f4a2a','#e8c46a','#f4f0e6','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Ramen de Tokushima',en:'Tokushima ramen'},
  p:{fr:'Tokushima, Shikoku, Japon',en:'Tokushima, Shikoku, Japan'},
  d:{fr:"Un ramen au bouillon de porc foncé et sucré, couronné de poitrine mijotée et d'un œuf cru cassé dessus. L'œuf n'est pas mollet mais entièrement cru : on le crève et on le mêle au bouillon brûlant, ce qui l'épaissit et adoucit le soja, très présent ici.",
     en:"A ramen in a dark, sweet pork broth, crowned with simmered belly and a raw egg cracked on top. The egg is not soft-boiled but entirely raw: it is broken and stirred into the scalding broth, which thickens it and softens the soy, very forward here."},
  i:[['pork_bones',1,'kg'],['pork_belly',500,'g'],['ramen_noodles',400,'g'],['soy_sauce',150,'ml'],['sugar',60,'g'],['mirin',60,'ml'],['sake',60,'ml'],['egg',4,'pc'],['bean_sprouts',200,'g'],['spring_onion',4,'pc'],['ginger',30,'g'],['garlic',6,'clove'],['salt',null,'']],
  s:{fr:["Blanchissez les os de porc cinq minutes, jetez l'eau et rincez-les : c'est ce qui donne un bouillon net plutôt que gris et écumeux.","Remettez-les à l'eau froide avec l'ail et le gingembre, et laissez frémir 3 heures sans jamais bouillir fort.","Faites mijoter la poitrine à part dans un sirop de soja, de sucre, de mirin et de saké pendant 90 minutes, puis taillez-la en lanières.","Assaisonnez le bouillon avec ce sirop de cuisson : c'est lui qui donne au ramen de Tokushima sa couleur brune et son goût sucré.","Dressez les nouilles, la poitrine et les germes de soja, et cassez un œuf cru au centre. Il se mêle au bouillon dès la première bouchée."],
     en:["Blanch the pork bones five minutes, throw the water away and rinse them: that is what gives a clean broth rather than a grey, scummy one.","Return them to cold water with the garlic and ginger, and simmer 3 hours without ever boiling hard.","Simmer the belly separately in a syrup of soy, sugar, mirin and sake for 90 minutes, then cut it into strips.","Season the broth with that cooking syrup: it gives Tokushima ramen its brown colour and its sweetness.","Assemble the noodles, belly and bean sprouts, and crack a raw egg in the centre. It blends into the broth from the first mouthful."]} },

{ id:'mentaiko', c:'as', lat:33.590, lon:130.402, base:8, prep:60, cook:0, diff:3, tags:['sea','spicy','slow'],
  art:{v:'bowl',bg:'#33251c',plate:'#f4f0e6',style:'other',food:['#c9402c','#e07a6a','#f4f0e6','#7fae5a'],garnish:'#6fbf8f'},
  n:{fr:'Mentaiko',en:'Mentaiko'},
  p:{fr:'Fukuoka, Kyūshū, Japon',en:'Fukuoka, Kyūshū, Japan'},
  d:{fr:"Des poches d'œufs de colin salées puis marinées au piment, mangées avec du riz ou mêlées à des pâtes. Un Japonais rapatrié de Corée les mit au point à Fukuoka en 1949 en adaptant le myeongnan-jeot coréen au goût local, moins salé et moins violemment pimenté.",
     en:"Pollock roe sacs salted then marinated in chilli, eaten with rice or tossed through pasta. A Japanese repatriate from Korea developed them in Fukuoka in 1949, adapting Korean myeongnan-jeot to local taste, less salty and less fiercely hot."},
  i:[['pollock_roe',500,'g'],['coarse_salt',50,'g'],['sake',100,'ml'],['mirin',60,'ml'],['gochugaru',40,'g'],['kombu',10,'g'],['garlic',2,'clove'],['sushi_rice',400,'g'],['nori',2,'sheet']],
  s:{fr:["Choisissez des poches intactes et fermes : une membrane percée laisse échapper les œufs pendant le salage et tout le lot est perdu.","Salez-les à sec entre deux couches de sel et laissez 12 heures au froid, en inclinant le plat pour que la saumure s'écoule.","Rincez au saké et laissez-les tremper deux heures dedans : l'alcool ôte l'amertume et raffermit la membrane.","Préparez la marinade avec le mirin, le piment coréen, le kombu et l'ail, et laissez-la reposer une nuit avant d'y coucher les poches.","Laissez mariner cinq jours au réfrigérateur en retournant chaque jour. Tranchez et servez sur du riz chaud, ou mêlez au beurre pour des pâtes."],
     en:["Choose intact, firm sacs: a pierced membrane lets the eggs escape during salting and the whole batch is lost.","Dry-salt them between two layers of salt and leave 12 hours in the cold, tilting the dish so the brine runs off.","Rinse with sake and let them soak in it for two hours: the alcohol removes bitterness and firms the membrane.","Make the marinade with mirin, Korean chilli, kombu and garlic, and rest it overnight before laying the sacs in.","Marinate five days in the fridge, turning daily. Slice and serve on hot rice, or mix with butter for pasta."]} },

{ id:'champon', c:'as', lat:32.750, lon:129.878, base:4, prep:40, cook:25, diff:2, tags:['noodles','sea','comfort'],
  art:{v:'bowl',bg:'#33291f',plate:'#f0e4c8',style:'noodle',food:['#f4f0e6','#e07a6a','#7fae5a','#e8c46a'],garnish:'#6fbf8f'},
  n:{fr:'Champon',en:'Champon'},
  p:{fr:'Nagasaki, Kyūshū, Japon',en:'Nagasaki, Kyūshū, Japan'},
  d:{fr:"Des nouilles dans un bouillon blanc de porc et de fruits de mer, avec une montagne de légumes sautés. Chen Ping-shun, restaurateur chinois de Nagasaki, l'inventa vers 1899 pour nourrir à bas prix les étudiants chinois : les nouilles cuisent dans le bouillon même, ce qui le rend laiteux.",
     en:"Noodles in a white pork and seafood broth, under a mountain of stir-fried vegetables. Chen Ping-shun, a Chinese restaurateur in Nagasaki, invented it around 1899 to feed Chinese students cheaply: the noodles cook in the broth itself, which turns it milky."},
  i:[['ramen_noodles',400,'g'],['pork_belly',200,'g'],['shrimp',150,'g'],['squid',150,'g'],['green_cabbage',300,'g'],['bean_sprouts',150,'g'],['carrot',1,'pc'],['kamaboko',100,'g'],['pork_bones',800,'g'],['chicken',300,'g'],['sesame_oil',20,'ml'],['whole_milk',100,'ml'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Faites bouillir os de porc et poulet à gros bouillons pendant 3 heures — contrairement aux autres bouillons japonais, celui-ci doit bouillir fort pour émulsionner le gras et blanchir.","Faites sauter les viandes, les fruits de mer et les légumes à feu très vif dans l'huile de sésame, dans cet ordre, en trois minutes.","Versez le bouillon brûlant sur les légumes dans le wok et portez à ébullition.","Jetez les nouilles crues directement dedans : leur amidon achève d'épaissir et de blanchir le bouillon, et c'est là toute la différence avec le ramen.","Comptez trois minutes, rectifiez au sel et servez aussitôt, légumes au-dessus. Un champon qui attend voit ses nouilles boire tout le bouillon."],
     en:["Boil the pork bones and chicken hard for 3 hours — unlike other Japanese broths this one must boil vigorously to emulsify the fat and turn white.","Stir-fry the meats, seafood and vegetables over fierce heat in sesame oil, in that order, within three minutes.","Pour the scalding broth over the vegetables in the wok and bring it to the boil.","Tip the raw noodles straight in: their starch finishes thickening and whitening the broth, and that is the whole difference from ramen.","Give it three minutes, adjust the salt and serve at once, vegetables on top. A champon that waits has its noodles drink the broth."]} },

{ id:'castella', c:'as', lat:32.744, lon:129.873, base:10, prep:50, cook:50, diff:3, tags:['sweet','bake','comfort'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'cake',food:['#e8c46a','#f2dfa8','#8f6a4a','#f0e8d0'],garnish:'#c9754a'},
  n:{fr:'Castella',en:'Castella'},
  p:{fr:'Nagasaki, Kyūshū, Japon',en:'Nagasaki, Kyūshū, Japan'},
  d:{fr:"Un gâteau de miel dense et humide, sans matière grasse, cuit dans un cadre de bois. Les marchands portugais l'apportèrent à Nagasaki au XVIᵉ siècle sous le nom de pão de Castela ; il ne contient ni beurre ni levure, et toute sa légèreté vient du battage des œufs.",
     en:"A dense, moist honey cake with no fat, baked in a wooden frame. Portuguese traders brought it to Nagasaki in the 16th century as pão de Castela; it holds neither butter nor leaven, and all its lightness comes from beating the eggs."},
  i:[['egg',6,'pc'],['sugar',200,'g'],['bread_flour',180,'g'],['honey',60,'g'],['mirin',20,'ml'],['whole_milk',30,'ml'],['salt',null,'']],
  s:{fr:["Employez une farine à forte teneur en gluten et tamisez-la trois fois : sans matière grasse, la structure ne tient que par le gluten et l'air.","Fouettez les œufs entiers et le sucre au bain-marie tiède 12 minutes, jusqu'à ce que le mélange forme un ruban qui met cinq secondes à s'effacer.","Ajoutez le miel délayé dans le lait tiède, puis la farine en trois fois, en mêlant à la spatule sans casser la mousse.","Versez dans un cadre chemisé de papier, tapez le moule pour faire remonter les grosses bulles, et raclez la surface à la baguette pour les crever.","Cuisez 50 minutes à 160 °C, démoulez tiède et enveloppez immédiatement de film : c'est ce repos d'une nuit dans son humidité qui donne la texture du castella."],
     en:["Use a high-gluten flour and sift it three times: with no fat, the structure holds only by gluten and air.","Whisk whole eggs and sugar over a warm bain-marie for 12 minutes, until the mixture ribbons and takes five seconds to settle.","Add the honey slaked in warm milk, then the flour in three additions, folding with a spatula without breaking the foam.","Pour into a paper-lined frame, rap the tin to bring the large bubbles up, and drag a chopstick across the surface to burst them.","Bake 50 minutes at 160°C, turn out warm and wrap in film at once: that overnight rest in its own moisture gives castella its texture."]} },

{ id:'rafute', c:'as', lat:26.212, lon:127.679, base:6, prep:40, cook:180, diff:2, tags:['pork','slow','comfort'],
  art:{v:'plate',bg:'#33291f',plate:'#f0e4c8',style:'stew',food:['#6f4a2a','#c9924a','#f4f0e6','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Rafute',en:'Rafute'},
  p:{fr:'Naha, Okinawa, Japon',en:'Naha, Okinawa, Japan'},
  d:{fr:"De la poitrine de porc mijotée trois heures dans l'awamori, le sucre noir et le soja, jusqu'à fondre. C'était un plat de la cour du royaume de Ryūkyū ; Okinawa mange le porc entier, du groin aux pieds, et dit qu'on n'en jette que le cri.",
     en:"Pork belly simmered three hours in awamori, black sugar and soy, until it melts. It was a dish of the Ryūkyū royal court; Okinawa eats the whole pig, from snout to trotters, and says only the squeal is wasted."},
  i:[['pork_belly',1,'kg'],['awamori',200,'ml'],['soy_sauce',100,'ml'],['brown_sugar',80,'g'],['ginger',40,'g'],['dashi_stock',600,'ml'],['spring_onion',4,'pc'],['mustard',1,'tbsp'],['long_grain_rice',300,'g'],['salt',null,'']],
  s:{fr:["Pochez la poitrine entière 1 heure à l'eau avec le gingembre, puis jetez cette eau : elle emporte l'essentiel du gras et l'odeur forte.","Laissez refroidir la viande avant de la tailler en cubes de 5 cm : chaude, elle s'effondre sous le couteau.","Faites-la mijoter dans l'awamori et le dashi 1 heure, sans soja ni sucre — le sel ajouté trop tôt raffermit les fibres et empêche l'attendrissement.","Ajoutez alors le sucre noir, puis vingt minutes plus tard le soja : le sucre pénètre avant le sel, c'est l'ordre japonais et il n'est pas arbitraire.","Laissez réduire 1 heure de plus à découvert, en arrosant, jusqu'à ce que la sauce nappe et brille. Servez avec du riz et une pointe de moutarde."],
     en:["Poach the whole belly 1 hour in water with the ginger, then throw that water away: it carries off most of the fat and the strong smell.","Let the meat cool before cutting it into 5 cm cubes: hot, it collapses under the knife.","Simmer it in awamori and dashi for 1 hour, with no soy or sugar — salt added too early firms the fibres and blocks the tenderising.","Then add the black sugar, and twenty minutes later the soy: sugar penetrates before salt, the Japanese order, and it is not arbitrary.","Reduce for another hour uncovered, basting, until the sauce coats and shines. Serve with rice and a touch of mustard."]} },

{ id:'sata-andagi', c:'as', lat:26.206, lon:127.687, base:12, prep:40, cook:25, diff:2, tags:['sweet','fry','festive'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'roll',food:['#c9924a','#e0b45a','#f2dfa8','#f0e8d0'],garnish:'#c9754a'},
  n:{fr:'Sātā andagī',en:'Sātā andagī'},
  p:{fr:'Naha, Okinawa, Japon',en:'Naha, Okinawa, Japan'},
  d:{fr:"Des beignets d'Okinawa qui se fendent en trois à la cuisson, comme une fleur qui s'ouvre. Le nom veut dire sucre frit en okinawaïen ; la fente est le signe d'une bonne cuisson, et une boule restée lisse signifie que l'huile était trop chaude.",
     en:"Okinawan doughnuts that split into three as they fry, like a flower opening. The name means fried sugar in Okinawan; the split is the sign of good frying, and a ball left smooth means the oil was too hot."},
  i:[['flour',300,'g'],['sugar',150,'g'],['egg',3,'pc'],['baking_powder',2,'tsp'],['sunflower_oil',1,'l'],['brown_sugar',30,'g'],['sesame_seeds',2,'tbsp'],['whole_milk',30,'ml'],['salt',null,'']],
  s:{fr:["Battez les œufs et le sucre sans les monter : une pâte aérée gonflerait trop vite et éclaterait au lieu de se fendre proprement.","Ajoutez la farine tamisée avec la levure et mêlez le moins possible ; la pâte doit être épaisse et collante, presque impossible à façonner.","Laissez-la reposer 30 minutes puis prélevez des boules à la main huilée, sans les lisser.","Plongez-les dans l'huile à 160 °C seulement — pas plus : c'est la basse température qui permet à la boule de gonfler lentement et de se fendre en trois.","Comptez 8 minutes en les retournant : elles doivent être brunes dehors et sèches dedans. À 180 °C elles brûleraient avant de s'ouvrir."],
     en:["Beat the eggs and sugar without aerating them: an airy batter would swell too fast and burst rather than split cleanly.","Add the flour sifted with the baking powder and mix as little as possible; the batter should be thick and sticky, almost impossible to shape.","Rest it 30 minutes then scoop balls with an oiled hand, without smoothing them.","Lower them into oil at 160°C only — no hotter: it is the low temperature that lets the ball swell slowly and split in three.","Allow 8 minutes, turning them: they should be brown outside and dry within. At 180°C they would burn before opening."]} },

{ id:'okinawa-soba', c:'as', lat:26.334, lon:127.804, base:4, prep:60, cook:180, diff:2, tags:['noodles','pork','comfort'],
  art:{v:'bowl',bg:'#33291f',plate:'#f0e4c8',style:'noodle',food:['#f4f0e6','#c9924a','#7fae5a','#e8dcb8'],garnish:'#7fae6a'},
  n:{fr:'Okinawa soba',en:'Okinawa soba'},
  p:{fr:'Nago, Okinawa, Japon',en:'Nago, Okinawa, Japan'},
  d:{fr:"Des nouilles de froment épaisses dans un bouillon de porc et de bonite, avec une côte de porc et du gingembre confit. Malgré son nom, il n'y entre pas un gramme de sarrasin : la fédération japonaise des sobas s'y opposa en 1976, et Okinawa obtint une dérogation pour garder le mot.",
     en:"Thick wheat noodles in a pork and bonito broth, with a pork rib and pickled ginger. Despite the name there is not a gram of buckwheat in it: the Japanese soba federation objected in 1976, and Okinawa won a dispensation to keep the word."},
  i:[['flour',400,'g'],['water',180,'ml'],['baking_soda',1,'tsp'],['pork_ribs',600,'g'],['pork_bones',600,'g'],['bonito_flakes',20,'g'],['soy_sauce',60,'ml'],['brown_sugar',40,'g'],['awamori',40,'ml'],['pickled_ginger',60,'g'],['spring_onion',4,'pc'],['kombu',15,'g'],['salt',null,'']],
  s:{fr:["Dissolvez le bicarbonate dans l'eau avant de pétrir : c'est lui qui donne aux nouilles leur couleur jaune et leur mâche, à défaut de kansui.","Pétrissez fermement, laissez reposer 2 heures, puis abaissez à 2 mm et coupez des nouilles larges de 3 mm.","Faites un bouillon de porc et de bonite, écumé sans relâche : à Okinawa il reste clair, contrairement au tonkotsu de Kyūshū.","Braisez les côtes de porc 2 heures dans un sirop de soja, de sucre brun et d'awamori jusqu'à ce que la viande quitte l'os.","Cuisez les nouilles, rincez-les, huilez-les légèrement et laissez-les reposer une heure — à Okinawa on les cuit à l'avance, et elles gagnent à attendre."],
     en:["Dissolve the bicarbonate in the water before kneading: it gives the noodles their yellow colour and their chew in place of kansui.","Knead firmly, rest 2 hours, then roll to 2 mm and cut noodles 3 mm wide.","Make a pork and bonito broth, skimmed relentlessly: in Okinawa it stays clear, unlike the tonkotsu of Kyūshū.","Braise the pork ribs 2 hours in a syrup of soy, brown sugar and awamori until the meat leaves the bone.","Cook the noodles, rinse them, oil them lightly and rest them an hour — in Okinawa they are cooked ahead, and they are the better for waiting."]} },

{ id:'jiaozi', c:'as', lat:39.904, lon:116.407, base:6, prep:120, cook:15, diff:2, tags:['pork','comfort','festive'],
  art:{v:'plate',bg:'#33291f',plate:'#f4f0e6',style:'other',food:['#f4f0e6','#e8dcb8','#7fae5a','#c9924a'],garnish:'#7fae6a'},
  n:{fr:'Jiaozi',en:'Jiaozi'},
  p:{fr:'Pékin, Chine du Nord',en:'Beijing, Northern China'},
  d:{fr:"Des raviolis de porc et de chou, pochés ou poêlés, préparés en famille la veille du Nouvel An. Leur forme rappelle les lingots d'argent de l'époque impériale, et l'on en mange à minuit pour appeler la prospérité ; on en cache parfois un contenant une pièce.",
     en:"Pork and cabbage dumplings, poached or pan-fried, made as a family on New Year's Eve. Their shape recalls imperial silver ingots, and they are eaten at midnight to call in prosperity; one is sometimes hidden with a coin inside."},
  i:[['flour',500,'g'],['water',250,'ml'],['ground_pork',400,'g'],['napa_cabbage',400,'g'],['spring_onion',5,'pc'],['ginger',30,'g'],['soy_sauce',40,'ml'],['sesame_oil',20,'ml'],['rice_vinegar',60,'ml'],['garlic',4,'clove'],['chili_oil',30,'ml'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Salez le chou haché et laissez-le dégorger 30 minutes, puis pressez-le à fond : son eau est l'ennemi du jiaozi, elle perce la pâte de l'intérieur.","Travaillez la farce toujours dans le même sens, cinq minutes, en ajoutant l'eau de gingembre cuillère par cuillère jusqu'à ce qu'elle devienne collante.","Cette émulsion est ce qui donne le jus : une farce simplement mêlée reste sèche et compacte.","Abaissez des disques plus épais au centre qu'aux bords, garnissez et plissez le bord supérieur seul contre le bord inférieur lisse.","Pochez trois fois en ajoutant un verre d'eau froide à chaque reprise d'ébullition — c'est la méthode du Nord, et elle empêche la pâte d'éclater."],
     en:["Salt the chopped cabbage and let it drain 30 minutes, then press it thoroughly: its water is the enemy of a jiaozi, piercing the wrapper from inside.","Work the filling always in the same direction for five minutes, adding ginger water a spoonful at a time until it turns sticky.","That emulsion is what gives the juice: a filling merely mixed stays dry and solid.","Roll discs thicker at the centre than at the edge, fill them and pleat only the upper edge against the smooth lower one.","Poach three times, adding a glass of cold water at each return to the boil — the northern method, and it stops the wrappers bursting."]} },

{ id:'zhajiangmian', c:'as', lat:39.916, lon:116.397, base:4, prep:40, cook:40, diff:2, tags:['noodles','pork','comfort'],
  art:{v:'bowl',bg:'#33291f',plate:'#f0e4c8',style:'noodle',food:['#4f3a2a','#f4f0e6','#7fae5a','#e8c46a'],garnish:'#6fbf8f'},
  n:{fr:'Zhájiàngmiàn',en:'Zhajiangmian'},
  p:{fr:'Pékin, Chine du Nord',en:'Beijing, Northern China'},
  d:{fr:"Des nouilles de blé sous une sauce très épaisse de porc et de pâte de soja fermentée, entourées de légumes crus taillés en bâtonnets. La sauce est presque noire et si salée qu'on n'en met qu'une cuillerée : ce sont les légumes crus, en quantité, qui équilibrent le bol.",
     en:"Wheat noodles under a very thick sauce of pork and fermented soybean paste, ringed with raw vegetables cut into batons. The sauce is nearly black and so salty that only a spoonful goes in: it is the raw vegetables, in quantity, that balance the bowl."},
  i:[['wheat_noodles',400,'g'],['ground_pork',300,'g'],['yellow_soybean_paste',100,'g'],['sweet_bean_sauce',60,'g'],['spring_onion',5,'pc'],['ginger',20,'g'],['cucumber',1,'pc'],['radish',6,'pc'],['bean_sprouts',150,'g'],['sunflower_oil',80,'ml'],['sake',30,'ml'],['sugar',1,'tbsp'],['salt',null,'']],
  s:{fr:["Délayez les deux pâtes de soja dans un peu d'eau et laissez-les reposer dix minutes : sèches, elles brûlent instantanément au wok.","Faites revenir le porc haché en le laissant rendre toute sa graisse et commencer à croustiller — c'est cette graisse qui portera la sauce.","Jetez-y les pâtes délayées et faites-les frire lentement 20 minutes à feu doux, en remuant : elles doivent foncer et l'huile remonter en surface.","Cette séparation de l'huile est le signe que la sauce est prête ; avant cela, elle garde un goût cru de fermentation.","Taillez tous les légumes crus en bâtonnets fins et disposez-les en couronne autour des nouilles. On mêle soi-même, dans le bol."],
     en:["Slake both soybean pastes in a little water and rest them ten minutes: dry, they burn instantly in the wok.","Fry the minced pork letting it render all its fat and begin to crisp — that fat will carry the sauce.","Tip in the slaked pastes and fry them slowly for 20 minutes over low heat, stirring: they must darken and the oil rise to the surface.","That separation of oil is the sign the sauce is ready; before it, the sauce keeps a raw fermented taste.","Cut every raw vegetable into fine batons and ring them around the noodles. Each person mixes their own bowl."]} },

{ id:'guo-bao-rou', c:'as', lat:45.803, lon:126.535, base:4, prep:40, cook:20, diff:3, tags:['pork','fry','comfort'],
  art:{v:'plate',bg:'#33291f',plate:'#f4ecd8',style:'flat',food:['#e0b45a','#c9754a','#f2dfa8','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Guō bāo ròu',en:'Guo bao rou'},
  p:{fr:'Harbin, Chine du Nord-Est',en:'Harbin, Northeastern China'},
  d:{fr:"Des tranches de filet de porc frites deux fois et laquées d'un caramel au vinaigre, croustillantes et acidulées. Un cuisinier de Harbin les créa vers 1907 pour des diplomates russes qui trouvaient la cuisine chinoise trop salée : il adoucit et acidifia, et le plat est resté.",
     en:"Slices of pork loin fried twice and lacquered with a vinegar caramel, crisp and sharp. A Harbin cook created them around 1907 for Russian diplomats who found Chinese food too salty: he sweetened and soured it, and the dish stayed."},
  i:[['pork_loin',500,'g'],['potato_starch',200,'g'],['sunflower_oil',1,'l'],['rice_vinegar',80,'ml'],['sugar',80,'g'],['soy_sauce',20,'ml'],['ginger',30,'g'],['carrot',1,'pc'],['spring_onion',3,'pc'],['cilantro',1,'bunch'],['sake',30,'ml'],['salt',null,'']],
  s:{fr:["Taillez le filet en tranches de 3 mm en travers des fibres et faites-les mariner vingt minutes au saké et au sel.","Faites tremper la fécule de pomme de terre dans l'eau une heure, puis jetez l'eau claire et gardez la pâte au fond : c'est cette fécule humide, non la poudre sèche, qui donne la croûte bullée.","Enrobez chaque tranche de cette pâte et frites une première fois à 160 °C, 2 minutes, jusqu'à ce qu'elles blanchissent.","Remontez l'huile à 190 °C et refaites-les frire 40 secondes : c'est le second bain qui donne le croustillant qui tient sous la sauce.","Faites un caramel clair au sucre et au vinaigre, jetez-y les tranches et remuez dix secondes seulement, hors du feu. Servez immédiatement."],
     en:["Cut the loin into 3 mm slices across the grain and marinate them twenty minutes in sake and salt.","Soak the potato starch in water for an hour, then pour off the clear water and keep the paste at the bottom: it is that wet starch, not dry powder, that gives the blistered crust.","Coat each slice in the paste and fry once at 160°C for 2 minutes, until they whiten.","Raise the oil to 190°C and fry them again for 40 seconds: the second bath gives the crispness that survives the sauce.","Make a pale caramel with sugar and vinegar, tip in the slices and toss for ten seconds only, off the heat. Serve immediately."]} },

{ id:'clay-pot-rice', c:'as', lat:23.117, lon:113.259, base:4, prep:40, cook:35, diff:3, tags:['rice','pork','comfort'],
  art:{v:'pot',bg:'#33291f',plate:'#f0e4c8',style:'rice',food:['#f4f0e6','#8f3b2a','#7fae5a','#c9924a'],garnish:'#7fae6a'},
  n:{fr:'Riz en marmite de terre',en:'Clay pot rice'},
  p:{fr:'Canton, Guangdong, Chine',en:'Guangzhou, Guangdong, China'},
  d:{fr:"Du riz cuit dans une marmite de terre avec des saucisses chinoises, servi directement dans le pot. Tout l'intérêt est dans le fond : une croûte de riz grillé qu'on décolle à la cuillère à la fin, et qu'un cuisinier obtient en inclinant le pot sur la flamme dans les dernières minutes.",
     en:"Rice cooked in an earthenware pot with Chinese sausage, served straight from the pot. The whole point is at the bottom: a crust of toasted rice scraped up at the end, which a cook achieves by tilting the pot over the flame in the last minutes."},
  i:[['long_grain_rice',300,'g'],['lap_cheong',150,'g'],['chicken_thighs',300,'g'],['shiitake_mushrooms',100,'g'],['ginger',20,'g'],['soy_sauce',60,'ml'],['oyster_sauce',2,'tbsp'],['sesame_oil',20,'ml'],['sugar',1,'tbsp'],['spring_onion',3,'pc'],['bok_choy',200,'g'],['sunflower_oil',30,'ml'],['salt',null,'']],
  s:{fr:["Faites tremper le riz 30 minutes et égouttez-le : trempé, il cuit plus vite et le fond croûte avant que le dessus ne brûle.","Huilez généreusement l'intérieur de la marmite froide, y compris les parois — sans cela, la croûte adhère et se déchire.","Versez le riz et l'eau à un volume et quart, portez à ébullition à découvert puis couvrez et baissez au minimum.","Au bout de dix minutes, posez les saucisses et le poulet mariné sur le riz, refermez et laissez douze minutes.","Inclinez la marmite sur la flamme et faites-la tourner d'un quart de tour toutes les trente secondes pendant trois minutes : c'est ainsi que se forme la croûte. Versez la sauce et mêlez à table."],
     en:["Soak the rice 30 minutes and drain it: soaked, it cooks faster and the base crusts before the top burns.","Oil the inside of the cold pot generously, sides included — without that the crust sticks and tears.","Add the rice and water at one and a quarter volumes, bring to the boil uncovered then cover and drop to the lowest heat.","After ten minutes, lay the sausages and marinated chicken on the rice, close it and give it twelve minutes.","Tilt the pot over the flame and turn it a quarter turn every thirty seconds for three minutes: that is how the crust forms. Pour over the sauce and mix at the table."]} },

{ id:'wonton-noodles', c:'as', lat:23.121, lon:113.271, base:4, prep:90, cook:20, diff:3, tags:['noodles','sea','comfort'],
  art:{v:'bowl',bg:'#33291f',plate:'#f0e4c8',style:'noodle',food:['#f4f0e6','#e07a6a','#7fae5a','#e8dcb8'],garnish:'#6fbf8f'},
  n:{fr:'Nouilles aux wontons',en:'Wonton noodles'},
  p:{fr:'Canton, Guangdong, Chine',en:'Guangzhou, Guangdong, China'},
  d:{fr:"Des nouilles fines aux œufs et des raviolis de crevettes dans un bouillon clair de crevettes séchées. Les nouilles cantonaises se pétrissent à l'aide d'un long bambou sur lequel le cuisinier s'assoit à califourchon : c'est la seule façon de comprimer une pâte aussi sèche.",
     en:"Fine egg noodles and shrimp dumplings in a clear broth of dried shrimp. Cantonese noodles are kneaded with a long bamboo pole the cook straddles and rides: the only way to compress so dry a dough."},
  i:[['egg_noodles',300,'g'],['shrimp',300,'g'],['ground_pork',150,'g'],['wonton_wrapper',30,'pc'],['dried_shrimp',30,'g'],['pork_bones',600,'g'],['bok_choy',200,'g'],['spring_onion',3,'pc'],['sesame_oil',20,'ml'],['white_pepper',1,'tsp'],['oyster_sauce',1,'tbsp'],['ginger',20,'g'],['salt',null,'']],
  s:{fr:["Faites un bouillon de os de porc et de crevettes séchées grillées à sec : ce sont elles qui donnent au bouillon cantonais son goût, et non le poisson.","Salez les crevettes crues vingt minutes, rincez-les et taillez-les en gros morceaux — jamais hachées, elles doivent craquer.","Mêlez-les au porc et à l'huile de sésame en travaillant dans un seul sens, et laissez reposer une heure au froid.","Pliez les wontons sans chercher la perfection : la queue de pâte flottante fait partie du plat, c'est elle qui donne la texture de nuage.","Cuisez les nouilles 20 secondes seulement, rincez-les à l'eau froide puis replongez-les cinq secondes dans l'eau bouillante : ce double passage donne la mâche cantonaise."],
     en:["Make a broth from pork bones and dry-toasted dried shrimp: they, not fish, give a Cantonese broth its flavour.","Salt the raw prawns for twenty minutes, rinse them and cut them into large pieces — never minced, they must snap.","Mix them with the pork and sesame oil, working in one direction only, and rest an hour in the cold.","Fold the wontons without seeking perfection: the floating tail of wrapper is part of the dish, and it gives the cloud texture.","Cook the noodles 20 seconds only, rinse them cold then return them to boiling water for five seconds: that double pass gives the Cantonese chew."]} },

{ id:'shuang-pi-nai', c:'as', lat:22.516, lon:113.392, base:4, prep:40, cook:30, diff:3, tags:['sweet','comfort','fresh'],
  art:{v:'bowl',bg:'#2c3440',plate:'#f4f0e6',style:'other',food:['#f4f0e6','#f0e8d0','#e8dcb8','#c9924a'],garnish:'#c9754a'},
  n:{fr:'Shuāng pí nǎi',en:'Double skin milk'},
  p:{fr:'Shunde, Guangdong, Chine',en:'Shunde, Guangdong, China'},
  d:{fr:"Un flan de lait de bufflonne à deux peaux, cuit à la vapeur dans son bol. La première peau se forme en refroidissant, on verse le lait dessous, puis une seconde se forme à la cuisson : d'où le nom, et l'opération échoue si l'on emploie un lait à moins de huit pour cent de matière grasse.",
     en:"A buffalo milk custard with two skins, steamed in its own bowl. The first skin forms as the milk cools, the milk is poured out from under it, then a second forms during steaming: hence the name, and the operation fails with milk below eight per cent fat."},
  i:[['buffalo_milk',500,'ml'],['egg_white',4,'pc'],['sugar',60,'g'],['red_bean_paste',100,'g']],
  s:{fr:["Portez le lait de bufflonne à frémissement puis versez-le dans les bols et laissez-le refroidir vingt minutes : une peau épaisse se forme en surface.","Percez délicatement cette peau sur le bord et versez le lait dessous dans un autre récipient, en laissant la peau collée au fond du bol.","C'est le geste décisif : une peau déchirée ou emportée avec le lait, et le plat n'a plus qu'une peau au lieu de deux.","Mêlez ce lait aux blancs battus et au sucre, filtrez, puis reversez très doucement le long du bord pour que la peau se soulève et remonte.","Cuisez 12 minutes à la vapeur douce, couvert d'un film : la condensation qui tomberait dessus percerait la seconde peau."],
     en:["Bring the buffalo milk to a tremble then pour it into the bowls and let it cool twenty minutes: a thick skin forms on the surface.","Pierce that skin gently at the edge and pour the milk out from beneath into another vessel, leaving the skin stuck to the bottom of the bowl.","This is the decisive gesture: a torn skin, or one carried off with the milk, and the dish has one skin instead of two.","Mix that milk with the beaten whites and sugar, strain, then pour it back very gently down the side so the skin lifts and rises.","Steam 12 minutes over gentle heat, covered with film: condensation falling on it would pierce the second skin."]} },

{ id:'hong-shao-rou', c:'as', lat:31.230, lon:121.474, base:4, prep:30, cook:120, diff:2, tags:['pork','slow','comfort'],
  art:{v:'pot',bg:'#33251c',plate:'#f0e4c8',style:'stew',food:['#6f2a2a','#c9754a','#f4f0e6','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Hóng shāo ròu',en:'Hong shao rou'},
  p:{fr:'Shanghai, Chine de l’Est',en:'Shanghai, Eastern China'},
  d:{fr:"Des cubes de poitrine de porc braisés dans un caramel de sucre de canne, de soja et de vin de riz, laqués et brillants. Le braisage rouge est une technique et non une recette : c'est le caramel, préparé à sec avant tout liquide, qui donne la couleur, et non la sauce soja.",
     en:"Cubes of pork belly braised in a caramel of cane sugar, soy and rice wine, lacquered and glossy. Red braising is a technique rather than a recipe: it is the caramel, made dry before any liquid, that gives the colour, not the soy sauce."},
  i:[['pork_belly',800,'g'],['rock_sugar',60,'g'],['soy_sauce',60,'ml'],['dark_soy_sauce',20,'ml'],['shaoxing_wine',100,'ml'],['ginger',40,'g'],['spring_onion',4,'pc'],['star_anise',2,'pc'],['cinnamon',1,'stick'],['sunflower_oil',20,'ml'],['water',600,'ml'],['salt',null,'']],
  s:{fr:["Pochez la poitrine entière 10 minutes avec du gingembre, jetez l'eau et rincez : c'est ce blanchiment qui ôte l'écume et l'odeur.","Taillez-la en cubes de 4 cm en gardant la couenne — sans elle, le morceau se défait et la sauce ne prend pas de gélatine.","Faites fondre le sucre candi à sec dans un peu d'huile jusqu'à une couleur d'ambre foncé, puis jetez-y les cubes de porc et enrobez-les.","Ce caramel est le cœur de la technique : trop clair, la couleur manquera ; brûlé, tout le plat devient amer et il faut recommencer.","Déglacez au vin de Shaoxing, ajoutez les soja, les épices et l'eau à hauteur, et laissez mijoter 1 h 30 puis réduire à découvert vingt minutes."],
     en:["Poach the whole belly 10 minutes with ginger, throw the water away and rinse: that blanching removes scum and odour.","Cut it into 4 cm cubes keeping the rind — without it the piece falls apart and the sauce gains no gelatine.","Melt the rock sugar dry in a little oil to a dark amber, then tip in the pork cubes and coat them.","That caramel is the heart of the technique: too pale and the colour is missing; burnt and the whole dish turns bitter and must be started again.","Deglaze with Shaoxing wine, add the soys, spices and water to cover, and simmer 1½ hours then reduce uncovered for twenty minutes."]} },

{ id:'chou-doufu', c:'as', lat:31.224, lon:121.480, base:4, prep:60, cook:15, diff:3, tags:['veg','fry','street'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'other',food:['#8f6a4a','#c9924a','#7fae5a','#c9402c'],garnish:'#6fbf8f'},
  n:{fr:'Tofu puant',en:'Stinky tofu'},
  p:{fr:'Shanghai, Chine de l’Est',en:'Shanghai, Eastern China'},
  d:{fr:"Du tofu fermenté dans une saumure de légumes et de crevettes, frit et servi avec une sauce pimentée. L'odeur est légendaire et se sent à cinquante mètres ; le goût, lui, est doux et lacté, ce qui déconcerte quiconque n'en avait connu que l'odeur.",
     en:"Tofu fermented in a brine of vegetables and shrimp, fried and served with a chilli sauce. The smell is legendary and carries fifty metres; the taste is mild and milky, which disconcerts anyone who knew only the smell."},
  i:[['tofu',600,'g'],['fermented_brine',1,'l'],['sunflower_oil',1,'l'],['chili_oil',40,'ml'],['soy_sauce',40,'ml'],['rice_vinegar',20,'ml'],['garlic',4,'clove'],['fermented_cabbage',150,'g'],['sugar',1,'tsp'],['spring_onion',3,'pc'],['salt',null,'']],
  s:{fr:["La saumure se prépare des semaines à l'avance en laissant fermenter légumes, crevettes séchées et sel dans l'eau, jusqu'à ce qu'elle sente franchement.","Pressez le tofu entre deux planches deux heures pour en chasser l'eau — un tofu gorgé d'eau ne s'imprègne pas de saumure.","Immergez-le complètement et laissez-le fermenter de six à quarante-huit heures selon la force voulue, au frais.","Rincez-le rapidement et épongez-le, puis frites-le à 180 °C, quatre minutes : l'extérieur doit être brun et craquant, l'intérieur rester crémeux.","Servez brûlant, fendu au centre, avec du chou fermenté et une sauce de piment, ail, soja et vinaigre versée dans l'entaille."],
     en:["The brine is made weeks ahead by fermenting vegetables, dried shrimp and salt in water, until it smells frankly.","Press the tofu between two boards for two hours to drive out the water — waterlogged tofu will not take up brine.","Submerge it completely and ferment it six to forty-eight hours according to the strength wanted, in the cold.","Rinse it quickly and blot it, then fry at 180°C for four minutes: the outside must be brown and crackling, the inside stay creamy.","Serve scalding, split at the centre, with fermented cabbage and a sauce of chilli, garlic, soy and vinegar poured into the cut."]} },

{ id:'nian-gao', c:'as', lat:31.235, lon:121.470, base:8, prep:60, cook:60, diff:2, tags:['sweet','festive','slow'],
  art:{v:'plate',bg:'#33291f',plate:'#f4ead4',style:'cake',food:['#8f6a4a','#c9924a','#f2dfa8','#f0e8d0'],garnish:'#c9754a'},
  n:{fr:'Nián gāo',en:'Nian gao'},
  p:{fr:'Shanghai, Chine de l’Est',en:'Shanghai, Eastern China'},
  d:{fr:"Un gâteau de riz gluant au sucre brun, cuit à la vapeur puis tranché et poêlé. Son nom est un jeu de mots : nian gao veut dire gâteau de l'an, mais se prononce comme année plus haute, et l'on en mange au Nouvel An pour que l'année qui vient soit meilleure que la précédente.",
     en:"A glutinous rice cake with brown sugar, steamed then sliced and fried. Its name is a pun: nian gao means year cake, but sounds like higher year, and it is eaten at New Year so that the coming one may rise above the last."},
  i:[['glutinous_rice_flour',400,'g'],['brown_sugar',200,'g'],['water',350,'ml'],['sunflower_oil',40,'ml'],['red_dates',60,'g'],['egg',2,'pc'],['sesame_seeds',2,'tbsp']],
  s:{fr:["Faites fondre le sucre brun dans l'eau chaude et laissez tiédir : versé bouillant sur la farine de riz gluant, il la cuit en grumeaux irrécupérables.","Versez le sirop tiède sur la farine en fouettant, jusqu'à obtenir une pâte lisse de la consistance d'une pâte à crêpes épaisse.","Filtrez-la : la farine de riz gluant forme des grumeaux qui restent durs après cuisson et ne se défont jamais.","Versez dans un moule huilé, posez les dates rouges dessus et cuisez 1 heure à la vapeur, couvert d'un film pour éviter la condensation.","Laissez refroidir douze heures — un nian gao chaud est impossible à trancher. Coupez en tranches, passez à l'œuf battu et poêlez jusqu'à dorure."],
     en:["Dissolve the brown sugar in hot water and let it cool: poured boiling onto glutinous rice flour it cooks it into unrecoverable lumps.","Pour the warm syrup onto the flour, whisking, to a smooth batter the consistency of thick pancake batter.","Strain it: glutinous rice flour forms lumps that stay hard after cooking and never break down.","Pour into an oiled tin, set the red dates on top and steam 1 hour, covered with film against condensation.","Cool twelve hours — a warm nian gao is impossible to slice. Cut slices, dip in beaten egg and fry until golden."]} },

{ id:'zui-ji', c:'as', lat:31.240, lon:121.490, base:6, prep:1440, cook:40, diff:2, tags:['poultry','fresh','festive'],
  art:{v:'plate',bg:'#2c3440',plate:'#f4f0e6',style:'other',food:['#f4f0e6','#e8dcb8','#7fae5a','#f0e8d0'],garnish:'#6fbf8f'},
  n:{fr:'Poulet ivre',en:'Drunken chicken'},
  p:{fr:'Shanghai, Chine de l’Est',en:'Shanghai, Eastern China'},
  d:{fr:"Du poulet poché puis mariné une nuit dans du vin de Shaoxing, servi froid en entrée. La chair doit rester à peine rosée près de l'os : à Shanghai, un poulet blanc jusqu'au cœur est réputé trop cuit, et la marinade ne rattrape jamais une viande sèche.",
     en:"Chicken poached then marinated overnight in Shaoxing wine, served cold as a starter. The flesh must stay barely pink at the bone: in Shanghai a chicken white right through is held to be overcooked, and the marinade never rescues dry meat."},
  i:[['chicken',1.5,'kg'],['shaoxing_wine',400,'ml'],['ginger',60,'g'],['spring_onion',6,'pc'],['goji_berries',30,'g'],['soy_sauce',40,'ml'],['sugar',1,'tbsp'],['star_anise',2,'pc'],['coarse_salt',40,'g'],['sesame_oil',10,'ml']],
  s:{fr:["Frottez le poulet de sel et laissez-le une heure, puis plongez-le dans une eau frémissante avec le gingembre et l'oignon vert.","Coupez le feu dès la reprise du frémissement, couvrez et laissez le poulet pocher dans l'eau qui refroidit pendant 40 minutes.","C'est cette cuisson par inertie qui garde la chair juteuse : une eau maintenue à ébullition la dessécherait en vingt minutes.","Plongez-le aussitôt dans l'eau glacée : le choc contracte la peau et lui donne sa texture gélatineuse caractéristique.","Découpez-le en morceaux, couchez-les dans le vin de Shaoxing avec les baies de goji et l'anis, et laissez mariner 24 heures au froid. Se sert glacé."],
     en:["Rub the chicken with salt and leave it an hour, then lower it into simmering water with the ginger and spring onion.","Kill the heat as soon as it returns to a tremble, cover, and let the chicken poach in the cooling water for 40 minutes.","That carry-over cooking is what keeps the flesh juicy: water held at a boil would dry it out within twenty minutes.","Plunge it at once into iced water: the shock contracts the skin and gives it its characteristic gelatinous texture.","Joint it, lay the pieces in the Shaoxing wine with the goji berries and star anise, and marinate 24 hours in the cold. Served chilled."]} },

{ id:'dandan-mian', c:'as', lat:30.660, lon:104.063, base:4, prep:30, cook:20, diff:2, tags:['noodles','spicy','fast'],
  art:{v:'bowl',bg:'#33251c',plate:'#f0e4c8',style:'noodle',food:['#c9402c','#f4f0e6','#4f3a2a','#7fae5a'],garnish:'#6fbf8f'},
  n:{fr:'Dàn dàn miàn',en:'Dandan noodles'},
  p:{fr:'Chengdu, Sichuan, Chine',en:'Chengdu, Sichuan, China'},
  d:{fr:"Des nouilles sur une sauce sans bouillon, au porc croustillant, au sésame et au poivre du Sichuan. Le nom vient de la palanche, dan dan, que le vendeur portait sur l'épaule avec ses paniers : la version d'origine n'a pas de bouillon précisément parce qu'il aurait fallu le transporter.",
     en:"Noodles over a broth-free sauce of crisp pork, sesame and Sichuan pepper. The name comes from the dan dan, the carrying pole the seller balanced on his shoulder with his baskets: the original has no broth precisely because it would have had to be carried."},
  i:[['wheat_noodles',400,'g'],['ground_pork',250,'g'],['preserved_mustard_greens',80,'g'],['sesame_paste',60,'g'],['chili_oil',80,'ml'],['sichuan_pepper',2,'tsp'],['soy_sauce',60,'ml'],['rice_vinegar',20,'ml'],['garlic',4,'clove'],['spring_onion',4,'pc'],['sugar',1,'tsp'],['peanuts',60,'g'],['salt',null,'']],
  s:{fr:["Faites frire le porc haché à sec jusqu'à ce qu'il croustille et se sépare en grains — dix bonnes minutes, jusqu'à ce qu'il ne grésille plus.","Ajoutez les légumes fermentés hachés et faites-les sauter deux minutes : leur acidité est ce qui empêche le plat d'être seulement gras et piquant.","Faites griller le poivre du Sichuan à sec puis moulez-le au mortier : moulu à l'avance, il perd son effet anesthésiant en quelques jours.","Montez la sauce au fond du bol — pâte de sésame, huile pimentée, soja, vinaigre, ail, poivre — sans ajouter une goutte de bouillon.","Posez les nouilles brûlantes dessus avec deux cuillerées de leur eau de cuisson, et mêlez à table. Couronnez de porc et de cacahuètes concassées."],
     en:["Fry the minced pork dry until it crisps and separates into grains — a good ten minutes, until it stops sizzling.","Add the chopped preserved greens and stir-fry two minutes: their acidity is what stops the dish being merely fatty and hot.","Toast the Sichuan pepper dry then grind it in a mortar: ground in advance, it loses its numbing effect within days.","Build the sauce in the bottom of the bowl — sesame paste, chilli oil, soy, vinegar, garlic, pepper — without a drop of broth.","Set the scalding noodles on top with two spoonfuls of their cooking water, and mix at the table. Crown with the pork and crushed peanuts."]} },

{ id:'gong-bao-ji-ding', c:'as', lat:30.580, lon:104.070, base:4, prep:30, cook:10, diff:2, tags:['poultry','spicy','fast'],
  art:{v:'plate',bg:'#33251c',plate:'#f4ecd8',style:'other',food:['#c9532c','#e0b45a','#4f6f3a','#8f6a4a'],garnish:'#7fae6a'},
  n:{fr:'Gōng bǎo jī dīng',en:'Kung Pao chicken'},
  p:{fr:'Chengdu, Sichuan, Chine',en:'Chengdu, Sichuan, China'},
  d:{fr:"Des dés de poulet sautés aux piments séchés, aux cacahuètes et à une sauce aigre-douce au vinaigre noir. Le plat porte le titre de Ding Baozhen, gouverneur du Sichuan au XIXᵉ siècle ; il fut rebaptisé pendant la Révolution culturelle pour effacer la référence impériale, puis retrouva son nom.",
     en:"Diced chicken stir-fried with dried chillies, peanuts and a sweet-sour black vinegar sauce. It carries the title of Ding Baozhen, governor of Sichuan in the 19th century; it was renamed during the Cultural Revolution to erase the imperial reference, then took its name back."},
  i:[['chicken_breast',500,'g'],['peanuts',100,'g'],['dried_chili',12,'pc'],['sichuan_pepper',1,'tsp'],['spring_onion',6,'pc'],['garlic',4,'clove'],['ginger',30,'g'],['black_vinegar',40,'ml'],['soy_sauce',40,'ml'],['sugar',2,'tbsp'],['potato_starch',2,'tbsp'],['shaoxing_wine',30,'ml'],['sunflower_oil',60,'ml'],['salt',null,'']],
  s:{fr:["Taillez le poulet en dés de 1,5 cm et faites-les mariner vingt minutes au vin de Shaoxing, au soja et à la fécule : cet enrobage retient l'eau de la chair.","Préparez la sauce entièrement à l'avance dans un bol — vinaigre noir, sucre, soja, fécule : le sauté dure quatre-vingt-dix secondes et rien ne s'improvise.","Faites griller les piments séchés et le poivre du Sichuan dans l'huile tiède jusqu'à ce qu'ils foncent, et retirez-les si vous les préférez doux.","Saisissez le poulet à feu maximal sans le remuer les premières trente secondes : c'est ainsi qu'il colore au lieu de bouillir.","Versez la sauce et remuez dix secondes seulement : elle épaissit instantanément. Ajoutez les cacahuètes hors du feu, pour qu'elles restent croquantes."],
     en:["Cut the chicken into 1.5 cm dice and marinate them twenty minutes in Shaoxing wine, soy and starch: that coating holds the water in the flesh.","Make the sauce entirely in advance in a bowl — black vinegar, sugar, soy, starch: the stir-fry takes ninety seconds and nothing can be improvised.","Toast the dried chillies and Sichuan pepper in warm oil until they darken, and lift them out if you prefer it mild.","Sear the chicken over maximum heat without stirring for the first thirty seconds: that is how it colours instead of boiling.","Pour in the sauce and stir ten seconds only: it thickens instantly. Add the peanuts off the heat, so they stay crisp."]} },

{ id:'tang-yuan', c:'as', lat:30.610, lon:104.080, base:6, prep:60, cook:15, diff:2, tags:['sweet','festive','comfort'],
  art:{v:'bowl',bg:'#33291f',plate:'#f4f0e6',style:'other',food:['#f4f0e6','#4f3a2a','#e8dcb8','#f0e8d0'],garnish:'#c9754a'},
  n:{fr:'Tāng yuán',en:'Tang yuan'},
  p:{fr:'Chengdu, Sichuan, Chine',en:'Chengdu, Sichuan, China'},
  d:{fr:"Des boules de riz gluant fourrées de sésame noir, servies dans leur eau de cuisson sucrée. On les mange à la fête des lanternes, qui clôt le Nouvel An : leur forme ronde et leur nom, proche de tuányuán, la réunion, en font le symbole de la famille rassemblée.",
     en:"Glutinous rice balls filled with black sesame, served in their sweetened cooking water. They are eaten at the Lantern Festival that closes New Year: their round shape and their name, close to tuányuán, reunion, make them the symbol of the family gathered."},
  i:[['glutinous_rice_flour',300,'g'],['water',250,'ml'],['black_sesame_seeds',120,'g'],['sugar',100,'g'],['lard',60,'g'],['ginger',30,'g'],['rock_sugar',60,'g'],['osmanthus',1,'tbsp']],
  s:{fr:["Faites griller le sésame noir à sec jusqu'à ce qu'il crépite, puis moulez-le encore tiède : froid, il ne rend pas son huile.","Mêlez-le au sucre et au saindoux, et laissez durcir au réfrigérateur avant de former des billes — une farce molle perce la pâte au façonnage.","Versez l'eau bouillante sur un cinquième de la farine pour faire une pâte cuite, puis mêlez-la au reste avec l'eau tiède : ce mélange de pâte cuite et crue est ce qui rend la boule extensible.","Enfermez chaque bille dans un disque de pâte en la remontant à la main, et roulez sans qu'il reste la moindre fissure.","Pochez à l'eau frémissante — jamais bouillante — jusqu'à ce qu'elles remontent, puis deux minutes de plus. Servez dans un sirop de gingembre et de sucre candi."],
     en:["Toast the black sesame dry until it crackles, then grind it while still warm: cold, it will not release its oil.","Mix it with the sugar and lard, and chill until firm before shaping balls — a soft filling pierces the dough as you work.","Pour boiling water onto a fifth of the flour to make a cooked paste, then mix it with the rest and warm water: that blend of cooked and raw dough is what makes the ball extensible.","Enclose each ball in a disc of dough, drawing it up by hand, and roll it smooth with not the least crack left.","Poach in trembling — never boiling — water until they rise, then two minutes more. Serve in a syrup of ginger and rock sugar."]} }
,

{ id:'bulgogi', c:'as', lat:37.567, lon:126.978, base:4, prep:180, cook:15, diff:1, tags:['beef','grill','festive'],
  art:{v:'plate',bg:'#2b2419',plate:'#f0e4c8',style:'grill',food:['#5a3020','#8f4a3a','#e8c46a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Bulgogi',en:'Bulgogi'},
  p:{fr:'Séoul, Corée du Sud',en:'Seoul, South Korea'},
  d:{fr:"Du bœuf tranché fin, mariné au soja, à la poire et au sésame, saisi à la plaque. La poire coréenne n'est pas là pour le goût : elle contient une enzyme, la calpaïne, qui découpe les fibres musculaires et attendrit la viande en quelques heures.",
     en:"Beef sliced thin, marinated in soy, pear and sesame, seared on a plate. The Korean pear is not there for flavour: it contains an enzyme, calpain, that cuts muscle fibres and tenderises the meat within hours."},
  i:[['beef_sirloin',700,'g'],['soy_sauce',100,'ml'],['asian_pear',1,'pc'],['sesame_oil',30,'ml'],['sugar',40,'g'],['garlic',8,'clove'],['scallion',1,'bunch'],['sesame_seeds',20,'g'],['onion',1,'pc'],['black_peppercorns',5,'g'],['short_grain_rice',400,'g'],['lettuce',12,'pc']],
  s:{fr:["Faites raffermir la viande une heure au congélateur avant de la trancher : à température ambiante, on n'obtient pas des tranches de deux millimètres.","Râpez la poire et l'oignon et mêlez-les au soja, au sucre, à l'ail pilé et à l'huile de sésame.","Ne dépassez pas quatre heures de marinade : l'enzyme de la poire continue son travail et la viande finit par devenir farineuse.","Saisissez sur une plaque très chaude, en une seule couche, sans jamais entasser — entassée, la viande rend son jus et bout.","Servez avec du riz et des feuilles de laitue dans lesquelles on enroule la viande, à la main."],
     en:["Firm the meat an hour in the freezer before slicing: at room temperature you will not get two-millimetre slices.","Grate the pear and onion and mix them with the soy, sugar, crushed garlic and sesame oil.","Do not exceed four hours of marinating: the pear enzyme keeps working and the meat eventually turns mealy.","Sear on a very hot plate in a single layer, never crowded — crowded, the meat gives up its juice and boils.","Serve with rice and lettuce leaves in which the meat is wrapped, by hand."]} },

{ id:'samgyeopsal', c:'as', lat:37.556, lon:126.910, base:4, prep:30, cook:20, diff:1, tags:['pork','grill','comfort'],
  art:{v:'plate',bg:'#2b2419',plate:'#f0e4c8',style:'grill',food:['#e8c46a','#c9754a','#f4f0e6','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Samgyeopsal',en:'Samgyeopsal'},
  p:{fr:'Séoul, Corée du Sud',en:'Seoul, South Korea'},
  d:{fr:"De la poitrine de porc grillée à table, sans marinade, mangée en feuille de laitue. Le nom veut dire « trois couches de chair » : gras, maigre, gras — et l'on ne la marine jamais, précisément pour que ces couches se distinguent au goût.",
     en:"Pork belly grilled at the table, unmarinated, eaten in a lettuce leaf. The name means three layers of flesh: fat, lean, fat — and it is never marinated, precisely so those layers stay distinct on the palate."},
  i:[['pork_belly',800,'g'],['lettuce',20,'pc'],['perilla_leaves',20,'pc'],['garlic',12,'clove'],['ssamjang',100,'g'],['sesame_oil',40,'ml'],['kimchi',300,'g'],['scallion',1,'bunch'],['short_grain_rice',400,'g'],['coarse_salt',20,'g'],['black_peppercorns',5,'g']],
  s:{fr:["Demandez une poitrine de porc coupée à un centimètre d'épaisseur, ni plus ni moins : plus fine elle se dessèche, plus épaisse le gras ne fond pas.","Chauffez la plaque à vide et posez les tranches sans matière grasse — le porc rend assez de gras pour cuire les légumes ensuite.","Ne retournez qu'une fois, quand le dessous est franchement doré, au bout de quatre ou cinq minutes.","Faites griller l'ail en tranches et le kimchi dans le gras rendu, sur le bord de la plaque.","Coupez la viande aux ciseaux, posez-la sur la laitue avec le ssamjang, l'ail et la feuille de périlla, refermez et mangez d'une bouchée."],
     en:["Ask for belly cut one centimetre thick, no more and no less: thinner it dries out, thicker the fat does not render.","Heat the plate empty and lay the slices on with no added fat — the pork gives up enough to cook the vegetables afterwards.","Turn only once, when the underside is well browned, after four or five minutes.","Grill sliced garlic and kimchi in the rendered fat at the edge of the plate.","Cut the meat with scissors, lay it on lettuce with ssamjang, garlic and a perilla leaf, close it and eat in one mouthful."]} },

{ id:'tteokbokki', c:'as', lat:37.556, lon:127.018, base:4, prep:20, cook:20, diff:1, tags:['street','fast','comfort'],
  art:{v:'pot',bg:'#33291f',plate:'#f0e4c8',style:'other',food:['#c9302a','#e07a6a','#f4f0e6','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Tteokbokki',en:'Tteokbokki'},
  p:{fr:'Sindang-dong, Séoul, Corée du Sud',en:'Sindang-dong, Seoul, South Korea'},
  d:{fr:"Des cylindres de pâte de riz mijotés dans une sauce rouge au gochujang. La version pimentée date des années 1950 : une restauratrice de Sindang-dong aurait laissé tomber un tteok dans une sauce au piment et servi l'accident, qui a fait fortune.",
     en:"Cylinders of rice cake simmered in a red gochujang sauce. The spicy version dates from the 1950s: a Sindang-dong restaurateur is said to have dropped a tteok into chilli sauce and served the accident, which made her fortune."},
  i:[['rice_cakes',600,'g'],['gochujang',80,'g'],['gochugaru',20,'g'],['fish_cake',200,'g'],['scallion',1,'bunch'],['garlic',5,'clove'],['sugar',30,'g'],['soy_sauce',30,'ml'],['anchovy_broth',600,'ml'],['egg',4,'pc'],['sesame_seeds',15,'g']],
  s:{fr:["Faites tremper les tteok trente minutes à l'eau froide s'ils sont secs ou réfrigérés — sinon ils restent durs au centre.","Préparez un bouillon d'anchois séchés et de kombu, vingt minutes à frémissement, puis filtrez-le.","Délayez le gochujang, le gochugaru, le sucre et le soja dans ce bouillon avant de le porter à ébullition.","Ajoutez les tteok et laissez cuire quinze minutes en remuant souvent : l'amidon qu'ils rendent épaissit la sauce, c'est le seul liant.","Ajoutez les gâteaux de poisson et les œufs durs en fin de cuisson. Servez brûlant, la sauce doit napper."],
     en:["Soak the tteok thirty minutes in cold water if dry or refrigerated — otherwise they stay hard in the middle.","Make a stock of dried anchovies and kombu, twenty minutes at a tremble, then strain it.","Slake the gochujang, gochugaru, sugar and soy in that stock before bringing it to the boil.","Add the tteok and cook fifteen minutes, stirring often: the starch they release thickens the sauce, the only thickener there is.","Add the fish cakes and hard-boiled eggs at the end. Serve scalding, with the sauce coating."]} },

{ id:'sundubu-jjigae', c:'as', lat:37.775, lon:128.910, base:4, prep:20, cook:25, diff:2, tags:['soup','comfort','sea'],
  art:{v:'pot',bg:'#33291f',plate:'#f0e4c8',style:'soup',food:['#c9302a','#f4f0e6','#e8a032','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Sundubu-jjigae',en:'Sundubu-jjigae'},
  p:{fr:'Chodang, Gangneung, Corée du Sud',en:'Chodang, Gangneung, South Korea'},
  d:{fr:"Un ragoût brûlant de tofu non pressé, servi bouillonnant dans son pot de terre. Le village de Chodang fabrique son tofu à l'eau de mer plutôt qu'au nigari, depuis le XVIe siècle : le sel marin coagule le soja en une masse plus douce et plus fondante.",
     en:"A scalding stew of unpressed tofu, served bubbling in its earthenware pot. The village of Chodang has made its tofu with seawater rather than nigari since the sixteenth century: sea salt sets the soy into a softer, meltier mass."},
  i:[['silken_tofu',600,'g'],['gochugaru',25,'g'],['pork_belly',150,'g'],['clams',300,'g'],['onion',1,'pc'],['garlic',6,'clove'],['scallion',1,'bunch'],['anchovy_broth',500,'ml'],['sesame_oil',30,'ml'],['soy_sauce',30,'ml'],['egg',4,'pc'],['zucchini',1,'pc'],['short_grain_rice',400,'g']],
  s:{fr:["Faites chauffer le pot de terre à vide sur feu moyen : chauffé trop vite ou vide sur feu vif, il se fend.","Faites revenir le porc dans l'huile de sésame, ajoutez le gochugaru et laissez-le grésiller vingt secondes pour libérer sa couleur.","Ce grésillement est ce qui donne l'huile rouge en surface ; ajouté au liquide, le piment reste terne et poudreux.","Mouillez au bouillon, ajoutez les palourdes et les légumes, et portez à forte ébullition.","Versez le tofu à la cuillère en grosses cuillerées sans l'écraser, cassez un œuf dessus et servez immédiatement, encore bouillonnant."],
     en:["Heat the earthenware pot empty over medium heat: heated too fast, or empty over a fierce flame, it cracks.","Fry the pork in sesame oil, add the gochugaru and let it sizzle twenty seconds to release its colour.","That sizzle is what gives the red oil on the surface; added to liquid, the chilli stays dull and powdery.","Moisten with stock, add the clams and vegetables, and bring to a hard boil.","Spoon in the tofu in large curds without crushing it, break an egg on top and serve at once, still bubbling."]} },

{ id:'japchae', c:'as', lat:37.572, lon:126.976, base:6, prep:50, cook:25, diff:2, tags:['noodles','veg','festive'],
  art:{v:'plate',bg:'#33291f',plate:'#f0e4c8',style:'noodle',food:['#8f7a5a','#7fae5a','#e8a032','#f4f0e6'],garnish:'#7fae6a'},
  n:{fr:'Japchae',en:'Japchae'},
  p:{fr:'Séoul, Corée du Sud',en:'Seoul, South Korea'},
  d:{fr:"Des vermicelles de patate douce sautés avec des légumes en julienne et du bœuf. Le plat a été inventé vers 1600 pour un banquet royal et ne contenait alors aucune nouille : les vermicelles n'y sont entrés qu'au XXe siècle, et ont fini par lui donner son nom.",
     en:"Sweet potato noodles stir-fried with julienned vegetables and beef. The dish was invented around 1600 for a royal banquet and then contained no noodles at all: they entered only in the twentieth century, and ended up giving it its name."},
  i:[['sweet_potato_noodles',300,'g'],['beef_sirloin',250,'g'],['spinach',300,'g'],['carrot',2,'pc'],['shiitake_mushrooms',150,'g'],['onion',2,'pc'],['bell_pepper',1,'pc'],['soy_sauce',80,'ml'],['sesame_oil',50,'ml'],['sugar',40,'g'],['garlic',6,'clove'],['sesame_seeds',20,'g'],['egg',2,'pc']],
  s:{fr:["Faites cuire les vermicelles six minutes à l'eau bouillante, rincez-les à l'eau froide et coupez-les aux ciseaux en deux.","Assaisonnez-les aussitôt de soja et d'huile de sésame, tièdes : froids, ils collent en bloc et n'absorbent plus rien.","Sautez chaque légume séparément, à feu vif et brièvement — cuits ensemble, ils rendent leur eau et le japchae devient mou.","Blanchissez les épinards dix secondes seulement, et pressez-les à fond entre les mains.","Réunissez tout hors du feu, mélangez à la main pour ne rien casser, et servez tiède ou à température ambiante."],
     en:["Cook the noodles six minutes in boiling water, rinse them cold and cut them in two with scissors.","Season them at once with soy and sesame oil while warm: cold, they clump into a block and absorb nothing.","Stir-fry each vegetable separately, hot and briefly — cooked together they give up their water and the japchae goes soggy.","Blanch the spinach for ten seconds only, and press it out thoroughly between your hands.","Combine everything off the heat, mixing by hand so nothing breaks, and serve warm or at room temperature."]} },

{ id:'gimbap', c:'as', lat:37.563, lon:126.982, base:4, prep:60, cook:25, diff:2, tags:['rice','fresh','street'],
  art:{v:'board',bg:'#28331f',plate:'#f4ead4',style:'roll',food:['#2a3a2a','#f4f0e6','#e8a032','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Gimbap',en:'Gimbap'},
  p:{fr:'Séoul, Corée du Sud',en:'Seoul, South Korea'},
  d:{fr:"Un rouleau d'algue garni de riz assaisonné au sésame et de bandes de légumes et de viande. On le confond souvent avec le maki japonais, mais son riz n'est jamais vinaigré : il est assaisonné à l'huile de sésame et au sel, ce qui change tout le goût.",
     en:"A seaweed roll filled with sesame-seasoned rice and strips of vegetables and meat. It is often confused with Japanese maki, but its rice is never vinegared: it is seasoned with sesame oil and salt, which changes the whole flavour."},
  i:[['short_grain_rice',500,'g'],['nori',6,'pc'],['carrot',2,'pc'],['spinach',200,'g'],['danmuji',150,'g'],['egg',4,'pc'],['kamaboko',150,'g'],['beef_sirloin',200,'g'],['sesame_oil',40,'ml'],['sesame_seeds',20,'g'],['soy_sauce',30,'ml'],['coarse_salt',10,'g']],
  s:{fr:["Cuisez le riz un peu plus ferme que d'ordinaire et assaisonnez-le tiède d'huile de sésame et de sel, jamais de vinaigre.","Préparez chaque garniture séparément en longues bandes de même section, et laissez-les refroidir complètement.","Une garniture tiède dégage de la vapeur qui ramollit l'algue et fait éclater le rouleau à la découpe.","Étalez le riz sur les deux tiers de la feuille en couche mince, alignez les garnitures et roulez serré sur la natte.","Huilez la lame du couteau avant chaque coupe et tranchez d'un seul mouvement, sans scier."],
     en:["Cook the rice slightly firmer than usual and season it warm with sesame oil and salt, never vinegar.","Prepare each filling separately in long strips of the same section, and cool them completely.","A warm filling gives off steam that softens the seaweed and bursts the roll when cut.","Spread the rice over two-thirds of the sheet in a thin layer, line up the fillings and roll tightly on the mat.","Oil the knife blade before each cut and slice in one movement, without sawing."]} },

{ id:'dakgangjeong', c:'as', lat:38.207, lon:128.591, base:4, prep:60, cook:30, diff:2, tags:['poultry','fry','street'],
  art:{v:'bowl',bg:'#33291f',plate:'#f4ead4',style:'other',food:['#c9302a','#e8a032','#c9924a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Dakgangjeong',en:'Dakgangjeong'},
  p:{fr:'Sokcho, Corée du Sud',en:'Sokcho, South Korea'},
  d:{fr:"Du poulet frit deux fois, enrobé d'une sauce collante au piment et au sirop de riz. La double friture est une invention coréenne : le premier bain cuit, le second déshydrate la croûte, et le poulet reste croustillant même noyé de sauce.",
     en:"Twice-fried chicken coated in a sticky chilli and rice-syrup sauce. Double frying is a Korean invention: the first bath cooks, the second dehydrates the crust, and the chicken stays crisp even drowned in sauce."},
  i:[['chicken_wings',1,'kg'],['cornstarch',150,'g'],['gochujang',60,'g'],['rice_syrup',100,'ml'],['soy_sauce',40,'ml'],['garlic',8,'clove'],['ginger',30,'g'],['peanuts',80,'g'],['frying_oil',1.5,'l'],['sesame_seeds',20,'g'],['white_wine_vinegar',20,'ml'],['black_peppercorns',5,'g']],
  s:{fr:["Séchez le poulet à fond et enrobez-le de fécule de maïs seule, sans œuf ni farine : c'est elle qui donne la croûte fine et sèche.","Laissez reposer vingt minutes que la fécule s'hydrate et adhère — enfournée sèche, elle tombe dans l'huile.","Première friture à 160 °C pendant dix minutes, jusqu'à ce que le poulet soit cuit mais encore pâle. Égouttez et laissez tiédir dix minutes.","Seconde friture à 190 °C pendant trois minutes : la croûte durcit et prend une couleur ambrée.","Faites réduire la sauce à part, jusqu'à ce qu'elle nappe, et enrobez le poulet hors du feu, au dernier moment."],
     en:["Dry the chicken thoroughly and coat it in cornflour alone, no egg and no wheat flour: that is what gives the fine, dry crust.","Rest it twenty minutes so the starch hydrates and adheres — put in dry, it falls off in the oil.","First fry at 160°C for ten minutes, until cooked but still pale. Drain and cool ten minutes.","Second fry at 190°C for three minutes: the crust hardens and turns amber.","Reduce the sauce separately until it coats, and toss the chicken off the heat, at the last moment."]} },

{ id:'bingsu', c:'as', lat:37.524, lon:127.040, base:4, prep:30, cook:20, diff:1, tags:['sweet','fresh','fast'],
  art:{v:'bowl',bg:'#2c3440',plate:'#f4ead4',style:'other',food:['#f4f0e6','#e07a6a','#f0e8d0','#c9754a'],garnish:'#c9754a'},
  n:{fr:'Bingsu',en:'Bingsu'},
  p:{fr:'Séoul, Corée du Sud',en:'Seoul, South Korea'},
  d:{fr:"Une montagne de glace rasée en flocons, couverte de haricots rouges sucrés et de lait concentré. La glace n'est pas pilée mais rasée en copeaux d'un dixième de millimètre : la texture qui en résulte fond dans la bouche sans jamais craquer sous la dent.",
     en:"A mountain of shaved ice, topped with sweet red beans and condensed milk. The ice is not crushed but shaved into flakes a tenth of a millimetre thick: the resulting texture melts in the mouth without ever crunching."},
  i:[['whole_milk',1,'l'],['red_kidney_beans',300,'g'],['sugar',250,'g'],['condensed_milk',150,'g'],['rice_cakes',150,'g'],['roasted_soybean_powder',40,'g'],['strawberries',300,'g']],
  s:{fr:["Congelez du lait plutôt que de l'eau : la matière grasse empêche la formation de gros cristaux et donne des flocons souples.","Cuisez les haricots rouges deux heures à l'eau, en jetant la première eau après dix minutes de bouillon pour ôter l'amertume.","Sucrez-les seulement une fois tendres — le sucre ajouté trop tôt durcit la peau et ils ne cuiront plus jamais.","Rasez la glace juste avant de servir, en couche haute et sans tasser.","Couvrez de haricots, de tteok, de fruits et de poudre de soja grillé, et versez le lait concentré au dernier moment."],
     en:["Freeze milk rather than water: the fat prevents large crystals forming and gives supple flakes.","Cook the red beans two hours, discarding the first water after ten minutes' boiling to remove bitterness.","Sweeten them only once tender — sugar added too early hardens the skins and they will never cook.","Shave the ice just before serving, piled high and unpacked.","Cover with beans, tteok, fruit and roasted soybean powder, and pour the condensed milk on at the last moment."]} },

{ id:'tteokguk', c:'as', lat:37.579, lon:126.977, base:6, prep:40, cook:60, diff:2, tags:['soup','festive','comfort'],
  art:{v:'bowl',bg:'#33291f',plate:'#f0e4c8',style:'soup',food:['#f4f0e6','#f0e8d0','#e8c46a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Tteokguk',en:'Tteokguk'},
  p:{fr:'Séoul, Corée du Sud',en:'Seoul, South Korea'},
  d:{fr:"Une soupe de rondelles de pâte de riz dans un bouillon de bœuf clair, mangée au Nouvel An. En Corée, on ne vieillit pas d'un an à son anniversaire mais au Nouvel An lunaire : manger le tteokguk, c'est prendre un an, et les enfants en réclament deux bols.",
     en:"A soup of rice-cake coins in clear beef broth, eaten at New Year. In Korea one does not age a year at one's birthday but at Lunar New Year: eating tteokguk is taking a year, and children ask for two bowls."},
  i:[['rice_cakes',600,'g'],['beef_brisket',500,'g'],['egg',3,'pc'],['nori',2,'pc'],['scallion',1,'bunch'],['garlic',6,'clove'],['soy_sauce',40,'ml'],['sesame_oil',20,'ml'],['black_peppercorns',5,'g'],['coarse_salt',10,'g']],
  s:{fr:["Faites dégorger la poitrine de bœuf une heure à l'eau froide, en changeant l'eau : c'est ce qui donne un bouillon clair et non trouble.","Cuisez-la deux heures à frémissement en écumant régulièrement, sans jamais laisser bouillir fort.","Faites tremper les tteok en rondelles trente minutes s'ils sont secs, et rincez-les pour retirer l'amidon de surface.","Cuisez-les six minutes dans le bouillon filtré ; ils sont prêts quand ils remontent et deviennent translucides sur les bords.","Séparez les œufs, faites deux omelettes fines, une jaune et une blanche, et détaillez-les en losanges pour garnir."],
     en:["Soak the brisket an hour in cold water, changing it: that is what gives a clear rather than cloudy broth.","Cook it two hours at a tremble, skimming regularly, never at a hard boil.","Soak the rice-cake coins thirty minutes if dry, and rinse them to remove surface starch.","Cook them six minutes in the strained broth; they are ready when they rise and turn translucent at the edges.","Separate the eggs, make two thin omelettes, one yellow and one white, and cut them into diamonds as garnish."]} }
,

{ id:'budae-jjigae', c:'as', lat:37.738, lon:127.034, base:4, prep:25, cook:25, diff:1, tags:['soup','comfort','pork'],
  art:{v:'pot',bg:'#33291f',plate:'#f0e4c8',style:'soup',food:['#c9302a','#e07a6a','#f4f0e6','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Budae-jjigae',en:'Budae-jjigae'},
  p:{fr:'Uijeongbu, Corée du Sud',en:'Uijeongbu, South Korea'},
  d:{fr:"Un ragoût pimenté mêlant kimchi, saucisses, jambon en conserve et nouilles instantanées. Né près des bases américaines après la guerre de Corée, il utilisait les surplus militaires ; son nom signifie « ragoût de l'armée » et il assume entièrement son origine de disette.",
     en:"A spicy stew combining kimchi, sausages, tinned ham and instant noodles. Born near the American bases after the Korean War, it used military surplus; its name means army stew and it fully owns its origin in scarcity."},
  i:[['kimchi',400,'g'],['spam',300,'g'],['hot_dog_sausage',200,'g'],['instant_noodles',150,'g'],['silken_tofu',300,'g'],['gochujang',60,'g'],['gochugaru',20,'g'],['garlic',6,'clove'],['scallion',1,'bunch'],['anchovy_broth',900,'ml'],['baked_beans',100,'g'],['processed_cheese',60,'g'],['onion',1,'pc']],
  s:{fr:["Employez un kimchi bien fermenté, acide et légèrement effervescent : un kimchi jeune ne donne pas la profondeur qui tient tout le plat.","Disposez les ingrédients en secteurs dans la casserole large plutôt que de les mélanger — c'est la présentation d'usage, et chacun pioche.","Mêlez le gochujang, le gochugaru et l'ail pilé au bouillon avant de le verser, jamais en pâte au fond du plat.","Portez à ébullition et laissez quinze minutes, jusqu'à ce que le kimchi s'attendrisse et que les saucisses parfument le bouillon.","Ajoutez les nouilles et le fromage dans les trois dernières minutes seulement. Plus tôt, les nouilles se délitent et épaississent tout."],
     en:["Use a well-fermented kimchi, sour and faintly fizzy: a young kimchi will not give the depth that holds the whole dish together.","Arrange the ingredients in sectors in a wide pan rather than mixing them — that is the customary presentation, and each diner picks.","Mix the gochujang, gochugaru and crushed garlic into the stock before pouring, never as a paste in the bottom of the pan.","Bring to the boil and give it fifteen minutes, until the kimchi softens and the sausages flavour the broth.","Add the noodles and cheese in the last three minutes only. Earlier, the noodles disintegrate and thicken everything."]} },

{ id:'sannakji', c:'as', lat:34.812, lon:126.392, base:2, prep:15, cook:0, diff:2, tags:['sea','fresh','fast'],
  art:{v:'plate',bg:'#2c3440',plate:'#f4ead4',style:'other',food:['#f4f0e6','#e07a6a','#f0e8d0','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Sannakji',en:'Sannakji'},
  p:{fr:'Mokpo, Corée du Sud',en:'Mokpo, South Korea'},
  d:{fr:"Du poulpe coupé vif, servi immédiatement, les tentacules encore mobiles. Le mouvement n'est pas celui d'un animal vivant mais un réflexe nerveux : les neurones du tentacule continuent de commander les ventouses plusieurs minutes après la découpe.",
     en:"Octopus cut live and served at once, the tentacles still moving. The movement is not that of a living animal but a nerve reflex: the neurons in the tentacle keep commanding the suckers for several minutes after cutting."},
  i:[['baby_octopus',400,'g'],['sesame_oil',40,'ml'],['sesame_seeds',20,'g'],['gochujang',40,'g'],['scallion',1,'bunch'],['garlic',3,'clove'],['coarse_salt',20,'g']],
  s:{fr:["N'employez que de très petits poulpes, vivants, achetés dans un vivier et préparés dans l'heure.","Frottez-les au gros sel pour retirer le mucus, puis rincez abondamment à l'eau froide.","Découpez les tentacules en tronçons de deux centimètres et assaisonnez aussitôt d'huile de sésame et de graines.","L'huile de sésame n'est pas seulement un assaisonnement : elle enrobe les ventouses et réduit leur adhérence.","Mâchez très longuement avant d'avaler. Les ventouses actives peuvent adhérer à la gorge, et c'est un risque réel d'étouffement."],
     en:["Use only very small octopus, alive, bought from a tank and prepared within the hour.","Rub them with coarse salt to remove the mucus, then rinse thoroughly in cold water.","Cut the tentacles into two-centimetre lengths and dress at once with sesame oil and seeds.","The sesame oil is not merely a dressing: it coats the suckers and reduces their grip.","Chew very thoroughly before swallowing. Active suckers can grip the throat, and the choking risk is real."]} },

{ id:'hobakjuk', c:'as', lat:37.550, lon:126.990, base:4, prep:30, cook:50, diff:1, tags:['soup','comfort','veg'],
  art:{v:'bowl',bg:'#33291f',plate:'#f0e4c8',style:'soup',food:['#e8a032','#e8c46a','#f4f0e6','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Hobakjuk',en:'Hobakjuk'},
  p:{fr:'Séoul, Corée du Sud',en:'Seoul, South Korea'},
  d:{fr:"Une bouillie de courge sucrée, épaissie à la farine de riz gluant. C'est le plat que l'on sert aux convalescents et aux femmes après un accouchement : facile à digérer, réchauffant, et considéré comme reconstituant depuis des siècles.",
     en:"A sweet pumpkin porridge thickened with glutinous rice flour. It is what is served to convalescents and to women after childbirth: easy to digest, warming, and held to be restorative for centuries."},
  i:[['pumpkin',1.2,'kg'],['glutinous_rice_flour',120,'g'],['sugar',80,'g'],['red_kidney_beans',100,'g'],['rice_cakes',100,'g'],['water',800,'ml'],['coarse_salt',5,'g'],['pine_nuts',30,'g']],
  s:{fr:["Employez une courge à chair dense et sèche, du type potimarron : les courges aqueuses donnent une bouillie liquide impossible à rattraper.","Cuisez-la à la vapeur plutôt qu'à l'eau, quarante minutes, jusqu'à ce qu'une pointe la traverse sans effort.","Passez-la au tamis ou au moulin — le mixeur incorpore de l'air et la bouillie devient mousseuse au lieu d'être onctueuse.","Délayez la farine de riz gluant dans l'eau froide avant de l'ajouter : versée sèche, elle prend en grumeaux instantanément.","Faites cuire dix minutes en remuant sans arrêt, salez une pincée pour relever le sucre, et garnissez de pignons."],
     en:["Use a dense, dry-fleshed squash such as red kuri: watery pumpkins give a thin porridge that cannot be rescued.","Steam it rather than boil it, forty minutes, until a knife passes through without resistance.","Pass it through a sieve or a food mill — a blender works in air and the porridge turns foamy instead of silky.","Slake the glutinous rice flour in cold water before adding it: tipped in dry it lumps instantly.","Cook ten minutes, stirring without pause, add a pinch of salt to lift the sugar, and garnish with pine nuts."]} },

{ id:'haejangguk', c:'as', lat:37.572, lon:126.983, base:6, prep:60, cook:180, diff:2, tags:['soup','beef','slow'],
  art:{v:'bowl',bg:'#33291f',plate:'#f0e4c8',style:'soup',food:['#8f5a3a','#4f6f3a','#c9302a','#f4f0e6'],garnish:'#7fae6a'},
  n:{fr:'Haejangguk',en:'Haejangguk'},
  p:{fr:'Cheongjin-dong, Séoul, Corée du Sud',en:'Cheongjin-dong, Seoul, South Korea'},
  d:{fr:"Une soupe d'os de bœuf, de sang caillé et de chou, mangée le lendemain de veille. Son nom signifie littéralement « soupe pour chasser la gueule de bois » ; certaines maisons de Cheongjin-dong la servent depuis les années 1930 sans jamais fermer la nuit.",
     en:"A soup of beef bones, congealed blood and cabbage, eaten the morning after. Its name means literally soup to chase the hangover; some houses in Cheongjin-dong have served it since the 1930s without ever closing at night."},
  i:[['beef_bones',1.5,'kg'],['ox_blood_curd',300,'g'],['napa_cabbage',500,'g'],['doenjang',80,'g'],['gochugaru',20,'g'],['scallion',2,'bunch'],['garlic',10,'clove'],['ginger',30,'g'],['short_grain_rice',400,'g'],['soy_sauce',30,'ml'],['black_peppercorns',5,'g']],
  s:{fr:["Faites dégorger les os six heures à l'eau froide en changeant l'eau trois fois, puis blanchissez-les dix minutes et jetez cette eau.","Ce double nettoyage est ce qui donne un bouillon net : sans lui, la soupe reste grise et sent le suif.","Faites bouillir les os trois heures au moins, à petits bouillons, jusqu'à ce que le bouillon devienne laiteux.","Blanchissez le chou et pressez-le, puis assaisonnez-le de pâte de soja fermentée et d'ail avant de l'ajouter.","Ajoutez le sang caillé en gros dés dans les dix dernières minutes, à frémissement — bouilli, il se désagrège en poudre."],
     en:["Soak the bones six hours in cold water, changing it three times, then blanch them ten minutes and discard that water.","This double cleaning is what gives a clean broth: without it the soup stays grey and smells of tallow.","Boil the bones at least three hours at a gentle roll, until the broth turns milky.","Blanch the cabbage and press it out, then season it with fermented soybean paste and garlic before adding it.","Add the blood curd in large dice in the last ten minutes, at a tremble — boiled, it disintegrates into powder."]} },

{ id:'sundae-coreen', c:'as', lat:36.833, lon:127.201, base:8, prep:120, cook:60, diff:3, tags:['pork','street','comfort'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'other',food:['#3a2018','#5a3020','#8f7a5a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Sundae',en:'Sundae'},
  p:{fr:'Byeongcheon, Corée du Sud',en:'Byeongcheon, South Korea'},
  d:{fr:"Un boudin de sang de porc farci de vermicelles de patate douce et de riz gluant. À la différence des boudins européens, il contient beaucoup plus de féculent que de sang : le sang y est un liant et un colorant, et le vermicelle fait le corps.",
     en:"A pork blood sausage stuffed with sweet potato noodles and glutinous rice. Unlike European blood sausages it contains far more starch than blood: the blood binds and colours, and the noodles make the body."},
  i:[['pork_blood',600,'ml'],['sweet_potato_noodles',300,'g'],['glutinous_rice',200,'g'],['napa_cabbage',300,'g'],['scallion',2,'bunch'],['garlic',10,'clove'],['ginger',30,'g'],['sausage_casings',3,'pc'],['doenjang',40,'g'],['sesame_oil',30,'ml'],['perilla_seeds',20,'g'],['coarse_salt',15,'g']],
  s:{fr:["Retournez les boyaux et frottez-les au gros sel et à la farine, puis rincez-les longuement — un boyau mal nettoyé gâche tout.","Faites tremper le riz gluant quatre heures et cuisez les vermicelles avant de les couper court.","Mêlez le sang filtré, les vermicelles, le riz, le chou blanchi et pressé et les aromates, et goûtez en faisant frire une cuillerée.","Embossez sans serrer, aux deux tiers seulement : la farce gonfle en cuisant et un boyau plein éclate à coup sûr.","Pochez à 80 °C pendant quarante minutes, en piquant les boudins d'une aiguille au bout de dix minutes pour évacuer la vapeur."],
     en:["Turn the casings inside out and rub them with coarse salt and flour, then rinse at length — a badly cleaned casing ruins everything.","Soak the glutinous rice four hours and cook the noodles before cutting them short.","Mix the strained blood, noodles, rice, blanched and pressed cabbage and aromatics, and taste by frying a spoonful.","Fill loosely, only two-thirds full: the stuffing swells as it cooks and a packed casing will certainly burst.","Poach at 80°C for forty minutes, pricking the sausages with a needle after ten minutes to let the steam out."]} },

{ id:'bossam', c:'as', lat:37.566, lon:126.985, base:6, prep:60, cook:110, diff:2, tags:['pork','slow','festive'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'other',food:['#f4f0e6','#e8c46a','#c9302a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Bossam',en:'Bossam'},
  p:{fr:'Séoul, Corée du Sud',en:'Seoul, South Korea'},
  d:{fr:"De la poitrine de porc pochée aux aromates, tranchée et mangée enroulée dans du chou saumuré. Le bossam est traditionnellement le repas du kimjang, la grande fabrication de kimchi de novembre : on le mange avec le chou fraîchement salé, avant qu'il ne fermente.",
     en:"Pork belly poached with aromatics, sliced and eaten wrapped in brined cabbage. Bossam is traditionally the meal of kimjang, the great November kimchi-making: it is eaten with freshly salted cabbage, before it ferments."},
  i:[['pork_belly',1.5,'kg'],['doenjang',80,'g'],['ginger',60,'g'],['garlic',12,'clove'],['scallion',2,'bunch'],['instant_coffee',10,'g'],['napa_cabbage',1,'pc'],['gochugaru',40,'g'],['daikon',400,'g'],['salted_shrimp',60,'g'],['asian_pear',1,'pc'],['coarse_salt',150,'g']],
  s:{fr:["Pochez la poitrine entière une heure et demie dans une eau parfumée à la pâte de soja, au gingembre et aux poireaux.","Ajoutez une cuillerée de café soluble à l'eau : c'est un usage moderne mais efficace, il neutralise l'odeur du porc et colore la couenne.","Laissez refroidir dix minutes hors du bouillon avant de trancher — chaude, la viande s'effondre sous le couteau.","Salez le chou deux heures au gros sel, rincez-le et pressez-le : il doit plier sans casser.","Préparez une salade de radis au gochugaru et aux crevettes salées, et servez les trois éléments à composer soi-même."],
     en:["Poach the whole belly for an hour and a half in water scented with soybean paste, ginger and leeks.","Add a spoonful of instant coffee to the water: a modern habit but an effective one, it neutralises the pork smell and colours the rind.","Cool ten minutes out of the broth before slicing — hot, the meat collapses under the knife.","Salt the cabbage two hours in coarse salt, rinse it and press it: it should bend without snapping.","Make a radish salad with gochugaru and salted shrimp, and serve the three elements to be assembled at table."]} },

{ id:'makgeolli', c:'as', lat:37.895, lon:127.200, base:12, prep:60, cook:0, diff:3, tags:['drink','slow','comfort'],
  art:{v:'bowl',bg:'#33291f',plate:'#f4ead4',style:'drink',food:['#f4f0e6','#f0e8d0','#e8dcb8','#c9a878'],garnish:'#7fae6a'},
  n:{fr:'Makgeolli',en:'Makgeolli'},
  p:{fr:'Pocheon, Corée du Sud',en:'Pocheon, South Korea'},
  d:{fr:"Un alcool de riz trouble et légèrement pétillant, filtré grossièrement. Il fermente grâce au nuruk, un ferment de blé porteur de moisissures et de levures sauvages : le champignon transforme d'abord l'amidon en sucre, la levure transforme ensuite le sucre en alcool.",
     en:"A cloudy, faintly sparkling rice alcohol, coarsely filtered. It ferments thanks to nuruk, a wheat ferment carrying moulds and wild yeasts: the fungus first turns starch into sugar, then the yeast turns sugar into alcohol."},
  i:[['short_grain_rice',1,'kg'],['nuruk',200,'g'],['water',2,'l'],['dry_yeast',5,'g']],
  s:{fr:["Lavez le riz jusqu'à ce que l'eau soit claire, faites-le tremper deux heures puis cuisez-le à la vapeur en grains fermes et détachés.","Étalez-le et laissez-le refroidir à 30 °C exactement : plus chaud, il tue les levures, plus froid, la fermentation ne démarre pas.","Émiettez le nuruk et mêlez-le au riz et à l'eau dans un récipient stérilisé, en laissant un tiers de vide.","Couvrez d'un linge et laissez fermenter sept jours à 22-25 °C, en remuant à la cuillère de bois chaque jour.","Filtrez à travers une étamine large, en pressant peu : le makgeolli doit rester trouble, c'est sa définition même."],
     en:["Wash the rice until the water runs clear, soak it two hours then steam it to firm, separate grains.","Spread it and cool it to exactly 30°C: hotter kills the yeasts, colder and fermentation will not start.","Crumble the nuruk and mix it with the rice and water in a sterilised vessel, leaving a third empty.","Cover with a cloth and ferment seven days at 22-25°C, stirring with a wooden spoon daily.","Strain through wide muslin, pressing lightly: makgeolli must stay cloudy, that is its very definition."]} },

{ id:'bori-cha', c:'as', lat:35.871, lon:128.601, base:8, prep:10, cook:25, diff:1, tags:['drink','fast','comfort'],
  art:{v:'glass',bg:'#33291f',plate:'#f4ead4',style:'drink',food:['#8f5a3a','#c9924a','#e8c46a','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Bori-cha',en:'Bori-cha'},
  p:{fr:'Daegu, Corée du Sud',en:'Daegu, South Korea'},
  d:{fr:"Une infusion d'orge grillée, bue froide en été et chaude en hiver, à la place de l'eau. Elle ne contient aucune caféine et se sert aux enfants comme aux adultes ; presque tous les foyers coréens en gardent une carafe au réfrigérateur toute l'année.",
     en:"An infusion of roasted barley, drunk cold in summer and hot in winter, in place of water. It holds no caffeine and is served to children and adults alike; nearly every Korean household keeps a jug of it in the refrigerator all year."},
  i:[['barley',150,'g'],['water',2,'l']],
  s:{fr:["Grillez l'orge à sec dans une poêle épaisse, en remuant sans arrêt, jusqu'à ce que les grains brunissent et embaument, une bonne dizaine de minutes.","Arrêtez avant qu'ils ne noircissent : un seul grain brûlé rend toute l'infusion amère.","Portez l'eau à ébullition, jetez l'orge et baissez immédiatement le feu.","Laissez infuser à frémissement dix à quinze minutes selon la force voulue, puis filtrez sans presser.","Se boit chaude ou glacée. Refroidie, elle se garde trois jours au réfrigérateur mais pas davantage."],
     en:["Toast the barley dry in a heavy pan, stirring without pause, until the grains brown and become fragrant, a good ten minutes.","Stop before they blacken: a single burnt grain makes the whole infusion bitter.","Bring the water to the boil, tip in the barley and lower the heat at once.","Infuse at a tremble for ten to fifteen minutes depending on the strength wanted, then strain without pressing.","Drunk hot or iced. Cooled, it keeps three days in the refrigerator but no longer."]} },

{ id:'sikhye', c:'as', lat:36.568, lon:128.730, base:8, prep:60, cook:300, diff:2, tags:['drink','sweet','slow'],
  art:{v:'glass',bg:'#33291f',plate:'#f4ead4',style:'drink',food:['#f0e8d0','#e8dcb8','#f4f0e6','#c9a878'],garnish:'#c9754a'},
  n:{fr:'Sikhye',en:'Sikhye'},
  p:{fr:'Andong, Corée du Sud',en:'Andong, South Korea'},
  d:{fr:"Une boisson sucrée de riz, où les grains flottent entiers en surface. Le malt d'orge y transforme l'amidon du riz en maltose : c'est exactement le début du brassage de la bière, arrêté avant toute fermentation alcoolique.",
     en:"A sweet rice drink in which the grains float whole on the surface. Barley malt turns the rice starch into maltose: exactly the beginning of brewing beer, halted before any alcoholic fermentation."},
  i:[['short_grain_rice',300,'g'],['malted_barley_powder',200,'g'],['water',3,'l'],['sugar',200,'g'],['ginger',30,'g'],['pine_nuts',30,'g'],['jujube',8,'pc']],
  s:{fr:["Délayez la poudre de malt dans l'eau tiède et laissez décanter une heure, puis récupérez le liquide clair en laissant le dépôt.","Cuisez le riz en grains fermes et mêlez-le au liquide de malt à 60 °C exactement.","Cette température est décisive : au-dessus de 65 °C l'enzyme est détruite, en dessous de 55 °C elle travaille trop lentement.","Maintenez à 60 °C pendant cinq heures, jusqu'à ce qu'une vingtaine de grains remontent à la surface — c'est le signal.","Retirez les grains flottants, faites bouillir le liquide dix minutes avec le sucre et le gingembre, et remettez les grains au moment de servir, glacé."],
     en:["Slake the malt powder in warm water and let it settle an hour, then draw off the clear liquid, leaving the sediment.","Cook the rice to firm grains and mix it into the malt liquid at exactly 60°C.","That temperature is decisive: above 65°C the enzyme is destroyed, below 55°C it works too slowly.","Hold at 60°C for five hours, until a couple of dozen grains rise to the surface — that is the signal.","Remove the floating grains, boil the liquid ten minutes with the sugar and ginger, and return the grains as you serve, iced."]} }
,

{ id:'shoyu-ramen-tokyo', c:'as', lat:35.712, lon:139.797, base:4, prep:120, cook:180, diff:3, tags:['noodles','soup','comfort'],
  art:{v:'bowl',bg:'#33291f',plate:'#f0e4c8',style:'noodle',food:['#8f5a3a','#f2dfa8','#e8c46a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Shoyu ramen de Tokyo',en:'Tokyo shoyu ramen'},
  p:{fr:'Asakusa, Tokyo, Japon',en:'Asakusa, Tokyo, Japan'},
  d:{fr:"Le ramen originel : bouillon clair de volaille au soja, nouilles ondulées et chashu. Il est né en 1910 au Rairaiken d'Asakusa, tenu par un Japonais avec douze cuisiniers cantonais — le ramen est donc chinois d'origine et tokyoïte de naissance.",
     en:"The original ramen: a clear poultry broth with soy, wavy noodles and chashu. It was born in 1910 at the Rairaiken in Asakusa, run by a Japanese owner with twelve Cantonese cooks — ramen is thus Chinese in origin and Tokyo-born."},
  i:[['chicken_bones',1.5,'kg'],['pork_belly',600,'g'],['ramen_noodles',480,'g'],['soy_sauce',150,'ml'],['mirin',60,'ml'],['sake',80,'ml'],['kombu',20,'g'],['bonito_flakes',30,'g'],['scallion',1,'bunch'],['egg',4,'pc'],['menma',150,'g'],['nori',4,'pc'],['ginger',30,'g'],['garlic',6,'clove']],
  s:{fr:["Faites dégorger les carcasses une heure à l'eau froide, blanchissez-les dix minutes et jetez cette eau.","Faites frémir trois heures avec gingembre et poireau, sans jamais bouillir : un bouillon shoyu doit rester translucide, et l'ébullition l'émulsionne en trouble.","Préparez le tare séparément — soja, mirin, saké réduits — et le dashi au kombu et à la bonite : les trois éléments ne se mélangent que dans le bol.","Braisez la poitrine roulée et ficelée deux heures dans le tare, puis laissez-la refroidir avant de la trancher.","Deux cuillerées de tare au fond du bol, le bouillon brûlant par-dessus, puis les nouilles égouttées d'un coup sec."],
     en:["Soak the carcasses an hour in cold water, blanch them ten minutes and discard that water.","Simmer three hours with ginger and leek, never boiling: a shoyu broth must stay translucent, and boiling emulsifies it cloudy.","Make the tare separately — soy, mirin and sake reduced — and the dashi with kombu and bonito: the three elements meet only in the bowl.","Braise the rolled, tied belly two hours in the tare, then cool it before slicing.","Two spoonfuls of tare in the bottom of the bowl, scalding broth over it, then the noodles drained with a sharp shake."]} },

{ id:'fukagawa-meshi', c:'as', lat:35.678, lon:139.800, base:4, prep:30, cook:35, diff:2, tags:['rice','sea','comfort'],
  art:{v:'bowl',bg:'#33291f',plate:'#f0e4c8',style:'rice',food:['#8f7a5a','#f4f0e6','#e8c46a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Fukagawa meshi',en:'Fukagawa meshi'},
  p:{fr:'Fukagawa, Tokyo, Japon',en:'Fukagawa, Tokyo, Japan'},
  d:{fr:"Du riz aux palourdes et au miso, plat des pêcheurs de la baie d'Edo. Fukagawa était un quartier de pêcheurs bâti sur des bancs de palourdes ; le plat se faisait sur les bateaux, et la version en bouillon versé sur le riz est la plus ancienne.",
     en:"Rice with clams and miso, the dish of the Edo bay fishermen. Fukagawa was a fishing quarter built on clam beds; the dish was made aboard the boats, and the version with broth poured over rice is the older one."},
  i:[['clams',1,'kg'],['short_grain_rice',400,'g'],['miso_paste',80,'g'],['scallion',1,'bunch'],['ginger',30,'g'],['sake',80,'ml'],['dashi_stock',600,'ml'],['nori',2,'pc'],['soy_sauce',20,'ml']],
  s:{fr:["Faites dégorger les palourdes trois heures dans l'eau salée à 3 %, dans le noir : elles rejettent leur sable, et l'obscurité les y encourage.","Faites-les ouvrir au saké à couvert, deux minutes, et retirez-les dès qu'elles s'entrebâillent.","Filtrez le jus rendu à l'étamine — il contient toujours du sable, et c'est lui qui donne tout le goût.","Diluez le miso dans un peu de bouillon tiède avant de l'ajouter, et ne le faites jamais bouillir : la chaleur détruit son parfum.","Versez le bouillon sur le riz chaud, ajoutez les palourdes décoquillées et le gingembre râpé, et servez aussitôt."],
     en:["Purge the clams three hours in 3% salt water, in the dark: they spit out their sand, and darkness encourages it.","Open them in sake, covered, for two minutes, and take them out as soon as they gape.","Strain the released juice through muslin — it always holds sand, and it carries all the flavour.","Slake the miso in a little warm broth before adding it, and never boil it: heat destroys its aroma.","Pour the broth over hot rice, add the shelled clams and grated ginger, and serve at once."]} },

{ id:'anmitsu', c:'as', lat:35.672, lon:139.765, base:4, prep:40, cook:20, diff:2, tags:['sweet','fresh','fruit'],
  art:{v:'bowl',bg:'#2c3440',plate:'#f4ead4',style:'other',food:['#f4f0e6','#3a2018','#e8c46a','#e07a6a'],garnish:'#7fae6a'},
  n:{fr:'Anmitsu',en:'Anmitsu'},
  p:{fr:'Ginza, Tokyo, Japon',en:'Ginza, Tokyo, Japan'},
  d:{fr:"Des cubes de gelée d'agar, de la pâte de haricots rouges, des fruits et un sirop noir. L'agar-agar est tiré d'une algue et prend à température ambiante, ce qui permettait de servir ce dessert en été bien avant la réfrigération.",
     en:"Cubes of agar jelly, red bean paste, fruit and a black syrup. Agar is drawn from seaweed and sets at room temperature, which allowed this dessert to be served in summer long before refrigeration."},
  i:[['agar_agar',8,'g'],['water',600,'ml'],['red_bean_paste',200,'g'],['mochi',150,'g'],['brown_sugar',200,'g'],['tangerine',2,'pc'],['cherries',8,'pc'],['peach',1,'pc'],['vanilla_ice_cream',200,'g']],
  s:{fr:["Faites tremper l'agar en poudre dans l'eau froide dix minutes, puis portez à ébullition exactement une minute.","Une minute suffit : l'agar s'active à 90 °C, et prolonger la cuisson le dégrade et la gelée ne prend plus.","Versez dans un moule plat sur deux centimètres et laissez prendre à température ambiante, une heure.","Faites le kuromitsu en réduisant le sucre brun et l'eau vingt minutes, jusqu'à ce qu'il nappe la cuillère.","Découpez la gelée en cubes d'un centimètre, disposez avec les fruits, l'anko et le mochi, et versez le sirop à table."],
     en:["Soak the powdered agar in cold water for ten minutes, then boil for exactly one minute.","One minute is enough: agar activates at 90°C, and longer cooking degrades it so the jelly will not set.","Pour into a flat mould two centimetres deep and let it set at room temperature, an hour.","Make the kuromitsu by reducing brown sugar and water for twenty minutes, until it coats the spoon.","Cut the jelly into one-centimetre cubes, arrange with the fruit, anko and mochi, and pour the syrup at the table."]} },

{ id:'yakitori', c:'as', lat:35.694, lon:139.700, base:4, prep:60, cook:25, diff:2, tags:['poultry','grill','street'],
  art:{v:'board',bg:'#2b2419',plate:'#f4ead4',style:'skewer',food:['#8f5a3a','#c9924a','#e8c46a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Yakitori',en:'Yakitori'},
  p:{fr:'Shinjuku, Tokyo, Japon',en:'Shinjuku, Tokyo, Japan'},
  d:{fr:"Des brochettes de poulet grillées au charbon binchotan, glacées à la tare ou simplement salées. Le binchotan brûle à très haute température sans flamme ni fumée : il cuit par rayonnement, et c'est pourquoi le yakitori ne sent jamais le brûlé.",
     en:"Chicken skewers grilled over binchotan charcoal, glazed with tare or simply salted. Binchotan burns very hot with no flame and no smoke: it cooks by radiant heat, which is why yakitori never tastes scorched."},
  i:[['chicken_thighs',600,'g'],['chicken_wings',400,'g'],['chicken_liver',200,'g'],['scallion',2,'bunch'],['soy_sauce',200,'ml'],['mirin',150,'ml'],['sake',100,'ml'],['sugar',60,'g'],['chicken_bones',500,'g'],['coarse_salt',30,'g'],['shichimi',10,'g']],
  s:{fr:["Préparez la tare en réduisant soja, mirin, saké et sucre avec des carcasses grillées, quarante minutes.","La tare d'une maison ne se jette jamais : on la complète et on y trempe les brochettes, et elle s'enrichit d'année en année.","Coupez la viande en morceaux réguliers et enfilez-les serrés, en alternant avec le poireau.","Grillez d'abord à sec, sans sauce, jusqu'à ce que la surface se raffermisse — glacée trop tôt, la sauce brûle avant que la viande cuise.","Trempez ensuite dans la tare et repassez sur le feu trois fois, en laissant caraméliser entre chaque passage."],
     en:["Make the tare by reducing soy, mirin, sake and sugar with grilled bones, for forty minutes.","A house's tare is never thrown out: it is topped up and skewers are dipped in it, and it deepens year on year.","Cut the meat into even pieces and thread them tightly, alternating with leek.","Grill dry first, without sauce, until the surface firms — glazed too early, the sauce burns before the meat cooks.","Then dip in the tare and return to the fire three times, letting it caramelise between each pass."]} },

{ id:'ningyo-yaki', c:'as', lat:35.686, lon:139.783, base:8, prep:40, cook:30, diff:2, tags:['sweet','street','bake'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'other',food:['#e8c46a','#f2dfa8','#3a2018','#c9924a'],garnish:'#c9754a'},
  n:{fr:'Ningyo-yaki',en:'Ningyo-yaki'},
  p:{fr:'Ningyocho, Tokyo, Japon',en:'Ningyocho, Tokyo, Japan'},
  d:{fr:"De petits gâteaux moulés en forme de personnages, fourrés de pâte de haricots rouges. Ningyocho était le quartier des théâtres de marionnettes d'Edo ; les moules reproduisaient les personnages joués sur scène, et certains n'ont pas changé depuis 1907.",
     en:"Small moulded cakes in the shape of figures, filled with red bean paste. Ningyocho was Edo's puppet theatre district; the moulds reproduced the characters played on stage, and some are unchanged since 1907."},
  i:[['flour',250,'g'],['egg',3,'pc'],['sugar',150,'g'],['honey',40,'g'],['baking_soda',4,'g'],['whole_milk',100,'ml'],['red_bean_paste',300,'g'],['mirin',15,'ml']],
  s:{fr:["Fouettez les œufs et le sucre au bain-marie tiède jusqu'à ce que le ruban tienne trois secondes à la surface.","Incorporez la farine tamisée en trois fois, à la spatule, sans jamais fouetter : le gluten développé rendrait le gâteau caoutchouteux.","Laissez reposer la pâte trente minutes au frais, le temps que les bulles se stabilisent.","Chauffez le moule de fonte, huilez-le au pinceau et remplissez les cavités à moitié seulement.","Déposez une bille d'anko, couvrez de pâte et refermez le moule. Deux minutes par face, à feu moyen."],
     en:["Whisk the eggs and sugar over a warm water bath until the ribbon holds three seconds on the surface.","Fold in the sifted flour in three additions with a spatula, never whisking: developed gluten would make the cake rubbery.","Rest the batter thirty minutes in the cold, so the bubbles stabilise.","Heat the cast-iron mould, brush it with oil and fill the cavities only halfway.","Set a ball of anko in, cover with batter and close the mould. Two minutes a side, over medium heat."]} },

{ id:'taiyaki', c:'as', lat:35.657, lon:139.735, base:6, prep:40, cook:25, diff:2, tags:['sweet','street','bake'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'fish',food:['#e8c46a','#c9924a','#3a2018','#f2dfa8'],garnish:'#c9754a'},
  n:{fr:'Taiyaki',en:'Taiyaki'},
  p:{fr:'Azabu, Tokyo, Japon',en:'Azabu, Tokyo, Japan'},
  d:{fr:"Un gâteau en forme de daurade, fourré de pâte de haricots rouges. La daurade, tai, est le poisson des fêtes au Japon, trop cher pour la plupart : le taiyaki en donne la forme à un gâteau à un sou, et c'est là toute l'idée depuis 1909.",
     en:"A cake shaped like a sea bream, filled with red bean paste. The tai is Japan's celebration fish, too dear for most: taiyaki gives its shape to a penny cake, and that has been the whole idea since 1909."},
  i:[['flour',300,'g'],['baking_powder',10,'g'],['egg',2,'pc'],['sugar',100,'g'],['whole_milk',350,'ml'],['red_bean_paste',400,'g'],['sunflower_oil',30,'ml'],['salt',null,'']],
  s:{fr:["Préparez une pâte fluide, à peine plus épaisse qu'une pâte à crêpes, et laissez-la reposer une heure au frais.","Le repos supprime les bulles d'air qui feraient des trous dans les nageoires et la queue du poisson.","Chauffez bien le moule à taiyaki et huilez-le à chaque fournée, y compris les bords.","Remplissez une moitié du moule à 60 %, posez l'anko en bâtonnet au centre, couvrez de pâte et refermez.","Trois minutes par face en retournant le moule. La pâte qui déborde forme une bavure : on la casse à la main, c'est le meilleur morceau."],
     en:["Make a loose batter, barely thicker than pancake batter, and rest it an hour in the cold.","Resting removes the air bubbles that would leave holes in the fish's fins and tail.","Heat the taiyaki mould well and oil it for every batch, edges included.","Fill one half of the mould 60% full, lay the anko in a bar down the centre, cover with batter and close.","Three minutes a side, turning the mould. The batter that escapes forms a frill: it is broken off by hand, and it is the best part."]} },

{ id:'melon-pan', c:'as', lat:35.714, lon:139.796, base:8, prep:180, cook:20, diff:3, tags:['sweet','bake','street'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'other',food:['#e8c46a','#f2dfa8','#f4f0e6','#c9924a'],garnish:'#7fae6a'},
  n:{fr:'Melon pan',en:'Melon pan'},
  p:{fr:'Asakusa, Tokyo, Japon',en:'Asakusa, Tokyo, Japan'},
  d:{fr:"Une brioche couverte d'une croûte de pâte à biscuit quadrillée. Il ne contient pas de melon : le nom vient du quadrillage, qui rappelle l'écorce d'un melon brodé, et la version classique n'a jamais eu le moindre parfum de fruit.",
     en:"A brioche topped with a crosshatched biscuit crust. It contains no melon: the name comes from the lattice, which recalls the rind of a netted melon, and the classic version never had any fruit flavour at all."},
  i:[['flour',500,'g'],['fresh_yeast',15,'g'],['whole_milk',180,'ml'],['egg',3,'pc'],['butter',150,'g'],['sugar',220,'g'],['baking_powder',6,'g'],['vanilla',1,'pc'],['salt',null,'']],
  s:{fr:["Faites une pâte à brioche souple et laissez-la pousser une heure et demie jusqu'à ce qu'elle double.","Préparez à part une pâte sablée molle, crémée au beurre, et laissez-la raffermir au froid trente minutes.","Étalez le sablé en disques fins et enveloppez chaque boule de brioche en laissant la base nue — couverte entièrement, la brioche ne peut plus lever.","Roulez dans le sucre cristallisé et tracez le quadrillage à la corne, sans traverser le sablé.","Laissez pousser une heure, puis cuisez 15 minutes à 180 °C. La croûte doit rester pâle et se craqueler le long des lignes."],
     en:["Make a soft brioche dough and prove it an hour and a half, until doubled.","Separately make a soft creamed biscuit dough, and firm it in the cold for thirty minutes.","Roll the biscuit into thin discs and wrap each brioche ball, leaving the base bare — fully covered, the brioche cannot rise.","Roll in granulated sugar and score the lattice with a scraper, without cutting through.","Prove an hour, then bake 15 minutes at 180°C. The crust should stay pale and crack along the lines."]} },

{ id:'yuba', c:'as', lat:35.017, lon:135.667, base:4, prep:30, cook:90, diff:3, tags:['veg','slow','fresh'],
  art:{v:'plate',bg:'#28331f',plate:'#f0e4c8',style:'other',food:['#f2dfa8','#f4f0e6','#e8c46a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Yuba',en:'Yuba'},
  p:{fr:'Sagano, Kyoto, Japon',en:'Sagano, Kyoto, Japan'},
  d:{fr:"La peau qui se forme à la surface du lait de soja chauffé, prélevée à la baguette. Elle est apparue avec la cuisine des monastères zen de Kyoto, qui interdit la viande : la yuba y apportait les protéines, et sa fabrication demande une attention de moine.",
     en:"The skin that forms on the surface of heated soy milk, lifted off with a chopstick. It came with the Zen monastery cooking of Kyoto, which forbids meat: yuba supplied the protein, and making it demands a monk's attention."},
  i:[['soy_milk',2,'l'],['soy_sauce',60,'ml'],['wasabi',20,'g'],['dashi_stock',300,'ml'],['mirin',30,'ml'],['scallion',1,'bunch']],
  s:{fr:["Employez un lait de soja épais et non sucré, à 10 % de matière sèche au moins : un lait dilué ne forme aucune peau.","Chauffez-le dans un récipient large et peu profond, à 80 °C exactement, sans jamais le laisser frémir.","La peau se forme en cinq à sept minutes. Glissez une baguette dessous et soulevez d'un seul geste, sans hésiter.","Une hésitation déchire la feuille ; il faut la lever d'un mouvement continu, du bord vers le centre.","Comptez une dizaine de feuilles par litre, de plus en plus épaisses. Servez avec du soja, du wasabi et un dashi léger."],
     en:["Use a thick unsweetened soy milk, at least 10% dry matter: a diluted milk forms no skin at all.","Heat it in a wide shallow vessel at exactly 80°C, never letting it tremble.","The skin forms in five to seven minutes. Slide a chopstick underneath and lift in one movement, without hesitating.","A hesitation tears the sheet; it must be lifted in one continuous motion, from the edge to the centre.","Reckon about ten sheets per litre, each thicker than the last. Serve with soy, wasabi and a light dashi."]} },

{ id:'kushikatsu', c:'as', lat:34.652, lon:135.506, base:4, prep:60, cook:25, diff:2, tags:['fry','street','pork'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'skewer',food:['#c9924a','#e8c46a','#8f5a3a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Kushikatsu',en:'Kushikatsu'},
  p:{fr:'Shinsekai, Osaka, Japon',en:'Shinsekai, Osaka, Japan'},
  d:{fr:"Des brochettes panées à la chapelure fine et frites, trempées dans une sauce commune. La règle absolue de Shinsekai : on ne trempe qu'une fois. Le bac de sauce est partagé par toute la salle, et y replonger une brochette entamée est la seule faute impardonnable.",
     en:"Skewers crumbed in fine panko and fried, dipped in a communal sauce. Shinsekai's absolute rule: dip once only. The sauce tray is shared by the whole room, and returning a bitten skewer to it is the one unforgivable offence."},
  i:[['pork_loin',300,'g'],['shrimp',200,'g'],['onion',2,'pc'],['bell_pepper',2,'pc'],['shiitake_mushrooms',150,'g'],['quail_egg',8,'pc'],['flour',150,'g'],['egg',3,'pc'],['panko',300,'g'],['frying_oil',1.5,'l'],['worcestershire',200,'ml'],['cabbage',400,'g'],['dashi_stock',100,'ml']],
  s:{fr:["Enfilez chaque ingrédient sur une brochette courte, sans mélanger : chacun a son temps de cuisson propre.","Préparez une pâte liquide à base de farine, d'œuf et d'eau plutôt qu'un panage sec — c'est ce qui donne l'enrobage fin d'Osaka.","Employez du panko passé au tamis pour n'en garder que la mouture fine ; le panko grossier absorbe trop d'huile.","Frites à 170 °C, deux à trois minutes selon l'ingrédient, et égouttez debout sur du papier.","Servez avec du chou cru en gros morceaux, qui sert à la fois d'accompagnement et de cuillère pour reprendre de la sauce."],
     en:["Thread each ingredient on its own short skewer, unmixed: each has its own cooking time.","Make a thin batter of flour, egg and water rather than a dry coating — that gives Osaka's fine crust.","Sieve the panko and keep only the fine crumb; coarse panko drinks too much oil.","Fry at 170°C for two to three minutes depending on the ingredient, and drain upright on paper.","Serve with raw cabbage in large pieces, which is both a side dish and a spoon for taking more sauce."]} },

{ id:'butaman', c:'as', lat:34.666, lon:135.501, base:8, prep:180, cook:20, diff:3, tags:['pork','street','comfort'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'other',food:['#f4f0e6','#f0e8d0','#8f5a3a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Butaman',en:'Butaman'},
  p:{fr:'Namba, Osaka, Japon',en:'Namba, Osaka, Japan'},
  d:{fr:"Une brioche vapeur farcie au porc et à l'oignon, spécialité d'Osaka. Elle descend du baozi chinois arrivé par Nagasaki, mais la version d'Osaka est plus grosse, plus sucrée et se mange debout sur le quai de la gare.",
     en:"A steamed bun filled with pork and onion, an Osaka speciality. It descends from the Chinese baozi that came through Nagasaki, but the Osaka version is larger, sweeter and eaten standing on the station platform."},
  i:[['flour',500,'g'],['fresh_yeast',12,'g'],['sugar',60,'g'],['lard',40,'g'],['water',260,'ml'],['ground_pork',500,'g'],['onion',3,'pc'],['soy_sauce',40,'ml'],['sesame_oil',20,'ml'],['oyster_sauce',30,'ml'],['ginger',30,'g'],['cornstarch',20,'g'],['salt',null,'']],
  s:{fr:["Hachez l'oignon très fin, salez-le dix minutes et pressez-le : sans cela il rend son eau dans la farce et détrempe la pâte.","Travaillez le porc haché en une seule direction, cinq minutes, jusqu'à ce qu'il devienne collant et élastique.","Ce brassage unidirectionnel aligne les protéines et donne une farce qui se tient ; brassée au hasard, elle s'effrite.","Pétrissez la pâte, laissez-la doubler, puis divisez et abaissez des disques plus épais au centre qu'aux bords.","Plissez en refermant vers le haut, laissez pousser vingt minutes et cuisez 15 minutes à la vapeur vive."],
     en:["Chop the onion very finely, salt it ten minutes and press it out: otherwise it weeps into the filling and soaks the dough.","Work the minced pork in one direction only, five minutes, until it turns tacky and elastic.","That one-way mixing aligns the proteins and gives a filling that holds; stirred at random, it crumbles.","Knead the dough, let it double, then divide and roll discs thicker at the centre than at the edge.","Pleat the closure upwards, prove twenty minutes and steam 15 minutes over a fierce boil."]} },

{ id:'nishin-soba', c:'as', lat:35.003, lon:135.782, base:4, prep:1440, cook:60, diff:2, tags:['noodles','sea','comfort'],
  art:{v:'bowl',bg:'#33291f',plate:'#f0e4c8',style:'noodle',food:['#8f7a5a','#5a3020','#e8c46a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Nishin soba',en:'Nishin soba'},
  p:{fr:'Higashiyama, Kyoto, Japon',en:'Higashiyama, Kyoto, Japan'},
  d:{fr:"Des nouilles de sarrasin dans un dashi clair, avec un hareng séché longuement mijoté. Kyoto est enclavée dans les terres : le poisson n'y arrivait que séché, et le migaki nishin, hareng séché de Hokkaido, y voyageait un mois sans se gâter.",
     en:"Buckwheat noodles in a clear dashi with a long-simmered dried herring. Kyoto is landlocked: fish reached it only dried, and migaki nishin, dried herring from Hokkaido, travelled a month without spoiling."},
  i:[['dried_herring',4,'pc'],['buckwheat_noodles',400,'g'],['kombu',20,'g'],['bonito_flakes',30,'g'],['soy_sauce',100,'ml'],['mirin',80,'ml'],['sake',80,'ml'],['sugar',60,'g'],['green_tea',10,'g'],['scallion',1,'bunch']],
  s:{fr:["Faites tremper le hareng séché vingt-quatre heures dans de l'eau de riz ou du thé vert léger, en changeant deux fois.","Le thé n'est pas une coquetterie : ses tanins neutralisent l'odeur forte du poisson séché, que l'eau claire laisse intacte.","Mijotez-le ensuite deux heures dans soja, mirin, saké et sucre, jusqu'à ce que les arêtes s'écrasent sous le doigt.","Préparez un dashi de kombu et de bonite, et assaisonnez-le légèrement — il ne doit pas concurrencer le hareng.","Cuisez les soba à l'eau non salée, rincez-les à l'eau froide pour ôter l'amidon, et réchauffez-les dans le bouillon."],
     en:["Soak the dried herring twenty-four hours in rice water or weak green tea, changing it twice.","The tea is not an affectation: its tannins neutralise the strong smell of dried fish, which plain water leaves untouched.","Then simmer it two hours in soy, mirin, sake and sugar, until the bones crush under a finger.","Make a kombu and bonito dashi and season it lightly — it must not compete with the herring.","Cook the soba in unsalted water, rinse them cold to remove the starch, and reheat them in the broth."]} },

{ id:'zangi', c:'as', lat:42.985, lon:144.382, base:4, prep:60, cook:20, diff:2, tags:['poultry','fry','comfort'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'other',food:['#c9924a','#8f5a3a','#e8c46a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Zangi',en:'Zangi'},
  p:{fr:'Kushiro, Hokkaido, Japon',en:'Kushiro, Hokkaido, Japan'},
  d:{fr:"Du poulet mariné et frit, cousin du karaage mais plus assaisonné. La distinction fait débat à Hokkaido : pour les uns le zangi est mariné plus longtemps, pour les autres il se trempe dans une sauce après friture — et Kushiro revendique l'invention en 1960.",
     en:"Marinated fried chicken, cousin to karaage but more heavily seasoned. The distinction is debated in Hokkaido: some say zangi marinates longer, others that it is dipped in sauce after frying — and Kushiro claims the 1960 invention."},
  i:[['chicken_thighs',800,'g'],['soy_sauce',80,'ml'],['sake',60,'ml'],['ginger',40,'g'],['garlic',6,'clove'],['egg',1,'pc'],['potato_starch',150,'g'],['flour',50,'g'],['frying_oil',1.5,'l'],['sesame_oil',15,'ml'],['lemon',1,'pc']],
  s:{fr:["Coupez le poulet en morceaux de la taille d'une bouchée, en gardant la peau — c'est elle qui croustille.","Faites mariner une heure au soja, saké, gingembre et ail râpés, puis incorporez l'œuf battu directement dans la marinade.","Enrobez de fécule de pomme de terre juste avant de frire : la fécule donne une croûte plus fine et plus sèche que la farine.","Frites une première fois à 160 °C, quatre minutes, puis laissez reposer trois minutes hors de l'huile.","Seconde friture à 190 °C pendant une minute. Ce repos entre les deux bains laisse la chaleur gagner le centre sans dessécher la surface."],
     en:["Cut the chicken into bite-sized pieces, keeping the skin — that is what crisps.","Marinate an hour in soy, sake, grated ginger and garlic, then beat the egg straight into the marinade.","Coat in potato starch just before frying: starch gives a finer, drier crust than flour.","Fry once at 160°C for four minutes, then rest three minutes out of the oil.","Second fry at 190°C for one minute. That rest between baths lets the heat reach the centre without drying the surface."]} }
,

{ id:'ika-meshi', c:'as', lat:42.108, lon:140.591, base:4, prep:40, cook:60, diff:2, tags:['sea','rice','comfort'],
  art:{v:'plate',bg:'#2c3440',plate:'#f0e4c8',style:'other',food:['#8f5a3a','#f4f0e6','#5a3020','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Ika-meshi',en:'Ika-meshi'},
  p:{fr:'Mori, Hokkaido, Japon',en:'Mori, Hokkaido, Japan'},
  d:{fr:"Des calmars farcis de riz et mijotés dans une sauce soja sucrée. Le plat est né en 1941 dans la gare de Mori : le riz manquait, le calmar abondait, et le bento vendu sur le quai a fini par devenir le plus célèbre du Japon.",
     en:"Squid stuffed with rice and simmered in sweet soy. The dish was born in 1941 at Mori station: rice was scarce, squid abundant, and the platform bento ended up the most famous in Japan."},
  i:[['squid',8,'pc'],['glutinous_rice',200,'g'],['short_grain_rice',100,'g'],['soy_sauce',120,'ml'],['mirin',80,'ml'],['sake',80,'ml'],['sugar',60,'g'],['ginger',30,'g'],['dashi_stock',400,'ml']],
  s:{fr:["Videz les calmars sans les fendre : tirez la tête, les viscères viennent avec, et le corps reste un tube intact.","Retirez la plume transparente et rincez l'intérieur, puis épongez soigneusement.","Ne remplissez qu'aux deux tiers de riz cru : le riz double de volume et un calmar trop plein éclate systématiquement.","Fermez l'ouverture avec un cure-dent en la pinçant, sans serrer.","Mijotez une heure à couvert dans le bouillon soja-mirin, à feu très doux. Laissez refroidir dans le jus avant de trancher."],
     en:["Gut the squid without slitting them: pull the head and the innards come with it, leaving the body an intact tube.","Remove the transparent quill and rinse the inside, then blot thoroughly.","Fill only two-thirds full with raw rice: rice doubles in volume and an overfilled squid bursts every time.","Close the opening with a cocktail stick, pinching without tightening.","Simmer an hour covered in the soy and mirin broth, over very low heat. Cool in the liquid before slicing."]} },

{ id:'chan-chan-yaki', c:'as', lat:43.913, lon:144.960, base:4, prep:30, cook:25, diff:1, tags:['sea','grill','comfort'],
  art:{v:'plate',bg:'#33291f',plate:'#f0e4c8',style:'fish',food:['#e07a6a','#7fae5a','#e8c46a','#f4f0e6'],garnish:'#7fae6a'},
  n:{fr:'Chan-chan yaki',en:'Chan-chan yaki'},
  p:{fr:'Shari, Hokkaido, Japon',en:'Shari, Hokkaido, Japan'},
  d:{fr:"Du saumon et des légumes cuits sur une plaque avec une sauce au miso et au beurre. Le plat est né sur les bateaux de pêche de la mer d'Okhotsk : on cuisait tout sur une plaque de fonte à même le pont, et le nom imiterait le bruit des spatules.",
     en:"Salmon and vegetables cooked on a plate with a miso and butter sauce. It was born on the fishing boats of the Sea of Okhotsk: everything was cooked on a cast-iron plate on deck, and the name is said to imitate the noise of the spatulas."},
  i:[['salmon',800,'g'],['cabbage',500,'g'],['onion',2,'pc'],['carrot',2,'pc'],['bean_sprouts',200,'g'],['miso_paste',120,'g'],['mirin',60,'ml'],['sake',60,'ml'],['sugar',30,'g'],['butter',80,'g'],['garlic',4,'clove'],['scallion',1,'bunch']],
  s:{fr:["Mélangez miso, mirin, saké, sucre et ail râpé en une pâte souple et laissez-la reposer une heure.","Posez le saumon peau vers le bas sur la plaque brûlante et laissez-le une bonne minute sans y toucher.","Disposez les légumes tout autour, jamais dessus : le poisson doit rester au contact de la fonte pour que la peau croustille.","Étalez la sauce miso sur le poisson, couvrez et laissez cuire dix minutes à la vapeur des légumes.","Ajoutez le beurre à la fin et mêlez tout d'un coup, à la spatule, directement sur la plaque."],
     en:["Mix miso, mirin, sake, sugar and grated garlic into a soft paste and rest it an hour.","Lay the salmon skin down on the scalding plate and leave it a good minute untouched.","Arrange the vegetables all around, never on top: the fish must stay in contact with the iron for the skin to crisp.","Spread the miso paste over the fish, cover and cook ten minutes in the vegetables' own steam.","Add the butter at the end and toss everything at once with the spatula, straight on the plate."]} },

{ id:'miso-ramen-sapporo', c:'as', lat:43.055, lon:141.353, base:4, prep:90, cook:180, diff:3, tags:['noodles','soup','comfort'],
  art:{v:'bowl',bg:'#33291f',plate:'#f0e4c8',style:'noodle',food:['#c9924a','#f2dfa8','#e8c46a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Miso ramen de Sapporo',en:'Sapporo miso ramen'},
  p:{fr:'Susukino, Sapporo, Japon',en:'Susukino, Sapporo, Japan'},
  d:{fr:"Un ramen au miso, riche et gras, couronné de beurre et de maïs. Il a été inventé en 1955 quand un client demanda à ajouter des nouilles dans sa soupe au miso ; la couche de gras en surface n'est pas un excès mais un couvercle thermique, indispensable à -15 °C.",
     en:"A rich, fatty miso ramen crowned with butter and sweetcorn. It was invented in 1955 when a customer asked to add noodles to his miso soup; the fat layer on top is no excess but a thermal lid, essential at -15°C."},
  i:[['pork_bones',1.5,'kg'],['ramen_noodles',480,'g'],['miso_paste',150,'g'],['ground_pork',200,'g'],['bean_sprouts',200,'g'],['sweetcorn',200,'g'],['butter',60,'g'],['garlic',8,'clove'],['ginger',30,'g'],['lard',60,'g'],['scallion',1,'bunch'],['egg',4,'pc'],['sesame_oil',20,'ml']],
  s:{fr:["Faites bouillir les os de porc trois heures à gros bouillons — ici, contrairement au shoyu, on cherche l'émulsion et le trouble.","Faites revenir le porc haché, l'ail et le gingembre dans le saindoux, à feu vif, dans le wok.","Ajoutez le miso et faites-le griller trente secondes dans le gras avant de mouiller : c'est ce qui lui donne son goût torréfié.","Versez le bouillon brûlant dans le wok et faites bouillir vingt secondes pour émulsionner le gras — le fouet ne suffit pas.","Jetez les pousses de soja dix secondes seulement. Beurre et maïs en surface au moment de servir."],
     en:["Boil the pork bones three hours at a hard rolling boil — here, unlike shoyu, cloudiness and emulsion are the aim.","Fry the minced pork, garlic and ginger in lard over fierce heat in a wok.","Add the miso and toast it thirty seconds in the fat before moistening: that gives its roasted flavour.","Pour the scalding broth into the wok and boil twenty seconds to emulsify the fat — a whisk alone will not do it.","Throw in the bean sprouts for ten seconds only. Butter and sweetcorn on top as you serve."]} },

{ id:'morioka-reimen', c:'as', lat:39.702, lon:141.155, base:4, prep:60, cook:30, diff:2, tags:['noodles','fresh','fruit'],
  art:{v:'bowl',bg:'#2c3440',plate:'#f0e4c8',style:'noodle',food:['#f4f0e6','#c9302a','#e07a6a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Morioka reimen',en:'Morioka reimen'},
  p:{fr:'Morioka, Iwate, Japon',en:'Morioka, Iwate, Japan'},
  d:{fr:"Des nouilles froides très élastiques dans un bouillon glacé, avec une tranche de pastèque. Le plat a été créé en 1954 par un restaurateur coréen installé à Morioka, qui a adapté le naengmyeon au goût japonais ; la pastèque est son ajout, et elle a fait scandale.",
     en:"Very elastic cold noodles in an iced broth, with a slice of watermelon. It was created in 1954 by a Korean restaurateur in Morioka who adapted naengmyeon to Japanese taste; the watermelon is his addition, and it caused an outcry."},
  i:[['potato_starch',300,'g'],['flour',150,'g'],['beef_brisket',500,'g'],['kimchi',200,'g'],['cucumber',1,'pc'],['watermelon',300,'g'],['egg',2,'pc'],['soy_sauce',60,'ml'],['rice_vinegar',60,'ml'],['scallion',1,'bunch'],['gochugaru',15,'g'],['salt',null,'']],
  s:{fr:["Pétrissez la fécule et la farine à l'eau bouillante : c'est l'eau brûlante qui gélatinise l'amidon et donne l'élasticité caractéristique.","Travaillez la pâte quinze minutes, jusqu'à ce qu'elle rebondisse sous la paume, puis extrudez-la directement dans l'eau bouillante.","Cuisez trois minutes et plongez aussitôt dans l'eau glacée en frottant les nouilles entre les mains pour ôter l'amidon.","Ce rinçage est décisif : mal rincées, les nouilles collent en bloc et perdent leur mordant.","Préparez un bouillon de bœuf dégraissé, assaisonné et refroidi jusqu'à ce que des cristaux de glace s'y forment."],
     en:["Knead the starch and flour with boiling water: scalding water gelatinises the starch and gives the characteristic elasticity.","Work the dough fifteen minutes, until it bounces back under your palm, then extrude it straight into boiling water.","Cook three minutes and plunge at once into iced water, rubbing the noodles between your hands to remove the starch.","That rinsing is decisive: badly rinsed, the noodles clump into a block and lose their bite.","Make a degreased beef broth, seasoned and chilled until ice crystals form in it."]} },

{ id:'morioka-jajamen', c:'as', lat:39.708, lon:141.148, base:4, prep:60, cook:40, diff:2, tags:['noodles','pork','comfort'],
  art:{v:'bowl',bg:'#33291f',plate:'#f0e4c8',style:'noodle',food:['#3a2018','#f2dfa8','#7fae5a','#f4f0e6'],garnish:'#7fae6a'},
  n:{fr:'Morioka jajamen',en:'Morioka jajamen'},
  p:{fr:'Morioka, Iwate, Japon',en:'Morioka, Iwate, Japan'},
  d:{fr:"Des nouilles plates tièdes couvertes d'une pâte de miso et de porc, mêlées à table. À la fin, on casse un œuf cru dans le bol vide, on rend le bol au cuisinier qui y verse l'eau de cuisson brûlante : ce chîtantan est la seconde partie obligatoire du repas.",
     en:"Flat warm noodles topped with a miso and pork paste, mixed at the table. At the end you crack a raw egg into the empty bowl and hand it back to the cook, who pours in scalding noodle water: this chîtantan is the obligatory second half of the meal."},
  i:[['wheat_noodles',480,'g'],['ground_pork',300,'g'],['miso_paste',150,'g'],['sesame_paste',60,'g'],['cucumber',2,'pc'],['scallion',1,'bunch'],['ginger',30,'g'],['garlic',6,'clove'],['egg',4,'pc'],['sugar',30,'g'],['sesame_oil',30,'ml'],['sake',40,'ml']],
  s:{fr:["Faites revenir le porc à sec jusqu'à ce qu'il rende son gras et commence à croustiller.","Ajoutez le miso, la pâte de sésame, le sucre et le saké, et laissez réduire vingt minutes à feu doux.","La pâte doit devenir presque noire et se détacher du fond en bloc ; trop claire, elle manque de puissance.","Cuisez les nouilles plates et égouttez-les sans les rincer — ici l'amidon de surface aide la sauce à adhérer.","Servez tiède, jamais brûlant, avec concombre et cives. Gardez de l'eau de cuisson pour le chîtantan final."],
     en:["Fry the pork dry until it renders its fat and starts to crisp.","Add the miso, sesame paste, sugar and sake, and reduce twenty minutes over low heat.","The paste should turn nearly black and pull from the base in one mass; too pale, it lacks power.","Cook the flat noodles and drain without rinsing — here the surface starch helps the sauce cling.","Serve warm, never scalding, with cucumber and spring onion. Keep some cooking water for the final chîtantan."]} },

{ id:'harako-meshi', c:'as', lat:38.037, lon:140.848, base:4, prep:60, cook:40, diff:3, tags:['sea','rice','festive'],
  art:{v:'bowl',bg:'#33291f',plate:'#f0e4c8',style:'rice',food:['#e8a032','#e07a6a','#f2dfa8','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Harako meshi',en:'Harako meshi'},
  p:{fr:'Watari, Miyagi, Japon',en:'Watari, Miyagi, Japan'},
  d:{fr:"Du riz cuit dans le bouillon de saumon, couvert du poisson et de ses propres œufs. Le nom veut dire « riz de l'enfant du ventre » : la mère et sa progéniture sont servies dans le même bol, et le plat ne se fait qu'à l'automne, quand le saumon remonte l'Abukuma.",
     en:"Rice cooked in salmon broth, topped with the fish and its own roe. The name means rice of the belly's child: mother and offspring are served in one bowl, and it is made only in autumn, when the salmon run up the Abukuma."},
  i:[['salmon',600,'g'],['salmon_roe',200,'g'],['short_grain_rice',400,'g'],['soy_sauce',100,'ml'],['sake',80,'ml'],['mirin',60,'ml'],['kombu',15,'g'],['ginger',30,'g'],['scallion',1,'bunch']],
  s:{fr:["Pochez le saumon dans un bouillon de soja, saké et mirin, dix minutes seulement, et retirez-le.","Cuisez le riz dans ce bouillon filtré et complété d'eau : c'est là que le plat se joue, le riz doit prendre toute la couleur du poisson.","Détachez les œufs de leur membrane dans de l'eau tiède salée, en les roulant du bout des doigts.","L'eau tiède, contre-intuitivement, détend la membrane ; l'eau froide la contracte et les œufs se déchirent.","Effeuillez le saumon sur le riz, ajoutez les œufs hors du feu et couvrez cinq minutes sans cuire — les œufs chauffés durcissent et blanchissent."],
     en:["Poach the salmon in a soy, sake and mirin broth for ten minutes only, and remove it.","Cook the rice in that strained broth made up with water: this is where the dish is decided, the rice must take all the fish's colour.","Free the roe from its membrane in warm salted water, rolling it with your fingertips.","Warm water, counterintuitively, relaxes the membrane; cold water contracts it and the eggs tear.","Flake the salmon over the rice, add the roe off the heat and cover five minutes without cooking — heated roe hardens and turns white."]} },

{ id:'imoni', c:'as', lat:38.255, lon:140.340, base:8, prep:40, cook:60, diff:2, tags:['soup','beef','festive'],
  art:{v:'pot',bg:'#33291f',plate:'#f0e4c8',style:'soup',food:['#8f7a5a','#5a3020','#e8c46a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Imoni',en:'Imoni'},
  p:{fr:'Yamagata, Japon',en:'Yamagata, Japan'},
  d:{fr:"Une soupe de taro et de bœuf au soja, cuite au bord de la rivière en grandes marmites. Chaque automne, des milliers de personnes se réunissent sur les berges du Mamigasaki ; à Yamagata la soupe est au bœuf et au soja, à Sendai au porc et au miso, et la querelle est sérieuse.",
     en:"A taro and beef soup with soy, cooked in great pots on the riverbank. Every autumn thousands gather on the banks of the Mamigasaki; in Yamagata the soup is beef and soy, in Sendai pork and miso, and the quarrel is taken seriously."},
  i:[['taro_root',1,'kg'],['beef_sirloin',500,'g'],['konjac',300,'g'],['scallion',2,'bunch'],['soy_sauce',150,'ml'],['sake',100,'ml'],['sugar',40,'g'],['dashi_stock',1.5,'l'],['shiitake_mushrooms',150,'g'],['burdock',150,'g']],
  s:{fr:["Pelez le taro avec des gants : sa sève provoque de fortes démangeaisons sur la peau nue.","Frottez-le au sel puis rincez-le : le mucilage part et le bouillon reste clair au lieu de tourner en colle.","Faites cuire le taro seul vingt minutes dans le dashi, avant toute autre chose — il est le plus long.","Ajoutez le konjac blanchi, le bardane et les champignons, puis le bœuf tranché fin en dernier.","Le bœuf ne doit cuire que deux minutes. Assaisonnez au soja et servez avec beaucoup de cives crues."],
     en:["Peel the taro wearing gloves: its sap causes severe itching on bare skin.","Rub it with salt then rinse: the mucilage comes away and the broth stays clear instead of turning gluey.","Cook the taro alone for twenty minutes in the dashi, before anything else — it takes the longest.","Add the blanched konjac, burdock and mushrooms, then the thinly sliced beef last.","The beef should cook two minutes only. Season with soy and serve with plenty of raw spring onion."]} },

{ id:'senbei-jiru', c:'as', lat:40.512, lon:141.488, base:6, prep:30, cook:50, diff:2, tags:['soup','poultry','comfort'],
  art:{v:'pot',bg:'#33291f',plate:'#f0e4c8',style:'soup',food:['#f2dfa8','#8f7a5a','#7fae5a','#e8c46a'],garnish:'#7fae6a'},
  n:{fr:'Senbei-jiru',en:'Senbei-jiru'},
  p:{fr:'Hachinohe, Aomori, Japon',en:'Hachinohe, Aomori, Japan'},
  d:{fr:"Une soupe où l'on casse des galettes de blé dures, qui s'assouplissent sans se déliter. Le nanbu senbei employé ici est cuit spécialement pour la soupe : plus épais et sans levure, il tient vingt minutes de bouillon là où un biscuit ordinaire fondrait en trois.",
     en:"A soup into which hard wheat crackers are broken, softening without disintegrating. The nanbu senbei used here is baked specially for soup: thicker and unleavened, it holds twenty minutes in broth where an ordinary biscuit would dissolve in three."},
  i:[['nanbu_senbei',8,'pc'],['chicken_thighs',500,'g'],['burdock',150,'g'],['carrot',2,'pc'],['shiitake_mushrooms',150,'g'],['scallion',1,'bunch'],['konjac',200,'g'],['soy_sauce',100,'ml'],['sake',60,'ml'],['dashi_stock',1.5,'l'],['mirin',40,'ml']],
  s:{fr:["Employez du senbei de type kayaki, vendu pour la soupe : le senbei à grignoter se dissout et épaissit tout en bouillie.","Faites revenir le poulet, puis mouillez au dashi et ajoutez les racines émincées.","Laissez cuire trente minutes à découvert, jusqu'à ce que le bardane perde son amertume.","Cassez les galettes en quatre et jetez-les dans le bouillon frémissant, dix minutes avant la fin.","Ne remuez plus une fois les galettes ajoutées : elles se brisent et le bouillon devient trouble."],
     en:["Use kayaki-type senbei, sold for soup: snacking senbei dissolves and thickens everything to porridge.","Fry the chicken, then moisten with dashi and add the sliced roots.","Cook thirty minutes uncovered, until the burdock loses its bitterness.","Break the crackers into quarters and drop them into the simmering broth ten minutes before the end.","Do not stir once the crackers are in: they break up and the broth turns cloudy."]} },

{ id:'hitsumabushi', c:'as', lat:35.128, lon:136.909, base:4, prep:60, cook:40, diff:3, tags:['sea','rice','festive'],
  art:{v:'bowl',bg:'#33291f',plate:'#f0e4c8',style:'rice',food:['#5a3020','#8f5a3a','#f4f0e6','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Hitsumabushi',en:'Hitsumabushi'},
  p:{fr:'Atsuta, Nagoya, Japon',en:'Atsuta, Nagoya, Japan'},
  d:{fr:"De l'anguille laquée servie sur du riz, qui se mange en trois temps successifs. Le premier quart nature, le deuxième aux condiments, le troisième en bouillon versé ; le quatrième se prend de la façon qu'on a préférée, et cet ordre n'est pas négociable à Nagoya.",
     en:"Lacquered eel served on rice, eaten in three successive ways. The first quarter plain, the second with condiments, the third with broth poured over; the fourth in whichever way you preferred, and that order is not negotiable in Nagoya."},
  i:[['eel',600,'g'],['short_grain_rice',500,'g'],['soy_sauce',150,'ml'],['mirin',150,'ml'],['sake',80,'ml'],['sugar',80,'g'],['wasabi',20,'g'],['nori',3,'pc'],['scallion',1,'bunch'],['green_tea',10,'g'],['dashi_stock',600,'ml']],
  s:{fr:["Grillez l'anguille à sec sur les braises, sans sauce, jusqu'à ce que le gras commence à tomber.","À Nagoya on ne la cuit pas à la vapeur, contrairement à Tokyo : elle reste ferme et croustillante, et c'est là toute la différence régionale.","Trempez-la ensuite dans la tare et repassez sur le feu quatre fois, en laissant sécher entre chaque passage.","Coupez-la en lanières fines et mêlez-en une partie au riz, en gardant le reste dessus.","Servez avec un dashi léger au thé vert dans une théière, pour le troisième temps."],
     en:["Grill the eel dry over coals, without sauce, until the fat begins to drip.","In Nagoya it is not steamed, unlike Tokyo: it stays firm and crisp, and that is the whole regional difference.","Then dip it in the tare and return it to the fire four times, letting it dry between passes.","Cut it into fine strips and mix some into the rice, keeping the rest on top.","Serve a light green-tea dashi in a teapot, for the third stage."]} },

{ id:'tebasaki', c:'as', lat:35.170, lon:136.908, base:4, prep:40, cook:25, diff:2, tags:['poultry','fry','street'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'other',food:['#8f5a3a','#c9924a','#e8c46a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Tebasaki',en:'Tebasaki'},
  p:{fr:'Sakae, Nagoya, Japon',en:'Sakae, Nagoya, Japan'},
  d:{fr:"Des ailes de poulet frites sans panure, laquées au soja sucré et poivrées à l'excès. Elles se frient deux fois et ne sont jamais farinées : la peau seule fait la croûte, et c'est ce qui les distingue de toutes les autres ailes du monde.",
     en:"Chicken wings fried without batter, glazed with sweet soy and heavily peppered. They are fried twice and never floured: the skin alone makes the crust, and that sets them apart from every other wing in the world."},
  i:[['chicken_wings',1,'kg'],['soy_sauce',100,'ml'],['mirin',80,'ml'],['sake',60,'ml'],['sugar',60,'g'],['garlic',6,'clove'],['ginger',30,'g'],['sesame_seeds',30,'g'],['black_peppercorns',15,'g'],['frying_oil',1.5,'l']],
  s:{fr:["Séchez les ailes à fond, à découvert au réfrigérateur une nuit si possible : la peau doit être sèche au toucher.","Frites-les nues à 160 °C pendant huit minutes, sans aucune farine ni fécule.","Laissez-les reposer cinq minutes, puis repassez-les à 190 °C pendant deux minutes pour durcir la peau.","Faites réduire la sauce à part jusqu'à ce qu'elle nappe, et enrobez les ailes hors du feu, dans un saladier.","Poivrez très généreusement, bien plus que l'instinct ne le suggère, et finissez au sésame grillé."],
     en:["Dry the wings thoroughly, uncovered in the refrigerator overnight if possible: the skin must feel dry to the touch.","Fry them bare at 160°C for eight minutes, with no flour and no starch at all.","Rest them five minutes, then return them to 190°C for two minutes to harden the skin.","Reduce the sauce separately until it coats, and toss the wings off the heat, in a bowl.","Pepper very generously, far beyond what instinct suggests, and finish with toasted sesame."]} },

{ id:'miso-nikomi-udon', c:'as', lat:35.181, lon:136.906, base:2, prep:30, cook:40, diff:2, tags:['noodles','soup','comfort'],
  art:{v:'pot',bg:'#33291f',plate:'#f0e4c8',style:'noodle',food:['#5a3020','#f2dfa8','#e8a032','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Miso nikomi udon',en:'Miso nikomi udon'},
  p:{fr:'Nagoya, Aichi, Japon',en:'Nagoya, Aichi, Japan'},
  d:{fr:"Des udon mijotés directement dans un bouillon de miso rouge, servis dans le pot de terre. Le miso hatcho de Nagoya fermente deux ans en fûts de bois lestés de pierres, sans riz ni orge : c'est le miso le plus foncé et le plus salé du Japon.",
     en:"Udon simmered directly in a red miso broth, served in the clay pot. Nagoya's hatcho miso ferments two years in wooden vats weighted with stones, with no rice or barley: the darkest and saltiest miso in Japan."},
  i:[['udon_noodles',400,'g'],['red_miso',120,'g'],['chicken_thighs',300,'g'],['egg',2,'pc'],['scallion',1,'bunch'],['shiitake_mushrooms',100,'g'],['fish_cake',100,'g'],['dashi_stock',800,'ml'],['mirin',40,'ml'],['sake',40,'ml']],
  s:{fr:["Employez des udon crus et non précuits : ils sont mijotés dans le bouillon et l'amidon qu'ils rendent l'épaissit, ce qui est voulu.","Ne rincez surtout pas les nouilles — le plat entier repose sur cet amidon.","Délayez le miso rouge dans le dashi froid, puis portez doucement à frémissement.","Ajoutez le poulet et les champignons, puis les nouilles, et laissez mijoter quinze minutes dans le pot de terre.","Cassez l'œuf sur le dessus deux minutes avant de servir et apportez le pot bouillonnant sur la table."],
     en:["Use raw, not pre-cooked udon: they are simmered in the broth and the starch they release thickens it, which is the point.","Do not rinse the noodles — the whole dish rests on that starch.","Slake the red miso in cold dashi, then bring gently to a tremble.","Add the chicken and mushrooms, then the noodles, and simmer fifteen minutes in the clay pot.","Crack the egg on top two minutes before serving and bring the pot to the table still bubbling."]} }
,

{ id:'hoba-miso', c:'as', lat:36.140, lon:137.252, base:4, prep:20, cook:20, diff:1, tags:['grill','veg','comfort'],
  art:{v:'leaf',bg:'#28331f',plate:'#f0e4c8',style:'other',food:['#5a3020','#e8c46a','#8f7a5a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Hoba miso',en:'Hoba miso'},
  p:{fr:'Takayama, Gifu, Japon',en:'Takayama, Gifu, Japan'},
  d:{fr:"Du miso grillé sur une feuille de magnolia séchée, posée directement sur la braise. La feuille de hoba est ignifuge une fois séchée et parfume le miso en chauffant ; les paysans de Hida s'en servaient d'assiette jetable en hiver, quand la vaisselle gelait.",
     en:"Miso grilled on a dried magnolia leaf set directly on the coals. The hoba leaf is fire-resistant once dried and scents the miso as it heats; Hida farmers used it as a disposable plate in winter, when the dishes froze."},
  i:[['magnolia_leaves',4,'pc'],['miso_paste',150,'g'],['scallion',1,'bunch'],['shiitake_mushrooms',150,'g'],['beef_sirloin',300,'g'],['mirin',40,'ml'],['sake',30,'ml'],['sugar',20,'g'],['short_grain_rice',400,'g']],
  s:{fr:["Faites tremper les feuilles séchées vingt minutes dans l'eau, puis épongez-les : humides, elles ne prennent pas feu sur la braise.","Mêlez le miso au mirin, au saké et au sucre, et travaillez jusqu'à obtenir une pâte souple mais non coulante.","Étalez-la au centre de la feuille en laissant trois centimètres de marge tout autour.","Disposez les champignons et le bœuf par-dessus, et posez la feuille sur des braises douces ou une plaque.","Le miso doit bouillonner et brunir sur les bords sans jamais brûler. Se mange à la cuillère, sur du riz."],
     en:["Soak the dried leaves twenty minutes in water, then blot them: damp, they will not catch fire on the coals.","Mix the miso with mirin, sake and sugar, working to a soft but not runny paste.","Spread it in the centre of the leaf leaving a three-centimetre margin all round.","Lay the mushrooms and beef on top, and set the leaf on gentle coals or a griddle.","The miso should bubble and brown at the edges without ever burning. Eaten with a spoon, over rice."]} },

{ id:'masu-sushi', c:'as', lat:36.696, lon:137.213, base:6, prep:180, cook:30, diff:3, tags:['sea','rice','slow'],
  art:{v:'plate',bg:'#2c3440',plate:'#f0e4c8',style:'other',food:['#e07a6a','#f4f0e6','#f0e8d0','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Masu sushi',en:'Masu sushi'},
  p:{fr:'Toyama, Japon',en:'Toyama, Japan'},
  d:{fr:"De la truite marinée pressée sur du riz vinaigré dans un moule rond, entre des feuilles de bambou. C'est un sushi de conservation, antérieur au sushi frais : la pression et le vinaigre le gardaient plusieurs jours, et il se vend en gare de Toyama depuis 1912.",
     en:"Marinated trout pressed onto vinegared rice in a round mould, between bamboo leaves. It is a keeping sushi, older than the fresh kind: pressure and vinegar preserved it for days, and it has been sold at Toyama station since 1912."},
  i:[['trout',600,'g'],['sushi_rice',500,'g'],['rice_vinegar',150,'ml'],['coarse_salt',60,'g'],['sugar',60,'g'],['bamboo_leaves',12,'pc'],['kombu',15,'g'],['sake',60,'ml']],
  s:{fr:["Levez les filets de truite, salez-les au gros sel deux heures puis rincez-les et épongez-les.","Faites-les mariner deux heures au vinaigre de riz sucré, jusqu'à ce que la chair pâlisse en surface mais reste rose au cœur.","Tapissez un moule rond de feuilles de bambou en les faisant largement déborder, puis disposez la truite peau vers le bas.","Tassez le riz vinaigré par-dessus, fermement, et rabattez les feuilles.","Pressez sous un poids de deux kilos pendant six heures au frais. Sans cette pression prolongée, le sushi se défait à la découpe."],
     en:["Fillet the trout, salt it in coarse salt for two hours then rinse and blot it.","Marinate it two hours in sweetened rice vinegar, until the flesh pales on the surface but stays pink at the centre.","Line a round mould with bamboo leaves overhanging generously, then lay the trout skin down.","Pack the vinegared rice on top, firmly, and fold the leaves over.","Press under a two-kilo weight for six hours in the cold. Without that prolonged pressing, the sushi falls apart when cut."]} },

{ id:'sauce-katsudon', c:'as', lat:35.729, lon:137.933, base:4, prep:40, cook:25, diff:2, tags:['pork','fry','comfort'],
  art:{v:'bowl',bg:'#33291f',plate:'#f0e4c8',style:'rice',food:['#c9924a','#5a3020','#f4f0e6','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Sauce katsudon',en:'Sauce katsudon'},
  p:{fr:'Komagane, Nagano, Japon',en:'Komagane, Nagano, Japan'},
  d:{fr:"Une côtelette panée trempée dans une sauce brune et posée sur du riz, sans œuf. Le katsudon ordinaire est lié à l'œuf battu ; la version de Komagane s'en passe entièrement, et les deux villes de Komagane et Fukui s'en disputent la paternité.",
     en:"A breaded cutlet dipped in brown sauce and set on rice, with no egg. Ordinary katsudon is bound with beaten egg; the Komagane version does without entirely, and Komagane and Fukui both claim its paternity."},
  i:[['pork_loin',600,'g'],['flour',100,'g'],['egg',2,'pc'],['panko',250,'g'],['short_grain_rice',500,'g'],['worcestershire',150,'ml'],['soy_sauce',40,'ml'],['mirin',40,'ml'],['sugar',30,'g'],['cabbage',300,'g'],['frying_oil',1.5,'l'],['dashi_stock',100,'ml']],
  s:{fr:["Incisez le nerf entre le gras et le maigre tous les deux centimètres : sans cela, la côtelette se recroqueville en cuisant.","Aplatissez-la au maillet jusqu'à un centimètre, puis salez-la et laissez-la reposer dix minutes.","Panez à l'anglaise en pressant fermement le panko, et laissez reposer un quart d'heure pour que la panure adhère.","Frites à 170 °C, six minutes, puis égouttez debout trois minutes — couchée, la panure du dessous ramollit.","Trempez la côtelette entière dans la sauce chaude, deux secondes seulement, et posez-la sur le riz avec du chou cru."],
     en:["Nick the sinew between fat and lean every two centimetres: without that, the cutlet curls as it cooks.","Flatten it with a mallet to a centimetre, then salt it and rest it ten minutes.","Crumb it in the standard way, pressing the panko on firmly, and rest a quarter of an hour so the coating adheres.","Fry at 170°C for six minutes, then drain upright for three — laid flat, the underside coating goes soft.","Dip the whole cutlet in the hot sauce for two seconds only, and set it on the rice with raw cabbage."]} },

{ id:'sasa-dango', c:'as', lat:37.916, lon:139.036, base:10, prep:120, cook:30, diff:2, tags:['sweet','comfort','slow'],
  art:{v:'leaf',bg:'#28331f',plate:'#f4ead4',style:'other',food:['#4f6f3a','#3a2018','#7fae5a','#f4f0e6'],garnish:'#7fae6a'},
  n:{fr:'Sasa dango',en:'Sasa dango'},
  p:{fr:'Niigata, Japon',en:'Niigata, Japan'},
  d:{fr:"Des boulettes de riz gluant à l'armoise, fourrées d'anko et enveloppées de feuilles de bambou nain. Les feuilles de sasa contiennent des composés antibactériens : elles conservaient les dango plusieurs jours l'été, avant toute réfrigération.",
     en:"Glutinous rice dumplings with mugwort, filled with anko and wrapped in dwarf bamboo leaves. Sasa leaves carry antibacterial compounds: they kept dango for days in summer, long before any refrigeration."},
  i:[['glutinous_rice_flour',400,'g'],['rice_flour',100,'g'],['mugwort',150,'g'],['red_bean_paste',400,'g'],['sugar',80,'g'],['bamboo_leaves',30,'pc'],['baking_soda',5,'g'],['water',350,'ml'],['salt',null,'']],
  s:{fr:["Blanchissez l'armoise avec une pointe de bicarbonate, deux minutes : le bicarbonate fixe le vert, sans lui la pâte vire au brun olive.","Rincez-la à l'eau glacée, pressez-la fort et hachez-la très fin avant de la piler.","Pétrissez les farines à l'eau chaude, incorporez l'armoise et travaillez jusqu'à ce que la pâte devienne lisse et souple comme un lobe d'oreille.","Enfermez l'anko, allongez en ovale et enveloppez dans trois feuilles de sasa liées à la paille.","Cuisez vingt minutes à la vapeur. Se mangent tièdes ou froides, et se gardent trois jours à température ambiante."],
     en:["Blanch the mugwort with a pinch of bicarbonate for two minutes: the bicarbonate fixes the green, without it the dough turns olive brown.","Rinse it in iced water, press it hard and chop it very finely before pounding.","Knead the flours with hot water, work in the mugwort and continue until the dough turns smooth and supple as an earlobe.","Enclose the anko, shape into ovals and wrap in three sasa leaves tied with straw.","Steam twenty minutes. Eaten warm or cold, and they keep three days at room temperature."]} },

{ id:'onomichi-ramen', c:'as', lat:34.409, lon:133.205, base:4, prep:90, cook:150, diff:3, tags:['noodles','soup','sea'],
  art:{v:'bowl',bg:'#33291f',plate:'#f0e4c8',style:'noodle',food:['#8f5a3a','#f2dfa8','#e8c46a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Onomichi ramen',en:'Onomichi ramen'},
  p:{fr:'Onomichi, Hiroshima, Japon',en:'Onomichi, Hiroshima, Japan'},
  d:{fr:"Un ramen au soja dont le bouillon marie petits poissons séchés et os de porc, couvert de dés de gras. Les cubes de lard flottant en surface, appelés seabura, ne sont pas un excès : ils fondent lentement et maintiennent la soupe brûlante jusqu'à la dernière bouchée.",
     en:"A soy ramen whose broth marries small dried fish with pork bones, topped with cubes of back fat. The floating lard cubes, called seabura, are no excess: they melt slowly and keep the soup scalding to the last mouthful."},
  i:[['pork_bones',1.5,'kg'],['sardines',80,'g'],['ramen_noodles',480,'g'],['soy_sauce',150,'ml'],['pork_fatback',200,'g'],['pork_belly',400,'g'],['scallion',1,'bunch'],['menma',150,'g'],['kombu',20,'g'],['sake',60,'ml'],['mirin',40,'ml']],
  s:{fr:["Faites mijoter les os de porc deux heures, puis ajoutez les petits poissons séchés pour les vingt dernières minutes seulement.","Bouillis plus longtemps, les niboshi deviennent franchement amers : c'est l'erreur qui gâche le plus d'Onomichi ramen.","Faites fondre le lard dorsal en dés à feu très doux, quarante minutes, jusqu'à ce qu'ils deviennent translucides sans colorer.","Employez des nouilles plates et droites, non ondulées : c'est la forme locale, et elles retiennent mieux le gras.","Deux cuillerées de tare au fond, le bouillon, les nouilles, et une bonne cuillerée de seabura en surface."],
     en:["Simmer the pork bones two hours, then add the small dried fish for the last twenty minutes only.","Boiled longer, niboshi turn frankly bitter: the mistake that ruins the most Onomichi ramen.","Render the diced back fat over very low heat for forty minutes, until the cubes turn translucent without colouring.","Use flat straight noodles, not wavy: that is the local shape, and they hold the fat better.","Two spoonfuls of tare in the bottom, the broth, the noodles, and a good spoonful of seabura on top."]} },

{ id:'fugu-sashimi', c:'as', lat:33.958, lon:130.941, base:4, prep:60, cook:0, diff:3, tags:['sea','fresh','festive'],
  art:{v:'plate',bg:'#2c3440',plate:'#f4ead4',style:'fish',food:['#f4f0e6','#f0e8d0','#e8dcb8','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Fugu sashimi',en:'Fugu sashimi'},
  p:{fr:'Shimonoseki, Yamaguchi, Japon',en:'Shimonoseki, Yamaguchi, Japan'},
  d:{fr:"Du poisson-globe tranché si fin qu'on voit l'assiette au travers, disposé en pétales. Le foie et les ovaires contiennent de la tétrodotoxine, mille fois plus toxique que le cyanure et sans antidote : seuls des cuisiniers titulaires d'une licence d'État peuvent le préparer.",
     en:"Pufferfish sliced so thin the plate shows through, arranged in petals. The liver and ovaries hold tetrodotoxin, a thousand times deadlier than cyanide and with no antidote: only cooks holding a state licence may prepare it."},
  i:[['pufferfish',600,'g'],['ponzu',150,'ml'],['scallion',1,'bunch'],['daikon',200,'g'],['chili_pepper',2,'pc'],['lime',2,'pc'],['nori',2,'pc']],
  s:{fr:["N'entreprenez jamais de préparer le fugu vous-même : la découpe demande une licence obtenue après trois ans d'apprentissage et un examen d'État.","Achetez-le déjà paré chez un poissonnier agréé, foie et gonades retirés et détruits selon la réglementation.","La chair est très ferme et n'a presque aucun goût : tout l'intérêt tient à la texture et à la finesse de la coupe.","Tranchez au couteau long et fin, d'un seul mouvement tiré, jusqu'à la transparence — le motif en chrysanthème est la présentation d'usage.","Servez avec un ponzu au radis râpé et au piment, et de la ciboule. Se mange par deux ou trois pétales à la fois."],
     en:["Never attempt to prepare fugu yourself: the butchery requires a licence earned through three years' apprenticeship and a state examination.","Buy it already trimmed from a licensed fishmonger, with liver and gonads removed and destroyed as regulations require.","The flesh is very firm and has almost no taste: the whole point is the texture and the fineness of the cut.","Slice with a long thin knife in one drawn movement, to transparency — the chrysanthemum pattern is the customary presentation.","Serve with ponzu, grated radish and chilli, and spring onion. Eaten two or three petals at a time."]} },

{ id:'izumo-soba', c:'as', lat:35.367, lon:132.755, base:4, prep:120, cook:15, diff:3, tags:['noodles','comfort','fast'],
  art:{v:'bowl',bg:'#33291f',plate:'#f0e4c8',style:'noodle',food:['#5a4a3a','#8f7a5a','#e8c46a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Izumo soba',en:'Izumo soba'},
  p:{fr:'Izumo, Shimane, Japon',en:'Izumo, Shimane, Japan'},
  d:{fr:"Des nouilles de sarrasin très foncées, servies empilées dans trois bols ronds. Le sarrasin y est moulu avec sa balle noire, ce qu'aucune autre région ne fait : la nouille est plus sombre, plus parfumée et plus rustique, et l'eau de cuisson se boit à la fin.",
     en:"Very dark buckwheat noodles served stacked in three round bowls. The buckwheat is milled with its black husk, which no other region does: the noodle is darker, more fragrant and rougher, and the cooking water is drunk at the end."},
  i:[['buckwheat_flour',400,'g'],['flour',100,'g'],['water',220,'ml'],['soy_sauce',100,'ml'],['mirin',60,'ml'],['bonito_flakes',30,'g'],['kombu',15,'g'],['daikon',200,'g'],['nori',2,'pc'],['scallion',1,'bunch'],['egg',2,'pc']],
  s:{fr:["Employez une farine de sarrasin complète, moulue avec la balle : c'est elle qui donne la couleur et le goût d'Izumo.","Versez l'eau en trois fois en mêlant du bout des doigts, jamais d'un coup — le sarrasin absorbe très inégalement.","Pétrissez dix minutes puis abaissez à deux millimètres et pliez avant de découper à la lame large.","Cuisez quarante secondes dans une grande eau bouillante et rincez immédiatement à l'eau glacée.","Servez empilé dans trois bols ronds, la sauce versée par-dessus et non à côté. Gardez l'eau de cuisson pour la boire ensuite."],
     en:["Use wholemeal buckwheat flour, milled with the husk: that gives Izumo its colour and flavour.","Add the water in three stages, mixing with your fingertips, never all at once — buckwheat absorbs very unevenly.","Knead ten minutes then roll to two millimetres and fold before cutting with a wide blade.","Cook forty seconds in plenty of boiling water and rinse at once in iced water.","Serve stacked in three round bowls, the sauce poured over rather than alongside. Keep the cooking water to drink afterwards."]} },

{ id:'uwajima-tai-meshi', c:'as', lat:33.223, lon:132.560, base:4, prep:30, cook:20, diff:2, tags:['sea','rice','fresh'],
  art:{v:'bowl',bg:'#33291f',plate:'#f0e4c8',style:'rice',food:['#f4f0e6','#e8a032','#f0e8d0','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Uwajima tai meshi',en:'Uwajima tai meshi'},
  p:{fr:'Uwajima, Ehime, Japon',en:'Uwajima, Ehime, Japan'},
  d:{fr:"De la daurade crue marinée à l'œuf et au soja, versée sur du riz chaud. Il ne faut pas le confondre avec le tai meshi de Matsuyama, où le poisson est cuit avec le riz : à Uwajima le poisson reste cru, et les deux villes ne s'entendent pas sur ce point.",
     en:"Raw sea bream marinated in egg and soy, poured over hot rice. It should not be confused with Matsuyama's tai meshi, where the fish is cooked with the rice: in Uwajima the fish stays raw, and the two towns do not agree on this."},
  i:[['sea_bream',400,'g'],['short_grain_rice',400,'g'],['egg',4,'pc'],['soy_sauce',80,'ml'],['mirin',40,'ml'],['sake',30,'ml'],['sesame_seeds',30,'g'],['scallion',1,'bunch'],['nori',2,'pc'],['shiso',6,'pc'],['dashi_stock',100,'ml']],
  s:{fr:["Levez les filets de daurade et tranchez-les en biais, un peu plus épais qu'un sashimi ordinaire.","Préparez la sauce en mêlant soja, mirin, saké et dashi, et laissez-la refroidir complètement avant d'y battre les œufs crus.","Ajoutée chaude, elle coagulerait les œufs et la marinade tournerait en omelette.","Laissez le poisson mariner dix minutes exactement : au-delà, le soja le sale à cœur et la chair durcit.","Versez le tout sur du riz brûlant et mêlez à table. La chaleur du riz épaissit à peine l'œuf, et c'est tout ce qu'on cherche."],
     en:["Fillet the sea bream and slice it on the bias, a little thicker than ordinary sashimi.","Make the sauce with soy, mirin, sake and dashi, and cool it completely before beating in the raw eggs.","Added warm, it would coagulate the eggs and the marinade would turn to omelette.","Marinate the fish exactly ten minutes: beyond that the soy salts it through and the flesh hardens.","Pour everything over scalding rice and mix at the table. The rice's heat barely thickens the egg, which is all that is wanted."]} },

{ id:'jakoten', c:'as', lat:33.228, lon:132.565, base:6, prep:60, cook:20, diff:2, tags:['sea','fry','street'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'other',food:['#c9924a','#e8c46a','#8f7a5a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Jakoten',en:'Jakoten'},
  p:{fr:'Uwajima, Ehime, Japon',en:'Uwajima, Ehime, Japan'},
  d:{fr:"Des galettes de petits poissons broyés entiers, frites, arêtes comprises. Contrairement au kamaboko, la chair n'est pas lavée ni blanchie : les arêtes, la peau et les viscères sont broyés avec, et c'est ce qui donne la couleur grise et le goût puissant.",
     en:"Cakes of small fish ground whole and fried, bones included. Unlike kamaboko the flesh is neither washed nor whitened: bones, skin and innards are ground in with it, which gives the grey colour and the strong flavour."},
  i:[['small_fish',800,'g'],['potato_starch',60,'g'],['egg',1,'pc'],['sake',30,'ml'],['sugar',15,'g'],['frying_oil',1,'l'],['ginger',20,'g'],['soy_sauce',40,'ml'],['daikon',150,'g'],['salt',null,'']],
  s:{fr:["Employez de très petits poissons — éperlans, anchois, hotarujako — étêtés et vidés mais non levés.","Broyez-les entiers au hachoir à grille fine, en passant deux fois : les arêtes doivent devenir imperceptibles.","Travaillez la pâte dix minutes avec le sel jusqu'à ce qu'elle devienne collante et élastique : c'est la myosine qui se développe, et sans elle la galette s'émiette à la friture.","Formez des ovales plats d'un demi-centimètre entre les paumes mouillées.","Frites à 170 °C, trois minutes par face. Se mangent chauds au gingembre râpé, ou froids dans une soupe d'udon."],
     en:["Use very small fish — smelt, anchovy, hotarujako — headed and gutted but not filleted.","Grind them whole through a fine plate, passing twice: the bones must become imperceptible.","Work the paste ten minutes with the salt until it turns tacky and elastic: that is the myosin developing, and without it the cake crumbles in the fryer.","Shape flat half-centimetre ovals between wetted palms.","Fry at 170°C, three minutes a side. Eaten hot with grated ginger, or cold in an udon soup."]} },

{ id:'mizutaki-hakata', c:'as', lat:33.590, lon:130.420, base:6, prep:60, cook:150, diff:2, tags:['poultry','soup','festive'],
  art:{v:'pot',bg:'#33291f',plate:'#f0e4c8',style:'soup',food:['#f4f0e6','#f0e8d0','#7fae5a','#e8c46a'],garnish:'#7fae6a'},
  n:{fr:'Mizutaki de Hakata',en:'Hakata mizutaki'},
  p:{fr:'Hakata, Fukuoka, Japon',en:'Hakata, Fukuoka, Japan'},
  d:{fr:"Un pot-au-feu de poulet dont le bouillon devient blanc et laiteux à force de bouillir. Le nom veut dire « cuit à l'eau » : ni dashi ni assaisonnement au départ, seulement du poulet et de l'eau, et tout le goût vient du collagène extrait des os.",
     en:"A chicken hotpot whose broth turns white and milky from long boiling. The name means cooked in water: no dashi and no seasoning at the start, only chicken and water, and all the flavour comes from collagen drawn out of the bones."},
  i:[['chicken',1.5,'kg'],['chicken_bones',1,'kg'],['napa_cabbage',600,'g'],['scallion',2,'bunch'],['tofu',400,'g'],['shiitake_mushrooms',200,'g'],['ponzu',200,'ml'],['daikon',200,'g'],['chili_pepper',2,'pc'],['short_grain_rice',300,'g'],['egg',2,'pc']],
  s:{fr:["Faites bouillir les carcasses à gros bouillons deux heures, à découvert : ici l'ébullition franche est recherchée, elle émulsionne le collagène.","C'est exactement l'inverse d'un bouillon clair — un mizutaki qui reste transparent est un mizutaki raté.","Ajoutez les morceaux de poulet et laissez cuire quarante minutes de plus, sans sel ni soja.","Apportez la marmite sur la table et faites-y cuire les légumes au fur et à mesure, en trempant chaque bouchée dans le ponzu.","À la fin, versez du riz dans le bouillon restant et liez à l'œuf battu : ce zosui clôt le repas."],
     en:["Boil the carcasses hard for two hours, uncovered: here a rolling boil is wanted, it emulsifies the collagen.","This is the exact opposite of a clear broth — a mizutaki that stays transparent has failed.","Add the jointed chicken and cook forty minutes more, with no salt and no soy.","Bring the pot to the table and cook the vegetables in it as you go, dipping each mouthful in ponzu.","At the end, tip rice into the remaining broth and bind with beaten egg: this zosui closes the meal."]} },

{ id:'karashi-renkon', c:'as', lat:32.803, lon:130.708, base:6, prep:60, cook:20, diff:2, tags:['veg','fry','festive'],
  art:{v:'plate',bg:'#33291f',plate:'#f4ead4',style:'other',food:['#e8c46a','#f2dfa8','#e8a032','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Karashi renkon',en:'Karashi renkon'},
  p:{fr:'Kumamoto, Japon',en:'Kumamoto, Japan'},
  d:{fr:"Des racines de lotus dont les trous sont farcis de miso à la moutarde, panées et frites. Le plat a été créé au XVIIe siècle pour un seigneur de Kumamoto de santé fragile ; la recette resta secrète de famille jusqu'à la fin de l'ère Meiji.",
     en:"Lotus root with its holes packed with mustard miso, battered and fried. It was created in the seventeenth century for a sickly lord of Kumamoto; the recipe stayed a family secret until the end of the Meiji era."},
  i:[['lotus_root',600,'g'],['miso_paste',150,'g'],['mustard_powder',40,'g'],['honey',30,'g'],['flour',150,'g'],['turmeric',5,'g'],['egg',1,'pc'],['frying_oil',1,'l'],['rice_vinegar',60,'ml'],['sake',30,'ml']],
  s:{fr:["Faites cuire les tronçons de lotus à l'eau vinaigrée vingt minutes, pour qu'ils restent blancs et légèrement croquants.","Le vinaigre empêche l'oxydation : sans lui, le lotus brunit en quelques minutes à l'air.","Mêlez le miso, la moutarde et le miel, et laissez reposer une heure — la moutarde a besoin de temps pour développer son piquant.","Farcissez les trous en pressant le miso avec le pouce, par les deux extrémités, jusqu'à ce qu'ils soient pleins.","Enrobez d'une pâte à la farine et au curcuma, et frites à 170 °C. Servez froid, tranché fin."],
     en:["Boil the lotus lengths in acidulated water for twenty minutes, so they stay white and slightly crisp.","The vinegar prevents oxidation: without it, lotus browns within minutes in the air.","Mix the miso, mustard and honey, and rest an hour — mustard needs time to develop its heat.","Pack the holes by pressing the miso in with your thumb, from both ends, until they are full.","Coat in a flour and turmeric batter, and fry at 170°C. Serve cold, thinly sliced."]} },

{ id:'chicken-nanban', c:'as', lat:32.582, lon:131.665, base:4, prep:60, cook:25, diff:2, tags:['poultry','fry','comfort'],
  art:{v:'plate',bg:'#33291f',plate:'#f4ead4',style:'other',food:['#c9924a','#f4f0e6','#e8c46a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Chicken nanban',en:'Chicken nanban'},
  p:{fr:'Nobeoka, Miyazaki, Japon',en:'Nobeoka, Miyazaki, Japan'},
  d:{fr:"Du poulet frit trempé dans un vinaigre sucré puis nappé d'une sauce tartare épaisse. Nanban désigne au Japon tout ce qui vient des « barbares du Sud », c'est-à-dire des Portugais : la technique du poisson mariné au vinaigre après friture leur est directement empruntée.",
     en:"Fried chicken dipped in sweet vinegar then covered with a thick tartare sauce. Nanban in Japan means anything from the southern barbarians, that is the Portuguese: the technique of vinegar-marinating fried fish is borrowed directly from them."},
  i:[['chicken_thighs',800,'g'],['flour',100,'g'],['egg',4,'pc'],['rice_vinegar',150,'ml'],['soy_sauce',80,'ml'],['sugar',80,'g'],['mayonnaise',200,'g'],['onion',1,'pc'],['pickles',60,'g'],['parsley',1,'bunch'],['frying_oil',1.5,'l'],['chili_pepper',1,'pc']],
  s:{fr:["Enrobez le poulet de farine puis d'œuf battu, sans chapelure : c'est un enrobage à la portugaise, léger et souple.","Frites à 170 °C, huit minutes, jusqu'à ce que la croûte dore sans durcir.","Plongez les morceaux brûlants dans le vinaigre sucré tiède, dix secondes seulement.","La viande chaude absorbe le vinaigre par capillarité ; refroidie, elle ne prend plus rien et le plat reste plat.","Préparez la tartare aux œufs durs hachés, oignon et cornichons, et nappez généreusement au moment de servir."],
     en:["Coat the chicken in flour then beaten egg, with no breadcrumbs: a Portuguese-style coating, light and supple.","Fry at 170°C for eight minutes, until the crust colours without hardening.","Plunge the scalding pieces into the warm sweet vinegar, ten seconds only.","Hot meat draws in the vinegar by capillary action; cooled, it takes up nothing and the dish falls flat.","Make the tartare with chopped hard-boiled egg, onion and gherkins, and spoon it on generously as you serve."]} }
,

{ id:'basashi', c:'as', lat:32.810, lon:130.700, base:4, prep:40, cook:0, diff:2, tags:['fresh','festive','beef'],
  art:{v:'plate',bg:'#2c3440',plate:'#f4ead4',style:'other',food:['#c9302a','#e07a6a','#f4f0e6','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Basashi',en:'Basashi'},
  p:{fr:'Kumamoto, Japon',en:'Kumamoto, Japan'},
  d:{fr:"Du cheval cru tranché fin, servi avec ail, gingembre et soja sucré. Kumamoto en est la capitale depuis le XVIe siècle, quand un seigneur assiégé en Corée aurait dû manger ses montures ; la viande de cheval porte peu de parasites, ce qui rend sa consommation crue plus sûre que celle du porc.",
     en:"Raw horse sliced thin, served with garlic, ginger and sweet soy. Kumamoto has been its capital since the sixteenth century, when a lord besieged in Korea is said to have had to eat his mounts; horsemeat carries few parasites, which makes eating it raw safer than pork."},
  i:[['horse_meat',400,'g'],['soy_sauce',80,'ml'],['garlic',4,'clove'],['ginger',30,'g'],['scallion',1,'bunch'],['shiso',8,'pc'],['onion',1,'pc'],['sesame_oil',20,'ml'],['mirin',20,'ml']],
  s:{fr:["N'employez que de la viande de cheval expressément vendue pour être mangée crue, congelée à -20 °C pendant 48 heures au préalable.","Cette congélation est une obligation sanitaire au Japon depuis 2011 : elle neutralise le sarcocystis, seul parasite réellement présent chez le cheval.","Laissez décongeler lentement au réfrigérateur, jamais à l'eau, et tranchez la viande encore très froide.","Coupez en travers de la fibre, à trois millimètres, avec un couteau parfaitement affûté et essuyé entre chaque tranche.","Servez avec de l'ail et du gingembre râpés, de l'oignon émincé et un soja sucré au mirin."],
     en:["Use only horsemeat expressly sold for raw consumption, previously frozen at -20°C for 48 hours.","That freezing has been a legal requirement in Japan since 2011: it neutralises sarcocystis, the only parasite genuinely found in horses.","Thaw slowly in the refrigerator, never in water, and slice the meat while still very cold.","Cut across the grain at three millimetres with a perfectly sharp knife, wiped between each slice.","Serve with grated garlic and ginger, sliced onion and soy sweetened with mirin."]} },

{ id:'sara-udon', c:'as', lat:32.750, lon:129.877, base:4, prep:40, cook:25, diff:2, tags:['noodles','sea','comfort'],
  art:{v:'plate',bg:'#33291f',plate:'#f0e4c8',style:'noodle',food:['#e8c46a','#f4f0e6','#7fae5a','#e07a6a'],garnish:'#7fae6a'},
  n:{fr:'Sara udon',en:'Sara udon'},
  p:{fr:'Nagasaki, Japon',en:'Nagasaki, Japan'},
  d:{fr:"Des nouilles fines et croustillantes couvertes d'un sauté de légumes et de fruits de mer en sauce. Malgré son nom, il ne contient aucun udon : les nouilles sont de fines vermicelles frites, et le plat a été inventé vers 1900 par le même restaurateur chinois que le champon.",
     en:"Fine crisp noodles under a sauced stir-fry of vegetables and seafood. Despite the name it contains no udon: the noodles are fine fried vermicelli, and the dish was invented around 1900 by the same Chinese restaurateur as champon."},
  i:[['fried_noodles',300,'g'],['pork_belly',200,'g'],['shrimp',200,'g'],['squid',150,'g'],['napa_cabbage',400,'g'],['bean_sprouts',200,'g'],['carrot',1,'pc'],['fish_cake',100,'g'],['chicken_broth',600,'ml'],['cornstarch',40,'g'],['oyster_sauce',40,'ml'],['soy_sauce',30,'ml'],['sesame_oil',20,'ml']],
  s:{fr:["Faites sauter le porc puis les fruits de mer à feu très vif, séparément, et réservez-les.","Ajoutez les légumes par ordre de fermeté : carotte, chou, puis pousses de soja en dernier, dix secondes seulement.","Mouillez au bouillon et liez à la fécule délayée dans l'eau froide, jamais versée sèche.","La sauce doit être épaisse et brillante : trop liquide, elle détrempe les nouilles avant qu'on arrive à table.","Disposez les nouilles frites dans l'assiette et versez le sauté par-dessus au dernier moment. Se mange dans les cinq minutes."],
     en:["Stir-fry the pork then the seafood over fierce heat, separately, and set them aside.","Add the vegetables in order of firmness: carrot, cabbage, then bean sprouts last, for ten seconds only.","Moisten with broth and thicken with cornflour slaked in cold water, never tipped in dry.","The sauce must be thick and glossy: too thin, it soaks the noodles before the plate reaches the table.","Lay the fried noodles on the plate and pour the stir-fry over at the last moment. Eaten within five minutes."]} },

{ id:'toriten', c:'as', lat:33.238, lon:131.613, base:4, prep:40, cook:20, diff:2, tags:['poultry','fry','fast'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'other',food:['#e8c46a','#f2dfa8','#c9924a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Toriten',en:'Toriten'},
  p:{fr:'Oita, Japon',en:'Oita, Japan'},
  d:{fr:"Du poulet en tempura, mariné avant d'être enrobé, servi avec du ponzu. Il se distingue du karaage par l'enrobage : ici une pâte à tempura légère et non de la fécule, et la pâte reste pâle et souple au lieu de croustiller sèchement.",
     en:"Chicken in tempura batter, marinated before coating, served with ponzu. It differs from karaage in the coating: a light tempura batter rather than starch, and the batter stays pale and supple instead of drily crisp."},
  i:[['chicken_breast',700,'g'],['soy_sauce',60,'ml'],['sake',40,'ml'],['garlic',4,'clove'],['ginger',30,'g'],['flour',200,'g'],['egg',1,'pc'],['ice_water',300,'ml'],['frying_oil',1.5,'l'],['ponzu',100,'ml'],['mustard',20,'g'],['cabbage',200,'g']],
  s:{fr:["Faites mariner le poulet trente minutes au soja, saké, ail et gingembre, puis épongez-le soigneusement.","Préparez la pâte à tempura avec de l'eau glacée et mélangez à peine, en laissant des grumeaux visibles.","Un mélange trop travaillé développe le gluten et donne une pâte lourde qui absorbe l'huile.","N'utilisez la pâte que dans les dix minutes : passé ce délai, elle se réchauffe et perd sa légèreté.","Frites à 175 °C, trois minutes. Servez avec du ponzu et de la moutarde japonaise, jamais avec la sauce à tempura habituelle."],
     en:["Marinate the chicken thirty minutes in soy, sake, garlic and ginger, then blot it thoroughly.","Make the tempura batter with iced water and barely mix, leaving visible lumps.","Overworked batter develops gluten and turns heavy, drinking up oil.","Use the batter within ten minutes: after that it warms and loses its lightness.","Fry at 175°C for three minutes. Serve with ponzu and Japanese mustard, never the usual tempura sauce."]} },

{ id:'taco-rice', c:'as', lat:26.362, lon:127.756, base:4, prep:30, cook:25, diff:1, tags:['rice','beef','fast'],
  art:{v:'plate',bg:'#33291f',plate:'#f0e4c8',style:'rice',food:['#8f4a3a','#f4f0e6','#7fae5a','#e07a6a'],garnish:'#7fae6a'},
  n:{fr:'Taco rice',en:'Taco rice'},
  p:{fr:'Kin, Okinawa, Japon',en:'Kin, Okinawa, Japan'},
  d:{fr:"De la viande de taco épicée, du fromage et de la salade servis sur du riz japonais. Inventé en 1984 par un restaurateur de Kin, près de la base américaine : les soldats voulaient des tacos, les locaux mangeaient du riz, et le compromis est devenu le plat emblématique d'Okinawa.",
     en:"Spiced taco meat, cheese and salad served over Japanese rice. Invented in 1984 by a restaurateur in Kin, near the American base: the soldiers wanted tacos, the locals ate rice, and the compromise became Okinawa's emblematic dish."},
  i:[['ground_beef',500,'g'],['short_grain_rice',400,'g'],['onion',1,'pc'],['cheddar_cheese',200,'g'],['lettuce',12,'pc'],['ripe_tomato',300,'g'],['chili_powder',15,'g'],['cumin',10,'g'],['ketchup',60,'g'],['worcestershire',30,'ml'],['garlic',4,'clove'],['salsa',150,'g']],
  s:{fr:["Faites revenir le bœuf haché avec l'oignon jusqu'à ce qu'il perde toute son eau et commence à attacher.","Ajoutez les épices et laissez-les griller trente secondes dans le gras avant de mouiller au ketchup et au worcestershire.","Laissez réduire jusqu'à ce que la viande soit sèche et brillante : une viande en sauce détremperait le riz.","Servez sur du riz japonais court, jamais du riz long — c'est ce qui fait tenir l'ensemble à la cuillère.","Montez dans l'ordre : riz, viande, fromage râpé qui fond au contact, puis salade et tomate crues par-dessus."],
     en:["Fry the minced beef with the onion until it loses all its water and begins to catch.","Add the spices and toast them thirty seconds in the fat before moistening with ketchup and Worcestershire.","Reduce until the meat is dry and glossy: meat in sauce would soak the rice.","Serve on short-grain Japanese rice, never long grain — that is what holds it together on a spoon.","Build in order: rice, meat, grated cheese that melts on contact, then raw lettuce and tomato on top."]} },

{ id:'jimami-tofu', c:'as', lat:26.212, lon:127.679, base:6, prep:480, cook:40, diff:3, tags:['veg','slow','comfort'],
  art:{v:'plate',bg:'#33291f',plate:'#f4ead4',style:'other',food:['#f2dfa8','#f4f0e6','#8f7a5a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Jimami tofu',en:'Jimami tofu'},
  p:{fr:'Naha, Okinawa, Japon',en:'Naha, Okinawa, Japan'},
  d:{fr:"Un « tofu » d'arachide qui ne contient pas de soja, pris à la fécule de patate douce. Sa texture est celle d'un flan très ferme et non d'un tofu : il ne coagule pas, il gélatinise, et c'est une confusion de nom plus qu'une parenté de technique.",
     en:"A peanut tofu containing no soy at all, set with sweet potato starch. Its texture is that of a very firm custard rather than tofu: it does not coagulate, it gelatinises, making the name a confusion rather than a kinship of technique."},
  i:[['peanuts',300,'g'],['sweet_potato_starch',100,'g'],['water',900,'ml'],['soy_sauce',60,'ml'],['mirin',30,'ml'],['sugar',40,'g'],['ginger',20,'g'],['wasabi',15,'g'],['dashi_stock',100,'ml'],['salt',null,'']],
  s:{fr:["Faites tremper les cacahuètes crues huit heures, puis frottez-les entre les mains pour retirer toutes les peaux rouges.","Ces peaux donnent une amertume tenace et tachent la préparation de points bruns.","Mixez avec l'eau et filtrez à l'étamine en pressant très fort : c'est le lait d'arachide, il doit être parfaitement lisse.","Délayez la fécule dans ce lait froid, puis chauffez à feu doux en remuant sans arrêt vingt minutes.","Le mélange épaissit brutalement puis devient élastique et se décolle du fond. Versez en moule et laissez prendre trois heures au frais."],
     en:["Soak raw peanuts eight hours, then rub them between your hands to remove every red skin.","Those skins give a stubborn bitterness and speckle the preparation brown.","Blend with the water and strain through muslin, pressing very hard: this is the peanut milk, and it must be perfectly smooth.","Slake the starch in that cold milk, then heat gently, stirring without pause for twenty minutes.","The mixture thickens abruptly then turns elastic and pulls from the base. Pour into a mould and set three hours in the cold."]} },

{ id:'umibudo', c:'as', lat:24.805, lon:125.281, base:4, prep:15, cook:0, diff:1, tags:['sea','fresh','fast'],
  art:{v:'bowl',bg:'#26485c',plate:'#f4ead4',style:'salad',food:['#4f6f3a','#7fae5a','#f4f0e6','#f0e8d0'],garnish:'#6fbf8f'},
  n:{fr:'Umibudo',en:'Umibudo'},
  p:{fr:'Miyakojima, Okinawa, Japon',en:'Miyakojima, Okinawa, Japan'},
  d:{fr:"Une algue en grappes de petites billes qui éclatent sous la dent. Chaque bille est une vésicule remplie d'eau de mer ; c'est cette explosion salée qui fait tout l'intérêt, et elle disparaît irrémédiablement au contact du froid.",
     en:"A seaweed in clusters of small beads that burst under the tooth. Each bead is a vesicle full of seawater; that salty burst is the whole point, and it is lost irretrievably on contact with cold."},
  i:[['sea_grapes',200,'g'],['ponzu',80,'ml'],['soy_sauce',30,'ml'],['ginger',20,'g'],['tofu',200,'g'],['shiso',6,'pc']],
  s:{fr:["Ne mettez jamais les umibudo au réfrigérateur : le froid fait dégonfler les vésicules, qui ne se regonflent plus jamais.","Conservez-les à température ambiante, dans leur eau salée, et consommez-les dans les trois jours.","Rincez-les à l'eau de mer ou à l'eau très salée, jamais à l'eau douce — l'osmose les ferait éclater instantanément.","Trempez-les trente secondes dans l'eau glacée juste avant de servir, ce qui les raffermit sans les faire dégonfler.","Ne versez pas la sauce dessus : servez-la à côté et trempez chaque bouchée, sinon le sel du soja les vide."],
     en:["Never refrigerate umibudo: cold deflates the vesicles, and they never plump again.","Keep them at room temperature in their salt water, and eat them within three days.","Rinse them in seawater or heavily salted water, never fresh water — osmosis would burst them instantly.","Dip them thirty seconds in iced water just before serving, which firms them without deflating them.","Do not pour the sauce over: serve it alongside and dip each mouthful, or the soy's salt empties them."]} },

{ id:'dorayaki', c:'as', lat:35.712, lon:139.775, base:6, prep:60, cook:25, diff:2, tags:['sweet','street','bake'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'other',food:['#c9924a','#3a2018','#e8c46a','#f2dfa8'],garnish:'#c9754a'},
  n:{fr:'Dorayaki',en:'Dorayaki'},
  p:{fr:'Ueno, Tokyo, Japon',en:'Ueno, Tokyo, Japan'},
  d:{fr:"Deux pancakes moelleux collés autour d'une pâte de haricots rouges. Le nom veut dire « grillé sur un gong » : la légende veut qu'un samouraï blessé ait laissé son gong chez un paysan, qui s'en servit de plaque de cuisson.",
     en:"Two soft pancakes joined around red bean paste. The name means grilled on a gong: legend has a wounded samurai leaving his gong with a farmer, who used it as a griddle."},
  i:[['flour',200,'g'],['egg',4,'pc'],['sugar',150,'g'],['honey',40,'g'],['mirin',20,'ml'],['baking_soda',5,'g'],['water',60,'ml'],['red_bean_paste',400,'g']],
  s:{fr:["Fouettez les œufs, le sucre, le miel et le mirin jusqu'à ce que le mélange blanchisse et double de volume.","Incorporez la farine tamisée sans travailler, puis laissez reposer la pâte trente minutes au frais.","Délayez le bicarbonate dans l'eau et ajoutez-le juste avant la cuisson : ajouté trop tôt, il perd tout son effet.","Cuisez à la poêle antiadhésive sans matière grasse, sur feu doux, jusqu'à ce que des bulles crèvent la surface.","Essuyez la poêle entre chaque pancake : la moindre trace de gras tache la surface et le dorayaki perd sa couleur unie."],
     en:["Whisk the eggs, sugar, honey and mirin until the mixture pales and doubles in volume.","Fold in the sifted flour without working it, then rest the batter thirty minutes in the cold.","Slake the bicarbonate in the water and add it just before cooking: added early, it loses all its lift.","Cook in a non-stick pan with no fat, over low heat, until bubbles break the surface.","Wipe the pan between each pancake: the least trace of fat marks the surface and the dorayaki loses its even colour."]} },

{ id:'nikujaga', c:'as', lat:34.249, lon:132.566, base:4, prep:30, cook:45, diff:1, tags:['beef','stew','comfort'],
  art:{v:'pot',bg:'#33291f',plate:'#f0e4c8',style:'stew',food:['#e8c46a','#8f5a3a','#f4f0e6','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Nikujaga',en:'Nikujaga'},
  p:{fr:'Kure, Hiroshima, Japon',en:'Kure, Hiroshima, Japan'},
  d:{fr:"Un ragoût de bœuf et de pommes de terre au soja sucré, plat familial par excellence. Il serait né dans la marine impériale vers 1870 : un amiral formé en Angleterre voulait un ragoût de bœuf, et le cuisinier, faute de vin et de sauce brune, employa soja et sucre.",
     en:"A beef and potato stew in sweet soy, the family dish par excellence. It is said to have been born in the imperial navy around 1870: an admiral trained in England wanted a beef stew, and the cook, lacking wine and brown sauce, used soy and sugar."},
  i:[['beef_sirloin',300,'g'],['potato',700,'g'],['onion',2,'pc'],['carrot',2,'pc'],['konjac',200,'g'],['soy_sauce',80,'ml'],['mirin',60,'ml'],['sake',60,'ml'],['sugar',40,'g'],['dashi_stock',500,'ml'],['peas',100,'g'],['sesame_oil',20,'ml']],
  s:{fr:["Employez du bœuf tranché très fin, presque translucide : le ragoût cuit quarante minutes et une viande épaisse durcirait.","Faites-la revenir d'abord, brièvement, puis ajoutez les légumes en gros morceaux et le dashi.","Ajoutez le sucre avant le soja, toujours : les grosses molécules de sucre pénètrent plus lentement, et l'ordre inverse les empêche d'entrer.","Posez un otoshibuta, un couvercle plus petit que la casserole posé à même le liquide, qui répartit le bouillon sans le faire réduire trop vite.","Laissez mijoter trente minutes, puis éteignez et laissez refroidir : c'est en refroidissant que le goût pénètre les pommes de terre."],
     en:["Use very thinly sliced beef, almost translucent: the stew cooks forty minutes and a thick piece would toughen.","Fry it first, briefly, then add the vegetables in large pieces and the dashi.","Add the sugar before the soy, always: large sugar molecules penetrate more slowly, and the reverse order shuts them out.","Set an otoshibuta, a lid smaller than the pan resting on the liquid itself, which spreads the broth without reducing it too fast.","Simmer thirty minutes, then turn off the heat and let it cool: it is in cooling that the flavour enters the potatoes."]} }
,

{ id:'tandoori-chicken', c:'as', lat:28.614, lon:77.209, base:4, prep:480, cook:30, diff:2, tags:['poultry','grill','festive'],
  art:{v:'plate',bg:'#33291f',plate:'#f0e4c8',style:'grill',food:['#c9302a','#8f4a3a','#e8c46a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Poulet tandoori',en:'Tandoori chicken'},
  p:{fr:'Delhi, Inde',en:'Delhi, India'},
  d:{fr:"Du poulet mariné au yaourt et aux épices, rôti dans un four d'argile vertical. Il a été mis au point à Peshawar avant la Partition puis apporté à Delhi en 1947 par Kundan Lal Gujral, qui a aussi inventé le butter chicken pour recycler les restes.",
     en:"Chicken marinated in yoghurt and spices, roasted in a vertical clay oven. It was developed in Peshawar before Partition then brought to Delhi in 1947 by Kundan Lal Gujral, who also invented butter chicken to use up the leftovers."},
  i:[['chicken',1.4,'kg'],['plain_yogurt',300,'g'],['ginger',40,'g'],['garlic',10,'clove'],['garam_masala',15,'g'],['kashmiri_chili',20,'g'],['cumin',10,'g'],['coriander_seeds',10,'g'],['lemon',3,'pc'],['mustard_oil',60,'ml'],['onion',2,'pc'],['salt',null,'']],
  s:{fr:["Retirez toute la peau et entaillez la chair jusqu'à l'os, tous les deux centimètres.","La peau empêche la marinade d'entrer et brûle avant que la chair cuise : c'est pourquoi le tandoori est toujours sans peau.","Faites une première marinade courte au citron, au sel et au piment, une heure, pour ouvrir les fibres.","Égouttez le yaourt une nuit dans une étamine avant la seconde marinade : un yaourt liquide glisse au lieu d'adhérer.","Faites cuire six heures plus tard à 250 °C, sur grille et à découvert, en badigeonnant d'huile de moutarde deux fois."],
     en:["Remove all the skin and score the flesh to the bone every two centimetres.","Skin stops the marinade entering and burns before the flesh cooks: that is why tandoori is always skinless.","Make a first short marinade of lemon, salt and chilli, one hour, to open the fibres.","Drain the yoghurt overnight in muslin before the second marinade: runny yoghurt slides off instead of clinging.","Cook six hours later at 250°C, on a rack and uncovered, brushing with mustard oil twice."]} },

{ id:'chole-bhature', c:'as', lat:28.650, lon:77.230, base:4, prep:720, cook:90, diff:3, tags:['legume','fry','comfort'],
  art:{v:'plate',bg:'#33291f',plate:'#f0e4c8',style:'other',food:['#5a3020','#e8c46a','#f2dfa8','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Chole bhature',en:'Chole bhature'},
  p:{fr:'Delhi, Inde',en:'Delhi, India'},
  d:{fr:"Un curry de pois chiches épicé accompagné d'un pain frit gonflé. La couleur très sombre du chole ne vient pas d'un colorant mais du thé noir : on fait cuire les pois chiches avec un sachet de thé, qui les teint sans rien apporter au goût.",
     en:"A spiced chickpea curry with a puffed fried bread. The chole's very dark colour comes not from any colouring but from black tea: the chickpeas are cooked with a tea bag, which stains them without affecting the flavour."},
  i:[['chickpeas',400,'g'],['black_tea',5,'g'],['onion',3,'pc'],['ripe_tomato',400,'g'],['ginger',40,'g'],['garlic',8,'clove'],['garam_masala',15,'g'],['amchur',10,'g'],['flour',400,'g'],['plain_yogurt',150,'g'],['semolina',60,'g'],['frying_oil',1.5,'l'],['sunflower_oil',80,'ml'],['salt',null,'']],
  s:{fr:["Faites tremper les pois chiches une nuit avec une pincée de bicarbonate, puis cuisez-les avec le sachet de thé.","Retirez le thé après vingt minutes : au-delà, ses tanins rendent les pois chiches amers et légèrement astringents.","Faites brunir les oignons longuement, quinze minutes au moins, jusqu'à ce qu'ils fondent en pâte sombre.","Pour les bhature, employez une pâte au yaourt et à la semoule, laissée fermenter trois heures — c'est elle qui les fait gonfler.","Frites à 190 °C en pressant le pain sous l'huile deux secondes : il se gonfle en ballon aussitôt."],
     en:["Soak the chickpeas overnight with a pinch of bicarbonate, then cook them with the tea bag.","Take out the tea after twenty minutes: longer, and its tannins turn the chickpeas bitter and slightly astringent.","Brown the onions at length, fifteen minutes at least, until they melt into a dark paste.","For the bhature, use a yoghurt and semolina dough left to ferment three hours — that is what makes them puff.","Fry at 190°C, holding the bread under the oil for two seconds: it balloons at once."]} },

{ id:'aloo-paratha', c:'as', lat:31.634, lon:74.872, base:4, prep:60, cook:30, diff:2, tags:['bread','veg','breakfast'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'flat',food:['#e8c46a','#f2dfa8','#c9924a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Aloo paratha',en:'Aloo paratha'},
  p:{fr:'Amritsar, Pendjab, Inde',en:'Amritsar, Punjab, India'},
  d:{fr:"Un pain plat farci de pomme de terre épicée, cuit au ghee sur la plaque. C'est le petit-déjeuner du Pendjab, servi avec du yaourt, du beurre blanc et des pickles ; la farce doit être froide et parfaitement sèche, faute de quoi le pain se déchire.",
     en:"A flatbread stuffed with spiced potato, cooked in ghee on a griddle. It is the Punjabi breakfast, served with yoghurt, white butter and pickles; the filling must be cold and perfectly dry, or the bread tears."},
  i:[['whole_wheat_flour',400,'g'],['potato',600,'g'],['onion',1,'pc'],['green_chili',3,'pc'],['ginger',30,'g'],['cilantro',1,'bunch'],['cumin',10,'g'],['amchur',8,'g'],['ghee',120,'g'],['plain_yogurt',200,'g'],['water',250,'ml'],['salt',null,'']],
  s:{fr:["Cuisez les pommes de terre à la vapeur, jamais à l'eau : bouillies, elles se gorgent et la farce devient humide.","Écrasez-les au presse-purée et laissez-les refroidir complètement, à découvert, une bonne demi-heure.","Pétrissez une pâte souple à la farine complète et laissez-la reposer trente minutes sous un linge humide.","Formez une coupelle dans la paume, garnissez généreusement et refermez en remontant les bords, puis aplatissez à la main avant le rouleau.","Cuisez sur plaque chaude, en badigeonnant de ghee, jusqu'à ce que des taches brunes apparaissent des deux côtés."],
     en:["Steam the potatoes, never boil them: boiled, they take on water and the filling turns wet.","Rice them and cool them completely, uncovered, for a good half hour.","Knead a soft wholemeal dough and rest it thirty minutes under a damp cloth.","Form a cup in your palm, fill generously and close by drawing up the edges, then flatten by hand before using the pin.","Cook on a hot griddle, brushing with ghee, until brown spots appear on both sides."]} },

{ id:'naan-beurre', c:'as', lat:28.620, lon:77.215, base:6, prep:180, cook:20, diff:2, tags:['bread','bake','comfort'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'flat',food:['#f2dfa8','#e8c46a','#f4f0e6','#c9924a'],garnish:'#7fae6a'},
  n:{fr:'Naan au beurre',en:'Butter naan'},
  p:{fr:'Delhi, Inde',en:'Delhi, India'},
  d:{fr:"Un pain plat levé, collé à la paroi du tandoor et badigeonné de ghee. Contrairement au chapati, le naan contient du levain et de la farine blanche : c'était un pain de cour, réservé aux cuisines royales mogholes jusqu'au XXe siècle.",
     en:"A leavened flatbread slapped onto the wall of the tandoor and brushed with ghee. Unlike chapati, naan contains leavening and white flour: it was a court bread, confined to Mughal royal kitchens until the twentieth century."},
  i:[['flour',500,'g'],['plain_yogurt',150,'g'],['whole_milk',150,'ml'],['fresh_yeast',10,'g'],['sugar',20,'g'],['egg',1,'pc'],['ghee',100,'g'],['nigella_seeds',10,'g'],['baking_soda',3,'g'],['salt',null,'']],
  s:{fr:["Pétrissez une pâte molle et laissez-la lever deux heures : elle doit rester légèrement collante au doigt.","Une pâte ferme donne un naan cassant ; c'est l'humidité qui crée la vapeur et les grosses bulles.","Étalez en larme allongée, à la main autant que possible, et mouillez une face à l'eau avant de la coller au four.","Si vous n'avez pas de tandoor, chauffez une poêle en fonte à blanc, posez le naan face mouillée dessous et couvrez.","Retournez la poêle vers la flamme pour dorer le dessus, puis badigeonnez de ghee fondu à la sortie."],
     en:["Knead a soft dough and prove it two hours: it should stay slightly tacky to the finger.","A firm dough gives a brittle naan; it is the moisture that creates the steam and the big bubbles.","Shape into a teardrop, by hand as far as possible, and wet one face with water before slapping it into the oven.","With no tandoor, heat a cast-iron pan white hot, lay the naan wet side down and cover.","Invert the pan towards the flame to colour the top, then brush with melted ghee as it comes off."]} },

{ id:'yakhni-pulao', c:'as', lat:34.084, lon:74.797, base:6, prep:60, cook:90, diff:3, tags:['rice','lamb','festive'],
  art:{v:'pot',bg:'#33291f',plate:'#f0e4c8',style:'rice',food:['#f4f0e6','#f0e8d0','#8f5a3a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Yakhni pulao',en:'Yakhni pulao'},
  p:{fr:'Srinagar, Cachemire, Inde',en:'Srinagar, Kashmir, India'},
  d:{fr:"Un riz cuit dans un bouillon d'agneau parfumé, pâle et non pimenté. Il se distingue du biryani sur un point décisif : ici riz et viande cuisent ensemble dans le même bouillon, quand le biryani superpose deux préparations cuites séparément.",
     en:"Rice cooked in a scented lamb broth, pale and unspiced with chilli. It differs from biryani on one decisive point: here rice and meat cook together in one broth, whereas biryani layers two separately cooked preparations."},
  i:[['lamb_shoulder',800,'g'],['basmati_rice',500,'g'],['plain_yogurt',200,'g'],['fennel_seed',15,'g'],['ground_ginger',10,'g'],['cardamom',8,'pc'],['cinnamon_stick',2,'pc'],['clove',8,'pc'],['bay_leaf',3,'pc'],['onion',3,'pc'],['ghee',100,'g'],['black_peppercorns',10,'g'],['salt',null,'']],
  s:{fr:["Faites bouillir l'agneau avec les épices entières enfermées dans une mousseline, quarante minutes, et filtrez le bouillon.","La mousseline permet de retirer toutes les épices d'un coup : dans un pulao, on ne doit jamais croquer un clou de girofle.","Faites tremper le riz basmati trente minutes seulement, puis égouttez-le une demi-heure à découvert.","Faites frire les oignons jusqu'au brun profond, réservez-en la moitié, et faites revenir la viande dans le reste.","Mouillez du bouillon mesuré, un volume et demi pour un de riz, et cuisez quinze minutes à couvert puis dix minutes hors du feu."],
     en:["Boil the lamb with the whole spices tied in muslin for forty minutes, and strain the broth.","The muslin lets you remove every spice at once: in a pulao one should never bite into a clove.","Soak the basmati for thirty minutes only, then drain it half an hour uncovered.","Fry the onions to deep brown, set half aside, and brown the meat in the rest.","Moisten with measured broth, one and a half parts to one of rice, and cook fifteen minutes covered then ten off the heat."]} },

{ id:'laal-maas', c:'as', lat:26.238, lon:73.024, base:6, prep:60, cook:90, diff:3, tags:['lamb','stew','spicy'],
  art:{v:'pot',bg:'#33291f',plate:'#f0e4c8',style:'stew',food:['#c9302a','#8f2a2a','#e8c46a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Laal maas',en:'Laal maas'},
  p:{fr:'Jodhpur, Rajasthan, Inde',en:'Jodhpur, Rajasthan, India'},
  d:{fr:"Un curry d'agneau d'un rouge intense, aux piments mathania et à l'ail. Il était le plat de chasse des rois rajputs : le piment en quantité masquait le goût très fort du gibier, et l'absence de tomate ou d'oignon en fait un curry d'une simplicité déroutante.",
     en:"An intensely red lamb curry with mathania chillies and garlic. It was the hunting dish of the Rajput kings: chilli in quantity masked the strong taste of game, and the absence of tomato or onion makes it a curry of disconcerting simplicity."},
  i:[['lamb_shoulder',1,'kg'],['kashmiri_chili',40,'g'],['garlic',20,'clove'],['plain_yogurt',300,'g'],['ghee',150,'g'],['coriander_seeds',20,'g'],['cumin',10,'g'],['clove',8,'pc'],['cardamom',6,'pc'],['onion',2,'pc'],['salt',null,'']],
  s:{fr:["Employez des piments mathania ou à défaut kashmiri : ils colorent intensément sans brûler autant qu'ils en ont l'air.","Faites-les tremper vingt minutes dans l'eau chaude puis mixez-les en pâte lisse avec l'ail.","Faites revenir la viande dans le ghee à feu vif, jusqu'à ce qu'elle soit dorée de tous côtés.","Ajoutez le yaourt battu hors du feu, cuillerée par cuillerée en remuant : versé d'un coup dans une casserole chaude, il tranche immanquablement.","Laissez mijoter une heure et demie à couvert. Le ghee doit remonter en surface, signe que le curry est prêt."],
     en:["Use mathania chillies or failing that Kashmiri: they colour intensely without burning as much as they look.","Soak them twenty minutes in hot water then blend them to a smooth paste with the garlic.","Brown the meat in ghee over fierce heat, until coloured on all sides.","Add the beaten yoghurt off the heat, a spoonful at a time, stirring: poured in at once into a hot pan it splits without fail.","Simmer an hour and a half covered. The ghee should rise to the surface, the sign the curry is ready."]} },

{ id:'rajma-chawal', c:'as', lat:28.630, lon:77.220, base:6, prep:720, cook:120, diff:2, tags:['legume','rice','comfort'],
  art:{v:'bowl',bg:'#33291f',plate:'#f0e4c8',style:'stew',food:['#5a2a2a','#f4f0e6','#e8c46a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Rajma chawal',en:'Rajma chawal'},
  p:{fr:'Delhi, Inde',en:'Delhi, India'},
  d:{fr:"Des haricots rouges mijotés servis sur du riz blanc, plat familial du nord de l'Inde. Le haricot rouge est américain : il est arrivé par les Portugais au XVIe siècle et s'est si bien acclimaté qu'il passe aujourd'hui pour indien de toujours.",
     en:"Stewed red kidney beans served over white rice, the family dish of North India. The kidney bean is American: it came with the Portuguese in the sixteenth century and naturalised so thoroughly that it now passes for immemorially Indian."},
  i:[['red_kidney_beans',400,'g'],['long_grain_rice',400,'g'],['onion',3,'pc'],['ripe_tomato',500,'g'],['ginger',40,'g'],['garlic',8,'clove'],['garam_masala',15,'g'],['cumin',10,'g'],['turmeric',8,'g'],['ghee',80,'g'],['cilantro',1,'bunch'],['bay_leaf',2,'pc'],['salt',null,'']],
  s:{fr:["Faites tremper les haricots douze heures : sans trempage, ils ne cuisent jamais correctement et restent toxiques.","Le haricot rouge cru contient de la phytohémagglutinine : une ébullition franche d'au moins dix minutes est indispensable, un mijotage doux ne suffit pas.","Faites cuire à gros bouillons dix minutes, puis à feu doux une heure et demie jusqu'à ce qu'ils s'écrasent.","Écrasez-en un quart contre la paroi et remettez-les : c'est ce qui donne la sauce onctueuse, sans farine ni crème.","Préparez le masala à part — oignons bruns, tomate, épices — et joignez-le aux haricots pour vingt minutes."],
     en:["Soak the beans twelve hours: without soaking they never cook properly and stay toxic.","Raw kidney beans contain phytohaemagglutinin: a hard boil of at least ten minutes is essential, a gentle simmer will not do.","Boil hard for ten minutes, then simmer an hour and a half until they crush easily.","Crush a quarter of them against the side and stir them back in: that gives the silky sauce, with no flour and no cream.","Make the masala separately — browned onions, tomato, spices — and bring it to the beans for twenty minutes."]} },

{ id:'amritsari-kulcha', c:'as', lat:31.628, lon:74.878, base:6, prep:120, cook:30, diff:3, tags:['bread','veg','street'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'flat',food:['#e8c46a','#f2dfa8','#c9924a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Kulcha d\'Amritsar',en:'Amritsari kulcha'},
  p:{fr:'Amritsar, Pendjab, Inde',en:'Amritsar, Punjab, India'},
  d:{fr:"Un pain farci de pomme de terre, croustillant et feuilleté, écrasé à la main à la sortie du four. Le geste d'écraser le pain n'est pas décoratif : il fait éclater les couches et libère la vapeur, sans quoi le kulcha ramollit en deux minutes.",
     en:"A potato-stuffed bread, crisp and layered, crushed by hand as it leaves the oven. Crushing it is not decorative: it bursts the layers and releases the steam, without which the kulcha goes soft within two minutes."},
  i:[['flour',500,'g'],['potato',500,'g'],['onion',2,'pc'],['green_chili',4,'pc'],['pomegranate',30,'g'],['cilantro',1,'bunch'],['garam_masala',12,'g'],['ghee',150,'g'],['plain_yogurt',100,'g'],['baking_powder',8,'g'],['nigella_seeds',10,'g'],['salt',null,'']],
  s:{fr:["Employez les graines de grenade séchées, l'anardana : leur acidité est ce qui distingue le kulcha d'Amritsar de tous les autres.","Écrasez les pommes de terre cuites à la vapeur et laissez-les refroidir complètement avant de les assaisonner.","Feuilletez la pâte : abaissez, badigeonnez de ghee, roulez en boudin, enroulez en escargot, et laissez reposer vingt minutes.","Ce feuilletage est ce qui donne les couches ; sans lui, on obtient un paratha ordinaire.","Cuisez au tandoor ou au four à 250 °C, puis écrasez le pain entre les paumes et arrosez de ghee fondu."],
     en:["Use dried pomegranate seeds, anardana: their sourness is what sets the Amritsari kulcha apart from every other.","Mash the steamed potatoes and cool them completely before seasoning.","Laminate the dough: roll it out, brush with ghee, roll into a rope, coil it into a spiral, and rest twenty minutes.","That lamination gives the layers; without it you get an ordinary paratha.","Bake in a tandoor or at 250°C, then crush the bread between your palms and douse it with melted ghee."]} },

{ id:'pakora', c:'as', lat:28.640, lon:77.200, base:6, prep:30, cook:25, diff:1, tags:['street','fry','veg'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'other',food:['#e8c46a','#c9924a','#7fae5a','#f2dfa8'],garnish:'#7fae6a'},
  n:{fr:'Pakora',en:'Pakora'},
  p:{fr:'Delhi, Inde',en:'Delhi, India'},
  d:{fr:"Des beignets de légumes à la farine de pois chiche, frits et servis avec du chutney. La farine de pois chiche ne contient pas de gluten : la pâte n'a rien qui la fasse gonfler, et c'est la vapeur du légume seule qui crée la texture irrégulière recherchée.",
     en:"Vegetable fritters in chickpea flour, fried and served with chutney. Chickpea flour has no gluten: the batter has nothing to make it rise, and it is the vegetable's own steam alone that creates the wanted ragged texture."},
  i:[['chickpea_flour',300,'g'],['onion',3,'pc'],['potato',300,'g'],['spinach',150,'g'],['green_chili',4,'pc'],['carom_seeds',8,'g'],['turmeric',8,'g'],['chili_powder',10,'g'],['baking_soda',3,'g'],['frying_oil',1.5,'l'],['water',250,'ml'],['salt',null,'']],
  s:{fr:["Salez les oignons émincés et laissez-les dix minutes : ils rendent l'eau qui hydratera la pâte, et l'on ajoute alors moins d'eau claire.","Mêlez la farine de pois chiche progressivement, jusqu'à obtenir une pâte qui nappe sans couler.","Ajoutez l'ajwain : il est là pour la digestion autant que pour le goût, et son absence se remarque immédiatement.","Frites à 170 °C, une première fois, quatre minutes, puis égouttez et laissez reposer.","Repassez à 190 °C une minute avant de servir. Cette double friture est ce qui les garde croustillants une demi-heure."],
     en:["Salt the sliced onions and leave them ten minutes: they release the water that hydrates the batter, so less plain water is needed.","Work in the chickpea flour gradually, to a batter that coats without running.","Add the ajwain: it is there for digestion as much as flavour, and its absence is noticed at once.","Fry at 170°C first, four minutes, then drain and rest.","Return them to 190°C for one minute before serving. That double fry keeps them crisp for half an hour."]} },

{ id:'jalebi', c:'as', lat:26.912, lon:75.787, base:8, prep:720, cook:30, diff:3, tags:['sweet','fry','street'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'other',food:['#e8a032','#e8c46a','#c9754a','#f2dfa8'],garnish:'#c9754a'},
  n:{fr:'Jalebi',en:'Jalebi'},
  p:{fr:'Jaipur, Rajasthan, Inde',en:'Jaipur, Rajasthan, India'},
  d:{fr:"Des spirales de pâte fermentée frites puis trempées dans le sirop de sucre. La fermentation est ce qui les distingue de l'imarti et du zulbia : elle donne une acidité légère qui coupe le sirop, et sans elle la jalebi n'est qu'écœurante.",
     en:"Spirals of fermented batter fried then steeped in sugar syrup. The fermentation sets them apart from imarti and zulbia: it gives a faint sourness that cuts the syrup, and without it a jalebi is merely cloying."},
  i:[['flour',300,'g'],['plain_yogurt',100,'g'],['cornstarch',30,'g'],['sugar',600,'g'],['water',300,'ml'],['saffron',0.5,'g'],['cardamom',6,'pc'],['lemon',1,'pc'],['ghee',1,'l'],['rose_water',20,'ml']],
  s:{fr:["Mêlez farine, yaourt et eau et laissez fermenter douze heures à température ambiante : la pâte doit sentir l'aigre et bulle.","Le sirop doit être à un fil, soit 105 °C : plus épais, il ne pénètre pas ; plus clair, la jalebi se détrempe.","Ajoutez le jus de citron au sirop pour l'empêcher de cristalliser en refroidissant.","Faites couler la pâte en spirales dans le ghee à 175 °C, à travers une bouteille souple percée, en partant du centre.","Trempez-les brûlantes dans le sirop tiède, trente secondes exactement. Le contraste de température fait entrer le sirop."],
     en:["Mix flour, yoghurt and water and ferment twelve hours at room temperature: the batter should smell sour and bubble.","The syrup must be at one-thread stage, 105°C: thicker, it will not penetrate; thinner, the jalebi goes soggy.","Add lemon juice to the syrup to stop it crystallising as it cools.","Pipe the batter into the ghee at 175°C in spirals, through a pierced squeeze bottle, starting from the centre.","Steep them scalding in the warm syrup, thirty seconds exactly. The temperature contrast draws the syrup in."]} },

{ id:'chaat-de-delhi', c:'as', lat:28.656, lon:77.240, base:4, prep:60, cook:20, diff:2, tags:['street','fresh','veg'],
  art:{v:'plate',bg:'#33291f',plate:'#f4ead4',style:'salad',food:['#e8c46a','#f4f0e6','#4f6f3a','#c9302a'],garnish:'#7fae6a'},
  n:{fr:'Chaat de Delhi',en:'Delhi chaat'},
  p:{fr:'Delhi, Inde',en:'Delhi, India'},
  d:{fr:"Un en-cas de rue mêlant croustillant, yaourt, chutneys et épices acidulées. Le chaat repose sur un principe précis : il doit réunir six saveurs à la fois — sucré, salé, acide, piquant, amer et astringent — et l'équilibre entre elles fait toute la réputation d'un vendeur.",
     en:"A street snack combining crisp elements, yoghurt, chutneys and sour spices. Chaat rests on a precise principle: it must bring six tastes together at once — sweet, salty, sour, hot, bitter and astringent — and the balance between them makes a vendor's name."},
  i:[['papdi',150,'g'],['potato',400,'g'],['chickpeas',200,'g'],['plain_yogurt',400,'g'],['tamarind_paste',80,'g'],['mint',1,'bunch'],['cilantro',1,'bunch'],['green_chili',3,'pc'],['chaat_masala',15,'g'],['sev',100,'g'],['pomegranate',80,'g'],['palm_sugar',60,'g'],['cumin',10,'g']],
  s:{fr:["Préparez les deux chutneys la veille : le vert à la menthe et à la coriandre, le brun au tamarin et au sucre de palme.","Battez le yaourt avec un peu d'eau et une pincée de sucre jusqu'à ce qu'il coule à la cuillère sans être liquide.","Montez le chaat dans l'ordre : croustillant en bas, pommes de terre et pois chiches, yaourt, puis les chutneys.","Le sev et la grenade se posent en tout dernier, à l'instant de servir.","Posés à l'avance, ils ramollissent en deux minutes, et un chaat sans croustillant n'est plus un chaat."],
     en:["Make both chutneys the day before: the green with mint and coriander, the brown with tamarind and palm sugar.","Whisk the yoghurt with a little water and a pinch of sugar until it falls from the spoon without being runny.","Build the chaat in order: crisp elements at the bottom, potato and chickpeas, yoghurt, then the chutneys.","The sev and pomegranate go on at the very last moment, as you serve.","Put on in advance, they soften within two minutes, and a chaat without crunch is no longer a chaat."]} },

{ id:'kulfi', c:'as', lat:28.635, lon:77.225, base:8, prep:60, cook:90, diff:2, tags:['sweet','slow','fresh'],
  art:{v:'plate',bg:'#33291f',plate:'#f4ead4',style:'other',food:['#f2dfa8','#f4f0e6','#7fae5a','#e8a032'],garnish:'#7fae6a'},
  n:{fr:'Kulfi',en:'Kulfi'},
  p:{fr:'Delhi, Inde',en:'Delhi, India'},
  d:{fr:"Une glace dense de lait réduit, prise en moule conique sans être turbinée. C'est précisément l'absence de turbinage qui fait le kulfi : sans air incorporé, il fond très lentement et sa texture est dense, presque cireuse, à l'opposé d'une glace occidentale.",
     en:"A dense ice of reduced milk, set in conical moulds without churning. It is precisely the absence of churning that makes kulfi: with no air worked in, it melts very slowly and its texture is dense, almost waxy, the opposite of a Western ice cream."},
  i:[['whole_milk',2,'l'],['sugar',200,'g'],['cardamom',10,'pc'],['pistachios',100,'g'],['almonds',80,'g'],['saffron',0.5,'g'],['rose_water',20,'ml'],['cornstarch',20,'g']],
  s:{fr:["Faites réduire le lait de moitié à feu moyen, une bonne heure, en raclant régulièrement les parois.","La peau qui se forme sur les bords ne se jette pas : on la racle et on la remet dedans, elle donne au kulfi son grain caractéristique.","Ajoutez le sucre seulement une fois la réduction faite, puis la cardamome et le safran infusé.","Laissez refroidir complètement avant de mouler : versé chaud, le kulfi forme de gros cristaux en congelant.","Congelez six heures dans des moules coniques. Démoulez en passant le moule sous l'eau tiède deux secondes."],
     en:["Reduce the milk by half over medium heat, a good hour, scraping the sides regularly.","The skin that forms at the edges is not discarded: it is scraped back in, and it gives kulfi its characteristic grain.","Add the sugar only once the reduction is done, then the cardamom and infused saffron.","Cool completely before moulding: poured warm, kulfi forms large crystals as it freezes.","Freeze six hours in conical moulds. Unmould by running the mould under warm water for two seconds."]} }
,

{ id:'awadhi-biryani', c:'as', lat:26.847, lon:80.947, base:8, prep:180, cook:90, diff:3, tags:['rice','lamb','festive'],
  art:{v:'pot',bg:'#33291f',plate:'#f0e4c8',style:'rice',food:['#f4f0e6','#e8a032','#8f5a3a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Biryani awadhi',en:'Awadhi biryani'},
  p:{fr:'Lucknow, Uttar Pradesh, Inde',en:'Lucknow, Uttar Pradesh, India'},
  d:{fr:"Un biryani pâle et parfumé, cuit scellé sous une croûte de pâte. Il s'oppose en tout au biryani de Hyderabad : ici la viande est précuite en bouillon plutôt que marinée crue, et les épices sont infusées puis retirées, ce qui donne un plat aromatique sans être piquant.",
     en:"A pale, fragrant biryani cooked sealed under a crust of dough. It opposes Hyderabad's in every respect: here the meat is pre-cooked in broth rather than marinated raw, and the spices are infused then removed, giving an aromatic dish that is not hot."},
  i:[['lamb_shoulder',1,'kg'],['basmati_rice',600,'g'],['onion',4,'pc'],['plain_yogurt',300,'g'],['ghee',150,'g'],['cardamom',10,'pc'],['mace',5,'g'],['kewra_water',20,'ml'],['saffron',1,'g'],['whole_milk',100,'ml'],['flour',200,'g'],['ginger',40,'g'],['garlic',10,'clove'],['salt',null,'']],
  s:{fr:["Faites cuire l'agneau en bouillon avec les épices en mousseline, une heure, jusqu'à ce qu'il soit presque tendre.","Précuisez le riz cinq minutes seulement dans une grande eau salée : il doit se casser net entre les ongles.","Superposez viande, riz, oignons frits et lait safrané, puis fermez la marmite avec un boudin de pâte tout autour du couvercle.","Ce scellage, le dum, emprisonne toute la vapeur : c'est lui qui cuit le riz et fait le biryani, et une marmite mal fermée le rate.","Cuisez trente minutes à feu très doux, sur une plaque diffusante. Ouvrez à table, en cassant la croûte de pâte."],
     en:["Cook the lamb in broth with the spices tied in muslin for an hour, until nearly tender.","Parboil the rice for five minutes only in plenty of salted water: it should snap cleanly between the nails.","Layer meat, rice, fried onions and saffron milk, then seal the pot with a rope of dough all round the lid.","That seal, the dum, traps every bit of steam: it is what cooks the rice and makes the biryani, and a badly sealed pot fails it.","Cook thirty minutes over very low heat on a diffuser. Open at the table, breaking the crust of dough."]} },

{ id:'petha', c:'as', lat:27.177, lon:78.008, base:10, prep:1440, cook:60, diff:3, tags:['sweet','slow','fruit'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'other',food:['#f4f0e6','#f0e8d0','#e8dcb8','#f2dfa8'],garnish:'#7fae6a'},
  n:{fr:'Petha',en:'Petha'},
  p:{fr:'Agra, Uttar Pradesh, Inde',en:'Agra, Uttar Pradesh, India'},
  d:{fr:"Des morceaux de courge cendrée confits, translucides et croquants. La légende les fait naître dans les cuisines de Shah Jahan pendant la construction du Taj Mahal ; leur transparence vient d'un traitement à la chaux qui raffermit les parois cellulaires du fruit.",
     en:"Candied ash gourd, translucent and crisp. Legend has them born in Shah Jahan's kitchens during the building of the Taj Mahal; their transparency comes from a lime treatment that firms the fruit's cell walls."},
  i:[['ash_gourd',2,'kg'],['sugar',1.5,'kg'],['alum',30,'g'],['water',3,'l'],['cardamom',8,'pc'],['rose_water',30,'ml'],['saffron',0.5,'g']],
  s:{fr:["Pelez la courge, retirez les graines et coupez-la en cubes, puis piquez chaque morceau de vingt coups de fourchette.","Faites tremper douze heures dans l'eau de chaux : c'est le calcium qui se fixe aux pectines et rend la chair croquante et translucide.","Rincez ensuite très longuement, cinq ou six eaux, jusqu'à ce que toute trace de chaux ait disparu.","Blanchissez avec une pointe d'alun, puis pochez dans le sirop de sucre en trois fois, en laissant reposer une nuit entre chaque.","Ces trempages successifs remplacent l'eau du fruit par le sucre sans le faire éclater. Séchez enfin à l'air douze heures."],
     en:["Peel the gourd, remove the seeds and cut it into cubes, then prick each piece twenty times with a fork.","Soak twelve hours in limewater: the calcium binds to the pectins and makes the flesh crisp and translucent.","Then rinse at great length, five or six changes of water, until every trace of lime is gone.","Blanch with a pinch of alum, then poach in sugar syrup in three stages, resting overnight between each.","Those successive steepings replace the fruit's water with sugar without bursting it. Finally air-dry twelve hours."]} },

{ id:'banarasi-dum-aloo', c:'as', lat:25.318, lon:82.973, base:6, prep:40, cook:50, diff:2, tags:['veg','stew','comfort'],
  art:{v:'pot',bg:'#33291f',plate:'#f0e4c8',style:'stew',food:['#c9302a','#e8c46a','#f4f0e6','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Dum aloo de Bénarès',en:'Banarasi dum aloo'},
  p:{fr:'Varanasi, Uttar Pradesh, Inde',en:'Varanasi, Uttar Pradesh, India'},
  d:{fr:"De petites pommes de terre frites puis mijotées dans une sauce sans oignon ni ail. Cette absence n'est pas un oubli : la cuisine des temples de Bénarès exclut oignon et ail, jugés stimulants, et la sauce tient sur le yaourt, la tomate et l'asafœtida.",
     en:"Small potatoes fried then simmered in a sauce with no onion or garlic. The absence is deliberate: the temple cooking of Varanasi excludes onion and garlic as stimulants, and the sauce rests on yoghurt, tomato and asafoetida."},
  i:[['baby_potatoes',800,'g'],['plain_yogurt',300,'g'],['ripe_tomato',400,'g'],['asafoetida',3,'g'],['ginger',40,'g'],['kashmiri_chili',15,'g'],['coriander_seeds',15,'g'],['fennel_seed',10,'g'],['garam_masala',10,'g'],['ghee',100,'g'],['cilantro',1,'bunch'],['salt',null,'']],
  s:{fr:["Faites cuire les pommes de terre à la vapeur, pelez-les et piquez-les partout à la fourchette.","Ces piqûres permettent à la sauce d'entrer : sans elles, la pomme de terre reste fade au centre quel que soit le temps de cuisson.","Frites-les au ghee jusqu'à ce qu'elles dorent et se rident légèrement, puis réservez.","Faites griller l'asafœtida quelques secondes dans le ghee chaud : elle remplace l'ail, mais brûlée elle devient franchement désagréable.","Ajoutez le yaourt battu hors du feu et remettez les pommes de terre pour vingt minutes à couvert."],
     en:["Steam the potatoes, peel them and prick them all over with a fork.","Those holes let the sauce in: without them the potato stays bland at the centre however long it cooks.","Fry them in ghee until golden and slightly wrinkled, then set aside.","Toast the asafoetida a few seconds in the hot ghee: it stands in for garlic, but burnt it turns frankly unpleasant.","Add the beaten yoghurt off the heat and return the potatoes for twenty minutes, covered."]} },

{ id:'poha-jalebi', c:'as', lat:22.720, lon:75.858, base:4, prep:30, cook:20, diff:1, tags:['breakfast','street','fast'],
  art:{v:'plate',bg:'#33291f',plate:'#f4ead4',style:'other',food:['#f2dfa8','#e8a032','#7fae5a','#f4f0e6'],garnish:'#7fae6a'},
  n:{fr:'Poha jalebi',en:'Poha jalebi'},
  p:{fr:'Indore, Madhya Pradesh, Inde',en:'Indore, Madhya Pradesh, India'},
  d:{fr:"Du riz aplati sauté servi avec une jalebi sucrée, petit-déjeuner d'Indore. L'association du salé et du sucré dans la même assiette au petit-déjeuner est propre au Madhya Pradesh ; on mange les deux ensemble, bouchée après bouchée, et non l'un après l'autre.",
     en:"Sautéed flattened rice served with a sweet jalebi, the Indore breakfast. Pairing savoury and sweet on the same breakfast plate is peculiar to Madhya Pradesh; the two are eaten together, mouthful by mouthful, not one after the other."},
  i:[['flattened_rice',300,'g'],['onion',2,'pc'],['green_chili',3,'pc'],['mustard_seeds',10,'g'],['curry_leaves',20,'pc'],['turmeric',8,'g'],['peanuts',80,'g'],['sev',80,'g'],['lemon',2,'pc'],['cilantro',1,'bunch'],['sunflower_oil',60,'ml'],['pomegranate',60,'g'],['sugar',20,'g'],['salt',null,'']],
  s:{fr:["Employez du poha épais, jamais du fin : le fin se réduit en bouillie dès qu'on le mouille.","Rincez-le dans une passoire sous un filet d'eau, dix secondes seulement, puis laissez-le égoutter dix minutes.","Il doit s'écraser sous le doigt sans coller. Trop trempé, rien ne le rattrape.","Faites éclater les graines de moutarde dans l'huile chaude avant tout le reste : elles doivent sauter, c'est le signal.","Ajoutez le poha hors du feu et mêlez délicatement à la fourchette, jamais à la cuillère qui l'écraserait."],
     en:["Use thick poha, never thin: thin poha collapses into paste the moment it is wetted.","Rinse it in a sieve under a thin stream of water for ten seconds only, then drain it ten minutes.","It should crush under a finger without stickiness. Over-soaked, nothing will save it.","Pop the mustard seeds in hot oil before anything else: they must jump, that is the signal.","Add the poha off the heat and fold gently with a fork, never a spoon, which would crush it."]} },

{ id:'bhutte-ka-kees', c:'as', lat:22.715, lon:75.865, base:4, prep:30, cook:25, diff:2, tags:['street','veg','fast'],
  art:{v:'bowl',bg:'#33291f',plate:'#f0e4c8',style:'other',food:['#e8c46a','#f2dfa8','#f4f0e6','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Bhutte ka kees',en:'Bhutte ka kees'},
  p:{fr:'Indore, Madhya Pradesh, Inde',en:'Indore, Madhya Pradesh, India'},
  d:{fr:"Du maïs frais râpé cuit au lait, aux épices et à la noix de coco. On le vend le soir dans la rue de Sarafa à Indore, marché de bijoutiers le jour et marché de nuit alimentaire de vingt heures à deux heures du matin.",
     en:"Fresh corn grated and cooked in milk with spices and coconut. It is sold in the evening in Indore's Sarafa lane, a jewellers' market by day and a food night market from eight in the evening to two in the morning."},
  i:[['sweetcorn',6,'pc'],['whole_milk',400,'ml'],['coconut',80,'g'],['green_chili',3,'pc'],['ginger',30,'g'],['mustard_seeds',8,'g'],['asafoetida',2,'g'],['turmeric',6,'g'],['ghee',60,'g'],['lemon',2,'pc'],['cilantro',1,'bunch'],['sev',60,'g'],['salt',null,'']],
  s:{fr:["Râpez le maïs frais sur la grille moyenne, directement sur l'épi, pour obtenir une purée grumeleuse et non des grains entiers.","Choisissez des épis à grain laiteux : un maïs mûr donne une texture farineuse et un goût plat.","Faites éclater la moutarde dans le ghee, ajoutez asafœtida, gingembre et piment, puis le maïs râpé.","Remuez sans arrêt cinq minutes avant de mouiller au lait : le maïs cru attache instantanément.","Ajoutez le lait chaud peu à peu, comme pour un risotto, jusqu'à obtenir une masse crémeuse. Citron et coco râpée hors du feu."],
     en:["Grate the fresh corn on the medium blade, straight off the cob, to get a lumpy purée and not whole kernels.","Choose ears with milky kernels: mature corn gives a floury texture and a flat taste.","Pop the mustard in ghee, add asafoetida, ginger and chilli, then the grated corn.","Stir without pause for five minutes before adding milk: raw corn catches instantly.","Add the hot milk little by little, as for a risotto, to a creamy mass. Lemon and grated coconut off the heat."]} },

{ id:'bhopali-gosht-korma', c:'as', lat:23.260, lon:77.413, base:6, prep:120, cook:120, diff:3, tags:['lamb','stew','festive'],
  art:{v:'pot',bg:'#33291f',plate:'#f0e4c8',style:'stew',food:['#8f5a3a','#e8c46a','#f2dfa8','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Korma de Bhopal',en:'Bhopali gosht korma'},
  p:{fr:'Bhopal, Madhya Pradesh, Inde',en:'Bhopal, Madhya Pradesh, India'},
  d:{fr:"Un korma d'agneau aux amandes et au yaourt, doux et très parfumé. Bhopal a été gouvernée par quatre femmes successives entre 1819 et 1926, les Begums, dont les cuisines ont donné à la ville une tradition culinaire distincte de celle de Lucknow ou de Hyderabad.",
     en:"A lamb korma with almonds and yoghurt, mild and deeply fragrant. Bhopal was ruled by four successive women between 1819 and 1926, the Begums, whose kitchens gave the city a culinary tradition distinct from Lucknow's or Hyderabad's."},
  i:[['lamb_shoulder',1,'kg'],['plain_yogurt',400,'g'],['almonds',120,'g'],['cashews',80,'g'],['onion',4,'pc'],['ghee',150,'g'],['cardamom',10,'pc'],['mace',5,'g'],['nutmeg',3,'g'],['poppy_seed',30,'g'],['ginger',40,'g'],['garlic',10,'clove'],['kewra_water',15,'ml'],['salt',null,'']],
  s:{fr:["Faites tremper amandes, cajous et pavot blanc une heure, puis mixez-les en pâte parfaitement lisse.","Le pavot blanc est l'épaississant traditionnel du korma : il donne du corps sans le goût de crème, et rien ne le remplace vraiment.","Faites frire les oignons jusqu'au brun profond, puis mixez-les avec le yaourt en une purée.","Faites revenir la viande, ajoutez la purée d'oignons puis la pâte de fruits secs, et mouillez à peine.","Laissez mijoter deux heures à couvert. Le korma ne doit jamais bouillir : à gros bouillons, le yaourt tranche et la sauce graine."],
     en:["Soak the almonds, cashews and white poppy seeds for an hour, then blend them to a perfectly smooth paste.","White poppy seed is korma's traditional thickener: it gives body without a creamy taste, and nothing truly replaces it.","Fry the onions to deep brown, then blend them with the yoghurt into a purée.","Brown the meat, add the onion purée then the nut paste, and moisten barely.","Simmer two hours covered. A korma must never boil: at a rolling boil the yoghurt splits and the sauce goes grainy."]} },

{ id:'malaiyo', c:'as', lat:25.310, lon:82.980, base:6, prep:720, cook:20, diff:3, tags:['sweet','fresh','slow'],
  art:{v:'bowl',bg:'#33291f',plate:'#f4ead4',style:'other',food:['#f4f0e6','#f0e8d0','#e8dcb8','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Malaiyo',en:'Malaiyo'},
  p:{fr:'Varanasi, Uttar Pradesh, Inde',en:'Varanasi, Uttar Pradesh, India'},
  d:{fr:"Une mousse de lait si légère qu'elle fond avant d'être avalée, faite uniquement en hiver. Le lait est laissé dehors toute la nuit pour recueillir la rosée : sans elle, la mousse ne monte pas, et la saison s'arrête net dès que les nuits se réchauffent.",
     en:"A milk foam so light it dissolves before it can be swallowed, made only in winter. The milk is left outdoors all night to catch the dew: without it the foam will not rise, and the season ends the moment the nights warm."},
  i:[['whole_milk',1.5,'l'],['sugar',150,'g'],['saffron',0.5,'g'],['cardamom',8,'pc'],['pistachios',60,'g'],['almonds',40,'g'],['heavy_cream',200,'ml']],
  s:{fr:["Faites bouillir le lait avec le safran et la cardamome, puis laissez-le refroidir.","Laissez-le dehors toute la nuit d'hiver, couvert d'une mousseline : c'est la rosée et le froid nocturne qui préparent le lait.","Au petit matin, fouettez-le au fouet de bambou pendant une heure, en écumant la mousse à mesure qu'elle monte.","Le fouettage doit se faire dans le froid : dès que le lait tiédit, la mousse retombe et ne remonte plus.","Empilez la mousse dans des coupelles, sucrez à peine et parsemez de pistaches. Se mange dans la minute."],
     en:["Boil the milk with the saffron and cardamom, then let it cool.","Leave it outside all winter night under muslin: it is the dew and the night cold that prepare the milk.","At dawn, whisk it with a bamboo whisk for an hour, skimming off the foam as it rises.","The whisking must be done in the cold: as soon as the milk warms, the foam collapses and will not rise again.","Pile the foam into small bowls, sweeten barely and scatter with pistachios. Eaten within the minute."]} },

{ id:'pav-bhaji', c:'as', lat:19.076, lon:72.878, base:6, prep:40, cook:50, diff:2, tags:['veg','street','comfort'],
  art:{v:'plate',bg:'#33291f',plate:'#f0e4c8',style:'other',food:['#c9302a','#e8c46a','#f2dfa8','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Pav bhaji',en:'Pav bhaji'},
  p:{fr:'Mumbai, Maharashtra, Inde',en:'Mumbai, Maharashtra, India'},
  d:{fr:"Une purée de légumes épicée servie avec des petits pains beurrés et grillés. Elle a été inventée dans les années 1850 pour les ouvriers du textile de Bombay : un repas complet, chaud, mangé debout pendant la pause de midi, à partir des restes de légumes de la veille.",
     en:"A spiced vegetable mash served with buttered griddled rolls. It was invented in the 1850s for Bombay's textile workers: a complete hot meal eaten standing during the midday break, made from the previous day's leftover vegetables."},
  i:[['potato',600,'g'],['cauliflower',300,'g'],['peas',200,'g'],['bell_pepper',2,'pc'],['ripe_tomato',600,'g'],['onion',3,'pc'],['pav_bhaji_masala',30,'g'],['kashmiri_chili',15,'g'],['butter',200,'g'],['bread_roll',12,'pc'],['ginger',30,'g'],['garlic',10,'clove'],['lemon',2,'pc'],['cilantro',1,'bunch'],['salt',null,'']],
  s:{fr:["Faites cuire tous les légumes à la vapeur puis écrasez-les grossièrement au presse-purée à main, directement dans la poêle.","Ne mixez jamais : le bhaji doit garder des morceaux, et une purée lisse le rend fade et pâteux.","Faites revenir oignons, gingembre, ail et tomates longuement, jusqu'à ce que le mélange se détache du fond.","Ajoutez le masala et laissez-le griller dans le beurre trente secondes avant d'ajouter les légumes.","Ne lésinez pas sur le beurre : c'est lui qui lie tout, et un pav bhaji maigre n'a jamais convaincu personne."],
     en:["Steam all the vegetables then crush them roughly with a hand masher, directly in the pan.","Never blend: bhaji must keep lumps, and a smooth purée makes it bland and pasty.","Fry the onions, ginger, garlic and tomatoes at length, until the mixture pulls from the base.","Add the masala and toast it in the butter for thirty seconds before adding the vegetables.","Do not stint on the butter: it binds everything, and a lean pav bhaji has never convinced anyone."]} },

{ id:'bhel-puri', c:'as', lat:19.020, lon:72.856, base:4, prep:30, cook:0, diff:1, tags:['street','fresh','fast'],
  art:{v:'bowl',bg:'#33291f',plate:'#f4ead4',style:'salad',food:['#f2dfa8','#e8c46a','#4f6f3a','#c9302a'],garnish:'#7fae6a'},
  n:{fr:'Bhel puri',en:'Bhel puri'},
  p:{fr:'Mumbai, Maharashtra, Inde',en:'Mumbai, Maharashtra, India'},
  d:{fr:"Du riz soufflé mêlé de chutneys, d'oignon et de croustillants, assemblé à la minute. C'est l'en-cas des plages de Mumbai ; il doit être mangé dans les deux minutes qui suivent le mélange, après quoi le riz soufflé s'affaisse et le plat n'a plus d'intérêt.",
     en:"Puffed rice tossed with chutneys, onion and crisp bits, assembled to order. It is the snack of Mumbai's beaches; it must be eaten within two minutes of mixing, after which the puffed rice slumps and the dish loses its point."},
  i:[['puffed_rice',150,'g'],['sev',100,'g'],['papdi',80,'g'],['onion',2,'pc'],['potato',200,'g'],['ripe_tomato',200,'g'],['tamarind_paste',60,'g'],['mint',1,'bunch'],['cilantro',1,'bunch'],['green_chili',3,'pc'],['chaat_masala',15,'g'],['lemon',2,'pc'],['peanuts',60,'g'],['palm_sugar',40,'g']],
  s:{fr:["Passez le riz soufflé quelques minutes au four tiède avant l'assemblage : l'humidité de l'air le ramollit en une journée.","Préparez les deux chutneys à l'avance et gardez-les froids, mais ne les versez qu'au tout dernier moment.","Épongez les légumes coupés sur du papier : leur eau est le premier ennemi du croustillant.","Mêlez tout dans un grand saladier, à la main, en soulevant plutôt qu'en remuant.","Servez immédiatement, sans exception. Un bhel puri qui attend cinq minutes est un bhel puri perdu."],
     en:["Warm the puffed rice a few minutes in a low oven before assembling: airborne moisture softens it within a day.","Make both chutneys ahead and keep them cold, but add them only at the very last moment.","Blot the cut vegetables on paper: their water is the first enemy of crispness.","Toss everything in a large bowl by hand, lifting rather than stirring.","Serve at once, without exception. A bhel puri that waits five minutes is a bhel puri lost."]} },

{ id:'bombay-duck-fry', c:'as', lat:19.010, lon:72.820, base:4, prep:40, cook:20, diff:2, tags:['sea','fry','street'],
  art:{v:'board',bg:'#2c3440',plate:'#f4ead4',style:'fish',food:['#e8c46a','#c9924a','#f4f0e6','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Bombay duck frit',en:'Bombay duck fry'},
  p:{fr:'Mumbai, Maharashtra, Inde',en:'Mumbai, Maharashtra, India'},
  d:{fr:"Un poisson-lézard à la chair très molle, pané à la semoule et frit. Malgré son nom, ce n'est pas un canard : l'appellation viendrait des trains postaux de Bombay qui transportaient le poisson séché, dont l'odeur puissante imprégnait les wagons.",
     en:"A lizardfish with very soft flesh, crumbed in semolina and fried. Despite the name it is no duck: the term is said to come from the Bombay mail trains that carried the dried fish, whose powerful smell filled the carriages."},
  i:[['bombay_duck',600,'g'],['semolina',150,'g'],['rice_flour',50,'g'],['kashmiri_chili',15,'g'],['turmeric',8,'g'],['garlic',6,'clove'],['ginger',20,'g'],['lemon',2,'pc'],['frying_oil',500,'ml'],['salt',null,'']],
  s:{fr:["Employez du poisson frais si vous en trouvez : le séché, très odorant, demande un trempage d'une heure et un tout autre traitement.","La chair contient jusqu'à 90 % d'eau : pressez délicatement les filets entre deux linges vingt minutes avant de les paner.","Faites mariner au citron, curcuma et piment une demi-heure, pas davantage — l'acide finit par désagréger cette chair fragile.","Panez à la semoule fine mêlée de farine de riz : la semoule seule tombe, la farine de riz la fait tenir.","Frites à 180 °C, deux minutes par face, sans retourner plus d'une fois. Le poisson se brise au moindre excès de manipulation."],
     en:["Use fresh fish if you can find it: the dried kind, very pungent, needs an hour's soaking and quite different handling.","The flesh is up to 90% water: press the fillets gently between two cloths for twenty minutes before crumbing.","Marinate in lemon, turmeric and chilli for half an hour, no longer — the acid eventually breaks down this fragile flesh.","Crumb in fine semolina mixed with rice flour: semolina alone falls off, rice flour makes it hold.","Fry at 180°C, two minutes a side, turning once only. The fish breaks at the least excess handling."]} },

{ id:'misal-pav', c:'as', lat:18.520, lon:73.857, base:6, prep:720, cook:60, diff:2, tags:['legume','street','spicy'],
  art:{v:'bowl',bg:'#33291f',plate:'#f0e4c8',style:'other',food:['#c9302a','#8f4a3a','#f2dfa8','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Misal pav',en:'Misal pav'},
  p:{fr:'Pune, Maharashtra, Inde',en:'Pune, Maharashtra, India'},
  d:{fr:"Un curry de haricots germés couvert de croustillants, servi avec un pain mou. Le kat, l'huile rouge qui surnage, est versé à part et à volonté : c'est lui qui fait la réputation d'un misal, et certaines maisons de Pune le servent dans un pichet.",
     en:"A sprouted bean curry topped with crisp bits, served with a soft roll. The kat, the red oil floating on top, is poured separately and to taste: it makes a misal's reputation, and some Pune houses serve it in a jug."},
  i:[['moth_beans',400,'g'],['onion',4,'pc'],['coconut',100,'g'],['goda_masala',30,'g'],['kashmiri_chili',25,'g'],['ginger',40,'g'],['garlic',10,'clove'],['farsan',150,'g'],['bread_roll',12,'pc'],['lemon',2,'pc'],['sunflower_oil',150,'ml'],['cilantro',1,'bunch'],['salt',null,'']],
  s:{fr:["Faites germer les haricots moth deux jours : trempés douze heures puis égouttés et couverts d'un linge humide.","Grillez à sec la noix de coco râpée et l'oignon jusqu'au brun profond avant de les mixer : c'est ce grillage qui donne le goût de fumée.","Préparez le kat séparément : une grande quantité d'huile chauffée avec la pâte d'épices, jusqu'à ce qu'elle se sépare et rougisse.","L'huile rouge se prélève en surface à la louche et se sert à part, jamais mêlée au curry.","Montez au dernier moment : haricots, farsan croustillant, oignon cru, coriandre, citron. Le kat se verse à table."],
     en:["Sprout the moth beans over two days: soaked twelve hours then drained and covered with a damp cloth.","Dry-toast the grated coconut and onion to deep brown before blending them: that toasting gives the smoky taste.","Make the kat separately: a generous quantity of oil heated with the spice paste, until it splits and reddens.","The red oil is skimmed off the top with a ladle and served apart, never stirred into the curry.","Assemble at the last moment: beans, crisp farsan, raw onion, coriander, lemon. The kat is poured at the table."]} },

{ id:'puran-poli', c:'as', lat:18.512, lon:73.850, base:8, prep:120, cook:40, diff:3, tags:['sweet','bread','festive'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'flat',food:['#e8c46a','#c9924a','#f2dfa8','#8f5a3a'],garnish:'#c9754a'},
  n:{fr:'Puran poli',en:'Puran poli'},
  p:{fr:'Pune, Maharashtra, Inde',en:'Pune, Maharashtra, India'},
  d:{fr:"Un pain plat farci d'une pâte de pois cassés et de sucre de palme. Il se prépare pour Holi et Gudi Padwa ; l'eau de cuisson des pois, appelée katachi amti, ne se jette jamais et sert à faire une soupe épicée servie à côté.",
     en:"A flatbread filled with a paste of split peas and palm sugar. It is made for Holi and Gudi Padwa; the pea cooking water, called katachi amti, is never discarded and is used for a spiced soup served alongside."},
  i:[['chana_dal',300,'g'],['palm_sugar',300,'g'],['flour',300,'g'],['ghee',150,'g'],['cardamom',8,'pc'],['nutmeg',3,'g'],['turmeric',3,'g'],['water',600,'ml'],['salt',null,'']],
  s:{fr:["Cuisez les pois cassés jusqu'à ce qu'ils s'écrasent, puis égouttez-les à fond en gardant l'eau pour l'amti.","Mêlez-les au sucre de palme et faites cuire à sec, en remuant, jusqu'à ce que la masse se détache du fond en bloc.","Une farce trop humide traverse la pâte et brûle sur la plaque : c'est le seul vrai obstacle de cette recette.","Passez la farce au moulin à légumes pendant qu'elle est chaude, pour la rendre parfaitement lisse.","Enfermez-la dans une pâte molle et très huilée, abaissez avec précaution et cuisez au ghee sur plaque douce."],
     en:["Cook the split peas until they crush, then drain them thoroughly, keeping the water for the amti.","Mix them with the palm sugar and cook dry, stirring, until the mass pulls from the base in one piece.","A filling that is too wet soaks through the dough and burns on the griddle: the one real obstacle in this recipe.","Pass the filling through a food mill while hot, to make it perfectly smooth.","Enclose it in a soft, heavily oiled dough, roll it out carefully and cook in ghee on a gentle griddle."]} }
,

{ id:'pani-puri', c:'as', lat:19.066, lon:72.870, base:6, prep:180, cook:30, diff:3, tags:['street','fresh','fast'],
  art:{v:'board',bg:'#28331f',plate:'#f4ead4',style:'other',food:['#e8c46a','#4f6f3a','#f2dfa8','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Pani puri',en:'Pani puri'},
  p:{fr:'Mumbai, Maharashtra, Inde',en:'Mumbai, Maharashtra, India'},
  d:{fr:"De petites sphères creuses garnies et remplies d'une eau épicée, mangées d'une bouchée. Elles portent six noms différents selon les régions — golgappa à Delhi, puchka à Calcutta, gup chup à Odisha — et chaque ville tient sa version pour la seule authentique.",
     en:"Small hollow spheres filled with stuffing and spiced water, eaten in one mouthful. They carry six different names across the country — golgappa in Delhi, puchka in Kolkata, gup chup in Odisha — and each city holds its version to be the only true one."},
  i:[['semolina',200,'g'],['flour',50,'g'],['mint',2,'bunch'],['cilantro',1,'bunch'],['tamarind_paste',80,'g'],['green_chili',5,'pc'],['chaat_masala',20,'g'],['black_salt',10,'g'],['potato',300,'g'],['chickpeas',200,'g'],['palm_sugar',60,'g'],['frying_oil',1.5,'l'],['water',1.5,'l']],
  s:{fr:["Pétrissez une pâte très ferme à la semoule fine, presque impossible à travailler, et laissez-la reposer une heure sous un linge humide.","Abaissez-la aussi fin que du papier et découpez de petits disques de quatre centimètres.","Frites à 190 °C en pressant chaque disque sous l'huile avec l'écumoire : la vapeur brutale le fait gonfler en sphère creuse.","Une huile trop tiède donne des disques plats et gras : c'est le seul point où la recette échoue vraiment.","Préparez l'eau verte à la menthe la veille et gardez-la glacée. Percez, garnissez, remplissez et mangez d'un coup."],
     en:["Knead a very firm dough of fine semolina, almost unworkable, and rest it an hour under a damp cloth.","Roll it paper-thin and cut small four-centimetre discs.","Fry at 190°C, pressing each disc under the oil with a skimmer: the violent steam balloons it into a hollow sphere.","Oil that is too cool gives flat greasy discs: the one point where this recipe genuinely fails.","Make the green mint water the day before and keep it iced. Pierce, fill, top up and eat in one go."]} },

{ id:'dhokla', c:'as', lat:23.023, lon:72.571, base:6, prep:480, cook:30, diff:3, tags:['veg','breakfast','fresh'],
  art:{v:'plate',bg:'#33291f',plate:'#f4ead4',style:'cake',food:['#e8c46a','#f2dfa8','#7fae5a','#f4f0e6'],garnish:'#7fae6a'},
  n:{fr:'Dhokla',en:'Dhokla'},
  p:{fr:'Ahmedabad, Gujarat, Inde',en:'Ahmedabad, Gujarat, India'},
  d:{fr:"Un gâteau salé de pois chiche fermenté, cuit à la vapeur, léger comme une éponge. La fermentation naturelle de la pâte produit du gaz carbonique : c'est elle qui fait lever le dhokla, et les versions rapides au bicarbonate n'ont ni son goût acidulé ni sa texture.",
     en:"A savoury steamed cake of fermented chickpea, light as a sponge. The batter's natural fermentation produces carbon dioxide: that is what raises a dhokla, and quick versions with bicarbonate have neither its tang nor its texture."},
  i:[['chickpea_flour',300,'g'],['plain_yogurt',200,'g'],['semolina',60,'g'],['ginger',30,'g'],['green_chili',3,'pc'],['turmeric',6,'g'],['mustard_seeds',10,'g'],['curry_leaves',20,'pc'],['sesame_seeds',20,'g'],['sugar',40,'g'],['lemon',2,'pc'],['sunflower_oil',60,'ml'],['eno',8,'g'],['salt',null,'']],
  s:{fr:["Mêlez farine de pois chiche, yaourt et eau et laissez fermenter huit heures dans un endroit tiède.","La pâte doit avoir visiblement gonflé et sentir franchement l'aigre : sous-fermentée, elle donne un gâteau dense.","Ajoutez l'eno ou le bicarbonate à la toute dernière seconde, mêlez trois tours et enfournez immédiatement.","Le gaz s'échappe en moins d'une minute : toute hésitation à ce stade se paie par un dhokla plat.","Cuisez quinze minutes à la vapeur vive, puis versez dessus un tempérage de moutarde, curry et sésame à l'huile brûlante."],
     en:["Mix chickpea flour, yoghurt and water and ferment eight hours somewhere warm.","The batter should have visibly risen and smell frankly sour: under-fermented, it gives a dense cake.","Add the eno or bicarbonate at the very last second, stir three times and steam immediately.","The gas escapes within a minute: any hesitation at this stage is paid for with a flat dhokla.","Steam fifteen minutes over a fierce boil, then pour over a tempering of mustard, curry leaf and sesame in scalding oil."]} },

{ id:'thepla', c:'as', lat:23.030, lon:72.580, base:6, prep:40, cook:30, diff:2, tags:['bread','veg','breakfast'],
  art:{v:'board',bg:'#28331f',plate:'#f4ead4',style:'flat',food:['#7fae5a','#e8c46a','#f2dfa8','#c9924a'],garnish:'#7fae6a'},
  n:{fr:'Thepla',en:'Thepla'},
  p:{fr:'Ahmedabad, Gujarat, Inde',en:'Ahmedabad, Gujarat, India'},
  d:{fr:"Un pain plat au fenugrec frais, souple et épicé, qui se conserve plusieurs jours. C'est le pain de voyage des Gujaratis : il se garde une semaine sans réfrigération, et l'on en trouve dans le bagage de presque tout Gujarati en déplacement.",
     en:"A soft, spiced flatbread with fresh fenugreek that keeps for days. It is the Gujarati travelling bread: it holds a week without refrigeration, and turns up in the luggage of almost any Gujarati on the move."},
  i:[['whole_wheat_flour',400,'g'],['fenugreek_leaves',200,'g'],['chickpea_flour',60,'g'],['plain_yogurt',100,'g'],['turmeric',8,'g'],['chili_powder',10,'g'],['coriander_seeds',10,'g'],['sesame_seeds',20,'g'],['sunflower_oil',80,'ml'],['ginger',30,'g'],['salt',null,'']],
  s:{fr:["Hachez le fenugrec frais très fin et salez-le dix minutes : il rend son eau, qui servira à hydrater la pâte.","Cette eau amère est ce qui donne le goût : la jeter et ajouter de l'eau claire fait un pain quelconque.","Pétrissez avec les farines et le yaourt sans ajouter d'eau tant que la pâte n'est pas formée.","Laissez reposer vingt minutes seulement — un repos long rend le fenugrec amer.","Cuisez à la plaque en badigeonnant d'huile, jusqu'à ce que des taches brunes apparaissent. Se garde une semaine dans un linge."],
     en:["Chop the fresh fenugreek very finely and salt it ten minutes: it releases water that will hydrate the dough.","That bitter water is what gives the flavour: throwing it out and adding plain water makes an ordinary bread.","Knead with the flours and yoghurt without adding water until the dough has come together.","Rest twenty minutes only — a long rest turns the fenugreek bitter.","Cook on a griddle, brushing with oil, until brown spots appear. Keeps a week wrapped in a cloth."]} },

{ id:'fafda-jalebi', c:'as', lat:23.018, lon:72.565, base:6, prep:60, cook:40, diff:3, tags:['street','fry','breakfast'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'other',food:['#e8c46a','#e8a032','#f2dfa8','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Fafda jalebi',en:'Fafda jalebi'},
  p:{fr:'Ahmedabad, Gujarat, Inde',en:'Ahmedabad, Gujarat, India'},
  d:{fr:"Des bandes croustillantes de pois chiche servies avec des jalebis sucrées et de la papaye râpée. C'est le petit-déjeuner du dimanche au Gujarat, et le plat rituel du jour de Dussehra ; le mélange salé, sucré et acide dans la même bouchée est le principe même du plat.",
     en:"Crisp chickpea strips served with sweet jalebis and grated papaya. It is the Gujarati Sunday breakfast and the ritual dish of Dussehra; combining salty, sweet and sour in one mouthful is the very principle of it."},
  i:[['chickpea_flour',400,'g'],['carom_seeds',10,'g'],['baking_soda',5,'g'],['turmeric',6,'g'],['sunflower_oil',1.5,'l'],['green_papaya',300,'g'],['mustard_seeds',10,'g'],['green_chili',6,'pc'],['flour',200,'g'],['plain_yogurt',80,'g'],['sugar',400,'g'],['salt',null,'']],
  s:{fr:["Pétrissez une pâte de pois chiche très ferme, en la battant contre le plan de travail plutôt qu'en la pétrissant.","Étalez chaque portion avec la paume, d'un mouvement glissé vers vous, pour former une bande longue et régulière.","C'est un geste qui demande de la pratique : la pâte doit s'étirer sans se déchirer, en une seule traction.","Frites à 180 °C jusqu'à ce que le grésillement cesse — le bruit s'arrête quand toute l'eau s'est évaporée.","Servez avec des jalebis chaudes, des piments frits et une salade de papaye verte râpée au sel et à la moutarde."],
     en:["Knead a very firm chickpea dough, slapping it against the worktop rather than kneading it.","Spread each portion with your palm in a single sliding movement towards you, forming a long even strip.","It is a gesture that takes practice: the dough must stretch without tearing, in one pull.","Fry at 180°C until the sizzling stops — the noise ends when all the water has gone.","Serve with hot jalebis, fried chillies and a salad of grated green papaya with salt and mustard."]} },

{ id:'khakhra', c:'as', lat:22.303, lon:70.802, base:8, prep:60, cook:40, diff:2, tags:['bread','fast','veg'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'flat',food:['#c9924a','#e8c46a','#f2dfa8','#8f7a5a'],garnish:'#7fae6a'},
  n:{fr:'Khakhra',en:'Khakhra'},
  p:{fr:'Rajkot, Gujarat, Inde',en:'Rajkot, Gujarat, India'},
  d:{fr:"Un pain plat cuit jusqu'à devenir cassant comme un biscuit, pressé pendant la cuisson. La pression continue au moyen d'un tampon de tissu est ce qui chasse toute l'humidité : c'est elle qui fait passer le pain du souple au cassant, et rien ne la remplace.",
     en:"A flatbread cooked until brittle as a biscuit, pressed throughout the cooking. Continuous pressure with a cloth pad is what drives out every trace of moisture: it is what takes the bread from supple to brittle, and nothing replaces it."},
  i:[['whole_wheat_flour',400,'g'],['chickpea_flour',60,'g'],['carom_seeds',8,'g'],['turmeric',6,'g'],['chili_powder',8,'g'],['sunflower_oil',60,'ml'],['cumin',8,'g'],['water',200,'ml'],['salt',null,'']],
  s:{fr:["Pétrissez une pâte ferme et laissez-la reposer trente minutes, puis abaissez-la aussi fin que possible, jusqu'à la transparence.","Un khakhra épais reste souple au centre quel que soit le temps de cuisson : la finesse est la condition première.","Cuisez sur une plaque à feu très doux, jamais vif — à feu fort, la surface brûle avant que l'intérieur sèche.","Pressez en continu avec un tampon de tissu plié, en tournant le pain, pendant trois à quatre minutes par face.","Le khakhra est prêt quand il est uniformément brun clair et sonne creux. Se garde un mois en boîte hermétique."],
     en:["Knead a firm dough and rest it thirty minutes, then roll it as thin as possible, to transparency.","A thick khakhra stays supple at the centre however long it cooks: thinness is the first condition.","Cook on a griddle over very low heat, never fierce — over high heat the surface burns before the inside dries.","Press continuously with a folded cloth pad, turning the bread, for three to four minutes a side.","The khakhra is ready when evenly pale brown and sounding hollow. Keeps a month in an airtight tin."]} },

{ id:'handvo', c:'as', lat:23.035, lon:72.560, base:8, prep:720, cook:60, diff:2, tags:['veg','bake','comfort'],
  art:{v:'plate',bg:'#33291f',plate:'#f4ead4',style:'cake',food:['#c9924a','#e8c46a','#7fae5a','#f2dfa8'],garnish:'#7fae6a'},
  n:{fr:'Handvo',en:'Handvo'},
  p:{fr:'Ahmedabad, Gujarat, Inde',en:'Ahmedabad, Gujarat, India'},
  d:{fr:"Un gâteau salé de riz et de lentilles fermentés, aux légumes râpés, cuit en croûte. La croûte du dessous, épaisse et dorée, est la partie que l'on se dispute ; on retourne le handvo à mi-cuisson pour en obtenir deux plutôt qu'une.",
     en:"A savoury cake of fermented rice and lentils with grated vegetables, baked with a crust. The thick golden bottom crust is the part people compete for; the handvo is turned halfway through to get two rather than one."},
  i:[['rice',200,'g'],['chana_dal',100,'g'],['toor_dal',100,'g'],['urad_dal',50,'g'],['bottle_gourd',400,'g'],['carrot',2,'pc'],['plain_yogurt',200,'g'],['ginger',30,'g'],['green_chili',4,'pc'],['sesame_seeds',30,'g'],['mustard_seeds',10,'g'],['curry_leaves',20,'pc'],['sunflower_oil',100,'ml'],['eno',8,'g'],['salt',null,'']],
  s:{fr:["Faites tremper riz et lentilles six heures, puis broyez-les en pâte grossière — le handvo doit garder du grain.","Mêlez au yaourt et laissez fermenter douze heures : la pâte doit gonfler et sentir l'aigre.","Râpez la courge bouteille et pressez-la : son eau ferait un gâteau détrempé, mais ne la jetez pas, elle sert à ajuster la pâte.","Ajoutez l'eno juste avant la cuisson et versez la pâte sur un tempérage de moutarde et de sésame déjà chaud dans le moule.","Cuisez à couvert vingt minutes, retournez d'un bloc, puis vingt minutes de l'autre côté. Deux croûtes valent mieux qu'une."],
     en:["Soak the rice and lentils six hours, then grind them to a coarse paste — handvo must keep some grain.","Mix with the yoghurt and ferment twelve hours: the batter should rise and smell sour.","Grate the bottle gourd and press it: its water would make a soggy cake, but do not throw it away, it serves to adjust the batter.","Add the eno just before baking and pour the batter onto a tempering of mustard and sesame already hot in the tin.","Cook covered twenty minutes, turn it over in one piece, then twenty minutes on the other side. Two crusts beat one."]} },

{ id:'xacuti', c:'as', lat:15.273, lon:73.958, base:6, prep:60, cook:80, diff:3, tags:['poultry','stew','spicy'],
  art:{v:'pot',bg:'#33291f',plate:'#f0e4c8',style:'stew',food:['#5a3020','#8f4a3a','#e8c46a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Xacuti',en:'Xacuti'},
  p:{fr:'Margão, Goa, Inde',en:'Margao, Goa, India'},
  d:{fr:"Un curry goanais très sombre à la noix de coco grillée et à une douzaine d'épices. Le nom se prononce chacouti : c'est une graphie portugaise, le x notant en portugais du XVIe siècle le son que le konkani rendait autrement.",
     en:"A very dark Goan curry with toasted coconut and a dozen spices. The name is pronounced shakuti: the spelling is Portuguese, the x standing in sixteenth-century Portuguese for a sound Konkani wrote otherwise."},
  i:[['chicken',1.4,'kg'],['coconut',200,'g'],['kashmiri_chili',15,'pc'],['coriander_seeds',20,'g'],['cumin',10,'g'],['star_anise',3,'pc'],['nutmeg',3,'g'],['clove',8,'pc'],['cinnamon_stick',2,'pc'],['black_peppercorns',10,'g'],['poppy_seed',20,'g'],['onion',3,'pc'],['tamarind_paste',50,'g'],['turmeric',8,'g'],['salt',null,'']],
  s:{fr:["Grillez la noix de coco râpée à sec, à feu doux et en remuant sans arrêt, jusqu'à ce qu'elle devienne brun foncé.","C'est ce grillage poussé qui donne au xacuti sa couleur presque noire et son goût de noisette ; une coco blonde donne un curry pâle et plat.","Grillez chaque épice séparément, quelques secondes, puis moulez-les avec la coco et un peu d'eau en pâte lisse.","Faites revenir le poulet, ajoutez les oignons fondus puis la pâte, et laissez-la cuire dix minutes dans le gras avant de mouiller.","Mijotez quarante minutes, ajoutez le tamarin en fin de cuisson. Le xacuti doit être épais et presque noir."],
     en:["Dry-toast the grated coconut over low heat, stirring without pause, until it turns deep brown.","That hard toasting gives xacuti its almost black colour and nutty taste; pale coconut gives a pale, flat curry.","Toast each spice separately for a few seconds, then grind them with the coconut and a little water to a smooth paste.","Brown the chicken, add the softened onions then the paste, and cook it ten minutes in the fat before moistening.","Simmer forty minutes, adding tamarind at the end. Xacuti should be thick and nearly black."]} },

{ id:'goan-fish-curry', c:'as', lat:15.491, lon:73.828, base:4, prep:40, cook:35, diff:2, tags:['sea','stew','spicy'],
  art:{v:'pot',bg:'#33291f',plate:'#f0e4c8',style:'fish',food:['#e8a032','#c9302a','#f4f0e6','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Curry de poisson goanais',en:'Goan fish curry'},
  p:{fr:'Panaji, Goa, Inde',en:'Panaji, Goa, India'},
  d:{fr:"Un curry de poisson au lait de coco, au piment et au kokum, orange vif et franchement acide. Le kokum, un fruit séché noir, apporte une acidité fruitée que ni le tamarin ni le citron ne reproduisent ; c'est la signature de la côte de Konkan.",
     en:"A fish curry with coconut milk, chilli and kokum, bright orange and frankly sour. Kokum, a dried black fruit, brings a fruity acidity that neither tamarind nor lemon reproduces; it is the signature of the Konkan coast."},
  i:[['kingfish',700,'g'],['coconut',200,'g'],['kashmiri_chili',20,'g'],['coriander_seeds',20,'g'],['cumin',8,'g'],['turmeric',8,'g'],['kokum',6,'pc'],['ginger',30,'g'],['garlic',8,'clove'],['onion',2,'pc'],['green_chili',3,'pc'],['long_grain_rice',400,'g'],['coconut_oil',60,'ml'],['salt',null,'']],
  s:{fr:["Mixez la coco fraîche râpée avec les épices et un peu d'eau chaude en une pâte parfaitement lisse, puis pressez pour extraire le lait.","N'employez pas de coco grillée ici : contrairement au xacuti, le curry de poisson goanais doit rester clair et vif.","Faites tremper les kokums dix minutes dans l'eau tiède et ajoutez-les avec leur eau.","Faites cuire la sauce vingt minutes à découvert avant d'y coucher le poisson, sans jamais la faire bouillir.","Pochez le poisson huit minutes à frémissement, sans remuer. On secoue la casserole, on ne touille pas."],
     en:["Blend fresh grated coconut with the spices and a little hot water to a perfectly smooth paste, then press out the milk.","Do not use toasted coconut here: unlike xacuti, a Goan fish curry must stay bright and clear.","Soak the kokum ten minutes in warm water and add it with its liquid.","Cook the sauce twenty minutes uncovered before laying in the fish, never letting it boil.","Poach the fish eight minutes at a tremble, without stirring. Shake the pan, do not stir."]} },

{ id:'bebinca', c:'as', lat:15.498, lon:73.833, base:10, prep:120, cook:180, diff:3, tags:['sweet','bake','slow'],
  art:{v:'plate',bg:'#33291f',plate:'#f4ead4',style:'cake',food:['#c9924a','#e8c46a','#8f5a3a','#f2dfa8'],garnish:'#c9754a'},
  n:{fr:'Bebinca',en:'Bebinca'},
  p:{fr:'Panaji, Goa, Inde',en:'Panaji, Goa, India'},
  d:{fr:"Un gâteau de seize couches cuites une à une, au lait de coco et au jaune d'œuf. Chaque couche est enfournée séparément et doit dorer avant la suivante : il faut compter trois heures, et le nombre de couches était autrefois un marqueur de richesse.",
     en:"A cake of sixteen layers baked one at a time, with coconut milk and egg yolk. Each layer is baked separately and must colour before the next: it takes three hours, and the number of layers was once a marker of wealth."},
  i:[['egg_yolk',12,'pc'],['coconut_milk',600,'ml'],['flour',250,'g'],['sugar',400,'g'],['ghee',300,'g'],['nutmeg',5,'g'],['cardamom',6,'pc'],['vanilla',1,'pc']],
  s:{fr:["Battez les jaunes, le sucre et le lait de coco, puis incorporez la farine tamisée : la pâte doit être fluide comme une pâte à crêpes.","Filtrez-la : le moindre grumeau se voit dans une couche de trois millimètres.","Beurrez généreusement le moule au ghee, versez une louche et enfournez sous le gril jusqu'à ce que la surface brunisse.","Badigeonnez de ghee entre chaque couche, sans exception : c'est le ghee qui sépare les couches et permet de les voir à la coupe.","Répétez seize fois. Laissez refroidir douze heures avant de démouler : chaud, le gâteau se déchire entre les couches."],
     en:["Beat the yolks, sugar and coconut milk, then fold in the sifted flour: the batter should be as loose as pancake batter.","Strain it: the least lump shows in a three-millimetre layer.","Butter the tin generously with ghee, pour a ladleful and put it under the grill until the surface browns.","Brush with ghee between every layer, without exception: the ghee separates the layers and is what makes them visible when cut.","Repeat sixteen times. Cool twelve hours before turning out: warm, the cake tears between layers."]} },

{ id:'prawn-balchao', c:'as', lat:15.395, lon:73.816, base:6, prep:60, cook:40, diff:2, tags:['sea','spicy','slow'],
  art:{v:'pot',bg:'#33291f',plate:'#f0e4c8',style:'other',food:['#c9302a','#8f2a2a','#e8c46a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Balchão de crevettes',en:'Prawn balchão'},
  p:{fr:'Vasco de Gama, Goa, Inde',en:'Vasco da Gama, Goa, India'},
  d:{fr:"Des crevettes confites dans une pâte de piment et de vinaigre, à mi-chemin du pickle et du curry. Le balchão descend du balichão macanais, lui-même venu de Malacca : c'est une recette qui a fait deux fois le tour de l'empire portugais avant de se fixer à Goa.",
     en:"Prawns preserved in a chilli and vinegar paste, halfway between pickle and curry. Balchão descends from Macanese balichão, itself from Malacca: a recipe that went twice round the Portuguese empire before settling in Goa."},
  i:[['shrimp',700,'g'],['kashmiri_chili',30,'g'],['palm_vinegar',200,'ml'],['garlic',15,'clove'],['ginger',40,'g'],['cumin',10,'g'],['clove',8,'pc'],['cinnamon_stick',2,'pc'],['black_peppercorns',10,'g'],['onion',3,'pc'],['sugar',40,'g'],['sunflower_oil',150,'ml'],['salt',null,'']],
  s:{fr:["Broyez les épices et l'ail dans le vinaigre de palme, jamais dans l'eau : le vinaigre est le conservateur, et l'eau ferait tourner la préparation.","Faites revenir les crevettes très brièvement, une minute, et retirez-les avant de faire la sauce.","Faites cuire la pâte dans l'huile vingt minutes, à feu doux, jusqu'à ce que l'huile se sépare et remonte en surface.","Cette séparation est le signe que la pâte est cuite : sans elle, le balchão a un goût de vinaigre cru et ne se conserve pas.","Remettez les crevettes cinq minutes seulement. Le balchão se garde deux semaines au frais et s'améliore les premiers jours."],
     en:["Grind the spices and garlic in palm vinegar, never in water: the vinegar is the preservative, and water would turn the preparation.","Fry the prawns very briefly, one minute, and remove them before making the sauce.","Cook the paste in oil for twenty minutes over low heat, until the oil splits and rises to the surface.","That separation is the sign the paste is cooked: without it the balchão tastes of raw vinegar and will not keep.","Return the prawns for five minutes only. Balchão keeps a fortnight in the cold and improves over the first days."]} },

{ id:'rasgulla', c:'as', lat:22.573, lon:88.364, base:8, prep:90, cook:30, diff:3, tags:['sweet','festive','comfort'],
  art:{v:'bowl',bg:'#33291f',plate:'#f4ead4',style:'other',food:['#f4f0e6','#f0e8d0','#e8dcb8','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Rasgulla',en:'Rasgulla'},
  p:{fr:'Calcutta, Bengale-Occidental, Inde',en:'Kolkata, West Bengal, India'},
  d:{fr:"Des boules de fromage frais pochées dans un sirop léger, spongieuses et gorgées de sucre. Le Bengale-Occidental et l'Odisha se sont disputés son origine devant les tribunaux pendant des années ; les deux ont finalement obtenu une indication géographique distincte.",
     en:"Balls of fresh cheese poached in a light syrup, spongy and saturated with sugar. West Bengal and Odisha fought over its origin in the courts for years; both were finally granted separate geographical indications."},
  i:[['whole_milk',2,'l'],['lemon',3,'pc'],['sugar',400,'g'],['water',1.5,'l'],['semolina',20,'g'],['cardamom',6,'pc'],['rose_water',20,'ml']],
  s:{fr:["Faites cailler le lait bouillant au jus de citron, puis filtrez et rincez le caillé à l'eau froide pour ôter l'acidité.","Pressez-le trente minutes seulement : trop sec, il ne gonflera pas ; trop humide, les boules se défont dans le sirop.","Pétrissez le paneer à la paume dix minutes, jusqu'à ce qu'il devienne parfaitement lisse et légèrement gras au toucher.","Ce pétrissage est tout le secret : il rompt les grains et donne l'élasticité qui permet à la boule de doubler de volume.","Pochez dans un sirop léger à couvert, quinze minutes à gros bouillons. Les boules doivent doubler ; si elles restent petites, le pétrissage était insuffisant."],
     en:["Curdle the boiling milk with lemon juice, then strain and rinse the curd in cold water to remove the acidity.","Press it thirty minutes only: too dry and it will not swell; too wet and the balls disintegrate in the syrup.","Knead the paneer with your palm for ten minutes, until perfectly smooth and slightly greasy to the touch.","That kneading is the whole secret: it breaks the grains and gives the elasticity that lets the ball double in size.","Poach in a light syrup, covered, fifteen minutes at a rolling boil. The balls must double; if they stay small, the kneading was not enough."]} },

{ id:'mishti-doi', c:'as', lat:22.580, lon:88.360, base:6, prep:720, cook:60, diff:2, tags:['sweet','slow','comfort'],
  art:{v:'bowl',bg:'#33291f',plate:'#f4ead4',style:'other',food:['#c9924a','#e8c46a','#f2dfa8','#f4f0e6'],garnish:'#c9754a'},
  n:{fr:'Mishti doi',en:'Mishti doi'},
  p:{fr:'Calcutta, Bengale-Occidental, Inde',en:'Kolkata, West Bengal, India'},
  d:{fr:"Un yaourt sucré au sucre de palme caramélisé, fermenté en pot de terre. Le pot de terre poreux n'est pas décoratif : il absorbe le petit-lait à travers ses parois, ce qui concentre le yaourt et lui donne une fermeté qu'aucun récipient étanche ne permet.",
     en:"A yoghurt sweetened with caramelised palm sugar, set in an earthenware pot. The porous clay is not decorative: it absorbs whey through its walls, concentrating the yoghurt and giving it a firmness no sealed vessel allows."},
  i:[['whole_milk',1.5,'l'],['palm_sugar',250,'g'],['plain_yogurt',100,'g'],['cardamom',6,'pc'],['heavy_cream',150,'ml']],
  s:{fr:["Faites réduire le lait d'un tiers, une bonne heure, en raclant les parois pour y remettre la peau.","Faites fondre le sucre de palme à part jusqu'à ce qu'il caramélise franchement, puis incorporez-le au lait chaud.","Laissez tiédir à 45 °C exactement avant d'ajouter le yaourt : plus chaud il tue les ferments, plus froid ils ne démarrent pas.","Versez dans des pots de terre non vernis, préalablement trempés dans l'eau une heure.","Laissez fermenter huit heures dans un endroit tiède, sans y toucher, puis réfrigérez six heures avant de servir."],
     en:["Reduce the milk by a third, a good hour, scraping the sides to return the skin to the pan.","Melt the palm sugar separately until it frankly caramelises, then stir it into the hot milk.","Cool to exactly 45°C before adding the yoghurt: hotter kills the cultures, colder and they will not start.","Pour into unglazed clay pots that have been soaked in water for an hour.","Ferment eight hours somewhere warm, untouched, then chill six hours before serving."]} }
,

{ id:'shorshe-ilish', c:'as', lat:22.568, lon:88.372, base:4, prep:40, cook:25, diff:3, tags:['sea','stew','festive'],
  art:{v:'plate',bg:'#33291f',plate:'#f0e4c8',style:'fish',food:['#e8c46a','#f2dfa8','#7fae5a','#f4f0e6'],garnish:'#7fae6a'},
  n:{fr:'Shorshe ilish',en:'Shorshe ilish'},
  p:{fr:'Calcutta, Bengale-Occidental, Inde',en:'Kolkata, West Bengal, India'},
  d:{fr:"De l'alose hilsa pochée dans une pâte de moutarde piquante et d'huile de moutarde. L'hilsa est un poisson d'une richesse extrême mais criblé d'arêtes fines en Y ; les Bengalis les mangent sans les retirer, en les séparant en bouche par une technique apprise dans l'enfance.",
     en:"Hilsa shad poached in a pungent mustard paste with mustard oil. Hilsa is an extremely rich fish but riddled with fine Y-shaped bones; Bengalis eat them without removing them, separating them in the mouth by a technique learnt in childhood."},
  i:[['hilsa_fish',700,'g'],['mustard_seeds',60,'g'],['mustard_oil',120,'ml'],['green_chili',6,'pc'],['turmeric',10,'g'],['nigella_seeds',5,'g'],['long_grain_rice',400,'g'],['salt',null,'']],
  s:{fr:["Faites tremper les graines de moutarde vingt minutes dans l'eau tiède salée avec un piment vert.","Le sel et le piment pendant le broyage empêchent l'amertume : broyée seule, la moutarde devient franchement amère et le plat est perdu.","Broyez-la lentement au mortier ou au mixeur à basse vitesse, en ajoutant l'eau peu à peu.","Faites fumer l'huile de moutarde puis laissez-la retomber avant de l'employer : crue, elle est âcre et agressive.","Couchez les darnes dans la pâte, couvrez et pochez douze minutes à feu très doux, sans jamais remuer ni retourner."],
     en:["Soak the mustard seeds twenty minutes in warm salted water with a green chilli.","Salt and chilli during grinding prevent bitterness: ground alone, mustard turns frankly bitter and the dish is lost.","Grind slowly in a mortar or a blender on low speed, adding the water little by little.","Heat the mustard oil to smoking then let it fall back before using it: raw, it is acrid and aggressive.","Lay the fish steaks in the paste, cover and poach twelve minutes over very low heat, never stirring or turning."]} },

{ id:'kathi-roll', c:'as', lat:22.560, lon:88.350, base:4, prep:120, cook:30, diff:2, tags:['street','fast','poultry'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'roll',food:['#e8c46a','#8f5a3a','#f4f0e6','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Kathi roll',en:'Kathi roll'},
  p:{fr:'Calcutta, Bengale-Occidental, Inde',en:'Kolkata, West Bengal, India'},
  d:{fr:"Un paratha enroulé autour de viande grillée à l'œuf, mangé en marchant. Il a été inventé chez Nizam's à Calcutta dans les années 1930 : les employés de bureau voulaient emporter leur kebab sans se salir les mains, et l'on a enroulé la brochette dans le pain.",
     en:"A paratha rolled around grilled meat with egg, eaten walking. It was invented at Nizam's in Kolkata in the 1930s: office workers wanted to take their kebab away without dirtying their hands, so the skewer was rolled into the bread."},
  i:[['chicken_thighs',600,'g'],['flour',400,'g'],['egg',4,'pc'],['plain_yogurt',150,'g'],['ginger',40,'g'],['garlic',8,'clove'],['garam_masala',15,'g'],['lemon',2,'pc'],['onion',3,'pc'],['green_chili',4,'pc'],['ghee',120,'g'],['chaat_masala',10,'g'],['cilantro',1,'bunch'],['salt',null,'']],
  s:{fr:["Faites mariner le poulet deux heures au yaourt égoutté, à l'ail, au gingembre et aux épices.","Grillez-le à la plancha très chaude, en fine couche, jusqu'à ce que les bords caramélisent.","Préparez les parathas feuilletés et gardez-les souples sous un linge, empilés — un paratha sec se casse au roulage.","Battez un œuf et versez-le sur le paratha posé à plat dans la poêle : il se soude au pain, c'est ce qui rend le kathi roll étanche.","Garnissez de viande, d'oignon cru au citron et de chaat masala, roulez serré et enveloppez de papier."],
     en:["Marinate the chicken two hours in drained yoghurt, garlic, ginger and spices.","Grill it on a very hot plate in a thin layer, until the edges caramelise.","Make layered parathas and keep them supple under a cloth, stacked — a dry paratha cracks when rolled.","Beat an egg and pour it onto the paratha lying flat in the pan: it bonds to the bread, which is what makes a kathi roll leakproof.","Fill with meat, raw onion with lemon and chaat masala, roll tightly and wrap in paper."]} },

{ id:'sandesh', c:'as', lat:22.576, lon:88.368, base:8, prep:60, cook:25, diff:3, tags:['sweet','fresh','festive'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'other',food:['#f4f0e6','#f0e8d0','#e8dcb8','#7fae5a'],garnish:'#c9754a'},
  n:{fr:'Sandesh',en:'Sandesh'},
  p:{fr:'Calcutta, Bengale-Occidental, Inde',en:'Kolkata, West Bengal, India'},
  d:{fr:"Une confiserie de fromage frais à peine sucré, moulée en petites formes. À la différence du rasgulla, le sandesh ne se poche pas : le caillé est cuit à sec avec le sucre, très brièvement, et toute la difficulté est de s'arrêter avant qu'il ne devienne granuleux.",
     en:"A confection of barely sweetened fresh cheese, pressed into small shapes. Unlike rasgulla, sandesh is not poached: the curd is cooked dry with sugar, very briefly, and the whole difficulty is stopping before it turns grainy."},
  i:[['whole_milk',2,'l'],['lemon',3,'pc'],['powdered_sugar',150,'g'],['cardamom',6,'pc'],['saffron',0.5,'g'],['pistachios',60,'g'],['rose_water',15,'ml']],
  s:{fr:["Faites cailler le lait, filtrez et rincez à l'eau glacée, puis pressez sous un poids une heure entière.","Le caillé doit être franchement sec : toute humidité résiduelle fera fondre le sandesh à la cuisson.","Pétrissez-le à la paume dix minutes jusqu'à ce qu'il devienne lisse, puis mêlez le sucre glace.","Cuisez à feu très doux cinq à sept minutes seulement, en remuant sans arrêt : la masse doit se détacher mais rester souple.","Une minute de trop et le sandesh devient sableux et cassant. Moulez tiède, décorez et laissez prendre au frais."],
     en:["Curdle the milk, strain and rinse in iced water, then press under a weight for a full hour.","The curd must be frankly dry: any residual moisture will make the sandesh melt as it cooks.","Knead it with your palm for ten minutes until smooth, then work in the icing sugar.","Cook over very low heat for five to seven minutes only, stirring without pause: the mass should pull away but stay supple.","One minute too long and sandesh turns sandy and brittle. Mould it warm, decorate and set in the cold."]} },

{ id:'luchi-alur-dom', c:'as', lat:22.582, lon:88.355, base:6, prep:60, cook:50, diff:2, tags:['bread','veg','breakfast'],
  art:{v:'plate',bg:'#33291f',plate:'#f4ead4',style:'other',food:['#f4f0e6','#e8a032','#f2dfa8','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Luchi alur dom',en:'Luchi alur dom'},
  p:{fr:'Calcutta, Bengale-Occidental, Inde',en:'Kolkata, West Bengal, India'},
  d:{fr:"Des pains blancs frits et gonflés servis avec un curry de pommes de terre. Le luchi se distingue du puri par la farine : blanche et raffinée ici, complète pour le puri, ce qui donne un pain plus pâle, plus tendre et qui reste blanc à la friture.",
     en:"White puffed fried breads served with a potato curry. Luchi differs from puri in the flour: refined white here, wholemeal for puri, giving a paler, softer bread that stays white in the fryer."},
  i:[['flour',400,'g'],['ghee',80,'g'],['baby_potatoes',700,'g'],['ripe_tomato',300,'g'],['ginger',40,'g'],['cumin',10,'g'],['bay_leaf',3,'pc'],['turmeric',8,'g'],['kashmiri_chili',12,'g'],['asafoetida',3,'g'],['panch_phoron',10,'g'],['frying_oil',1,'l'],['water',180,'ml'],['salt',null,'']],
  s:{fr:["Sablez la farine avec le ghee avant d'ajouter l'eau : ce sablage empêche le gluten de se développer et donne un luchi tendre.","Pétrissez brièvement, une pâte ferme, et laissez reposer trente minutes sous un linge humide.","N'employez pas de farine pour abaisser mais un peu d'huile : la farine brûle dans le bain et noircit l'huile.","Frites à 180 °C en pressant le disque sous l'huile deux secondes. Il gonfle immédiatement et doit rester blanc.","Une huile trop chaude le colore avant qu'il gonfle ; c'est la seule erreur possible avec le luchi."],
     en:["Rub the ghee into the flour before adding water: that rubbing stops the gluten developing and gives a tender luchi.","Knead briefly to a firm dough and rest it thirty minutes under a damp cloth.","Do not use flour for rolling but a little oil: flour burns in the bath and blackens the oil.","Fry at 180°C, holding the disc under the oil for two seconds. It puffs at once and must stay white.","Oil that is too hot colours it before it puffs; that is the only mistake possible with luchi."]} },

{ id:'kosha-mangsho', c:'as', lat:22.570, lon:88.362, base:6, prep:120, cook:150, diff:3, tags:['lamb','stew','slow'],
  art:{v:'pot',bg:'#2b2419',plate:'#f0e4c8',style:'stew',food:['#3a2018','#5a3020','#e8c46a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Kosha mangsho',en:'Kosha mangsho'},
  p:{fr:'Calcutta, Bengale-Occidental, Inde',en:'Kolkata, West Bengal, India'},
  d:{fr:"Un curry de mouton presque sec, d'un brun très foncé, obtenu par un sauté prolongé. Kosha veut dire « frotté, travaillé » : la viande est remuée dans sa sauce pendant plus d'une heure, sans ajouter d'eau, jusqu'à ce que tout ait réduit et bruni.",
     en:"An almost dry mutton curry, very dark brown, got by prolonged sautéing. Kosha means rubbed, worked: the meat is stirred in its sauce for over an hour, with no water added, until everything has reduced and browned."},
  i:[['mutton_shoulder',1,'kg'],['onion',5,'pc'],['plain_yogurt',300,'g'],['ginger',50,'g'],['garlic',12,'clove'],['garam_masala',15,'g'],['bay_leaf',3,'pc'],['cardamom',8,'pc'],['cinnamon_stick',2,'pc'],['mustard_oil',150,'ml'],['kashmiri_chili',15,'g'],['sugar',15,'g'],['potato',400,'g'],['salt',null,'']],
  s:{fr:["Faites mariner le mouton deux heures au yaourt, à l'ail et au gingembre broyés.","Faites caraméliser une cuillerée de sucre dans l'huile de moutarde chaude avant tout : c'est ce sucre brûlé qui donne la couleur sombre.","Ajoutez la viande et remuez-la sans arrêt à feu moyen, quarante minutes, sans ajouter une goutte d'eau.","C'est ce sauté prolongé qui fait le plat : chaque fois que la sauce attache, on gratte et l'on continue, et la couleur s'approfondit.","Ajoutez ensuite un peu d'eau chaude et laissez mijoter une heure à couvert. Le kosha est prêt quand l'huile se sépare franchement."],
     en:["Marinate the mutton two hours in yoghurt with crushed garlic and ginger.","Caramelise a spoonful of sugar in the hot mustard oil before anything else: that burnt sugar gives the dark colour.","Add the meat and stir it without pause over medium heat for forty minutes, without adding a drop of water.","That prolonged sautéing makes the dish: each time the sauce catches, you scrape and continue, and the colour deepens.","Then add a little hot water and simmer an hour covered. Kosha is ready when the oil frankly separates."]} },

{ id:'masor-tenga', c:'as', lat:26.145, lon:91.736, base:4, prep:30, cook:30, diff:2, tags:['sea','soup','fresh'],
  art:{v:'bowl',bg:'#28331f',plate:'#f0e4c8',style:'fish',food:['#f4f0e6','#e8c46a','#7fae5a','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Masor tenga',en:'Masor tenga'},
  p:{fr:'Guwahati, Assam, Inde',en:'Guwahati, Assam, India'},
  d:{fr:"Un curry de poisson assamais léger et acide, sans épices piquantes. L'acidité vient du thekera, une mangoustane séchée, ou du citron ; c'est un plat d'été destiné à rafraîchir, et l'absence de piment et d'huile lourde le distingue de tous les curries voisins.",
     en:"A light, sour Assamese fish curry with no hot spices. The acidity comes from thekera, a dried mangosteen, or from lemon; it is a summer dish meant to cool, and the absence of chilli and heavy oil sets it apart from every neighbouring curry."},
  i:[['freshwater_fish',700,'g'],['ripe_tomato',400,'g'],['thekera',4,'pc'],['turmeric',10,'g'],['fenugreek_seeds',5,'g'],['green_chili',3,'pc'],['cilantro',1,'bunch'],['mustard_oil',60,'ml'],['bottle_gourd',300,'g'],['long_grain_rice',400,'g'],['salt',null,'']],
  s:{fr:["Frottez les darnes de curcuma et de sel et laissez-les vingt minutes avant de les faire dorer à l'huile de moutarde.","Faites frire le poisson en premier et réservez-le : ajouté cru au bouillon, il s'émiette et trouble la soupe.","Faites craquer les graines de fenugrec dans l'huile, quelques secondes seulement — brûlées, elles deviennent amères.","Ajoutez tomates et courge, mouillez et laissez cuire quinze minutes, puis ajoutez le thekera trempé.","Remettez le poisson pour cinq minutes. Le bouillon doit rester clair et franchement acide, jamais épais."],
     en:["Rub the fish steaks with turmeric and salt and leave them twenty minutes before browning them in mustard oil.","Fry the fish first and set it aside: added raw to the broth it flakes apart and clouds the soup.","Crackle the fenugreek seeds in the oil for a few seconds only — burnt, they turn bitter.","Add tomatoes and gourd, moisten and cook fifteen minutes, then add the soaked thekera.","Return the fish for five minutes. The broth should stay clear and frankly sour, never thick."]} },

{ id:'pitha-assam', c:'as', lat:26.752, lon:94.203, base:8, prep:480, cook:40, diff:3, tags:['sweet','festive','slow'],
  art:{v:'leaf',bg:'#28331f',plate:'#f4ead4',style:'other',food:['#f4f0e6','#8f5a3a','#f2dfa8','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Pitha',en:'Pitha'},
  p:{fr:'Jorhat, Assam, Inde',en:'Jorhat, Assam, India'},
  d:{fr:"Des gâteaux de riz gluant farcis de coco et de sucre de palme, grillés ou frits. Ils se préparent pour Bihu, la fête des moissons assamaise ; le riz doit être trempé, pilé et tamisé le jour même, car la farine achetée n'a pas la même plasticité.",
     en:"Glutinous rice cakes filled with coconut and palm sugar, griddled or fried. They are made for Bihu, the Assamese harvest festival; the rice must be soaked, pounded and sieved the same day, since bought flour lacks the same plasticity."},
  i:[['glutinous_rice',500,'g'],['coconut',300,'g'],['palm_sugar',250,'g'],['sesame_seeds',100,'g'],['ghee',80,'g'],['cardamom',6,'pc'],['banana_leaf',12,'pc'],['salt',null,'']],
  s:{fr:["Faites tremper le riz gluant six heures, égouttez-le une heure puis pilez-le encore humide et tamisez au tamis fin.","La farine doit rester légèrement humide au toucher : sèche, elle ne se soude pas et le pitha se fend à la cuisson.","Faites griller le sésame et la coco à sec, puis mêlez-les au sucre de palme fondu et laissez refroidir.","Étalez une fine couche de farine sur la plaque chaude, laissez-la prendre trente secondes, garnissez et repliez.","Le pitha se soude par la seule vapeur du riz : il n'y a ni œuf ni liant, et une plaque trop chaude l'empêche de coller."],
     en:["Soak the glutinous rice six hours, drain it an hour then pound it while still damp and sieve it finely.","The flour must stay slightly damp to the touch: dry, it will not bind and the pitha splits as it cooks.","Dry-toast the sesame and coconut, then mix them with melted palm sugar and cool.","Spread a thin layer of flour on the hot griddle, let it set for thirty seconds, fill and fold.","Pitha binds through the rice's own steam alone: there is no egg and no binder, and too hot a griddle stops it sticking."]} },

{ id:'haleem', c:'as', lat:17.385, lon:78.487, base:10, prep:480, cook:420, diff:3, tags:['lamb','slow','festive'],
  art:{v:'bowl',bg:'#33291f',plate:'#f0e4c8',style:'other',food:['#8f7a5a','#c9924a','#e8c46a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Haleem',en:'Haleem'},
  p:{fr:'Hyderabad, Telangana, Inde',en:'Hyderabad, Telangana, India'},
  d:{fr:"Une bouillie de blé et de viande pilée pendant des heures jusqu'à devenir filante. Le haleem de Hyderabad bénéficie d'une indication géographique protégée depuis 2010 ; on ne le prépare que pendant le Ramadan, et les restaurants ferment ce rayon le reste de l'année.",
     en:"A porridge of wheat and meat pounded for hours until it turns stringy. Hyderabadi haleem has held a protected geographical indication since 2010; it is made only during Ramadan, and restaurants close that counter the rest of the year."},
  i:[['mutton_shoulder',1.5,'kg'],['cracked_wheat',400,'g'],['chana_dal',150,'g'],['lentils',100,'g'],['onion',5,'pc'],['ghee',300,'g'],['ginger',60,'g'],['garlic',15,'clove'],['garam_masala',20,'g'],['plain_yogurt',300,'g'],['mint',2,'bunch'],['lemon',4,'pc'],['cashews',80,'g'],['salt',null,'']],
  s:{fr:["Faites tremper le blé concassé et les lentilles une nuit, puis cuisez-les à part jusqu'à ce qu'ils se défassent complètement.","Faites cuire la viande séparément avec les épices, trois heures, jusqu'à ce qu'elle se détache des os.","Réunissez tout et pilez au pilon de bois, sans interruption, pendant deux heures.","Ce pilonnage est le plat lui-même : il rompt les fibres de la viande et les mêle à l'amidon du blé, ce qu'aucun mixeur ne reproduit.","Le haleem est prêt quand il file en longs filaments et qu'aucun morceau n'est plus identifiable. Servez avec du ghee fondu et du citron."],
     en:["Soak the cracked wheat and lentils overnight, then cook them separately until they collapse completely.","Cook the meat separately with the spices for three hours, until it falls from the bones.","Bring everything together and pound with a wooden pestle, without pause, for two hours.","That pounding is the dish itself: it breaks the meat fibres and blends them into the wheat starch, which no blender reproduces.","Haleem is ready when it pulls into long strands and no piece is identifiable. Serve with melted ghee and lemon."]} },

{ id:'double-ka-meetha', c:'as', lat:17.390, lon:78.480, base:8, prep:40, cook:50, diff:2, tags:['sweet','festive','comfort'],
  art:{v:'plate',bg:'#33291f',plate:'#f4ead4',style:'other',food:['#c9924a','#f2dfa8','#e8c46a','#f4f0e6'],garnish:'#c9754a'},
  n:{fr:'Double ka meetha',en:'Double ka meetha'},
  p:{fr:'Hyderabad, Telangana, Inde',en:'Hyderabad, Telangana, India'},
  d:{fr:"Du pain de mie frit puis trempé dans un lait sucré au safran et aux fruits secs. Double désigne le pain de mie en argot hyderabadi, parce qu'il double de volume à la cuisson ; le dessert est servi aux mariages musulmans de la ville depuis l'époque des Nizams.",
     en:"Sliced bread fried then steeped in saffron milk with dried fruit. Double is Hyderabadi slang for sliced bread, because it doubles in size as it bakes; the dessert has been served at the city's Muslim weddings since the time of the Nizams."},
  i:[['white_bread',10,'slice'],['whole_milk',1,'l'],['sugar',250,'g'],['ghee',200,'g'],['saffron',0.5,'g'],['cardamom',8,'pc'],['almonds',80,'g'],['cashews',80,'g'],['raisins',60,'g'],['heavy_cream',150,'ml']],
  s:{fr:["Retirez les croûtes et coupez le pain en triangles, puis laissez-le sécher deux heures à l'air.","Un pain frais absorbe le ghee comme une éponge et le dessert devient gras et lourd.","Frites au ghee jusqu'au brun doré, puis égouttez sur grille et non sur papier, pour que les deux faces restent croustillantes.","Faites réduire le lait d'un tiers avec le safran et la cardamome, puis sucrez.","Versez le lait chaud sur le pain juste avant de servir, et non à l'avance : le pain doit être imbibé mais garder sa forme."],
     en:["Cut off the crusts and cut the bread into triangles, then let it dry two hours in the air.","Fresh bread drinks ghee like a sponge and the dessert turns greasy and heavy.","Fry in ghee to golden brown, then drain on a rack rather than paper, so both faces stay crisp.","Reduce the milk by a third with the saffron and cardamom, then sweeten.","Pour the hot milk over the bread just before serving, not in advance: the bread should be soaked but keep its shape."]} },

{ id:'osmania-irani-chai', c:'as', lat:17.380, lon:78.474, base:8, prep:120, cook:30, diff:2, tags:['sweet','bake','drink'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'other',food:['#e8c46a','#f2dfa8','#8f5a3a','#f4f0e6'],garnish:'#c9754a'},
  n:{fr:'Biscuit Osmania et chai irani',en:'Osmania biscuit and Irani chai'},
  p:{fr:'Hyderabad, Telangana, Inde',en:'Hyderabad, Telangana, India'},
  d:{fr:"Un biscuit salé-sucré au beurre, trempé dans un thé au lait très réduit. Le biscuit porte le nom du dernier Nizam, Osman Ali Khan ; les cafés irani de Hyderabad, tenus par des Zoroastriens venus de Perse au XIXe siècle, en servent depuis plus de cent ans.",
     en:"A sweet-salty butter biscuit dunked in heavily reduced milk tea. The biscuit is named after the last Nizam, Osman Ali Khan; Hyderabad's Irani cafés, run by Zoroastrians who came from Persia in the nineteenth century, have served it for over a century."},
  i:[['flour',400,'g'],['butter',200,'g'],['powdered_sugar',120,'g'],['milk_powder',60,'g'],['egg',1,'pc'],['cardamom',6,'pc'],['baking_powder',6,'g'],['black_tea',30,'g'],['whole_milk',1,'l'],['sugar',150,'g'],['salt',null,'']],
  s:{fr:["Le biscuit doit être franchement salé autant que sucré : c'est cet équilibre inhabituel qui fait l'Osmania, et une main timide sur le sel le rend banal.","Crémez le beurre et le sucre glace longuement, puis incorporez farine, lait en poudre et cardamome sans pétrir.","Laissez reposer la pâte une heure au froid, abaissez à sept millimètres et découpez des disques.","Cuisez 15 minutes à 170 °C : les biscuits doivent rester pâles et blondir à peine sur les bords.","Pour le chai, faites bouillir le thé dans le lait vingt minutes en le versant de haut d'un récipient à l'autre pour l'aérer."],
     en:["The biscuit must be as frankly salty as it is sweet: that unusual balance makes an Osmania, and a timid hand with salt makes it ordinary.","Cream the butter and icing sugar at length, then fold in flour, milk powder and cardamom without kneading.","Rest the dough an hour in the cold, roll to seven millimetres and cut discs.","Bake 15 minutes at 170°C: the biscuits should stay pale and barely colour at the edges.","For the chai, boil the tea in the milk for twenty minutes, pouring it from height between two vessels to aerate it."]} },

{ id:'idli-sambar', c:'as', lat:13.083, lon:80.271, base:6, prep:720, cook:60, diff:3, tags:['breakfast','veg','comfort'],
  art:{v:'plate',bg:'#33291f',plate:'#f0e4c8',style:'other',food:['#f4f0e6','#e8a032','#7fae5a','#f2dfa8'],garnish:'#7fae6a'},
  n:{fr:'Idli sambar',en:'Idli sambar'},
  p:{fr:'Chennai, Tamil Nadu, Inde',en:'Chennai, Tamil Nadu, India'},
  d:{fr:"Des galettes de riz et lentilles fermentées, cuites à la vapeur, avec un ragoût de lentilles acidulé. La fermentation repose sur une bactérie présente naturellement sur la peau des lentilles urad : c'est pourquoi on ne les lave jamais trop, et pourquoi la pâte lève sans levure ajoutée.",
     en:"Steamed cakes of fermented rice and lentils with a sour lentil stew. The fermentation relies on a bacterium naturally present on the skin of urad lentils: which is why they are never washed too much, and why the batter rises with no added yeast."},
  i:[['rice',400,'g'],['urad_dal',150,'g'],['fenugreek_seeds',10,'g'],['toor_dal',200,'g'],['tamarind_paste',60,'g'],['sambar_powder',30,'g'],['drumstick',2,'pc'],['pearl_onions',150,'g'],['ripe_tomato',200,'g'],['mustard_seeds',10,'g'],['curry_leaves',20,'pc'],['asafoetida',3,'g'],['sunflower_oil',60,'ml'],['salt',null,'']],
  s:{fr:["Faites tremper riz et lentilles séparément six heures, avec le fenugrec dans les lentilles.","Broyez les lentilles en premier, à l'eau glacée et par à-coups : la pâte doit rester froide, la chaleur du broyeur tuerait les ferments.","Broyez ensuite le riz plus grossièrement, mêlez à la main — c'est la main qui apporte les ferments, dit-on, et l'usage est constant.","Laissez fermenter dix heures à 28-30 °C : la pâte doit doubler et sentir franchement l'aigre.","Ne remuez pas la pâte levée avant de la verser dans les moules : chaque tour de cuillère chasse le gaz et alourdit l'idli."],
     en:["Soak rice and lentils separately for six hours, with the fenugreek among the lentils.","Grind the lentils first, with iced water and in bursts: the batter must stay cold, the grinder's heat would kill the cultures.","Then grind the rice more coarsely and mix by hand — the hand carries the cultures, it is said, and the practice is universal.","Ferment ten hours at 28-30°C: the batter should double and smell frankly sour.","Do not stir the risen batter before pouring it into the moulds: every turn of the spoon drives out gas and weighs the idli down."]} },

{ id:'meen-curry-kerala', c:'as', lat:9.498, lon:76.339, base:4, prep:40, cook:35, diff:2, tags:['sea','stew','spicy'],
  art:{v:'pot',bg:'#33291f',plate:'#f0e4c8',style:'fish',food:['#c9302a','#8f2a2a','#e8c46a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Meen curry du Kerala',en:'Kerala meen curry'},
  p:{fr:'Alleppey, Kerala, Inde',en:'Alleppey, Kerala, India'},
  d:{fr:"Un curry de poisson rouge foncé au kudampuli, cuit en pot de terre. Le kudampuli, ou tamarin de Malabar, noircit le curry et lui donne une acidité fumée ; le pot de terre non vernissé, le manchatti, absorbe et rend le goût d'un jour sur l'autre.",
     en:"A deep red fish curry with kudampuli, cooked in an earthenware pot. Kudampuli, or Malabar tamarind, darkens the curry and gives a smoky sourness; the unglazed clay manchatti absorbs and returns the flavour from one day to the next."},
  i:[['kingfish',700,'g'],['kudampuli',6,'pc'],['kashmiri_chili',30,'g'],['coconut_oil',80,'ml'],['shallot',10,'pc'],['ginger',40,'g'],['garlic',10,'clove'],['curry_leaves',30,'pc'],['fenugreek_seeds',5,'g'],['turmeric',10,'g'],['mustard_seeds',8,'g'],['long_grain_rice',400,'g'],['salt',null,'']],
  s:{fr:["Faites tremper le kudampuli vingt minutes dans l'eau tiède ; ne le remplacez pas par du tamarin ordinaire, l'acidité n'est pas la même.","Employez l'huile de coco et rien d'autre : c'est elle qui donne l'odeur reconnaissable d'un curry du Kerala.","Faites craquer moutarde et fenugrec, puis faites revenir échalotes, ail, gingembre et curry très longuement.","Ajoutez la pâte de piment et laissez-la cuire dans l'huile jusqu'à ce qu'elle se sépare, avant tout liquide.","Couchez le poisson, couvrez et laissez frémir quinze minutes sans remuer. Le curry est meilleur le lendemain."],
     en:["Soak the kudampuli twenty minutes in warm water; do not substitute ordinary tamarind, the acidity is not the same.","Use coconut oil and nothing else: it gives the recognisable smell of a Kerala curry.","Crackle the mustard and fenugreek, then fry the shallots, garlic, ginger and curry leaves at length.","Add the chilli paste and cook it in the oil until it splits, before any liquid goes in.","Lay in the fish, cover and simmer fifteen minutes without stirring. The curry is better the next day."]} }
,

{ id:'avial', c:'as', lat:8.524, lon:76.937, base:6, prep:40, cook:35, diff:2, tags:['veg','comfort','festive'],
  art:{v:'bowl',bg:'#28331f',plate:'#f0e4c8',style:'other',food:['#f4f0e6','#7fae5a','#e8c46a','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Avial',en:'Avial'},
  p:{fr:'Thiruvananthapuram, Kerala, Inde',en:'Thiruvananthapuram, Kerala, India'},
  d:{fr:"Un mélange de légumes en bâtonnets lié à la coco et au yaourt, à peine épicé. La légende l'attribue à Bhima, du Mahabharata, qui aurait improvisé un plat avec tous les restes de légumes ; c'est le plat central du sadya, le banquet servi sur feuille de bananier.",
     en:"A mixture of vegetables cut into batons bound with coconut and yoghurt, barely spiced. Legend credits it to Bhima of the Mahabharata, who improvised a dish from every leftover vegetable; it is the centrepiece of the sadya, the banquet served on a banana leaf."},
  i:[['drumstick',2,'pc'],['plantain',2,'pc'],['carrot',2,'pc'],['yam',300,'g'],['green_beans',200,'g'],['ash_gourd',300,'g'],['coconut',250,'g'],['plain_yogurt',200,'g'],['green_chili',5,'pc'],['cumin',10,'g'],['curry_leaves',30,'pc'],['coconut_oil',60,'ml'],['turmeric',8,'g'],['salt',null,'']],
  s:{fr:["Coupez tous les légumes en bâtonnets de même taille, cinq centimètres sur un : la forme est canonique et fait partie du plat.","Ajoutez-les par ordre de fermeté, à quelques minutes d'intervalle, dans très peu d'eau.","Les légumes doivent rester entiers et reconnaissables : un avial en purée est un avial raté.","Broyez la coco fraîche avec le cumin et le piment vert, grossièrement, sans en faire une pâte lisse.","Ajoutez la coco puis le yaourt hors du feu, et finissez par un filet d'huile de coco crue et des feuilles de curry."],
     en:["Cut all the vegetables into batons of the same size, five centimetres by one: the shape is canonical and part of the dish.","Add them in order of firmness, a few minutes apart, in very little water.","The vegetables must stay whole and recognisable: a puréed avial has failed.","Grind the fresh coconut with the cumin and green chilli, coarsely, without making a smooth paste.","Add the coconut then the yoghurt off the heat, and finish with a thread of raw coconut oil and curry leaves."]} },

{ id:'ven-pongal', c:'as', lat:13.078, lon:80.265, base:4, prep:30, cook:40, diff:1, tags:['breakfast','rice','comfort'],
  art:{v:'bowl',bg:'#33291f',plate:'#f0e4c8',style:'rice',food:['#f2dfa8','#f4f0e6','#e8c46a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Ven pongal',en:'Ven pongal'},
  p:{fr:'Chennai, Tamil Nadu, Inde',en:'Chennai, Tamil Nadu, India'},
  d:{fr:"Une bouillie de riz et de lentilles mung au poivre, au cumin et au ghee. Ven veut dire blanc : c'est la version salée du pongal, par opposition au sakkarai pongal sucré, et le poivre noir y remplace entièrement le piment.",
     en:"A porridge of rice and mung lentils with pepper, cumin and ghee. Ven means white: it is the savoury version of pongal, as against the sweet sakkarai pongal, and black pepper entirely replaces chilli."},
  i:[['rice',250,'g'],['mung_beans',150,'g'],['ghee',120,'g'],['black_peppercorns',15,'g'],['cumin',10,'g'],['ginger',30,'g'],['curry_leaves',20,'pc'],['cashews',60,'g'],['asafoetida',3,'g'],['water',1.2,'l'],['salt',null,'']],
  s:{fr:["Grillez les lentilles mung à sec jusqu'à ce qu'elles embaument, avant de les rincer : c'est ce grillage qui donne le goût de noisette.","Cuisez riz et lentilles ensemble dans beaucoup d'eau, jusqu'à ce que tout se défasse en bouillie.","Le pongal doit être franchement mou et coulant ; ferme, il durcit en refroidissant et devient immangeable.","Concassez le poivre grossièrement au mortier plutôt que de le moudre : on doit croquer des morceaux.","Faites frire les cajous, le poivre, le cumin et les feuilles de curry dans le ghee et versez le tout sur le pongal."],
     en:["Dry-toast the mung lentils until fragrant before rinsing them: that toasting gives the nutty flavour.","Cook rice and lentils together in plenty of water, until everything collapses into porridge.","Pongal must be frankly soft and loose; firm, it hardens as it cools and becomes inedible.","Crack the pepper roughly in a mortar rather than grinding it: you should bite into pieces.","Fry the cashews, pepper, cumin and curry leaves in ghee and pour the lot over the pongal."]} },

{ id:'mysore-pak', c:'as', lat:12.295, lon:76.639, base:10, prep:30, cook:40, diff:3, tags:['sweet','festive','fast'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'other',food:['#e8c46a','#f2dfa8','#c9924a','#f4f0e6'],garnish:'#c9754a'},
  n:{fr:'Mysore pak',en:'Mysore pak'},
  p:{fr:'Mysore, Karnataka, Inde',en:'Mysore, Karnataka, India'},
  d:{fr:"Une confiserie de farine de pois chiche, de ghee et de sucre, poreuse et fondante. Elle a été créée vers 1935 dans les cuisines du palais de Mysore par le chef Kakasura Madappa ; la version originale employait une quantité de ghee que la plupart des recettes modernes n'osent plus.",
     en:"A confection of chickpea flour, ghee and sugar, porous and melting. It was created around 1935 in the kitchens of Mysore Palace by the cook Kakasura Madappa; the original used a quantity of ghee most modern recipes no longer dare."},
  i:[['chickpea_flour',250,'g'],['ghee',500,'g'],['sugar',500,'g'],['water',200,'ml'],['cardamom',6,'pc']],
  s:{fr:["Tamisez la farine de pois chiche trois fois et faites-la griller à sec deux minutes : sans cela, le goût cru domine.","Portez le sucre et l'eau à 118 °C au thermomètre, stade du boulé mou, avant d'incorporer la farine.","Versez le ghee bouillant en filet, louche par louche, sans jamais cesser de remuer.","C'est l'ajout progressif du ghee qui crée les alvéoles : versé d'un coup, il se sépare et le mysore pak devient dense et gras.","Arrêtez quand la masse mousse et se détache du fond. Versez aussitôt et découpez au bout de trois minutes, pas plus tard."],
     en:["Sift the chickpea flour three times and dry-toast it two minutes: without that the raw taste dominates.","Bring the sugar and water to 118°C on a thermometer, the soft ball stage, before working in the flour.","Pour in boiling ghee in a stream, ladle by ladle, without ever stopping stirring.","It is the gradual addition of ghee that creates the honeycomb: poured in at once it splits and the mysore pak turns dense and greasy.","Stop when the mass foams and pulls from the base. Pour at once and cut after three minutes, no later."]} },

{ id:'bisi-bele-bath', c:'as', lat:12.300, lon:76.645, base:6, prep:60, cook:70, diff:3, tags:['rice','legume','comfort'],
  art:{v:'bowl',bg:'#33291f',plate:'#f0e4c8',style:'rice',food:['#e8a032','#c9924a','#7fae5a','#f2dfa8'],garnish:'#7fae6a'},
  n:{fr:'Bisi bele bath',en:'Bisi bele bath'},
  p:{fr:'Mysore, Karnataka, Inde',en:'Mysore, Karnataka, India'},
  d:{fr:"Un plat unique de riz, lentilles et légumes lié par un masala à la coco. Le nom signifie littéralement « riz-lentilles chaud » en kannada : il ne se mange jamais froid, et sa texture se resserre en refroidissant au point de devenir un bloc.",
     en:"A one-pot dish of rice, lentils and vegetables bound by a coconut masala. The name means literally hot lentil rice in Kannada: it is never eaten cold, and its texture tightens as it cools to the point of becoming a block."},
  i:[['rice',300,'g'],['toor_dal',200,'g'],['tamarind_paste',60,'g'],['coconut',100,'g'],['kashmiri_chili',10,'pc'],['coriander_seeds',20,'g'],['chana_dal',20,'g'],['cinnamon_stick',2,'pc'],['clove',6,'pc'],['carrot',2,'pc'],['green_beans',150,'g'],['peas',150,'g'],['ghee',120,'g'],['curry_leaves',20,'pc'],['salt',null,'']],
  s:{fr:["Grillez chaque épice du masala séparément, à sec et à feu doux : ensemble, certaines brûlent pendant que d'autres restent crues.","Grillez la coco en dernier et laissez tout refroidir avant de moudre — moulues chaudes, les épices rendent leur huile et forment une pâte.","Cuisez le riz et les lentilles ensemble, plus longtemps que d'ordinaire : ils doivent se défaire, contrairement à un pulao.","Ajoutez le tamarin, les légumes et le masala, et laissez cuire vingt minutes de plus.","Le plat doit être franchement coulant à la sortie du feu : il épaissit énormément en dix minutes. Servez brûlant avec du ghee."],
     en:["Toast each masala spice separately, dry and over low heat: together, some burn while others stay raw.","Toast the coconut last and cool everything before grinding — ground hot, the spices release their oil and form a paste.","Cook the rice and lentils together, longer than usual: they must collapse, unlike a pulao.","Add the tamarind, vegetables and masala, and cook twenty minutes more.","The dish must be frankly loose as it leaves the heat: it thickens enormously within ten minutes. Serve scalding with ghee."]} },

{ id:'rasam', c:'as', lat:9.925, lon:78.120, base:6, prep:30, cook:35, diff:2, tags:['soup','veg','comfort'],
  art:{v:'bowl',bg:'#33291f',plate:'#f0e4c8',style:'soup',food:['#c9302a','#e8a032','#f4f0e6','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Rasam',en:'Rasam'},
  p:{fr:'Madurai, Tamil Nadu, Inde',en:'Madurai, Tamil Nadu, India'},
  d:{fr:"Un bouillon clair au tamarin, au poivre et à la tomate, bu ou versé sur le riz. Il ne se fait jamais bouillir une fois assaisonné : dès qu'il bout, le rasam perd son parfum et devient plat, et le moment où l'on coupe le feu est tout l'art du plat.",
     en:"A clear broth of tamarind, pepper and tomato, drunk or poured over rice. It is never boiled once seasoned: the moment it boils, rasam loses its perfume and goes flat, and knowing when to cut the heat is the whole art of it."},
  i:[['tamarind_paste',60,'g'],['ripe_tomato',400,'g'],['toor_dal',100,'g'],['black_peppercorns',15,'g'],['cumin',15,'g'],['garlic',8,'clove'],['kashmiri_chili',4,'pc'],['curry_leaves',30,'pc'],['mustard_seeds',10,'g'],['asafoetida',3,'g'],['cilantro',1,'bunch'],['ghee',40,'g'],['turmeric',8,'g'],['salt',null,'']],
  s:{fr:["Concassez grossièrement poivre, cumin et ail au mortier juste avant l'emploi : moulus à l'avance, ils perdent l'essentiel de leur parfum.","Faites cuire l'eau de tamarin avec les tomates et le curcuma dix minutes, jusqu'à ce que l'odeur crue du tamarin disparaisse.","Ajoutez l'eau de cuisson des lentilles et la poudre concassée, et surveillez la casserole.","Coupez le feu dès que la mousse blanche monte à la surface, avant l'ébullition franche : c'est le signal.","Versez par-dessus un tempérage de moutarde, piment et feuilles de curry frits au ghee, et couvrez aussitôt."],
     en:["Crack the pepper, cumin and garlic roughly in a mortar just before use: ground ahead, they lose most of their perfume.","Cook the tamarind water with the tomatoes and turmeric for ten minutes, until the raw tamarind smell goes.","Add the lentil cooking water and the cracked powder, and watch the pan.","Cut the heat the moment white foam rises to the surface, before a proper boil: that is the signal.","Pour over a tempering of mustard, chilli and curry leaves fried in ghee, and cover at once."]} },

{ id:'puttu-kadala', c:'as', lat:11.259, lon:75.780, base:4, prep:720, cook:60, diff:2, tags:['breakfast','legume','veg'],
  art:{v:'plate',bg:'#33291f',plate:'#f0e4c8',style:'other',food:['#f4f0e6','#5a3020','#f0e8d0','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Puttu kadala',en:'Puttu kadala'},
  p:{fr:'Kozhikode, Kerala, Inde',en:'Kozhikode, Kerala, India'},
  d:{fr:"Un cylindre de farine de riz et de coco cuit à la vapeur, servi avec un curry de pois chiches noirs. Le puttu se cuit dans un tube de bambou ou de laiton ; le mot vient du tamoul et signifie « portionné », d'après la manière dont il se casse en tronçons.",
     en:"A cylinder of rice flour and coconut steamed and served with a black chickpea curry. Puttu is cooked in a bamboo or brass tube; the word comes from Tamil and means portioned, from the way it breaks into sections."},
  i:[['rice_flour',300,'g'],['coconut',200,'g'],['black_chickpeas',300,'g'],['coconut_oil',60,'ml'],['shallot',8,'pc'],['ginger',30,'g'],['garlic',6,'clove'],['coriander_seeds',15,'g'],['kashmiri_chili',15,'g'],['curry_leaves',20,'pc'],['mustard_seeds',8,'g'],['coconut_milk',200,'ml'],['salt',null,'']],
  s:{fr:["Grillez la farine de riz à sec cinq minutes, puis laissez-la refroidir avant de l'humecter.","Humectez-la du bout des doigts avec de l'eau salée, jusqu'à ce qu'elle s'agglomère à peine sous la pression sans former de pâte.","C'est le point le plus délicat : trop sèche, le puttu s'effrite ; trop humide, il devient compact et lourd.","Passez au tamis, puis remplissez le tube en alternant couches de farine et de coco râpée, sans jamais tasser.","Dix minutes à la vapeur suffisent. Poussez le cylindre hors du tube avec une baguette et servez avec le curry de pois chiches."],
     en:["Dry-toast the rice flour five minutes, then cool it before moistening.","Moisten it with salted water using your fingertips, until it barely clumps under pressure without forming a paste.","This is the most delicate point: too dry and the puttu crumbles; too wet and it turns dense and heavy.","Sieve it, then fill the tube alternating layers of flour and grated coconut, never pressing.","Ten minutes' steaming is enough. Push the cylinder out of the tube with a stick and serve with the chickpea curry."]} },

{ id:'thayir-sadam', c:'as', lat:13.070, lon:80.260, base:4, prep:30, cook:25, diff:1, tags:['rice','comfort','fresh'],
  art:{v:'bowl',bg:'#33291f',plate:'#f0e4c8',style:'rice',food:['#f4f0e6','#f0e8d0','#7fae5a','#e8c46a'],garnish:'#7fae6a'},
  n:{fr:'Thayir sadam',en:'Thayir sadam'},
  p:{fr:'Chennai, Tamil Nadu, Inde',en:'Chennai, Tamil Nadu, India'},
  d:{fr:"Du riz mêlé de yaourt et de lait, tempéré aux épices, mangé en fin de repas. Il clôt tout repas tamoul et sert de tampon après les plats acides et pimentés ; il se transporte aussi très bien, et c'est le repas de train par excellence en Inde du Sud.",
     en:"Rice mixed with yoghurt and milk, tempered with spices, eaten at the end of a meal. It closes every Tamil meal and acts as a buffer after sour and spicy dishes; it also travels well, and is the South Indian train meal par excellence."},
  i:[['rice',300,'g'],['plain_yogurt',500,'g'],['whole_milk',200,'ml'],['mustard_seeds',10,'g'],['urad_dal',15,'g'],['green_chili',3,'pc'],['ginger',30,'g'],['curry_leaves',20,'pc'],['asafoetida',3,'g'],['cilantro',1,'bunch'],['sunflower_oil',40,'ml'],['pomegranate',60,'g'],['salt',null,'']],
  s:{fr:["Cuisez le riz plus longtemps que d'ordinaire, jusqu'à ce qu'il soit franchement mou, puis écrasez-le à moitié à la cuillère.","Laissez-le tiédir avant d'ajouter le yaourt : chaud, il ferait tourner le yaourt en petit-lait.","Ajoutez le lait en plus du yaourt : il tempère l'acidité et empêche le plat de devenir trop aigre en quelques heures.","Faites craquer moutarde et lentilles urad dans l'huile chaude, avec le piment et les feuilles de curry, et versez sur le riz.","Salez au dernier moment : salé à l'avance, le yaourt rend son eau et le riz devient liquide."],
     en:["Cook the rice longer than usual, until frankly soft, then half-crush it with a spoon.","Let it cool to warm before adding the yoghurt: hot, it would curdle the yoghurt into whey.","Add milk as well as yoghurt: it tempers the acidity and stops the dish turning too sour within hours.","Crackle mustard and urad lentils in hot oil with the chilli and curry leaves, and pour over the rice.","Salt at the last moment: salted ahead, the yoghurt weeps and the rice goes runny."]} }
,

{ id:'hui-guo-rou', c:'as', lat:30.580, lon:104.070, base:4, prep:40, cook:25, diff:2, tags:['pork','spicy','comfort'],
  art:{v:'plate',bg:'#33291f',plate:'#f0e4c8',style:'other',food:['#c9302a','#7fae5a','#e8c46a','#8f5a3a'],garnish:'#7fae6a'},
  n:{fr:'Porc deux fois cuit',en:'Twice-cooked pork'},
  p:{fr:'Chengdu, Sichuan, Chine',en:'Chengdu, Sichuan, China'},
  d:{fr:"De la poitrine de porc pochée puis sautée à la pâte de fèves pimentée. Le nom chinois signifie « viande revenue au wok » : elle était d'abord bouillie pour les offrandes aux ancêtres, puis resautée pour être mangée, et l'usage rituel a fait la recette.",
     en:"Pork belly poached then stir-fried with fermented chilli bean paste. The Chinese name means meat returned to the wok: it was first boiled as an offering to the ancestors, then re-fried to be eaten, and the ritual made the recipe."},
  i:[['pork_belly',600,'g'],['doubanjiang',60,'g'],['sweet_bean_sauce',30,'g'],['fermented_black_beans',20,'g'],['leek',3,'pc'],['garlic',6,'clove'],['ginger',30,'g'],['shaoxing_wine',40,'ml'],['sugar',15,'g'],['peanut_oil',40,'ml'],['sichuan_peppercorns',8,'g']],
  s:{fr:["Pochez la poitrine entière trente minutes avec gingembre et poireau, jusqu'à ce qu'une baguette la traverse sans résistance.","Laissez-la refroidir complètement, deux heures au réfrigérateur : chaude, elle est impossible à trancher fin.","Coupez des tranches de deux millimètres, aussi larges que possible — la finesse fait tout le plat.","Faites-les sauter à sec dans le wok jusqu'à ce qu'elles se recroquevillent en godets et que le gras devienne translucide.","Ajoutez alors la doubanjiang et laissez-la griller dans le gras rendu, jusqu'à ce que l'huile rougisse."],
     en:["Poach the whole belly thirty minutes with ginger and leek, until a chopstick passes through without resistance.","Cool it completely, two hours in the refrigerator: warm, it cannot be sliced thin.","Cut two-millimetre slices, as wide as possible — the thinness makes the dish.","Stir-fry them dry in the wok until they curl into cups and the fat turns translucent.","Only then add the doubanjiang and let it toast in the rendered fat, until the oil reddens."]} },

{ id:'fuqi-feipian', c:'as', lat:30.660, lon:104.063, base:6, prep:120, cook:150, diff:3, tags:['beef','spicy','fresh'],
  art:{v:'plate',bg:'#33291f',plate:'#f0e4c8',style:'salad',food:['#c9302a','#8f4a3a','#f2dfa8','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Fuqi feipian',en:'Fuqi feipian'},
  p:{fr:'Chengdu, Sichuan, Chine',en:'Chengdu, Sichuan, China'},
  d:{fr:"Des tranches fines d'abats de bœuf froids, noyées d'huile pimentée et de cacahuètes. Le nom veut dire « tranches de poumon du couple » : il vient d'un couple de vendeurs des années 1930 dont les tranches étaient réputées les plus fines de Chengdu, et il n'y a jamais eu de poumon dedans.",
     en:"Thin slices of cold beef offal drowned in chilli oil with peanuts. The name means husband-and-wife lung slices: it comes from a couple of vendors in the 1930s whose slices were reckoned the thinnest in Chengdu, and there has never been any lung in it."},
  i:[['beef_tripe',400,'g'],['beef_tongue',300,'g'],['beef_heart',300,'g'],['star_anise',3,'pc'],['cinnamon_stick',2,'pc'],['sichuan_peppercorns',15,'g'],['chili_oil',100,'ml'],['soy_sauce',60,'ml'],['peanuts',80,'g'],['celery',3,'stalk'],['scallion',1,'bunch'],['sesame_seeds',20,'g'],['sugar',10,'g']],
  s:{fr:["Faites dégorger les abats trois heures à l'eau froide en changeant l'eau, puis blanchissez-les dix minutes.","Cuisez-les deux heures dans un bouillon d'épices très parfumé, puis laissez-les refroidir dedans une nuit entière.","C'est ce refroidissement dans le bouillon qui les parfume à cœur ; sortis chauds, ils restent fades au centre.","Tranchez-les glacés, à un millimètre, avec un couteau parfaitement affûté — la finesse est le nom même du plat.","Nappez d'huile pimentée et de bouillon réduit, et parsemez de cacahuètes concassées et de céleri cru."],
     en:["Soak the offal three hours in cold water, changing it, then blanch it ten minutes.","Cook it two hours in a heavily spiced broth, then let it cool in that broth overnight.","It is cooling in the broth that flavours it through; taken out hot, it stays bland at the centre.","Slice it ice-cold at one millimetre with a perfectly sharp knife — thinness is the dish's very name.","Coat with chilli oil and reduced broth, and scatter crushed peanuts and raw celery."]} },

{ id:'yuxiang-rousi', c:'as', lat:30.590, lon:104.080, base:4, prep:40, cook:12, diff:3, tags:['pork','spicy','fast'],
  art:{v:'plate',bg:'#33291f',plate:'#f0e4c8',style:'other',food:['#8f4a3a','#c9302a','#f2dfa8','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Porc parfumé au poisson',en:'Fish-fragrant pork slivers'},
  p:{fr:'Sichuan, Chine',en:'Sichuan, China'},
  d:{fr:"Des lanières de porc sautées dans une sauce aigre-douce et pimentée, sans aucun poisson. Le nom vient de l'assaisonnement traditionnellement employé pour le poisson au Sichuan ; il n'y en a jamais eu dans le plat, et c'est une source d'incompréhension permanente hors de Chine.",
     en:"Slivers of pork stir-fried in a sweet, sour and spicy sauce, with no fish at all. The name comes from the seasoning traditionally used for fish in Sichuan; there has never been any in the dish, a permanent source of confusion outside China."},
  i:[['pork_loin',400,'g'],['wood_ear_mushrooms',30,'g'],['bamboo_shoots',150,'g'],['pickled_chili',60,'g'],['garlic',8,'clove'],['ginger',40,'g'],['scallion',1,'bunch'],['black_vinegar',40,'ml'],['sugar',30,'g'],['soy_sauce',30,'ml'],['cornstarch',25,'g'],['shaoxing_wine',30,'ml'],['peanut_oil',60,'ml']],
  s:{fr:["Coupez le porc en lanières fines dans le sens de la fibre et veloutez-le à la fécule et au vin.","Employez du piment mariné, le paojiao, et non de la doubanjiang : c'est son acidité qui définit le goût yuxiang.","Préparez la sauce à l'avance en équilibrant sucre et vinaigre à parts presque égales, et goûtez-la crue.","L'équilibre aigre-doux est tout le plat : trop de sucre l'affadit, trop de vinaigre le rend agressif.","Sautez à feu maximal, quatre-vingt-dix secondes en tout, et versez la sauce en dernier, en une seule fois."],
     en:["Cut the pork into fine slivers with the grain and velvet it with cornflour and wine.","Use pickled chilli, paojiao, not doubanjiang: its sourness defines the yuxiang flavour.","Make the sauce ahead, balancing sugar and vinegar in almost equal parts, and taste it raw.","The sweet-sour balance is the whole dish: too much sugar dulls it, too much vinegar makes it aggressive.","Stir-fry over maximum heat, ninety seconds in all, and add the sauce last, all at once."]} },

{ id:'zhong-shui-jiao', c:'as', lat:30.665, lon:104.070, base:6, prep:120, cook:20, diff:3, tags:['pork','street','comfort'],
  art:{v:'bowl',bg:'#33291f',plate:'#f0e4c8',style:'other',food:['#c9302a','#f4f0e6','#e8c46a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Raviolis Zhong',en:'Zhong dumplings'},
  p:{fr:'Chengdu, Sichuan, Chine',en:'Chengdu, Sichuan, China'},
  d:{fr:"Des raviolis de porc pochés, servis dans une huile pimentée sucrée à l'ail. Ils portent le nom de Zhong Xiesen, qui ouvrit son échoppe en 1893 ; la sauce sucrée à l'ail est sa signature, et elle distingue ces raviolis de tous les autres de Chine.",
     en:"Poached pork dumplings served in a sweetened garlic chilli oil. They carry the name of Zhong Xiesen, who opened his stall in 1893; the sweet garlic sauce is his signature, and it sets these dumplings apart from every other in China."},
  i:[['flour',400,'g'],['ground_pork',400,'g'],['ginger',40,'g'],['scallion',1,'bunch'],['soy_sauce',40,'ml'],['sesame_oil',20,'ml'],['chili_oil',100,'ml'],['garlic',10,'clove'],['sweet_soy_sauce',60,'ml'],['sichuan_peppercorns',8,'g'],['sesame_seeds',20,'g'],['water',180,'ml']],
  s:{fr:["Travaillez le porc haché en une seule direction avec l'eau de gingembre, dix minutes, jusqu'à ce qu'il devienne collant.","Ajoutez l'eau par petites quantités pendant le brassage : la farce doit absorber son poids en liquide pour rester juteuse.","Abaissez des disques plus épais au centre qu'au bord et pincez sans plisser, en simple demi-lune.","Pochez à l'eau frémissante en ajoutant un verre d'eau froide dès que ça bout, trois fois de suite.","Ce choc thermique répété cuit la farce sans faire éclater la pâte. Nappez d'huile pimentée et de soja sucré à l'ail."],
     en:["Work the minced pork in one direction with ginger water for ten minutes, until it turns tacky.","Add the water in small additions while mixing: the filling must absorb its own weight in liquid to stay juicy.","Roll discs thicker at the centre than the edge and pinch shut without pleating, in a simple half-moon.","Poach in trembling water, adding a glass of cold water each time it boils, three times over.","That repeated thermal shock cooks the filling without bursting the wrapper. Coat with chilli oil and sweet garlic soy."]} },

{ id:'mayi-shangshu', c:'as', lat:30.550, lon:104.100, base:4, prep:30, cook:15, diff:2, tags:['noodles','pork','spicy'],
  art:{v:'plate',bg:'#33291f',plate:'#f0e4c8',style:'noodle',food:['#f0e8d0','#8f4a3a','#c9302a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Fourmis grimpant à l\'arbre',en:'Ants climbing a tree'},
  p:{fr:'Sichuan rural, Chine',en:'Rural Sichuan, China'},
  d:{fr:"Des vermicelles de patate douce sautés avec du porc haché émietté. Le nom décrit l'aspect : les grains de viande accrochés aux vermicelles translucides évoquent des fourmis grimpant le long de branches, et l'image remonte au moins au XIIIe siècle.",
     en:"Sweet potato noodles stir-fried with crumbled minced pork. The name describes the look: grains of meat clinging to translucent noodles suggest ants climbing branches, an image at least as old as the thirteenth century."},
  i:[['sweet_potato_noodles',200,'g'],['ground_pork',250,'g'],['doubanjiang',40,'g'],['garlic',6,'clove'],['ginger',30,'g'],['scallion',1,'bunch'],['soy_sauce',30,'ml'],['chicken_broth',300,'ml'],['shaoxing_wine',30,'ml'],['peanut_oil',50,'ml'],['sichuan_peppercorns',6,'g']],
  s:{fr:["Faites tremper les vermicelles vingt minutes à l'eau tiède, pas chaude : à l'eau bouillante ils deviennent gluants et collent en bloc.","Égouttez-les et coupez-les aux ciseaux en longueurs de vingt centimètres, sans quoi ils sont impossibles à manger.","Faites revenir le porc jusqu'à ce qu'il croustille, puis ajoutez la doubanjiang et laissez rougir l'huile.","Mouillez au bouillon et jetez les vermicelles dedans : ils doivent absorber tout le liquide, c'est ainsi qu'ils prennent le goût.","Remuez à la baguette plutôt qu'à la spatule, en soulevant : ils se cassent au moindre excès de force."],
     en:["Soak the noodles twenty minutes in warm, not hot, water: in boiling water they go gluey and clump into a block.","Drain them and cut them with scissors into twenty-centimetre lengths, or they are impossible to eat.","Fry the pork until crisp, then add the doubanjiang and let the oil redden.","Moisten with broth and drop in the noodles: they must absorb all the liquid, which is how they take the flavour.","Toss with chopsticks rather than a spatula, lifting: they break at the least excess force."]} },

{ id:'bangbang-ji', c:'as', lat:29.552, lon:103.766, base:4, prep:60, cook:30, diff:2, tags:['poultry','spicy','fresh'],
  art:{v:'plate',bg:'#33291f',plate:'#f0e4c8',style:'salad',food:['#f4f0e6','#c9302a','#f2dfa8','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Poulet bang bang',en:'Bang bang chicken'},
  p:{fr:'Leshan, Sichuan, Chine',en:'Leshan, Sichuan, China'},
  d:{fr:"Du poulet poché effiloché au bâton, servi froid sous une sauce au sésame et au piment. Bang veut dire bâton : la chair était frappée au maillet de bois pour se détacher en fibres régulières, et le bruit rythmé des vendeurs annonçait leur passage dans la rue.",
     en:"Poached chicken shredded with a stick, served cold under a sesame and chilli sauce. Bang means stick: the flesh was beaten with a wooden mallet to separate into even fibres, and the vendors' rhythmic knocking announced them in the street."},
  i:[['chicken_breast',600,'g'],['sesame_paste',60,'g'],['chili_oil',80,'ml'],['sichuan_peppercorns',10,'g'],['soy_sauce',50,'ml'],['black_vinegar',30,'ml'],['sugar',20,'g'],['garlic',6,'clove'],['cucumber',2,'pc'],['scallion',1,'bunch'],['sesame_seeds',20,'g'],['ginger',30,'g']],
  s:{fr:["Pochez le poulet vingt minutes à frémissement avec gingembre et cives, puis coupez le feu et laissez-le refroidir dans l'eau.","Ce refroidissement dans le bouillon garde la chair juteuse ; sortie chaude, elle sèche en dix minutes.","Frappez le blanc refroidi au rouleau à pâtisserie, sans l'écraser, jusqu'à ce que les fibres se séparent.","Effilochez-les à la main dans le sens de la fibre : un couteau donne des morceaux qui n'accrochent pas la sauce.","Détendez la pâte de sésame avec le bouillon froid avant d'ajouter les autres éléments — versée directement dans l'huile, elle se fige."],
     en:["Poach the chicken twenty minutes at a tremble with ginger and spring onion, then cut the heat and let it cool in the water.","Cooling in the broth keeps the flesh juicy; taken out hot, it dries within ten minutes.","Beat the cooled breast with a rolling pin, without crushing it, until the fibres separate.","Shred them by hand along the grain: a knife gives pieces the sauce will not cling to.","Loosen the sesame paste with cold broth before adding anything else — poured straight into oil, it seizes."]} },

{ id:'mao-xuewang', c:'as', lat:29.570, lon:106.560, base:6, prep:60, cook:30, diff:3, tags:['spicy','soup','pork'],
  art:{v:'bowl',bg:'#33291f',plate:'#f0e4c8',style:'stew',food:['#c9302a','#8f2a2a','#f2dfa8','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Mao xuewang',en:'Mao xuewang'},
  p:{fr:'Chongqing, Chine',en:'Chongqing, China'},
  d:{fr:"Un ragoût brûlant de sang de canard caillé, d'abats et de légumes dans un bouillon pimenté. Il est né sur les quais du Yangtsé, où les bateliers rachetaient à bas prix les abats dont les bouchers ne voulaient pas ; mao signifie « brut, grossier », et le nom l'assume.",
     en:"A scalding stew of congealed duck blood, offal and vegetables in a chilli broth. It was born on the Yangtze wharves, where boatmen bought cheap the offal butchers did not want; mao means rough or coarse, and the name owns it."},
  i:[['duck_blood_curd',400,'g'],['pork_tripe',300,'g'],['luncheon_meat',200,'g'],['bean_sprouts',200,'g'],['wood_ear_mushrooms',30,'g'],['doubanjiang',80,'g'],['dried_chili',20,'pc'],['sichuan_peppercorns',20,'g'],['beef_stock',1,'l'],['garlic',10,'clove'],['ginger',40,'g'],['peanut_oil',200,'ml'],['scallion',1,'bunch']],
  s:{fr:["Coupez le sang caillé en gros dés et pochez-les à l'eau frémissante salée cinq minutes avant tout le reste.","Ce pochage préalable raffermit le sang : jeté cru dans le bouillon, il se désagrège en poudre.","Faites griller la doubanjiang dans l'huile jusqu'à ce qu'elle rougisse, puis mouillez au bouillon et laissez infuser dix minutes.","Ajoutez les ingrédients par ordre de fermeté, en terminant par le sang et les pousses de soja.","Versez une louche d'huile brûlante aux piments sur le tout au moment de servir, comme pour le shui zhu yu."],
     en:["Cut the blood curd into large dice and poach them in salted trembling water for five minutes before anything else.","That prior poaching firms the blood: dropped raw into the broth, it disintegrates into powder.","Toast the doubanjiang in oil until it reddens, then moisten with stock and infuse ten minutes.","Add the ingredients in order of firmness, finishing with the blood and bean sprouts.","Pour a ladle of scalding chilli oil over the lot as you serve, as for shui zhu yu."]} },

{ id:'liangfen', c:'as', lat:30.837, lon:106.110, base:4, prep:180, cook:20, diff:2, tags:['street','spicy','fresh'],
  art:{v:'bowl',bg:'#33291f',plate:'#f4ead4',style:'noodle',food:['#f0e8d0','#c9302a','#7fae5a','#e8c46a'],garnish:'#7fae6a'},
  n:{fr:'Gelée de haricot froide',en:'Cold mung bean jelly'},
  p:{fr:'Nanchong, Sichuan, Chine',en:'Nanchong, Sichuan, China'},
  d:{fr:"Une gelée d'amidon de haricot mungo découpée en lanières, servie froide et très pimentée. C'est le plat d'été des rues du Sichuan : la gelée est neutre et froide, l'assaisonnement brûlant, et le contraste des deux est tout le principe.",
     en:"A jelly of mung bean starch cut into strips, served cold and heavily spiced. It is the summer street food of Sichuan: the jelly neutral and cold, the dressing burning, and the contrast between them is the whole point."},
  i:[['mung_bean_flour',150,'g'],['water',900,'ml'],['chili_oil',80,'ml'],['soy_sauce',50,'ml'],['black_vinegar',40,'ml'],['garlic',8,'clove'],['sichuan_peppercorns',10,'g'],['sugar',15,'g'],['scallion',1,'bunch'],['cilantro',1,'bunch'],['peanuts',60,'g'],['sesame_oil',15,'ml']],
  s:{fr:["Délayez l'amidon dans un tiers de l'eau froide, parfaitement, avant de porter le reste à ébullition.","Versez le mélange froid dans l'eau bouillante en fouettant sans arrêt : l'inverse donne des grumeaux irrécupérables.","Faites cuire cinq minutes en remuant, jusqu'à ce que la préparation devienne translucide et très épaisse.","Versez dans un moule huilé et laissez prendre trois heures à température ambiante, jamais au réfrigérateur — le froid la rend cassante.","Découpez en lanières épaisses au couteau mouillé et nappez de l'assaisonnement au moment de servir."],
     en:["Slake the starch in a third of the cold water, perfectly, before bringing the rest to the boil.","Pour the cold mixture into the boiling water, whisking without pause: the reverse gives irrecoverable lumps.","Cook five minutes, stirring, until the mixture turns translucent and very thick.","Pour into an oiled mould and set three hours at room temperature, never in the refrigerator — cold makes it brittle.","Cut into thick strips with a wetted knife and dress as you serve."]} },

{ id:'zhangcha-ya', c:'as', lat:30.600, lon:104.050, base:6, prep:1440, cook:120, diff:3, tags:['poultry','slow','festive'],
  art:{v:'plate',bg:'#33291f',plate:'#f0e4c8',style:'other',food:['#8f5a3a','#5a3020','#e8c46a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Canard fumé au thé',en:'Tea-smoked duck'},
  p:{fr:'Chengdu, Sichuan, Chine',en:'Chengdu, Sichuan, China'},
  d:{fr:"Un canard mariné, fumé aux feuilles de thé et au camphre, puis cuit à la vapeur et frit. Les quatre étapes successives — saumure, fumage, vapeur, friture — prennent deux jours, et chacune fait une chose que les autres ne peuvent pas faire.",
     en:"A duck cured, smoked over tea leaves and camphor, then steamed and fried. The four successive stages — cure, smoke, steam, fry — take two days, and each does something the others cannot."},
  i:[['duck',2,'kg'],['sichuan_peppercorns',30,'g'],['coarse_salt',80,'g'],['green_tea',60,'g'],['rice',100,'g'],['brown_sugar',80,'g'],['camphor_leaves',30,'g'],['ginger',50,'g'],['shaoxing_wine',80,'ml'],['star_anise',4,'pc'],['frying_oil',2,'l'],['steamed_buns',12,'pc']],
  s:{fr:["Grillez le poivre du Sichuan avec le gros sel et frottez-en le canard dedans et dehors, puis laissez-le vingt-quatre heures au frais.","Fumez-le vingt minutes sur un mélange de thé, de riz et de sucre brun chauffé au fond d'un wok couvert.","Le riz et le sucre servent de combustible ; le thé seul brûle trop vite et donne une fumée âcre.","Cuisez ensuite à la vapeur une heure et demie : c'est cette étape qui attendrit la chair et fond la graisse.","Frites enfin le canard entier trois minutes à 190 °C pour croustiller la peau. Servez avec des petits pains vapeur."],
     en:["Toast the Sichuan pepper with the coarse salt and rub the duck inside and out, then cure twenty-four hours in the cold.","Smoke it twenty minutes over a mixture of tea, rice and brown sugar heated in the bottom of a covered wok.","The rice and sugar are the fuel; tea alone burns too fast and gives acrid smoke.","Then steam it an hour and a half: that stage tenderises the flesh and renders the fat.","Finally deep-fry the whole duck three minutes at 190°C to crisp the skin. Serve with steamed buns."]} },

{ id:'lazi-ji', c:'as', lat:29.545, lon:106.540, base:4, prep:60, cook:20, diff:3, tags:['poultry','spicy','fry'],
  art:{v:'plate',bg:'#33291f',plate:'#f0e4c8',style:'other',food:['#c9302a','#8f4a3a','#e8c46a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Poulet aux piments séchés',en:'Chongqing chilli chicken'},
  p:{fr:'Chongqing, Chine',en:'Chongqing, China'},
  d:{fr:"Des dés de poulet frits enfouis sous une montagne de piments séchés. On ne mange pas les piments : ils sont là pour parfumer l'huile et le poulet, et l'on cherche les morceaux de viande dedans à la baguette, ce qui fait partie du plaisir du plat.",
     en:"Fried chicken cubes buried under a mountain of dried chillies. The chillies are not eaten: they are there to scent the oil and the chicken, and the meat is hunted out among them with chopsticks, which is part of the pleasure."},
  i:[['chicken_thighs',600,'g'],['dried_chili',150,'g'],['sichuan_peppercorns',30,'g'],['garlic',10,'clove'],['ginger',40,'g'],['shaoxing_wine',40,'ml'],['soy_sauce',30,'ml'],['cornstarch',40,'g'],['peanut_oil',1,'l'],['sesame_seeds',20,'g'],['scallion',1,'bunch'],['sugar',10,'g']],
  s:{fr:["Coupez le poulet en petits dés avec l'os, à la feuille : c'est l'os qui garde la chair juteuse à la double friture.","Faites mariner trente minutes au vin, au soja et au gingembre, puis enrobez de fécule.","Frites une première fois à 160 °C, quatre minutes, puis une seconde à 190 °C, une minute, pour durcir la croûte.","Coupez les piments en tronçons et retirez-en les graines, sinon le plat devient réellement immangeable.","Faites-les griller trente secondes dans un peu d'huile avec le poivre, ajoutez le poulet et sautez à sec."],
     en:["Cut the chicken into small cubes on the bone, with a cleaver: the bone keeps the flesh juicy through the double fry.","Marinate thirty minutes in wine, soy and ginger, then coat in cornflour.","Fry once at 160°C for four minutes, then again at 190°C for one minute, to harden the crust.","Cut the chillies into lengths and shake out the seeds, or the dish becomes genuinely inedible.","Toast them thirty seconds in a little oil with the pepper, add the chicken and toss dry."]} }
,

{ id:'char-siu-bao', c:'as', lat:23.129, lon:113.264, base:8, prep:180, cook:20, diff:3, tags:['pork','street','comfort'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'other',food:['#f4f0e6','#8f4a3a','#f0e8d0','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Brioches au porc laqué',en:'Char siu bao'},
  p:{fr:'Guangzhou, Guangdong, Chine',en:'Guangzhou, Guangdong, China'},
  d:{fr:"Des brioches vapeur fendues en trois, garnies de porc laqué en sauce. La fente en étoile au sommet n'est pas décorative : elle prouve que la pâte a bien levé, et une brioche qui reste fermée est jugée ratée dans les maisons de dim sum.",
     en:"Steamed buns split into three, filled with sauced barbecued pork. The star split at the top is not decorative: it proves the dough has risen properly, and a bun that stays closed is judged a failure in dim sum houses."},
  i:[['flour',500,'g'],['fresh_yeast',10,'g'],['sugar',80,'g'],['baking_powder',8,'g'],['lard',50,'g'],['whole_milk',220,'ml'],['char_siu',400,'g'],['oyster_sauce',40,'ml'],['hoisin_sauce',40,'ml'],['shallot',3,'pc'],['cornstarch',25,'g'],['sesame_oil',15,'ml']],
  s:{fr:["Employez une farine à faible teneur en protéines, ou coupez-la de fécule : c'est la blancheur et la finesse qui font le bao cantonais.","Ajoutez la levure chimique en plus de la levure de boulanger, au dernier pétrissage seulement.","C'est elle qui provoque la poussée brutale à la vapeur et fait éclater le sommet en trois pointes.","Faites refroidir complètement la garniture liée à la fécule : tiède, elle traverse la pâte pendant la seconde pousse.","Cuisez douze minutes à la vapeur vive et n'ouvrez pas le panier avant deux minutes — le choc d'air froid les fait retomber."],
     en:["Use a low-protein flour, or cut it with cornflour: whiteness and fineness make the Cantonese bao.","Add baking powder as well as yeast, at the final kneading only.","It causes the violent lift in the steamer and bursts the top into three points.","Cool the cornflour-thickened filling completely: warm, it soaks through the dough during the second prove.","Steam twelve minutes over a fierce boil and do not open the basket for two minutes — the cold air makes them collapse."]} },

{ id:'oie-rotie-cantonaise', c:'as', lat:23.022, lon:113.121, base:6, prep:1440, cook:90, diff:3, tags:['poultry','slow','festive'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'other',food:['#8f4a3a','#5a3020','#e8c46a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Oie rôtie cantonaise',en:'Cantonese roast goose'},
  p:{fr:'Foshan, Guangdong, Chine',en:'Foshan, Guangdong, China'},
  d:{fr:"Une oie laquée rôtie à la broche, à la peau vernie et croustillante. La peau est séparée de la chair en soufflant de l'air entre les deux : c'est ce décollement qui permet à la graisse de fondre et à la peau de croustiller sans que la chair sèche.",
     en:"A lacquered goose roasted on a spit, with a glassy crisp skin. The skin is separated from the flesh by blowing air between them: that separation lets the fat render and the skin crisp without the meat drying."},
  i:[['duck',4,'kg'],['maltose',80,'g'],['rice_vinegar',150,'ml'],['shaoxing_wine',80,'ml'],['five_spice',20,'g'],['star_anise',6,'pc'],['ginger',60,'g'],['scallion',2,'bunch'],['sugar',40,'g'],['soy_sauce',80,'ml'],['plum_sauce',150,'g'],['coarse_salt',40,'g']],
  s:{fr:["Décollez la peau de la chair en insufflant de l'air par le cou, sans la percer : c'est le geste décisif de la recette.","Ébouillantez ensuite l'oie entière trente secondes, ce qui contracte la peau et referme les pores.","Badigeonnez d'un mélange de maltose et de vinaigre, puis laissez sécher douze heures suspendue devant un ventilateur.","Ce séchage est ce qui donne le vernis : une peau humide ne laque jamais, elle boursoufle et grise.","Rôtissez une heure et demie à 200 °C, en commençant dos vers le haut. Servez avec de la sauce aux prunes."],
     en:["Separate the skin from the flesh by blowing air in at the neck, without piercing it: the decisive gesture of the recipe.","Then scald the whole goose thirty seconds, which contracts the skin and closes the pores.","Brush with a mixture of maltose and vinegar, then dry twelve hours hung in front of a fan.","That drying is what gives the glaze: damp skin never lacquers, it blisters and greys.","Roast an hour and a half at 200°C, starting back upwards. Serve with plum sauce."]} },

{ id:'wonton-crevettes', c:'as', lat:23.135, lon:113.270, base:4, prep:90, cook:15, diff:3, tags:['sea','soup','comfort'],
  art:{v:'bowl',bg:'#33291f',plate:'#f0e4c8',style:'soup',food:['#e07a6a','#f4f0e6','#f2dfa8','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Wonton aux crevettes',en:'Shrimp wonton'},
  p:{fr:'Guangzhou, Guangdong, Chine',en:'Guangzhou, Guangdong, China'},
  d:{fr:"Des raviolis à la crevette entière dans un bouillon de poisson séché. La crevette doit craquer sous la dent : on la traite au sel et au bicarbonate puis on la rince, ce qui modifie sa texture et lui donne le croquant que les Cantonais appellent shuang.",
     en:"Dumplings with a whole prawn in a dried fish broth. The prawn must snap under the tooth: it is treated with salt and bicarbonate then rinsed, which alters its texture and gives the crunch Cantonese call shuang."},
  i:[['shrimp',400,'g'],['ground_pork',200,'g'],['wonton_wrapper',40,'pc'],['dried_flounder',20,'g'],['pork_bones',800,'g'],['baking_soda',5,'g'],['egg_white',1,'pc'],['sesame_oil',15,'ml'],['white_pepper',5,'g'],['scallion',1,'bunch'],['garlic_chives',100,'g'],['shaoxing_wine',20,'ml'],['salt',null,'']],
  s:{fr:["Frottez les crevettes décortiquées au sel et au bicarbonate, laissez-les vingt minutes, puis rincez-les longuement à l'eau glacée.","Séchez-les à fond entre deux linges : c'est ce traitement qui donne le craquant, et il ne se remplace pas.","Faites griller la plie séchée au four avant de la mettre dans le bouillon — c'est la signature du bouillon de wonton cantonais.","Pliez les wontons en gardant beaucoup de pâte libre : la queue flottante est voulue, elle donne la texture soyeuse.","Pochez-les à part dans une eau claire, jamais dans le bouillon : ils le troubleraient d'amidon."],
     en:["Rub the shelled prawns with salt and bicarbonate, leave twenty minutes, then rinse at length in iced water.","Dry them thoroughly between two cloths: that treatment gives the snap, and nothing replaces it.","Toast the dried flounder in the oven before adding it to the broth — it is the signature of Cantonese wonton soup.","Fold the wontons keeping plenty of loose wrapper: the floating tail is intended, it gives the silky texture.","Poach them separately in clear water, never in the broth: they would cloud it with starch."]} },

{ id:'poisson-vapeur-cantonais', c:'as', lat:22.805, lon:113.293, base:4, prep:30, cook:15, diff:2, tags:['sea','fresh','fast'],
  art:{v:'plate',bg:'#33291f',plate:'#f0e4c8',style:'fish',food:['#f4f0e6','#7fae5a','#f0e8d0','#e8c46a'],garnish:'#7fae6a'},
  n:{fr:'Poisson à la vapeur cantonais',en:'Cantonese steamed fish'},
  p:{fr:'Shunde, Guangdong, Chine',en:'Shunde, Guangdong, China'},
  d:{fr:"Un poisson entier cuit à la vapeur, arrosé de soja et d'huile brûlante. C'est le plat qui mesure la fraîcheur du poisson comme aucun autre : sans épices ni sauce pour masquer, la moindre approximation de fraîcheur se voit immédiatement.",
     en:"A whole fish steamed and doused with soy and scalding oil. It is the dish that measures a fish's freshness as no other does: with no spices or sauce to mask, the least approximation of freshness shows at once."},
  i:[['sea_bass',800,'g'],['ginger',60,'g'],['scallion',2,'bunch'],['soy_sauce',60,'ml'],['peanut_oil',60,'ml'],['cilantro',1,'bunch'],['sugar',10,'g'],['shaoxing_wine',20,'ml'],['white_pepper',3,'g']],
  s:{fr:["Posez le poisson sur deux baguettes croisées dans le plat, pour que la vapeur circule dessous.","Sans cela, le dessous baigne dans son jus et cuit deux fois plus vite que le dessus.","Comptez huit minutes pour huit cents grammes, à la vapeur la plus vive possible, et pas une seconde de plus.","Jetez impérativement le liquide rendu au fond du plat : il est amer et gâcherait toute la sauce.","Versez le soja tiède, puis l'huile fumante sur le gingembre et les cives crues posés en surface."],
     en:["Set the fish on two crossed chopsticks in the dish, so steam circulates underneath.","Without that, the underside sits in its own juices and cooks twice as fast as the top.","Allow eight minutes for eight hundred grams, over the fiercest steam possible, and not a second more.","Throw away the liquid in the bottom of the dish without fail: it is bitter and would spoil the whole sauce.","Pour over warm soy, then smoking oil onto the raw ginger and spring onion laid on top."]} },

{ id:'cheung-fun', c:'as', lat:23.120, lon:113.255, base:4, prep:60, cook:30, diff:3, tags:['sea','street','breakfast'],
  art:{v:'plate',bg:'#33291f',plate:'#f0e4c8',style:'roll',food:['#f4f0e6','#f0e8d0','#e07a6a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Rouleaux de riz à la vapeur',en:'Steamed rice rolls'},
  p:{fr:'Guangzhou, Guangdong, Chine',en:'Guangzhou, Guangdong, China'},
  d:{fr:"De larges feuilles de riz cuites à la vapeur et roulées autour d'une garniture. La pâte doit être remuée juste avant chaque louche : l'amidon de riz se dépose au fond en moins d'une minute, et une pâte non remuée donne une feuille inégale et cassante.",
     en:"Wide sheets of rice steamed and rolled around a filling. The batter must be stirred just before each ladleful: rice starch settles within a minute, and unstirred batter gives an uneven, brittle sheet."},
  i:[['rice_flour',200,'g'],['tapioca_starch',40,'g'],['cornstarch',20,'g'],['water',700,'ml'],['shrimp',300,'g'],['scallion',1,'bunch'],['soy_sauce',80,'ml'],['sugar',30,'g'],['sesame_oil',20,'ml'],['peanut_oil',40,'ml'],['cilantro',1,'bunch']],
  s:{fr:["Mêlez les trois amidons à l'eau froide et laissez reposer une heure : la farine de riz seule donne une feuille qui casse.","Huilez très légèrement le plateau, puis versez une louche fine en inclinant pour l'étaler d'un seul mouvement.","Remuez la pâte à chaque louche, sans exception : c'est là que se joue la régularité de la feuille.","Cuisez trois minutes à la vapeur maximale, à couvert. La feuille est prête quand elle boursoufle et devient translucide.","Décollez à la corne huilée en partant d'un coin, garnissez et roulez pendant que la feuille est brûlante et souple."],
     en:["Mix the three starches with cold water and rest an hour: rice flour alone gives a sheet that cracks.","Oil the tray very lightly, then pour a thin ladleful, tilting to spread it in one movement.","Stir the batter for every ladleful, without exception: that is where the sheet's evenness is decided.","Steam three minutes at maximum, covered. The sheet is ready when it blisters and turns translucent.","Lift it with an oiled scraper starting at one corner, fill and roll while the sheet is scalding and supple."]} },

{ id:'poulet-blanc-coupe', c:'as', lat:23.140, lon:113.250, base:6, prep:60, cook:40, diff:3, tags:['poultry','fresh','festive'],
  art:{v:'plate',bg:'#33291f',plate:'#f0e4c8',style:'other',food:['#f4f0e6','#f2dfa8','#7fae5a','#e8c46a'],garnish:'#7fae6a'},
  n:{fr:'Poulet blanc coupé',en:'White cut chicken'},
  p:{fr:'Guangzhou, Guangdong, Chine',en:'Guangzhou, Guangdong, China'},
  d:{fr:"Un poulet poché à cœur tout juste pris, servi froid avec une sauce au gingembre. La chair doit rester rosée près de l'os : les Cantonais considèrent qu'un poulet cuit à blanc jusqu'à l'os est un poulet gâché, et le jus qui perle doit encore être légèrement rouge.",
     en:"A chicken poached until barely set, served cold with a ginger sauce. The flesh must stay pink near the bone: Cantonese hold that a chicken cooked white through to the bone is a chicken ruined, and the juices should still run faintly red."},
  i:[['chicken',1.6,'kg'],['ginger',100,'g'],['scallion',3,'bunch'],['peanut_oil',100,'ml'],['coarse_salt',30,'g'],['shaoxing_wine',60,'ml'],['star_anise',3,'pc'],['sesame_oil',20,'ml'],['ice',2,'kg'],['sugar',10,'g']],
  s:{fr:["Plongez le poulet entier dans une grande eau frémissante, retirez-le après trente secondes, et répétez trois fois.","Ce va-et-vient égalise la température entre la peau et le cœur, et empêche la peau d'éclater.","Laissez-le ensuite pocher vingt-cinq minutes à 85 °C, sans jamais laisser bouillir.","Plongez-le aussitôt dans un bain d'eau glacée : le choc contracte la peau et la sépare de la chair en une pellicule gélatineuse.","Cette gelée sous la peau est la marque d'un poulet réussi. Servez froid, découpé à la feuille, avec une pâte de gingembre et de cives à l'huile brûlante."],
     en:["Plunge the whole chicken into a large pan of trembling water, lift it out after thirty seconds, and repeat three times.","That in-and-out evens the temperature between skin and centre, and stops the skin splitting.","Then poach it twenty-five minutes at 85°C, never letting it boil.","Plunge it straight into iced water: the shock contracts the skin and separates it from the flesh in a gelatinous film.","That jelly under the skin is the mark of a good chicken. Serve cold, chopped with a cleaver, with a ginger and spring onion paste in scalding oil."]} },

{ id:'crevettes-sel-poivre', c:'as', lat:22.319, lon:114.169, base:4, prep:30, cook:15, diff:2, tags:['sea','fry','fast'],
  art:{v:'plate',bg:'#33291f',plate:'#f4ead4',style:'other',food:['#e07a6a','#e8c46a','#f2dfa8','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Crevettes au sel et poivre',en:'Salt and pepper prawns'},
  p:{fr:'Hong Kong, Chine',en:'Hong Kong, China'},
  d:{fr:"Des crevettes entières frites dans leur carapace, sautées au sel, au poivre et à l'ail. La carapace se mange : frite à haute température elle devient friable et concentre l'essentiel du goût, et la décortiquer revient à jeter la moitié du plat.",
     en:"Whole prawns fried in their shells and tossed with salt, pepper and garlic. The shell is eaten: fried at high temperature it turns brittle and concentrates most of the flavour, and peeling them means throwing half the dish away."},
  i:[['shrimp',800,'g'],['cornstarch',80,'g'],['garlic',12,'clove'],['green_chili',4,'pc'],['scallion',1,'bunch'],['white_pepper',10,'g'],['sichuan_peppercorns',8,'g'],['coarse_salt',15,'g'],['peanut_oil',1,'l'],['shaoxing_wine',30,'ml']],
  s:{fr:["Coupez les antennes et les pattes aux ciseaux mais gardez la carapace et la tête, et fendez le dos pour retirer le boyau.","Séchez-les à fond : une crevette humide fait exploser l'huile et sa carapace ne devient jamais friable.","Enrobez de fécule seule et frites à 190 °C, quatre-vingt-dix secondes, jusqu'à ce que la carapace craque sous la pince.","Faites griller le sel et les poivres à sec au préalable, puis moulez-les grossièrement.","Videz l'huile, remettez les crevettes dans le wok brûlant avec l'ail et les épices, et sautez trente secondes à sec."],
     en:["Snip off the antennae and legs but keep the shell and head, and split the back to remove the vein.","Dry them thoroughly: a wet prawn makes the oil erupt and its shell never turns brittle.","Coat in cornflour alone and fry at 190°C for ninety seconds, until the shell cracks under tongs.","Dry-toast the salt and peppercorns beforehand, then grind them coarsely.","Pour off the oil, return the prawns to the scalding wok with the garlic and spices, and toss dry for thirty seconds."]} },

{ id:'dun-tang', c:'as', lat:23.132, lon:113.260, base:4, prep:30, cook:240, diff:2, tags:['soup','slow','poultry'],
  art:{v:'bowl',bg:'#33291f',plate:'#f0e4c8',style:'soup',food:['#f0e8d0','#e8dcb8','#8f5a3a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Soupe à double vapeur',en:'Double-steamed soup'},
  p:{fr:'Guangzhou, Guangdong, Chine',en:'Guangzhou, Guangdong, China'},
  d:{fr:"Un bouillon cuit quatre heures dans un pot scellé lui-même placé dans un cuiseur vapeur. Le liquide ne bout jamais et reste parfaitement limpide ; c'est une cuisson dite tonique, associée en médecine chinoise à la reconstitution des forces après maladie.",
     en:"A broth cooked four hours in a sealed pot itself set inside a steamer. The liquid never boils and stays perfectly clear; it is a tonic cooking, associated in Chinese medicine with restoring strength after illness."},
  i:[['chicken',800,'g'],['pork_shank',300,'g'],['dried_scallops',20,'g'],['goji_berries',20,'g'],['red_dates',8,'pc'],['ginseng',10,'g'],['ginger',40,'g'],['shiitake_mushrooms',50,'g'],['water',1.2,'l'],['coarse_salt',10,'g']],
  s:{fr:["Blanchissez viandes et os cinq minutes et rincez-les à l'eau froide, jusqu'à ce qu'aucune écume ne reste.","Le double-vapeur ne permet pas d'écumer en cours de cuisson : tout doit être propre au départ.","Disposez tout dans un pot de porcelaine, couvrez d'eau froide et scellez le couvercle avec un papier mouillé ou un film résistant.","Posez le pot dans un cuiseur vapeur, l'eau arrivant à mi-hauteur, et laissez quatre heures à petits bouillons.","Le bouillon obtenu doit être parfaitement translucide. Salez seulement à la fin, dans le bol."],
     en:["Blanch the meats and bones five minutes and rinse them cold, until no scum remains.","Double steaming allows no skimming during cooking: everything must be clean at the start.","Put it all in a porcelain pot, cover with cold water and seal the lid with wet paper or heatproof film.","Set the pot in a steamer with water halfway up, and leave four hours at a gentle boil.","The resulting broth must be perfectly translucent. Salt only at the end, in the bowl."]} },

{ id:'poulet-braise-dezhou', c:'as', lat:37.436, lon:116.359, base:6, prep:120, cook:300, diff:3, tags:['poultry','slow','festive'],
  art:{v:'plate',bg:'#33291f',plate:'#f0e4c8',style:'other',food:['#8f5a3a','#c9924a','#e8c46a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Poulet braisé de Dezhou',en:'Dezhou braised chicken'},
  p:{fr:'Dezhou, Shandong, Chine',en:'Dezhou, Shandong, China'},
  d:{fr:"Un poulet frit puis braisé des heures, si tendre qu'on le désosse d'une secousse. Il se vend depuis 1692 sur le quai de la gare de Dezhou, aux voyageurs du train Pékin-Shanghai ; on l'appelle le poulet dont les os se détachent en secouant.",
     en:"A chicken fried then braised for hours, so tender it bones itself with a shake. It has been sold since 1692 on the platform at Dezhou station to travellers on the Beijing-Shanghai line; it is called the chicken whose bones fall out when shaken."},
  i:[['chicken',1.6,'kg'],['maltose',60,'g'],['star_anise',5,'pc'],['cinnamon_stick',2,'pc'],['sichuan_peppercorns',15,'g'],['clove',8,'pc'],['fennel_seed',10,'g'],['ginger',60,'g'],['soy_sauce',150,'ml'],['rock_sugar',60,'g'],['shaoxing_wine',100,'ml'],['frying_oil',2,'l'],['sand_ginger',10,'g']],
  s:{fr:["Bridez le poulet en repliant les ailes et en glissant les pattes à l'intérieur : il doit rester compact pendant cinq heures de cuisson.","Badigeonnez-le de maltose dilué et laissez-le sécher une heure avant de le frire.","Frites-le entier deux minutes à 200 °C : la peau prend une couleur d'ambre et se raffermit, ce qui l'empêchera d'éclater au braisage.","Braisez ensuite cinq heures à frémissement dans le bouillon d'épices, sans jamais laisser bouillir.","Laissez refroidir dans le bouillon. Le poulet est prêt quand une secousse suffit à séparer la chair des os."],
     en:["Truss the chicken by folding the wings and tucking the legs inside: it must stay compact through five hours' cooking.","Brush it with diluted maltose and let it dry an hour before frying.","Deep-fry it whole for two minutes at 200°C: the skin takes an amber colour and firms, which stops it splitting during the braise.","Then braise five hours at a tremble in the spiced broth, never letting it boil.","Cool it in the broth. The chicken is ready when a shake is enough to part the flesh from the bones."]} },

{ id:'tangcu-liyu', c:'as', lat:36.651, lon:117.120, base:4, prep:40, cook:25, diff:3, tags:['sea','fry','festive'],
  art:{v:'plate',bg:'#33291f',plate:'#f0e4c8',style:'fish',food:['#c9302a','#e8a032','#e8c46a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Carpe aigre-douce',en:'Sweet and sour carp'},
  p:{fr:'Jinan, Shandong, Chine',en:'Jinan, Shandong, China'},
  d:{fr:"Une carpe du fleuve Jaune frite entière et nappée d'une sauce aigre-douce brillante. Le poisson est servi cambré, la queue relevée : on le maintient dans cette position pendant la friture, et la posture symbolise la carpe qui remonte les rapides.",
     en:"A Yellow River carp fried whole and coated in a glossy sweet-sour sauce. The fish is served arched with the tail raised: it is held in that position during frying, and the posture stands for the carp leaping the rapids."},
  i:[['carp',1.2,'kg'],['cornstarch',150,'g'],['flour',80,'g'],['rice_vinegar',120,'ml'],['sugar',150,'g'],['tomato_paste',40,'g'],['ginger',40,'g'],['garlic',6,'clove'],['scallion',1,'bunch'],['shaoxing_wine',40,'ml'],['frying_oil',2,'l'],['soy_sauce',30,'ml']],
  s:{fr:["Entaillez la carpe en biais de chaque côté, jusqu'à l'arête, en cinq ou six coups de couteau réguliers.","Ces entailles ouvrent la chair en éventail à la friture et permettent à la sauce de pénétrer.","Enrobez de fécule en écartant les entailles à la main, pour que chacune soit couverte.","Tenez le poisson par la queue et plongez-le en le maintenant cambré trente secondes avant de le lâcher : il gardera cette forme.","Faites la sauce à part et versez-la brûlante sur le poisson à table, pour que le grésillement s'entende."],
     en:["Score the carp diagonally on each side, down to the bone, in five or six even cuts.","Those cuts open the flesh into a fan in the fryer and let the sauce penetrate.","Coat in cornflour, spreading the cuts open by hand so each one is covered.","Hold the fish by the tail and lower it in arched for thirty seconds before letting go: it will keep that shape.","Make the sauce separately and pour it scalding over the fish at the table, so the sizzle is heard."]} },

{ id:'cong-shao-haishen', c:'as', lat:37.464, lon:121.448, base:4, prep:1440, cook:60, diff:3, tags:['sea','slow','festive'],
  art:{v:'plate',bg:'#2b2419',plate:'#f0e4c8',style:'other',food:['#3a2a2a','#5a3020','#7fae5a','#e8c46a'],garnish:'#7fae6a'},
  n:{fr:'Concombre de mer aux oignons',en:'Sea cucumber with scallions'},
  p:{fr:'Yantai, Shandong, Chine',en:'Yantai, Shandong, China'},
  d:{fr:"Du concombre de mer braisé dans une sauce brune aux cives, plat de banquet du Shandong. L'animal séché doit tremper trois à cinq jours en changeant l'eau matin et soir ; il gonfle jusqu'à cinq fois son volume, et un contact avec le gras l'empêche de se réhydrater.",
     en:"Sea cucumber braised in a brown scallion sauce, a Shandong banquet dish. The dried animal must soak three to five days with the water changed morning and evening; it swells to five times its volume, and any contact with fat stops it rehydrating."},
  i:[['dried_sea_cucumber',150,'g'],['scallion',4,'bunch'],['soy_sauce',80,'ml'],['dark_soy_sauce',20,'ml'],['oyster_sauce',40,'ml'],['shaoxing_wine',60,'ml'],['sugar',30,'g'],['chicken_broth',400,'ml'],['peanut_oil',150,'ml'],['cornstarch',20,'g'],['ginger',40,'g'],['lard',40,'g']],
  s:{fr:["Faites tremper les concombres de mer trois jours à l'eau froide, en changeant l'eau deux fois par jour.","N'employez que des récipients parfaitement dégraissés : une trace de gras empêche la réhydratation et le concombre se dissout.","Ouvrez-les, retirez les viscères et les tendons blancs internes, puis pochez-les vingt minutes avant de les rincer.","Faites frire les blancs de cives dans l'huile jusqu'à ce qu'ils brunissent, puis retirez-les et gardez l'huile parfumée.","Braisez les concombres dans cette huile et le bouillon vingt minutes, liez à la fécule et remettez les cives en surface."],
     en:["Soak the sea cucumbers three days in cold water, changing it twice a day.","Use only perfectly degreased vessels: a trace of fat prevents rehydration and the cucumber dissolves.","Open them, remove the innards and the white internal tendons, then poach twenty minutes before rinsing.","Fry the scallion whites in oil until browned, then remove them and keep the scented oil.","Braise the cucumbers in that oil and the stock for twenty minutes, thicken with cornflour and return the scallions on top."]} }
,

{ id:'jiuzhuan-dachang', c:'as', lat:36.660, lon:117.130, base:6, prep:180, cook:120, diff:3, tags:['pork','slow','festive'],
  art:{v:'plate',bg:'#33291f',plate:'#f0e4c8',style:'other',food:['#8f4a3a','#5a3020','#e8c46a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Intestins aux neuf tours',en:'Nine-turn large intestine'},
  p:{fr:'Jinan, Shandong, Chine',en:'Jinan, Shandong, China'},
  d:{fr:"Des intestins de porc emboîtés les uns dans les autres, braisés en sauce aigre-douce. Le nom vient d'un client lettré du XIXe siècle qui compara les neuf couches emboîtées aux neuf niveaux du ciel taoïste ; le plat en compte réellement trois superposées.",
     en:"Pork intestines nested inside one another and braised in a sweet-sour sauce. The name comes from a scholarly customer of the nineteenth century who compared the nine nested layers to the nine levels of the Taoist heaven; the dish actually has three."},
  i:[['pork_intestines',1,'kg'],['rice_vinegar',150,'ml'],['sugar',80,'g'],['soy_sauce',80,'ml'],['shaoxing_wine',60,'ml'],['cinnamon_stick',2,'pc'],['sichuan_peppercorns',10,'g'],['coarse_salt',80,'g'],['flour',100,'g'],['cilantro',1,'bunch'],['peanut_oil',150,'ml']],
  s:{fr:["Retournez les intestins et frottez-les au gros sel et à la farine, puis rincez ; répétez quatre fois au moins.","Un nettoyage insuffisant se sent immédiatement et ne se rattrape par aucune sauce : c'est tout l'enjeu du plat.","Emboîtez les segments les uns dans les autres, trois épaisseurs, pour obtenir un boudin épais.","Pochez une heure, puis frites brièvement pour raffermir, avant de braiser une heure en sauce aigre-douce.","Tranchez en rondelles d'un centimètre : les trois couches doivent apparaître nettement en coupe."],
     en:["Turn the intestines inside out and scrub them with coarse salt and flour, then rinse; repeat at least four times.","Inadequate cleaning is noticed at once and no sauce will cover it: that is the whole challenge of the dish.","Nest the segments inside one another, three thicknesses, to make a thick roll.","Poach an hour, then fry briefly to firm them, before braising an hour in the sweet-sour sauce.","Slice into one-centimetre rounds: the three layers should show clearly in cross-section."]} },

{ id:'hongshao-baoyu', c:'as', lat:36.067, lon:120.383, base:4, prep:1440, cook:180, diff:3, tags:['sea','slow','festive'],
  art:{v:'plate',bg:'#33291f',plate:'#f0e4c8',style:'other',food:['#5a3020','#8f5a3a','#e8c46a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Ormeau braisé',en:'Braised abalone'},
  p:{fr:'Qingdao, Shandong, Chine',en:'Qingdao, Shandong, China'},
  d:{fr:"Des ormeaux braisés longuement dans un bouillon brun réduit, servis entiers. L'ormeau séché coûte plus cher que le frais et se réhydrate trois jours ; sa texture après braisage, à la fois ferme et fondante, est jugée impossible à obtenir avec l'animal frais.",
     en:"Abalone long braised in a reduced brown broth and served whole. Dried abalone costs more than fresh and rehydrates over three days; its texture after braising, at once firm and yielding, is held impossible to achieve with the fresh animal."},
  i:[['dried_abalone',6,'pc'],['chicken',600,'g'],['pork_ribs',400,'g'],['jinhua_ham',100,'g'],['oyster_sauce',60,'ml'],['dark_soy_sauce',30,'ml'],['rock_sugar',40,'g'],['shaoxing_wine',80,'ml'],['ginger',60,'g'],['scallion',2,'bunch'],['cornstarch',20,'g'],['bok_choy',300,'g']],
  s:{fr:["Faites tremper les ormeaux séchés trois jours à l'eau froide, en changeant l'eau matin et soir.","Brossez-les ensuite pour ôter le sable des replis, puis pochez-les une heure avant le braisage.","Préparez un bouillon supérieur avec poulet, travers et jambon de Jinhua, mijoté quatre heures et dégraissé.","Braisez les ormeaux dans ce bouillon huit heures à frémissement, ou trois heures en cocotte sous pression.","Réduisez le jus jusqu'à ce qu'il nappe, liez à peine à la fécule et nappez les ormeaux entiers. Ne les tranchez jamais."],
     en:["Soak the dried abalone three days in cold water, changing it morning and evening.","Then brush them to remove sand from the folds, and poach them an hour before braising.","Make a superior stock with chicken, pork ribs and Jinhua ham, simmered four hours and degreased.","Braise the abalone in that stock eight hours at a tremble, or three hours under pressure.","Reduce the liquid until it coats, thicken barely with cornflour and nap the whole abalone. Never slice them."]} },

{ id:'liangban-haizhe', c:'as', lat:36.075, lon:120.390, base:4, prep:120, cook:5, diff:2, tags:['sea','fresh','fast'],
  art:{v:'bowl',bg:'#26485c',plate:'#f4ead4',style:'salad',food:['#f0e8d0','#f4f0e6','#7fae5a','#e8c46a'],garnish:'#6fbf8f'},
  n:{fr:'Méduses marinées',en:'Marinated jellyfish'},
  p:{fr:'Qingdao, Shandong, Chine',en:'Qingdao, Shandong, China'},
  d:{fr:"Des lanières de méduse salée, croquantes et translucides, assaisonnées au vinaigre. La méduse n'a presque aucun goût : tout l'intérêt tient à sa texture, un craquement particulier qui disparaît irrémédiablement si on la chauffe plus de quelques secondes.",
     en:"Strips of salted jellyfish, crunchy and translucent, dressed with vinegar. Jellyfish has almost no flavour: the whole point is its texture, a particular crunch lost irretrievably if heated more than a few seconds."},
  i:[['salted_jellyfish',400,'g'],['cucumber',2,'pc'],['rice_vinegar',60,'ml'],['soy_sauce',40,'ml'],['sesame_oil',30,'ml'],['garlic',6,'clove'],['sugar',15,'g'],['cilantro',1,'bunch'],['chili_oil',20,'ml'],['sesame_seeds',15,'g']],
  s:{fr:["Rincez la méduse salée sous l'eau courante, puis faites-la dessaler deux heures en changeant l'eau trois fois.","Ébouillantez-la cinq secondes exactement, pas davantage : elle se rétracte et devient croquante.","Au-delà de dix secondes, elle fond littéralement et se réduit au quart de son volume, sans retour possible.","Plongez-la aussitôt dans l'eau glacée, ce qui fixe la texture, et laissez-la vingt minutes.","Égouttez à fond, coupez en lanières et assaisonnez juste avant de servir — marinée à l'avance, elle rend son eau."],
     en:["Rinse the salted jellyfish under running water, then desalt it two hours, changing the water three times.","Scald it for exactly five seconds, no longer: it contracts and turns crunchy.","Beyond ten seconds it literally melts and shrinks to a quarter of its volume, with no way back.","Plunge it straight into iced water, which fixes the texture, and leave it twenty minutes.","Drain thoroughly, cut into strips and dress just before serving — dressed ahead, it weeps."]} },

{ id:'songshu-guiyu', c:'as', lat:31.299, lon:120.585, base:4, prep:60, cook:25, diff:3, tags:['sea','fry','festive'],
  art:{v:'plate',bg:'#33291f',plate:'#f0e4c8',style:'fish',food:['#c9302a','#e8a032','#e8c46a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Poisson écureuil',en:'Squirrel fish'},
  p:{fr:'Suzhou, Jiangsu, Chine',en:'Suzhou, Jiangsu, China'},
  d:{fr:"Un poisson désossé, entaillé en losanges et frit jusqu'à se hérisser comme une queue d'écureuil. Les entailles doivent traverser la chair sans couper la peau : c'est la contraction de la peau à la friture qui fait s'écarter les losanges et donne la forme.",
     en:"A boned fish scored in diamonds and fried until it bristles like a squirrel's tail. The cuts must pass through the flesh without cutting the skin: it is the skin contracting in the fryer that spreads the diamonds and makes the shape."},
  i:[['freshwater_fish',1,'kg'],['cornstarch',200,'g'],['egg',1,'pc'],['rice_vinegar',100,'ml'],['sugar',150,'g'],['tomato_paste',60,'g'],['peas',80,'g'],['pine_nuts',40,'g'],['shaoxing_wine',40,'ml'],['ginger',30,'g'],['frying_oil',2,'l'],['salt',null,'']],
  s:{fr:["Levez les deux filets en gardant la peau et la queue attachées à la tête, puis retirez toutes les arêtes.","Entaillez chaque filet en losanges, à un centimètre d'écart, en vous arrêtant juste avant la peau.","C'est le point décisif : une entaille trop profonde coupe la peau et le poisson se défait dans l'huile.","Enrobez chaque losange de fécule en les écartant à la main, puis secouez pour retirer l'excédent.","Tenez le poisson par la queue et plongez-le tête la première à 190 °C, en le maintenant relevé trente secondes."],
     en:["Fillet both sides keeping the skin and the tail attached to the head, then remove every bone.","Score each fillet in diamonds a centimetre apart, stopping just short of the skin.","This is the decisive point: a cut too deep goes through the skin and the fish falls apart in the oil.","Coat each diamond in cornflour, spreading them by hand, then shake off the excess.","Hold the fish by the tail and lower it head first into 190°C oil, holding it raised for thirty seconds."]} },

{ id:'shizi-tou', c:'as', lat:32.394, lon:119.413, base:4, prep:60, cook:120, diff:3, tags:['pork','slow','comfort'],
  art:{v:'bowl',bg:'#33291f',plate:'#f0e4c8',style:'stew',food:['#f2dfa8','#8f5a3a','#7fae5a','#f4f0e6'],garnish:'#7fae6a'},
  n:{fr:'Têtes de lion',en:'Lion\'s head meatballs'},
  p:{fr:'Yangzhou, Jiangsu, Chine',en:'Yangzhou, Jiangsu, China'},
  d:{fr:"D'énormes boulettes de porc mijotées deux heures, si tendres qu'elles se mangent à la cuillère. Le nom vient de leur taille et de la surface irrégulière, comparée à la crinière d'un lion ; la viande est coupée au couteau et jamais hachée à la machine.",
     en:"Enormous pork meatballs simmered two hours, so tender they are eaten with a spoon. The name comes from their size and their rough surface, likened to a lion's mane; the meat is cut by knife and never machine-minced."},
  i:[['pork_belly',700,'g'],['water_chestnuts',100,'g'],['egg',1,'pc'],['ginger',40,'g'],['scallion',1,'bunch'],['shaoxing_wine',40,'ml'],['cornstarch',30,'g'],['napa_cabbage',600,'g'],['chicken_broth',800,'ml'],['soy_sauce',30,'ml'],['white_pepper',5,'g'],['salt',null,'']],
  s:{fr:["Coupez le porc au couteau en dés minuscules, moitié gras moitié maigre : c'est cette proportion qui fait la tendreté.","Un hachoir écrase les fibres et rend la boulette dense ; la coupe au couteau les laisse entières et la boulette reste aérée.","Travaillez la farce en une seule direction avec l'eau de gingembre, puis lancez-la vingt fois contre le bol.","Ce lancer chasse l'air emprisonné et empêche la boulette d'éclater ; sans lui, elle se fend au pochage.","Formez quatre boulettes énormes et pochez-les deux heures à 80 °C dans le bouillon, avec le chou. Jamais d'ébullition."],
     en:["Cut the pork by knife into tiny dice, half fat and half lean: that proportion makes the tenderness.","A mincer crushes the fibres and makes a dense ball; knife cutting leaves them whole and the ball stays open.","Work the mixture in one direction with ginger water, then throw it against the bowl twenty times.","That throwing drives out trapped air and stops the ball bursting; without it, it splits during poaching.","Shape four enormous balls and poach them two hours at 80°C in the broth with the cabbage. Never boiling."]} },

{ id:'yanshui-ya', c:'as', lat:32.060, lon:118.796, base:6, prep:1440, cook:60, diff:3, tags:['poultry','slow','fresh'],
  art:{v:'plate',bg:'#33291f',plate:'#f0e4c8',style:'other',food:['#f4f0e6','#f0e8d0','#e8c46a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Canard salé de Nankin',en:'Nanjing salted duck'},
  p:{fr:'Nanjing, Jiangsu, Chine',en:'Nanjing, Jiangsu, China'},
  d:{fr:"Un canard saumuré puis poché, servi froid, à la chair blanche et ferme. Nankin est surnommée la ville qui mange le canard ; on y en consommerait cent mille par jour, et le canard salé se distingue par une chair pâle et non laquée, à l'opposé du canard laqué de Pékin.",
     en:"A duck brined then poached and served cold, its flesh white and firm. Nanjing is nicknamed the duck-eating city; a hundred thousand a day are said to be eaten there, and salted duck is marked by pale unlacquered flesh, the opposite of Peking duck."},
  i:[['duck',2,'kg'],['coarse_salt',150,'g'],['sichuan_peppercorns',30,'g'],['star_anise',5,'pc'],['ginger',60,'g'],['scallion',2,'bunch'],['shaoxing_wine',80,'ml'],['bay_leaf',3,'pc'],['sand_ginger',10,'g'],['water',3,'l']],
  s:{fr:["Grillez le sel avec le poivre du Sichuan jusqu'à ce qu'il embaume, puis frottez-en le canard dedans et dehors.","Laissez saumurer à sec six heures, puis rincez et faites tremper deux heures à l'eau claire pour dessaler la surface.","Ce dessalage est indispensable : sans lui, la peau est immangeable tandis que le cœur reste fade.","Pochez à 80 °C pendant quarante minutes, en remplissant et vidant la cavité d'eau chaude trois fois pour égaliser la cuisson.","Laissez refroidir dans le bouillon, puis réfrigérez douze heures avant de découper. Se mange froid."],
     en:["Toast the salt with the Sichuan pepper until fragrant, then rub the duck inside and out.","Dry-cure six hours, then rinse and soak two hours in clear water to desalt the surface.","That desalting is essential: without it the skin is inedible while the centre stays bland.","Poach at 80°C for forty minutes, filling and emptying the cavity with hot water three times to even the cooking.","Cool in the broth, then chill twelve hours before carving. Eaten cold."]} },

{ id:'wuxi-paigu', c:'as', lat:31.491, lon:120.312, base:4, prep:60, cook:120, diff:2, tags:['pork','slow','comfort'],
  art:{v:'plate',bg:'#33291f',plate:'#f0e4c8',style:'other',food:['#8f4a3a','#5a3020','#e8c46a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Travers de porc de Wuxi',en:'Wuxi spare ribs'},
  p:{fr:'Wuxi, Jiangsu, Chine',en:'Wuxi, Jiangsu, China'},
  d:{fr:"Des travers braisés dans une sauce rouge très sucrée, luisante et collante. Wuxi est réputée pour la main lourde de ses cuisiniers sur le sucre : la cuisine du Jiangsu est douce en général, mais celle de Wuxi l'est au point de surprendre les Chinois eux-mêmes.",
     en:"Spare ribs braised in a very sweet red sauce, glossy and sticky. Wuxi is known for its cooks' heavy hand with sugar: Jiangsu cooking is sweet in general, but Wuxi's is sweet enough to surprise Chinese diners themselves."},
  i:[['pork_ribs',1.2,'kg'],['rock_sugar',120,'g'],['soy_sauce',100,'ml'],['dark_soy_sauce',30,'ml'],['shaoxing_wine',100,'ml'],['red_yeast_rice',20,'g'],['star_anise',4,'pc'],['cinnamon_stick',2,'pc'],['ginger',50,'g'],['scallion',2,'bunch'],['peanut_oil',60,'ml'],['fennel_seed',8,'g']],
  s:{fr:["Blanchissez les travers dix minutes et rincez-les à l'eau chaude, jamais froide — l'eau froide contracte la viande.","Employez du riz rouge fermenté pour la couleur : c'est un colorant naturel, et la sauce brune n'en donne jamais le rouge vif.","Faites caraméliser le sucre candi dans l'huile avant tout, jusqu'à une couleur ambrée, puis jetez-y les travers.","Braisez une heure et demie à couvert, puis découvrez et laissez réduire vingt minutes en arrosant sans arrêt.","La sauce doit napper les travers d'une pellicule brillante. Trop réduite, elle cristallise et devient amère."],
     en:["Blanch the ribs ten minutes and rinse them in hot water, never cold — cold water contracts the meat.","Use red yeast rice for the colour: it is a natural colouring, and dark soy never gives that bright red.","Caramelise the rock sugar in oil first, to an amber colour, then drop in the ribs.","Braise an hour and a half covered, then uncover and reduce twenty minutes, basting without pause.","The sauce must coat the ribs in a glossy film. Reduced too far, it crystallises and turns bitter."]} },

{ id:'yaxue-fensi-tang', c:'as', lat:32.055, lon:118.790, base:4, prep:40, cook:60, diff:2, tags:['soup','poultry','street'],
  art:{v:'bowl',bg:'#33291f',plate:'#f0e4c8',style:'soup',food:['#f0e8d0','#5a2a2a','#7fae5a','#e8c46a'],garnish:'#7fae6a'},
  n:{fr:'Soupe de vermicelles au sang de canard',en:'Duck blood and vermicelli soup'},
  p:{fr:'Nanjing, Jiangsu, Chine',en:'Nanjing, Jiangsu, China'},
  d:{fr:"Un bouillon clair de canard aux vermicelles, sang caillé et abats. C'est le petit-déjeuner de Nankin : il tire parti de tout ce que le canard salé laisse de côté, et l'on en compte plusieurs milliers d'échoppes dans la seule ville.",
     en:"A clear duck broth with vermicelli, blood curd and offal. It is the Nanjing breakfast: it uses everything salted duck leaves behind, and the city alone counts several thousand stalls."},
  i:[['duck_blood_curd',300,'g'],['duck_gizzards',200,'g'],['duck_liver',150,'g'],['duck_intestines',150,'g'],['sweet_potato_noodles',200,'g'],['duck_bones',1,'kg'],['ginger',40,'g'],['scallion',1,'bunch'],['cilantro',1,'bunch'],['white_pepper',5,'g'],['chili_oil',30,'ml'],['tofu_skin',100,'g'],['salt',null,'']],
  s:{fr:["Faites bouillir la carcasse de canard deux heures avec gingembre et cives, en écumant, jusqu'à obtenir un bouillon clair et léger.","Pochez le sang caillé en dés dans l'eau frémissante salée avant de le mettre dans le bouillon : cru, il se désagrège.","Nettoyez les intestins au sel et à la farine, puis pochez chaque abat séparément selon son temps propre.","Les vermicelles se pochent à part et se rincent : dans le bouillon, leur amidon le troublerait immédiatement.","Assemblez dans le bol au dernier moment et versez le bouillon brûlant. Poivre blanc et huile pimentée à volonté."],
     en:["Boil the duck carcass two hours with ginger and spring onion, skimming, to a clear light broth.","Poach the diced blood curd in salted trembling water before adding it to the broth: raw, it disintegrates.","Clean the intestines with salt and flour, then poach each offal separately according to its own time.","The vermicelli are poached apart and rinsed: in the broth their starch would cloud it at once.","Assemble in the bowl at the last moment and pour over the scalding broth. White pepper and chilli oil to taste."]} },

{ id:'wensi-doufu', c:'as', lat:33.550, lon:119.113, base:4, prep:90, cook:20, diff:3, tags:['soup','veg','festive'],
  art:{v:'bowl',bg:'#33291f',plate:'#f0e4c8',style:'soup',food:['#f4f0e6','#f0e8d0','#7fae5a','#e8c46a'],garnish:'#7fae6a'},
  n:{fr:'Tofu Wensi',en:'Wensi tofu'},
  p:{fr:'Yangzhou, Jiangsu, Chine',en:'Yangzhou, Jiangsu, China'},
  d:{fr:"Un bloc de tofu soyeux taillé en milliers de filaments plus fins qu'un cheveu, servi en soupe. Il porte le nom d'un moine du XVIIIe siècle ; un cuisinier accompli tire d'un seul bloc plus de cinq mille filaments, et le plat sert d'épreuve de couteau dans les écoles chinoises.",
     en:"A block of silken tofu cut into thousands of threads finer than a hair, served in soup. It bears the name of an eighteenth-century monk; an accomplished cook draws more than five thousand threads from a single block, and the dish serves as a knife test in Chinese schools."},
  i:[['silken_tofu',400,'g'],['chicken_broth',800,'ml'],['shiitake_mushrooms',60,'g'],['bamboo_shoots',60,'g'],['jinhua_ham',40,'g'],['bok_choy',100,'g'],['cornstarch',20,'g'],['ginger',20,'g'],['sesame_oil',10,'ml'],['salt',null,'']],
  s:{fr:["Employez un tofu soyeux ferme et laissez-le une heure au réfrigérateur : froid, il se tient mieux sous la lame.","Retirez d'abord la peau extérieure sur les six faces, sans quoi les filaments resteront attachés entre eux.","Tranchez horizontalement en lamelles les plus fines possible, sans écarter le bloc, puis tournez-le d'un quart et recoupez en travers.","Faites glisser le tout dans un bol d'eau froide : les filaments se séparent d'eux-mêmes et flottent.","Versez le bouillon brûlant dessus. Ne remuez jamais à la cuillère : on fait tourner le bol pour mêler."],
     en:["Use a firm silken tofu and chill it an hour: cold, it holds better under the blade.","First remove the outer skin from all six faces, or the threads will stay joined.","Slice horizontally as thinly as possible without spreading the block, then turn it a quarter and cut across.","Slide the whole thing into a bowl of cold water: the threads separate by themselves and float.","Pour the scalding broth over. Never stir with a spoon: the bowl is swirled to mix."]} },

{ id:'xihu-cuyu', c:'as', lat:30.274, lon:120.155, base:4, prep:60, cook:20, diff:3, tags:['sea','fresh','festive'],
  art:{v:'plate',bg:'#33291f',plate:'#f0e4c8',style:'fish',food:['#8f5a3a','#e8c46a','#f4f0e6','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Poisson du lac de l\'Ouest au vinaigre',en:'West Lake vinegar fish'},
  p:{fr:'Hangzhou, Zhejiang, Chine',en:'Hangzhou, Zhejiang, China'},
  d:{fr:"Une carbe herbivore pochée, nappée d'une sauce claire au vinaigre de Zhenjiang. Le poisson doit jeûner deux jours en eau claire avant d'être cuit : cela purge la vase de sa chair, et sans ce jeûne le goût de fond de lac domine tout.",
     en:"A grass carp poached and coated in a clear Zhenjiang vinegar sauce. The fish must fast two days in clean water before cooking: this purges the mud from its flesh, and without it the taste of lake bottom dominates everything."},
  i:[['carp',800,'g'],['black_vinegar',80,'ml'],['sugar',60,'g'],['soy_sauce',40,'ml'],['ginger',50,'g'],['shaoxing_wine',30,'ml'],['cornstarch',20,'g'],['scallion',1,'bunch'],['water',300,'ml']],
  s:{fr:["Fendez le poisson en deux dans la longueur en gardant le dos attaché, pour qu'il cuise à plat et régulièrement.","Pochez-le trois minutes exactement dans l'eau frémissante, jamais bouillante — c'est un poisson à chair très fragile.","Retirez-le dès que l'œil blanchit et que la nageoire dorsale se détache d'une simple traction.","Préparez la sauce dans le liquide de pochage : vinaigre, sucre, gingembre râpé, liés d'un peu de fécule.","La sauce doit rester claire et transparente. Nappez le poisson et servez dans la minute, sinon la chair se défait."],
     en:["Split the fish lengthways keeping the back attached, so it cooks flat and evenly.","Poach it exactly three minutes in trembling, never boiling water — this is a very fragile-fleshed fish.","Take it out as soon as the eye whitens and the dorsal fin pulls away with a light tug.","Make the sauce in the poaching liquid: vinegar, sugar, grated ginger, thickened with a little cornflour.","The sauce must stay clear and transparent. Nap the fish and serve within the minute, or the flesh falls apart."]} }
,

{ id:'longjing-xiaren', c:'as', lat:30.240, lon:120.130, base:4, prep:40, cook:8, diff:3, tags:['sea','fresh','fast'],
  art:{v:'plate',bg:'#28331f',plate:'#f0e4c8',style:'other',food:['#f4f0e6','#e07a6a','#7fae5a','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Crevettes au thé Longjing',en:'Longjing shrimp'},
  p:{fr:'Hangzhou, Zhejiang, Chine',en:'Hangzhou, Zhejiang, China'},
  d:{fr:"De petites crevettes de rivière sautées avec des feuilles de thé vert Longjing. Le plat ne se fait qu'en avril, avec les feuilles de la première cueillette ; on emploie aussi l'eau d'infusion, et les feuilles se mangent avec les crevettes.",
     en:"Small river shrimp stir-fried with Longjing green tea leaves. It is made only in April, with the first flush; the infusion water is used too, and the leaves are eaten with the shrimp."},
  i:[['river_prawns',400,'g'],['longjing_tea',10,'g'],['egg_white',1,'pc'],['cornstarch',20,'g'],['shaoxing_wine',20,'ml'],['peanut_oil',60,'ml'],['scallion',1,'bunch'],['ginger',20,'g'],['water',200,'ml'],['salt',null,'']],
  s:{fr:["Décortiquez les crevettes à la main et veloutez-les au blanc d'œuf, à la fécule et au sel, puis laissez-les une heure au froid.","Infusez le thé à 80 °C pendant trois minutes seulement : plus chaud ou plus long, il devient amer et gâche le plat.","Séparez les feuilles de l'infusion et gardez les deux ; les feuilles s'ajoutent en fin de cuisson, l'eau sert de liquide.","Sautez les crevettes trente secondes à feu vif dans une huile à peine chaude — elles doivent blanchir sans dorer.","Ajoutez les feuilles et deux cuillerées d'infusion, sautez dix secondes de plus et servez. Le plat entier dure une minute."],
     en:["Shell the shrimp by hand and velvet them with egg white, cornflour and salt, then rest them an hour in the cold.","Steep the tea at 80°C for three minutes only: hotter or longer and it turns bitter and spoils the dish.","Separate the leaves from the infusion and keep both; the leaves go in at the end, the water is the liquid.","Stir-fry the shrimp thirty seconds over high heat in barely warm oil — they should whiten without colouring.","Add the leaves and two spoonfuls of infusion, toss ten seconds more and serve. The whole dish takes a minute."]} },

{ id:'jiaohua-ji', c:'as', lat:30.280, lon:120.160, base:6, prep:1440, cook:240, diff:3, tags:['poultry','slow','festive'],
  art:{v:'leaf',bg:'#2b2419',plate:'#f0e4c8',style:'other',food:['#8f5a3a','#c9924a','#7fae5a','#e8c46a'],garnish:'#7fae6a'},
  n:{fr:'Poulet du mendiant',en:'Beggar\'s chicken'},
  p:{fr:'Hangzhou, Zhejiang, Chine',en:'Hangzhou, Zhejiang, China'},
  d:{fr:"Un poulet farci, enveloppé de feuilles de lotus et cuit enfermé dans une coque d'argile. La légende veut qu'un mendiant ayant volé un poulet l'ait enterré sous un feu pour le cacher ; la coque se casse au maillet à table, et la vapeur emprisonnée s'échappe d'un coup.",
     en:"A stuffed chicken wrapped in lotus leaves and baked sealed in a clay shell. Legend has a beggar who stole a chicken burying it under a fire to hide it; the shell is cracked with a mallet at the table, and the trapped steam escapes all at once."},
  i:[['chicken',1.6,'kg'],['pork_belly',200,'g'],['shiitake_mushrooms',80,'g'],['pickled_mustard_greens',100,'g'],['lotus_leaves',6,'pc'],['shaoxing_wine',100,'ml'],['soy_sauce',60,'ml'],['ginger',50,'g'],['scallion',2,'bunch'],['star_anise',3,'pc'],['sugar',20,'g'],['sesame_oil',20,'ml']],
  s:{fr:["Faites mariner le poulet douze heures au vin de Shaoxing, au soja et aux épices, en le massant plusieurs fois.","Farcissez-le de porc, champignons et légumes marinés revenus ensemble et refroidis.","Enveloppez-le de feuilles de lotus trempées, en trois couches croisées, puis de papier sulfurisé.","Enrobez d'une couche d'argile de trois centimètres, sans laisser la moindre ouverture : c'est l'étanchéité qui fait tout.","Cuisez quatre heures à 200 °C. Cassez la coque au maillet devant les convives, l'odeur du lotus s'échappe en une bouffée."],
     en:["Marinate the chicken twelve hours in Shaoxing wine, soy and spices, massaging it several times.","Stuff it with pork, mushrooms and pickled greens fried together and cooled.","Wrap it in soaked lotus leaves, three crossed layers, then in parchment.","Coat with a three-centimetre layer of clay, leaving not the smallest opening: the seal is everything.","Bake four hours at 200°C. Crack the shell with a mallet in front of the guests, and the lotus scent escapes in one breath."]} },

{ id:'meicai-kourou', c:'as', lat:30.000, lon:120.580, base:6, prep:120, cook:180, diff:3, tags:['pork','slow','comfort'],
  art:{v:'plate',bg:'#33291f',plate:'#f0e4c8',style:'other',food:['#5a3020','#3a2a1a','#e8c46a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Porc au légume sec',en:'Pork with preserved greens'},
  p:{fr:'Shaoxing, Zhejiang, Chine',en:'Shaoxing, Zhejiang, China'},
  d:{fr:"De la poitrine de porc cuite à la vapeur sur un lit de moutarde séchée fermentée. Le légume absorbe la graisse fondue et la rend en cuisant : c'est un échange, et c'est pourquoi le plat n'est jamais gras malgré la quantité de poitrine employée.",
     en:"Pork belly steamed on a bed of dried fermented mustard greens. The vegetable absorbs the rendered fat and gives it back as it cooks: it is an exchange, and why the dish is never greasy despite the quantity of belly used."},
  i:[['pork_belly',800,'g'],['preserved_mustard_greens',200,'g'],['dark_soy_sauce',60,'ml'],['soy_sauce',40,'ml'],['shaoxing_wine',80,'ml'],['rock_sugar',50,'g'],['star_anise',3,'pc'],['ginger',40,'g'],['garlic',6,'clove'],['frying_oil',500,'ml'],['scallion',1,'bunch']],
  s:{fr:["Faites tremper la moutarde séchée une heure et rincez-la cinq fois : elle est très salée et retient beaucoup de sable.","Pochez la poitrine entière quarante minutes, puis piquez la couenne partout et badigeonnez-la de soja foncé.","Frites-la couenne vers le bas, à couvert et à bout de bras : elle éclate violemment pendant les premières secondes.","Plongez-la aussitôt dans l'eau froide dix minutes : ce choc fait boursoufler la couenne, qui devient poreuse et fondante.","Tranchez, rangez les tranches couenne vers le bas dans un bol, couvrez de moutarde et cuisez trois heures à la vapeur. Retournez sur l'assiette."],
     en:["Soak the dried mustard greens an hour and rinse them five times: they are very salty and hold a lot of grit.","Poach the whole belly forty minutes, then prick the rind all over and brush it with dark soy.","Fry it rind down, covered and at arm's length: it spits violently for the first few seconds.","Plunge it straight into cold water for ten minutes: that shock blisters the rind, which turns porous and melting.","Slice, pack the slices rind down in a bowl, cover with the greens and steam three hours. Invert onto the plate."]} },

{ id:'wenzhou-yuwan', c:'as', lat:27.994, lon:120.699, base:4, prep:60, cook:20, diff:3, tags:['sea','soup','comfort'],
  art:{v:'bowl',bg:'#33291f',plate:'#f0e4c8',style:'soup',food:['#f4f0e6','#f0e8d0','#7fae5a','#e8c46a'],garnish:'#7fae6a'},
  n:{fr:'Boulettes de poisson de Wenzhou',en:'Wenzhou fish balls'},
  p:{fr:'Wenzhou, Zhejiang, Chine',en:'Wenzhou, Zhejiang, China'},
  d:{fr:"Des lanières de poisson roulées à la main dans la fécule, pochées en soupe aigre au vinaigre. Elles ne sont pas rondes malgré leur nom : le poisson est coupé en bandes, non broyé, et la texture fibreuse qui en résulte est propre à Wenzhou.",
     en:"Strips of fish rolled by hand in starch and poached in a sour vinegar soup. They are not round despite the name: the fish is cut into strips rather than ground, and the fibrous texture that results is peculiar to Wenzhou."},
  i:[['white_fish',600,'g'],['sweet_potato_starch',150,'g'],['ginger',40,'g'],['rice_vinegar',60,'ml'],['white_pepper',8,'g'],['scallion',1,'bunch'],['cilantro',1,'bunch'],['chicken_broth',1,'l'],['shaoxing_wine',20,'ml'],['egg_white',1,'pc'],['salt',null,'']],
  s:{fr:["Levez les filets et coupez-les en bandes de cinq centimètres sur un, en travers de la fibre.","Ne les broyez pas : la texture de la boulette de Wenzhou vient précisément de ces fibres restées entières.","Malaxez les bandes avec du sel et de l'eau de gingembre dix minutes, jusqu'à ce qu'elles deviennent collantes.","Enrobez chaque bande de fécule de patate douce en la roulant à la main, sans laisser de zone nue.","Pochez à frémissement trois minutes ; elles remontent quand elles sont prêtes. Servez dans un bouillon très vinaigré et poivré."],
     en:["Fillet the fish and cut it into strips five centimetres by one, across the grain.","Do not grind it: the texture of a Wenzhou fish ball comes precisely from those intact fibres.","Work the strips with salt and ginger water for ten minutes, until they turn tacky.","Coat each strip in sweet potato starch, rolling by hand, leaving no bare patch.","Poach at a tremble for three minutes; they rise when ready. Serve in a heavily vinegared and peppered broth."]} },

{ id:'runbing-quanzhou', c:'as', lat:24.874, lon:118.676, base:6, prep:90, cook:40, diff:3, tags:['street','veg','fresh'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'roll',food:['#f4f0e6','#7fae5a','#e8c46a','#f2dfa8'],garnish:'#7fae6a'},
  n:{fr:'Rouleaux de printemps du Fujian',en:'Fujian spring rolls'},
  p:{fr:'Quanzhou, Fujian, Chine',en:'Quanzhou, Fujian, China'},
  d:{fr:"De grandes crêpes translucides roulées à froid autour de légumes braisés et de cacahuètes sucrées. Contrairement au rouleau frit, le runbing se mange cru et se roule à table ; la crêpe se fabrique en tamponnant une boule de pâte collante sur une plaque brûlante.",
     en:"Large translucent pancakes rolled cold around braised vegetables and sweetened peanuts. Unlike the fried roll, runbing is eaten uncooked and rolled at the table; the pancake is made by dabbing a ball of sticky dough onto a scalding plate."},
  i:[['flour',400,'g'],['water',350,'ml'],['cabbage',400,'g'],['carrot',3,'pc'],['bean_sprouts',200,'g'],['pork_belly',200,'g'],['shrimp',150,'g'],['peanuts',150,'g'],['sugar',60,'g'],['seaweed',30,'g'],['garlic_chives',100,'g'],['soy_sauce',40,'ml'],['salt',null,'']],
  s:{fr:["Travaillez la pâte à la main quinze minutes, jusqu'à ce qu'elle devienne très élastique et collante, puis laissez-la reposer une heure.","Prenez-en une poignée et tamponnez-la sur la plaque brûlante d'un mouvement circulaire : il en reste une pellicule fine.","Le geste demande de la pratique — trop appuyé, la crêpe est épaisse ; trop léger, elle est trouée.","Braisez les légumes séparément selon leur temps propre, puis mêlez-les et égouttez-les à fond une heure.","Concassez les cacahuètes grillées avec le sucre. On roule à table : crêpe, algue grillée, légumes, cacahuètes sucrées."],
     en:["Work the dough by hand for fifteen minutes, until very elastic and sticky, then rest it an hour.","Take a handful and dab it onto the scalding plate in a circular motion: a thin film is left behind.","The gesture takes practice — too firm and the pancake is thick, too light and it has holes.","Braise the vegetables separately according to their own times, then combine them and drain thoroughly for an hour.","Crush the toasted peanuts with sugar. Rolling happens at the table: pancake, toasted seaweed, vegetables, sweet peanuts."]} },

{ id:'lizhi-rou', c:'as', lat:26.074, lon:119.296, base:4, prep:60, cook:20, diff:3, tags:['pork','fry','festive'],
  art:{v:'plate',bg:'#33291f',plate:'#f0e4c8',style:'other',food:['#c9302a','#f4f0e6','#e8a032','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Porc litchi',en:'Lychee pork'},
  p:{fr:'Fuzhou, Fujian, Chine',en:'Fuzhou, Fujian, China'},
  d:{fr:"Du porc entaillé qui s'ouvre en boule hérissée à la friture, dans une sauce aigre-douce rouge. Il ne contient aucun litchi : les morceaux, une fois frits, prennent la forme et la couleur du fruit, et c'est de là que vient le nom.",
     en:"Pork scored so that it opens into a bristling ball in the fryer, in a red sweet-sour sauce. It contains no lychee: the pieces, once fried, take the shape and colour of the fruit, and that is where the name comes from."},
  i:[['pork_loin',500,'g'],['water_chestnuts',150,'g'],['sweet_potato_starch',100,'g'],['red_yeast_rice',15,'g'],['rice_vinegar',60,'ml'],['sugar',80,'g'],['garlic',6,'clove'],['scallion',1,'bunch'],['shaoxing_wine',30,'ml'],['egg',1,'pc'],['frying_oil',1,'l'],['cornstarch',20,'g']],
  s:{fr:["Coupez le porc en carrés de trois centimètres et entaillez chacun en croisillons serrés, sur les deux faces, sans traverser.","Ce sont ces entailles qui font s'ouvrir le morceau en boule à la friture : plus elles sont fines, plus l'effet est net.","Faites mariner au vin et au riz rouge fermenté, qui donne la couleur sans colorant artificiel.","Enrobez de fécule de patate douce et frites à 190 °C, quatre-vingt-dix secondes : les morceaux se hérissent aussitôt.","Sautez-les dans la sauce aigre-douce dix secondes seulement, pour qu'ils gardent leur croustillant."],
     en:["Cut the pork into three-centimetre squares and score each in a tight lattice on both faces, without cutting through.","Those cuts are what make the piece open into a ball in the fryer: the finer they are, the sharper the effect.","Marinate in wine and red yeast rice, which gives the colour without artificial colouring.","Coat in sweet potato starch and fry at 190°C for ninety seconds: the pieces bristle at once.","Toss them in the sweet-sour sauce for ten seconds only, so they keep their crispness."]} },

{ id:'shacha-mian', c:'as', lat:24.480, lon:118.089, base:4, prep:40, cook:25, diff:2, tags:['noodles','sea','comfort'],
  art:{v:'bowl',bg:'#33291f',plate:'#f0e4c8',style:'noodle',food:['#c9924a','#e8a032','#f2dfa8','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Nouilles au shacha',en:'Shacha noodles'},
  p:{fr:'Xiamen, Fujian, Chine',en:'Xiamen, Fujian, China'},
  d:{fr:"Des nouilles dans un bouillon à la pâte de shacha, aux cacahuètes et poisson séché. Le shacha est la version chinoise du satay malais, rapporté par les émigrés du Fujian revenus d'Asie du Sud-Est : le nom vient de sate, prononcé en hokkien.",
     en:"Noodles in a broth of shacha paste, with peanuts and dried fish. Shacha is the Chinese version of Malay satay, brought back by Fujianese emigrants returning from Southeast Asia: the name comes from sate, said in Hokkien."},
  i:[['wheat_noodles',400,'g'],['shacha_sauce',80,'g'],['shrimp',200,'g'],['squid',150,'g'],['pork_liver',100,'g'],['chicken_broth',1,'l'],['coconut_milk',150,'ml'],['bean_sprouts',150,'g'],['bok_choy',200,'g'],['garlic',6,'clove'],['peanut_oil',40,'ml'],['sugar',15,'g']],
  s:{fr:["Faites griller la pâte de shacha dans l'huile chaude une minute avant de mouiller : c'est ce qui réveille les arômes de poisson séché.","Ajoutez le bouillon peu à peu en fouettant, pour que la pâte se dissolve sans former de grumeaux.","Un filet de lait de coco arrondit le bouillon : c'est l'héritage direct du satay d'Asie du Sud-Est.","Pochez chaque garniture séparément dans le bouillon, selon son temps propre, et réservez-la.","Cuisez les nouilles à part et rincez-les. Assemblez dans le bol et versez le bouillon brûlant par-dessus."],
     en:["Toast the shacha paste in hot oil for a minute before moistening: that wakes the dried fish aromas.","Add the broth little by little, whisking, so the paste dissolves without lumping.","A thread of coconut milk rounds the broth: the direct inheritance from Southeast Asian satay.","Poach each topping separately in the broth according to its own time, and set it aside.","Cook the noodles apart and rinse them. Assemble in the bowl and pour the scalding broth over."]} },

{ id:'sibao-tang', c:'as', lat:24.485, lon:118.095, base:6, prep:60, cook:40, diff:2, tags:['sweet','fresh','fruit'],
  art:{v:'bowl',bg:'#33291f',plate:'#f4ead4',style:'other',food:['#f4f0e6','#7fae5a','#e07a6a','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Soupe aux quatre fruits',en:'Four fruits soup'},
  p:{fr:'Xiamen, Fujian, Chine',en:'Xiamen, Fujian, China'},
  d:{fr:"Un dessert glacé mêlant quatre éléments dans un sirop léger, servi en été. Les quatre ne sont pas fixés : chaque échoppe compose les siens parmi une dizaine d'ingrédients possibles, et le nom désigne la structure plutôt qu'une recette précise.",
     en:"A chilled dessert combining four elements in a light syrup, served in summer. The four are not fixed: each stall composes its own from a dozen possible ingredients, and the name describes the structure rather than a set recipe."},
  i:[['mung_beans',150,'g'],['lotus_seeds',100,'g'],['taro_root',200,'g'],['agar_agar',6,'g'],['rock_sugar',150,'g'],['coconut_milk',200,'ml'],['water',1,'l'],['osmanthus',5,'g'],['ice',500,'g']],
  s:{fr:["Cuisez chaque élément séparément : ils n'ont pas le même temps, et ensemble certains se défont pendant que d'autres restent durs.","Faites tremper les haricots mungo une nuit et cuisez-les jusqu'à ce qu'ils s'écrasent sans se dissoudre.","Retirez le germe vert au centre des graines de lotus : il est franchement amer et gâche l'ensemble.","Préparez le sirop léger à part et refroidissez-le complètement avant d'assembler.","Montez dans le bol au dernier moment, avec la glace pilée en dernier. Se mange dans les cinq minutes."],
     en:["Cook each element separately: they do not share a cooking time, and together some collapse while others stay hard.","Soak the mung beans overnight and cook them until they crush without dissolving.","Remove the green germ at the centre of the lotus seeds: it is frankly bitter and spoils the whole.","Make the light syrup separately and chill it completely before assembling.","Build in the bowl at the last moment, with the crushed ice last. Eaten within five minutes."]} },

{ id:'fuzhou-yuwan', c:'as', lat:26.080, lon:119.300, base:4, prep:90, cook:20, diff:3, tags:['sea','soup','comfort'],
  art:{v:'bowl',bg:'#33291f',plate:'#f0e4c8',style:'soup',food:['#f4f0e6','#f0e8d0','#8f5a3a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Boulettes de poisson de Fuzhou',en:'Fuzhou fish balls'},
  p:{fr:'Fuzhou, Fujian, Chine',en:'Fuzhou, Fujian, China'},
  d:{fr:"Des boulettes de poisson blanches et parfaitement lisses, fourrées de porc haché. Elles diffèrent de celles de Wenzhou en tout point : ici la chair est broyée jusqu'à devenir une pâte élastique, et la boulette est ronde, lisse et creuse d'une farce.",
     en:"White, perfectly smooth fish balls filled with minced pork. They differ from Wenzhou's in every respect: here the flesh is ground to an elastic paste, and the ball is round, smooth and hollowed around a filling."},
  i:[['eel',500,'g'],['sweet_potato_starch',120,'g'],['ground_pork',200,'g'],['egg_white',2,'pc'],['ginger',40,'g'],['white_pepper',8,'g'],['scallion',1,'bunch'],['chicken_broth',1,'l'],['sesame_oil',15,'ml'],['ice_water',150,'ml'],['salt',null,'']],
  s:{fr:["Employez de préférence de l'anguille de mer ou un poisson blanc très ferme, parfaitement dénervé.","Broyez la chair avec du sel et de l'eau glacée, en plusieurs fois, en maintenant la pâte sous 10 °C.","La température est décisive : au-dessus de 12 °C, les protéines coagulent et la pâte perd son élasticité définitivement.","Battez la pâte contre le bol cinquante fois, jusqu'à ce qu'une boulette jetée dans l'eau froide flotte.","Formez les boulettes dans la paume autour de la farce de porc et pochez à 80 °C, sans jamais bouillir."],
     en:["Use sea eel for preference, or a very firm white fish, perfectly free of sinew.","Grind the flesh with salt and iced water in several stages, keeping the paste below 10°C.","Temperature is decisive: above 12°C the proteins coagulate and the paste loses its elasticity for good.","Beat the paste against the bowl fifty times, until a test ball dropped in cold water floats.","Shape the balls in your palm around the pork filling and poach at 80°C, never boiling."]} },

{ id:'duojiao-yutou', c:'as', lat:28.228, lon:112.939, base:4, prep:40, cook:30, diff:2, tags:['sea','spicy','festive'],
  art:{v:'plate',bg:'#33291f',plate:'#f0e4c8',style:'fish',food:['#c9302a','#f4f0e6','#e8a032','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Tête de poisson au piment haché',en:'Fish head with chopped chilli'},
  p:{fr:'Changsha, Hunan, Chine',en:'Changsha, Hunan, China'},
  d:{fr:"Une tête de carpe fendue, couverte de piments fermentés hachés et cuite à la vapeur. Le duojiao est un piment haché fermenté au sel pendant des mois ; il est acide autant que piquant, et c'est cette acidité qui distingue le piment du Hunan de celui du Sichuan.",
     en:"A split carp head covered with chopped fermented chillies and steamed. Duojiao is chilli chopped and salt-fermented for months; it is as sour as it is hot, and that sourness is what distinguishes Hunan chilli from Sichuan's."},
  i:[['fish_head',1.2,'kg'],['pickled_chili',200,'g'],['ginger',60,'g'],['garlic',12,'clove'],['scallion',2,'bunch'],['shaoxing_wine',60,'ml'],['soy_sauce',40,'ml'],['peanut_oil',100,'ml'],['sugar',15,'g'],['wheat_noodles',200,'g'],['fermented_black_beans',20,'g']],
  s:{fr:["Fendez la tête en deux par le dessous en laissant la peau du dessus attachée, pour qu'elle s'ouvre à plat.","Frottez-la de vin et de sel et laissez-la vingt minutes, puis épongez le liquide rendu.","Étalez le piment fermenté en couche épaisse et régulière sur toute la surface, sans laisser de zone nue.","Cuisez douze minutes à la vapeur la plus vive, pas davantage : la joue est cuite bien avant le reste.","Versez l'huile fumante sur les cives crues et servez avec des nouilles à tremper dans le jus, comme il est d'usage à Changsha."],
     en:["Split the head from underneath, leaving the top skin attached, so it opens out flat.","Rub it with wine and salt and leave twenty minutes, then blot off the released liquid.","Spread the fermented chilli in a thick even layer over the whole surface, leaving no bare patch.","Steam twelve minutes over the fiercest steam, no longer: the cheek is cooked well before the rest.","Pour smoking oil over the raw spring onions and serve with noodles to soak in the juices, as is the custom in Changsha."]} }
,

{ id:'dongan-ji', c:'as', lat:26.394, lon:111.317, base:4, prep:40, cook:30, diff:2, tags:['poultry','spicy','fresh'],
  art:{v:'plate',bg:'#33291f',plate:'#f0e4c8',style:'other',food:['#f4f0e6','#c9302a','#e8c46a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Poulet de Dong\'an',en:'Dong\'an chicken'},
  p:{fr:'Dong\'an, Hunan, Chine',en:'Dong\'an, Hunan, China'},
  d:{fr:"Du poulet poché puis sauté au vinaigre, au gingembre et au poivre du Sichuan. Il remonte à la dynastie Tang et figure au menu des banquets d'État chinois depuis 1949 ; c'est un plat aigre plutôt que piquant, ce qui est rare au Hunan.",
     en:"Chicken poached then stir-fried with vinegar, ginger and Sichuan pepper. It goes back to the Tang dynasty and has featured at Chinese state banquets since 1949; it is a sour rather than hot dish, which is rare in Hunan."},
  i:[['chicken',1.2,'kg'],['rice_vinegar',80,'ml'],['ginger',80,'g'],['sichuan_peppercorns',10,'g'],['dried_chili',8,'pc'],['scallion',1,'bunch'],['chicken_broth',200,'ml'],['cornstarch',20,'g'],['shaoxing_wine',30,'ml'],['peanut_oil',60,'ml'],['salt',null,'']],
  s:{fr:["Pochez le poulet entier vingt minutes à 85 °C, puis laissez-le refroidir dans son bouillon.","Désossez-le tiède et coupez la chair en lanières avec la peau attachée : elle apporte le gras qui manquerait sinon.","Employez beaucoup plus de gingembre que ne le suggère l'instinct — en julienne, il fait presque office de légume.","Sautez à feu vif une minute, ajoutez le vinaigre par les parois du wok pour qu'il s'évapore en partie.","Versé au centre, le vinaigre reste cru et agressif ; versé sur le métal brûlant, il perd son mordant et garde son parfum."],
     en:["Poach the whole chicken twenty minutes at 85°C, then let it cool in its broth.","Bone it warm and cut the flesh into strips with the skin attached: it brings fat that would otherwise be missing.","Use far more ginger than instinct suggests — in julienne it acts almost as a vegetable.","Stir-fry over high heat for a minute, adding the vinegar down the sides of the wok so part of it flashes off.","Poured into the centre, vinegar stays raw and aggressive; poured onto scalding metal, it loses its bite and keeps its scent."]} },

{ id:'xiaochao-huangniurou', c:'as', lat:28.235, lon:112.945, base:4, prep:30, cook:10, diff:2, tags:['beef','spicy','fast'],
  art:{v:'plate',bg:'#33291f',plate:'#f0e4c8',style:'other',food:['#8f4a3a','#7fae5a','#c9302a','#e8c46a'],garnish:'#7fae6a'},
  n:{fr:'Bœuf sauté du Hunan',en:'Hunan stir-fried beef'},
  p:{fr:'Changsha, Hunan, Chine',en:'Changsha, Hunan, China'},
  d:{fr:"Du bœuf sauté très vite avec des piments verts frais et du piment fermenté. La cuisine du Hunan emploie le piment frais là où le Sichuan emploie le séché : le résultat est plus vif, plus végétal, et brûle davantage la gorge que la langue.",
     en:"Beef stir-fried very fast with fresh green chillies and fermented chilli. Hunan cooking uses fresh chilli where Sichuan uses dried: the result is sharper, greener, and burns the throat more than the tongue."},
  i:[['beef_sirloin',400,'g'],['green_chili',10,'pc'],['pickled_chili',60,'g'],['garlic',10,'clove'],['ginger',40,'g'],['soy_sauce',40,'ml'],['shaoxing_wine',30,'ml'],['cornstarch',20,'g'],['peanut_oil',80,'ml'],['fermented_black_beans',20,'g'],['scallion',1,'bunch']],
  s:{fr:["Tranchez le bœuf très fin en travers de la fibre et veloutez-le à la fécule et au vin quinze minutes.","Employez des piments verts longs et charnus, fendus en deux et non hachés : ils doivent rester des morceaux qu'on mange.","Chauffez le wok jusqu'à ce qu'il fume avant d'y verser l'huile — c'est le wok hei, et sans lui le plat n'a pas son goût de brûlé caractéristique.","Sautez le bœuf quarante secondes, retirez-le, puis faites les piments à part avant de tout réunir.","Le plat entier ne dépasse pas deux minutes de cuisson. Au-delà, le bœuf durcit et les piments s'affaissent."],
     en:["Slice the beef very thinly across the grain and velvet it with cornflour and wine for fifteen minutes.","Use long fleshy green chillies, split in two rather than chopped: they must stay pieces you eat.","Heat the wok until it smokes before adding the oil — that is wok hei, and without it the dish lacks its characteristic scorched note.","Stir-fry the beef forty seconds, remove it, then do the chillies separately before bringing everything together.","The whole dish takes no more than two minutes' cooking. Beyond that the beef toughens and the chillies collapse."]} },

{ id:'yongzhou-xueya', c:'as', lat:26.420, lon:111.613, base:4, prep:40, cook:40, diff:3, tags:['poultry','spicy','stew'],
  art:{v:'pot',bg:'#33291f',plate:'#f0e4c8',style:'stew',food:['#5a2a2a','#c9302a','#e8c46a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Canard au sang de Yongzhou',en:'Yongzhou blood duck'},
  p:{fr:'Yongzhou, Hunan, Chine',en:'Yongzhou, Hunan, China'},
  d:{fr:"Du canard sauté puis lié avec son propre sang, qui enrobe chaque morceau. Le sang est recueilli sur du vinaigre pour l'empêcher de coaguler, puis versé cru en fin de cuisson : il ne fait pas de sauce mais une pellicule sombre et brillante sur la viande.",
     en:"Duck stir-fried then bound with its own blood, which coats every piece. The blood is collected onto vinegar to stop it clotting, then poured in raw at the end: it makes no sauce but a dark glossy film on the meat."},
  i:[['duck',1.5,'kg'],['duck_blood',300,'ml'],['rice_vinegar',60,'ml'],['green_chili',8,'pc'],['pickled_chili',60,'g'],['ginger',60,'g'],['garlic',12,'clove'],['shaoxing_wine',80,'ml'],['soy_sauce',40,'ml'],['perilla_leaves',20,'pc'],['peanut_oil',80,'ml'],['salt',null,'']],
  s:{fr:["Battez le sang avec le vinaigre dès la collecte, sans quoi il caille en blocs et ne pourra plus enrober la viande.","Découpez le canard en petits morceaux avec l'os, à la feuille, pour qu'ils cuisent vite et présentent beaucoup de surface.","Sautez-les à feu vif jusqu'à ce qu'ils rendent leur gras et brunissent, une bonne quinzaine de minutes.","Ajoutez piments et aromates, mouillez à peine et laissez cuire vingt minutes à couvert.","Coupez le feu, puis versez le sang en remuant sans arrêt. Il coagule à la chaleur résiduelle : sur le feu, il grainerait."],
     en:["Beat the blood with the vinegar as soon as it is collected, or it clots into lumps and will no longer coat the meat.","Chop the duck into small pieces on the bone with a cleaver, so they cook fast and present plenty of surface.","Stir-fry over high heat until they render their fat and brown, a good fifteen minutes.","Add chillies and aromatics, moisten barely and cook twenty minutes covered.","Cut the heat, then pour in the blood, stirring without pause. It sets in the residual heat: over the flame it would go grainy."]} },

{ id:'kouwei-xia', c:'as', lat:28.220, lon:112.930, base:4, prep:60, cook:30, diff:2, tags:['sea','spicy','street'],
  art:{v:'bowl',bg:'#33291f',plate:'#f0e4c8',style:'other',food:['#c9302a','#e07a6a','#e8c46a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Écrevisses à la mode du Hunan',en:'Hunan-style crayfish'},
  p:{fr:'Changsha, Hunan, Chine',en:'Changsha, Hunan, China'},
  d:{fr:"Des écrevisses braisées dans une sauce très pimentée, mangées à la main l'été. Elles sont devenues dans les années 2000 le rituel nocturne des villes chinoises : on les mange à minuit, avec des gants de plastique, en buvant de la bière glacée.",
     en:"Crayfish braised in a heavily spiced sauce, eaten with the hands in summer. In the 2000s they became the night ritual of Chinese cities: eaten at midnight, with plastic gloves, alongside iced beer."},
  i:[['crayfish',2,'kg'],['doubanjiang',80,'g'],['dried_chili',20,'pc'],['sichuan_peppercorns',15,'g'],['garlic',20,'clove'],['ginger',60,'g'],['beer',500,'ml'],['shaoxing_wine',80,'ml'],['star_anise',4,'pc'],['cinnamon_stick',2,'pc'],['peanut_oil',200,'ml'],['sugar',20,'g'],['scallion',2,'bunch']],
  s:{fr:["Brossez les écrevisses vivantes une par une sous l'eau, en insistant sur le ventre, puis retirez le boyau en tirant la nageoire centrale de la queue.","Ce nettoyage est long mais il n'est pas facultatif : l'écrevisse vit dans la vase et un lot mal brossé est immangeable.","Coupez la pointe du rostre aux ciseaux, ce qui permet à la sauce d'entrer dans la tête.","Faites-les sauter à l'huile brûlante jusqu'à ce qu'elles rougissent, puis retirez-les avant de faire la sauce.","Braisez vingt minutes à la bière et aux épices, puis laissez refroidir dedans une heure — c'est en refroidissant qu'elles prennent le goût."],
     en:["Scrub the live crayfish one by one under water, working the belly, then pull out the vein by twisting the central tail fin.","This cleaning is slow but not optional: crayfish live in mud and a badly scrubbed batch is inedible.","Snip off the tip of the rostrum with scissors, which lets the sauce into the head.","Toss them in scalding oil until they redden, then remove them before making the sauce.","Braise twenty minutes in beer and spices, then let them cool in it for an hour — cooling is when they take the flavour."]} },

{ id:'chou-guiyu', c:'as', lat:29.715, lon:118.338, base:4, prep:2880, cook:30, diff:3, tags:['sea','slow','festive'],
  art:{v:'plate',bg:'#33291f',plate:'#f0e4c8',style:'fish',food:['#8f5a3a','#c9302a','#e8c46a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Mandarin puant',en:'Stinky mandarin fish'},
  p:{fr:'Huangshan, Anhui, Chine',en:'Huangshan, Anhui, China'},
  d:{fr:"Un poisson fermenté une semaine sous presse, à l'odeur puissante et à la chair feuilletée. La fermentation a été découverte par accident : des marchands transportant du poisson salé vers les montagnes le trouvaient odorant à l'arrivée, et le cuisaient plutôt que de le jeter.",
     en:"A fish fermented a week under a weight, powerfully smelling and flaky-fleshed. The fermentation was discovered by accident: merchants carrying salted fish into the mountains found it smelling on arrival, and cooked it rather than throw it away."},
  i:[['freshwater_fish',1,'kg'],['coarse_salt',80,'g'],['pork_belly',150,'g'],['bamboo_shoots',100,'g'],['ginger',40,'g'],['garlic',8,'clove'],['dried_chili',6,'pc'],['soy_sauce',50,'ml'],['shaoxing_wine',60,'ml'],['sugar',20,'g'],['peanut_oil',80,'ml'],['scallion',1,'bunch']],
  s:{fr:["Salez le poisson vidé et empilez-le sous une pierre dans un récipient de bois, à 20-25 °C.","Comptez six à sept jours en été, davantage en hiver ; retournez-le chaque jour et remettez la pierre.","L'odeur devient franchement forte, mais la chair doit rester ferme et blanche : si elle se délite ou vire au gris, jetez tout.","Rincez, épongez et faites dorer le poisson à la poêle sur les deux faces avant de le braiser.","Braisez vingt minutes avec le porc et les pousses de bambou. La chair se détache alors en pétales, comme des feuilles."],
     en:["Salt the gutted fish and stack it under a stone in a wooden vessel, at 20-25°C.","Allow six or seven days in summer, longer in winter; turn it daily and replace the stone.","The smell turns frankly strong, but the flesh must stay firm and white: if it softens or greys, throw it all away.","Rinse, blot and brown the fish in a pan on both sides before braising.","Braise twenty minutes with the pork and bamboo shoots. The flesh then parts into petals, like leaves."]} },

{ id:'li-hongzhang-zahui', c:'as', lat:31.821, lon:117.227, base:6, prep:120, cook:60, diff:3, tags:['sea','stew','festive'],
  art:{v:'pot',bg:'#33291f',plate:'#f0e4c8',style:'stew',food:['#f0e8d0','#8f5a3a','#e8c46a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Pot-pourri de Li Hongzhang',en:'Li Hongzhang hotchpotch'},
  p:{fr:'Hefei, Anhui, Chine',en:'Hefei, Anhui, China'},
  d:{fr:"Un ragoût de produits de mer séchés et de viandes, réunis dans un bouillon épais. Il porte le nom du diplomate Li Hongzhang qui, recevant des invités américains en 1896 et n'ayant plus de plat prêt, aurait fait réunir tous les restes de la cuisine.",
     en:"A stew of dried seafood and meats brought together in a thick broth. It is named for the diplomat Li Hongzhang, who in 1896, entertaining American guests with no dish left ready, is said to have had all the kitchen's leftovers combined."},
  i:[['dried_sea_cucumber',80,'g'],['squid',150,'g'],['chicken',300,'g'],['pork_belly',200,'g'],['ham',80,'g'],['bamboo_shoots',150,'g'],['shiitake_mushrooms',80,'g'],['quail_egg',12,'pc'],['sweet_potato_noodles',100,'g'],['chicken_broth',1,'l'],['cornstarch',25,'g'],['ginger',40,'g'],['shaoxing_wine',60,'ml'],['cilantro',1,'bunch']],
  s:{fr:["Réhydratez chaque produit séché séparément et selon son temps propre : le concombre de mer demande trois jours, le calmar une nuit.","Précuisez chaque viande à part, puis coupez tout en morceaux de même taille pour que rien ne domine.","Montez le ragoût par ordre de fermeté, en ajoutant les éléments à cinq minutes d'intervalle.","Liez le bouillon à la fécule en fin de cuisson : ce plat doit napper, à mi-chemin entre la soupe et le ragoût.","Ne mêlez pas au moment de servir : les éléments se disposent en couronne et chacun se sert de ce qu'il veut."],
     en:["Rehydrate each dried item separately and to its own timetable: sea cucumber needs three days, squid one night.","Pre-cook each meat apart, then cut everything into pieces of the same size so nothing dominates.","Build the stew in order of firmness, adding elements five minutes apart.","Thicken the broth with cornflour at the end: this dish should coat, halfway between soup and stew.","Do not stir when serving: the elements are arranged in a ring and each diner takes what they want."]} },

{ id:'wenzheng-shansun', c:'as', lat:29.720, lon:118.345, base:4, prep:60, cook:40, diff:2, tags:['veg','festive','fresh'],
  art:{v:'plate',bg:'#28331f',plate:'#f0e4c8',style:'other',food:['#f2dfa8','#8f5a3a','#7fae5a','#e8c46a'],garnish:'#7fae6a'},
  n:{fr:'Pousses de bambou du mont Wenzheng',en:'Wenzheng mountain bamboo shoots'},
  p:{fr:'Huangshan, Anhui, Chine',en:'Huangshan, Anhui, China'},
  d:{fr:"Des pousses de bambou de printemps braisées avec du jambon sec et du poulet. Elles doivent être cuisinées dans les heures qui suivent la récolte : passé un jour, la pousse se ligniﬁe et développe une amertume que rien n'enlève.",
     en:"Spring bamboo shoots braised with dry-cured ham and chicken. They must be cooked within hours of harvest: after a day the shoot lignifies and develops a bitterness nothing removes."},
  i:[['bamboo_shoots',800,'g'],['jinhua_ham',150,'g'],['chicken',300,'g'],['chicken_broth',600,'ml'],['lard',60,'g'],['shaoxing_wine',40,'ml'],['sugar',15,'g'],['ginger',30,'g'],['scallion',1,'bunch'],['salt',null,'']],
  s:{fr:["Fendez la pousse dans la longueur avant de la peler : les gaines se retirent alors d'un coup, au lieu de s'arracher une à une.","Blanchissez dix minutes à l'eau salée pour ôter l'acide oxalique, qui donne la sensation râpeuse en bouche.","Coupez en biseau à angle très ouvert : cela augmente la surface et permet au bouillon d'entrer dans la fibre.","Braisez avec le jambon et le poulet quarante minutes, à couvert, dans un bouillon peu salé — le jambon apporte déjà beaucoup de sel.","Le plat est fini quand la pousse est translucide sur les bords. Servez-la seule, le jambon n'ayant servi qu'à parfumer."],
     en:["Split the shoot lengthways before peeling: the sheaths then come away in one, instead of being torn off one by one.","Blanch ten minutes in salted water to remove the oxalic acid, which gives a rasping feel in the mouth.","Cut on a very open bias: this increases the surface and lets the broth into the fibre.","Braise with the ham and chicken for forty minutes, covered, in a lightly salted broth — the ham already brings plenty of salt.","It is done when the shoot is translucent at the edges. Serve it alone, the ham having served only to flavour."]} },

{ id:'mao-doufu', c:'as', lat:29.710, lon:118.330, base:4, prep:2880, cook:20, diff:3, tags:['veg','slow','fry'],
  art:{v:'plate',bg:'#33291f',plate:'#f4ead4',style:'other',food:['#f4f0e6','#c9924a','#e8c46a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Tofu poilu',en:'Hairy tofu'},
  p:{fr:'Tunxi, Anhui, Chine',en:'Tunxi, Anhui, China'},
  d:{fr:"Du tofu couvert d'un duvet blanc de moisissure, poêlé jusqu'à ce que la peau dore. La moisissure est un Mucor, le même genre que celui des fromages : elle décompose les protéines du soja et donne au tofu un goût qui rappelle un fromage affiné.",
     en:"Tofu covered with a white bloom of mould, pan-fried until the skin colours. The mould is a Mucor, the same genus as on cheeses: it breaks down the soy proteins and gives the tofu a flavour recalling a ripened cheese."},
  i:[['firm_tofu',600,'g'],['peanut_oil',80,'ml'],['chili_sauce',60,'g'],['scallion',1,'bunch'],['ginger',30,'g'],['soy_sauce',40,'ml'],['sugar',10,'g'],['sichuan_peppercorns',5,'g'],['garlic',4,'clove']],
  s:{fr:["Découpez le tofu ferme en cubes et disposez-les espacés sur une claie de bambou, sans qu'ils se touchent.","Laissez-les trois jours à 20 °C dans un endroit humide et à l'abri des courants d'air.","Le duvet blanc doit être uniforme et sentir le champignon frais. Une trace noire, verte ou rose signifie une contamination : jetez tout.","Poêlez à feu moyen dans peu d'huile, sans retourner avant que la face soit franchement dorée — le duvet forme une croûte.","Servez avec une sauce pimentée. Le goût est proche d'un fromage à croûte fleurie, ce qui surprend toujours."],
     en:["Cut firm tofu into cubes and set them spaced on a bamboo rack, not touching.","Leave them three days at 20°C somewhere humid and out of draughts.","The white bloom should be even and smell of fresh mushroom. Any black, green or pink patch means contamination: throw it all away.","Pan-fry over medium heat in a little oil, without turning until the face is frankly golden — the bloom forms a crust.","Serve with a chilli sauce. The taste is close to a bloomy-rind cheese, which always surprises."]} },

{ id:'wuwei-xunya', c:'as', lat:31.187, lon:117.911, base:6, prep:1440, cook:90, diff:3, tags:['poultry','slow','festive'],
  art:{v:'plate',bg:'#33291f',plate:'#f0e4c8',style:'other',food:['#8f5a3a','#5a3020','#e8c46a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Canard fumé de Wuwei',en:'Wuwei smoked duck'},
  p:{fr:'Wuwei, Anhui, Chine',en:'Wuwei, Anhui, China'},
  d:{fr:"Un canard fumé au thé et au bois de camphrier, puis cuit à la vapeur. Il se distingue du canard de Chengdu par le fumage à froid : la fumée pénètre plusieurs heures sans cuire l'animal, et la chair garde une couleur rosée jusqu'à l'os.",
     en:"A duck smoked over tea and camphor wood, then steamed. It differs from the Chengdu duck in being cold-smoked: the smoke penetrates over several hours without cooking the bird, and the flesh keeps a pink tone to the bone."},
  i:[['duck',2,'kg'],['coarse_salt',100,'g'],['sichuan_peppercorns',20,'g'],['green_tea',40,'g'],['camphor_leaves',40,'g'],['rice',80,'g'],['brown_sugar',60,'g'],['star_anise',4,'pc'],['ginger',50,'g'],['shaoxing_wine',60,'ml'],['scallion',2,'bunch'],['sesame_oil',20,'ml']],
  s:{fr:["Saumurez le canard à sec au sel et au poivre grillés, vingt-quatre heures, en le retournant deux fois.","Suspendez-le ensuite quatre heures dans un courant d'air pour que la peau sèche et devienne collante au toucher.","Cette pellicule collante, la pellicule, est ce à quoi la fumée s'accroche : sans elle, le fumage ne prend pas.","Fumez à froid, sous 30 °C, pendant deux heures : le canard ne doit pas cuire à ce stade.","Cuisez enfin une heure et demie à la vapeur. La chair reste rosée près de l'os, ce qui est normal pour ce plat."],
     en:["Dry-cure the duck with toasted salt and pepper for twenty-four hours, turning it twice.","Then hang it four hours in a draught so the skin dries and becomes tacky to the touch.","That tacky film, the pellicle, is what the smoke clings to: without it, smoking does not take.","Cold-smoke below 30°C for two hours: the duck must not cook at this stage.","Finally steam it an hour and a half. The flesh stays pink near the bone, which is normal for this dish."]} },

{ id:'jingjiang-rousi', c:'as', lat:39.910, lon:116.400, base:4, prep:40, cook:15, diff:2, tags:['pork','fast','comfort'],
  art:{v:'plate',bg:'#33291f',plate:'#f0e4c8',style:'other',food:['#5a3020','#7fae5a','#f4f0e6','#e8c46a'],garnish:'#7fae6a'},
  n:{fr:'Lanières de porc sauce de Pékin',en:'Beijing-sauce pork slivers'},
  p:{fr:'Pékin, Chine',en:'Beijing, China'},
  d:{fr:"Des lanières de porc sautées à la pâte de soja sucrée, roulées dans des feuilles de tofu. Le plat descend directement du canard laqué : même sauce, mêmes cives, même geste d'enroulement, mais avec du porc à la place du canard et pour un dixième du prix.",
     en:"Pork slivers stir-fried in sweet soybean paste and rolled in tofu skin. The dish descends directly from Peking duck: same sauce, same spring onions, same rolling gesture, but with pork instead of duck and at a tenth of the price."},
  i:[['pork_loin',400,'g'],['sweet_bean_sauce',80,'g'],['tofu_skin',12,'pc'],['scallion',3,'bunch'],['egg_white',1,'pc'],['cornstarch',25,'g'],['shaoxing_wine',30,'ml'],['sugar',30,'g'],['sesame_oil',15,'ml'],['peanut_oil',80,'ml'],['ginger',30,'g']],
  s:{fr:["Coupez le porc en lanières fines et veloutez-les au blanc d'œuf et à la fécule vingt minutes.","Faites cuire la pâte de soja sucrée séparément dans l'huile, cinq minutes, jusqu'à ce qu'elle brille et perde son goût cru.","Sautez le porc trente secondes à l'huile tiède, puis égouttez-le avant de le mêler à la sauce.","Cette précuisson à basse température est ce qui garde les lanières tendres : sautées à feu vif, elles durcissent.","Dressez sur un lit de cives crues en julienne et servez avec des feuilles de tofu pour rouler à table."],
     en:["Cut the pork into fine slivers and velvet them with egg white and cornflour for twenty minutes.","Cook the sweet soybean paste separately in oil for five minutes, until it shines and loses its raw taste.","Stir-fry the pork thirty seconds in warm oil, then drain it before folding it into the sauce.","That low-temperature pre-cooking is what keeps the slivers tender: seared over high heat, they toughen.","Plate on a bed of raw julienned spring onion and serve with tofu skins for rolling at the table."]} },

{ id:'douzhi-jiaoquan', c:'as', lat:39.895, lon:116.415, base:4, prep:2880, cook:30, diff:3, tags:['breakfast','street','fry'],
  art:{v:'bowl',bg:'#33291f',plate:'#f0e4c8',style:'other',food:['#8f7a5a','#e8c46a','#c9924a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Jus de haricot mungo et beignet',en:'Fermented mung bean juice with fried ring'},
  p:{fr:'Pékin, Chine',en:'Beijing, China'},
  d:{fr:"Un jus de haricot mungo fermenté, à l'odeur aigre, bu avec un anneau frit. C'est le petit-déjeuner pékinois le plus difficile pour un étranger : l'odeur évoque le lait tourné, et l'on dit à Pékin qu'aimer le douzhi est la preuve qu'on est vraiment de la ville.",
     en:"A sour-smelling fermented mung bean juice drunk with a fried ring. It is the Beijing breakfast hardest on outsiders: the smell suggests soured milk, and Beijingers say that liking douzhi proves you are truly of the city."},
  i:[['mung_beans',500,'g'],['water',3,'l'],['flour',300,'g'],['baking_soda',5,'g'],['frying_oil',1.5,'l'],['pickled_mustard_greens',150,'g'],['chili_oil',20,'ml'],['salt',null,'']],
  s:{fr:["Faites tremper les haricots mungo une nuit, broyez-les avec beaucoup d'eau et laissez décanter six heures.","Séparez l'amidon qui se dépose au fond du liquide trouble au-dessus : c'est ce liquide qui devient le douzhi.","Laissez-le fermenter deux jours à température ambiante, jusqu'à ce qu'il sente franchement l'aigre.","Chauffez-le sans le faire bouillir, en remuant : bouilli, il tranche et se sépare irrémédiablement.","Servez brûlant avec un anneau de pâte frite et des légumes marinés, qui coupent l'acidité."],
     en:["Soak the mung beans overnight, grind them with plenty of water and let them settle six hours.","Separate the starch that sinks from the cloudy liquid above: that liquid becomes the douzhi.","Let it ferment two days at room temperature, until it smells frankly sour.","Heat it without boiling, stirring: boiled, it splits and separates beyond recovery.","Serve scalding with a fried dough ring and pickled vegetables, which cut the acidity."]} }
,

{ id:'shuan-yangrou', c:'as', lat:39.900, lon:116.410, base:6, prep:60, cook:60, diff:2, tags:['lamb','soup','festive'],
  art:{v:'pot',bg:'#33291f',plate:'#f0e4c8',style:'soup',food:['#f4f0e6','#f0e8d0','#7fae5a','#e8c46a'],garnish:'#7fae6a'},
  n:{fr:'Fondue d\'agneau pékinoise',en:'Beijing lamb hotpot'},
  p:{fr:'Pékin, Chine',en:'Beijing, China'},
  d:{fr:"De l'agneau tranché très fin trempé quelques secondes dans un bouillon d'eau claire. Le bouillon ne contient presque rien — de l'eau, du gingembre, quelques jujubes : la fondue pékinoise mise tout sur la qualité de la viande, à l'opposé du hot pot sichuanais.",
     en:"Lamb sliced very thin and dipped a few seconds in a clear water broth. The broth holds almost nothing — water, ginger, a few jujubes: the Beijing hotpot stakes everything on the quality of the meat, the opposite of the Sichuan version."},
  i:[['lamb_leg',1,'kg'],['sesame_paste',150,'g'],['fermented_tofu',40,'g'],['chinese_chives_flower',40,'g'],['napa_cabbage',600,'g'],['sweet_potato_noodles',200,'g'],['tofu_skin',150,'g'],['ginger',40,'g'],['red_dates',6,'pc'],['scallion',1,'bunch'],['cilantro',1,'bunch'],['water',2,'l']],
  s:{fr:["Faites raffermir le gigot deux heures au congélateur, puis tranchez-le à un millimètre et demi, en travers de la fibre.","Les tranches doivent être si fines qu'on voit le motif de l'assiette au travers : c'est le critère qu'emploient les maisons pékinoises.","Le bouillon ne s'assaisonne pas : eau, gingembre, jujubes et cives entières, rien de plus.","Trempez chaque tranche dix secondes en la tenant à la baguette, jusqu'à ce qu'elle change de couleur, et pas davantage.","Toute la saveur vient de la sauce au sésame et au tofu fermenté, mêlée dans le bol individuel de chacun."],
     en:["Firm the leg two hours in the freezer, then slice it at a millimetre and a half, across the grain.","The slices must be thin enough to see the plate's pattern through: that is the test Beijing houses use.","The broth is not seasoned: water, ginger, jujubes and whole spring onions, nothing more.","Dip each slice ten seconds holding it with chopsticks, until it changes colour, and no longer.","All the flavour comes from the sesame and fermented tofu sauce, mixed in each diner's own bowl."]} },

{ id:'shengjian-bao', c:'as', lat:31.230, lon:121.474, base:6, prep:150, cook:20, diff:3, tags:['pork','street','breakfast'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'other',food:['#f4f0e6','#c9924a','#7fae5a','#e8c46a'],garnish:'#7fae6a'},
  n:{fr:'Bao frits à la poêle',en:'Pan-fried buns'},
  p:{fr:'Shanghai, Chine',en:'Shanghai, China'},
  d:{fr:"Des brioches farcies au porc, dorées au fond et cuites à la vapeur au-dessus, pleines de bouillon. Le bouillon vient d'une gelée de couenne mêlée à la farce : elle fond à la cuisson et remplit la brioche, et il faut mordre prudemment.",
     en:"Filled pork buns browned at the base and steamed above, full of broth. The broth comes from a pork skin jelly mixed into the filling: it melts as it cooks and fills the bun, so the first bite must be cautious."},
  i:[['flour',400,'g'],['fresh_yeast',8,'g'],['ground_pork',400,'g'],['pork_skin',300,'g'],['ginger',40,'g'],['scallion',1,'bunch'],['soy_sauce',40,'ml'],['shaoxing_wine',30,'ml'],['sesame_seeds',20,'g'],['sesame_oil',20,'ml'],['peanut_oil',60,'ml'],['sugar',15,'g'],['water',200,'ml']],
  s:{fr:["Faites cuire la couenne de porc trois heures avec du gingembre, filtrez et laissez prendre en gelée au froid.","Hachez la gelée froide en petits dés et mêlez-la à la farce, à raison d'un tiers pour deux tiers de viande.","Faites lever la pâte à moitié seulement : trop levée, la brioche gonfle et le bouillon perce la base.","Disposez les bao serrés, joint vers le haut, dans une poêle huilée et faites-les dorer trois minutes à sec.","Versez alors de l'eau à un centimètre, couvrez immédiatement et laissez la vapeur cuire dix minutes."],
     en:["Cook the pork skin three hours with ginger, strain and set it to a jelly in the cold.","Chop the cold jelly into small dice and mix it into the filling, one part jelly to two of meat.","Prove the dough only halfway: over-proved, the bun swells and the broth pierces the base.","Pack the buns close, seam up, in an oiled pan and brown them three minutes dry.","Then pour in water to a centimetre, cover at once and let the steam cook them ten minutes."]} },

{ id:'congyou-banmian', c:'as', lat:31.235, lon:121.480, base:4, prep:20, cook:40, diff:2, tags:['noodles','fast','comfort'],
  art:{v:'bowl',bg:'#33291f',plate:'#f0e4c8',style:'noodle',food:['#8f7a5a','#f2dfa8','#7fae5a','#5a3020'],garnish:'#7fae6a'},
  n:{fr:'Nouilles à l\'huile de ciboule',en:'Scallion oil noodles'},
  p:{fr:'Shanghai, Chine',en:'Shanghai, China'},
  d:{fr:"Des nouilles mêlées à une huile de ciboule confite et à un soja sucré. Il n'y a rien d'autre : quatre ingrédients en tout, et toute la réussite tient à la patience avec laquelle on fait brunir les cives sans jamais les brûler.",
     en:"Noodles tossed with confited scallion oil and sweetened soy. There is nothing else: four ingredients in all, and success rests entirely on the patience with which the scallions are browned without ever burning."},
  i:[['wheat_noodles',400,'g'],['scallion',6,'bunch'],['peanut_oil',250,'ml'],['soy_sauce',80,'ml'],['dark_soy_sauce',20,'ml'],['sugar',40,'g'],['dried_shrimp',30,'g']],
  s:{fr:["Coupez les cives en tronçons de cinq centimètres et séparez les blancs des verts : ils ne cuisent pas au même rythme.","Faites-les confire dans l'huile à feu très doux, les blancs d'abord, pendant trente à quarante minutes.","À feu vif, les cives noircissent en trois minutes et l'huile devient amère : c'est la seule façon de rater ce plat.","Elles sont prêtes quand elles sont brun foncé, ratatinées et cassantes ; retirez-les et gardez l'huile.","Mêlez le soja et le sucre à l'huile chaude, versez sur les nouilles égouttées et remettez les cives frites par-dessus."],
     en:["Cut the scallions into five-centimetre lengths and separate whites from greens: they do not cook at the same rate.","Confit them in the oil over very low heat, whites first, for thirty to forty minutes.","Over high heat the scallions blacken in three minutes and the oil turns bitter: the only way to fail this dish.","They are ready when deep brown, shrivelled and brittle; lift them out and keep the oil.","Stir the soy and sugar into the hot oil, pour over the drained noodles and return the fried scallions on top."]} },

{ id:'cifantuan', c:'as', lat:31.225, lon:121.470, base:4, prep:480, cook:40, diff:2, tags:['rice','street','breakfast'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'roll',food:['#f4f0e6','#c9924a','#8f7a5a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Boule de riz gluant',en:'Glutinous rice roll'},
  p:{fr:'Shanghai, Chine',en:'Shanghai, China'},
  d:{fr:"Du riz gluant pressé à la main autour d'un beignet frit, de porc séché et de légumes marinés. C'est le petit-déjeuner que les Shanghaiens mangent en marchant vers le métro ; le beignet doit être de la veille et refrit, pour qu'il reste croustillant sous le riz humide.",
     en:"Glutinous rice pressed by hand around a fried dough stick, dried pork and pickled vegetables. It is the breakfast Shanghainese eat walking to the metro; the dough stick should be a day old and refried, so it stays crisp under the damp rice."},
  i:[['glutinous_rice',400,'g'],['youtiao',2,'pc'],['pork_floss',80,'g'],['pickled_mustard_greens',80,'g'],['sesame_seeds',20,'g'],['sugar',20,'g'],['salted_egg_yolk',2,'pc']],
  s:{fr:["Faites tremper le riz gluant six heures au moins, puis cuisez-le à la vapeur quarante minutes sur un linge.","Cuit à l'eau, il devient collant et informe ; à la vapeur, chaque grain reste distinct tout en adhérant aux autres.","Étalez le riz brûlant sur un linge humide, en couche d'un centimètre, et laissez-le tiédir deux minutes.","Disposez la garniture en ligne au centre, refermez à l'aide du linge et pressez fermement en cylindre.","Le riz doit être encore chaud pour se souder : refroidi, il ne colle plus et le rouleau se défait."],
     en:["Soak the glutinous rice at least six hours, then steam it forty minutes on a cloth.","Boiled, it turns sticky and shapeless; steamed, each grain stays distinct while clinging to the others.","Spread the scalding rice on a damp cloth in a one-centimetre layer, and let it cool two minutes.","Lay the filling in a line down the centre, close it using the cloth and press firmly into a cylinder.","The rice must still be hot to bind: cooled, it no longer sticks and the roll falls apart."]} },

{ id:'yangrou-chuan', c:'as', lat:39.467, lon:75.990, base:6, prep:120, cook:20, diff:2, tags:['lamb','grill','street'],
  art:{v:'board',bg:'#2b2419',plate:'#f4ead4',style:'skewer',food:['#8f4a3a','#c9302a','#e8c46a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Brochettes d\'agneau ouïghoures',en:'Uyghur lamb skewers'},
  p:{fr:'Kashgar, Xinjiang, Chine',en:'Kashgar, Xinjiang, China'},
  d:{fr:"Des brochettes d'agneau au cumin et au piment, grillées sur un long brasero étroit. L'alternance maigre-gras sur la brochette n'est pas décorative : le gras fond et arrose le maigre pendant toute la cuisson, et une brochette sans gras sèche en trois minutes.",
     en:"Lamb skewers with cumin and chilli, grilled over a long narrow brazier. Alternating lean and fat on the skewer is not decorative: the fat renders and bastes the lean throughout, and a skewer without fat dries in three minutes."},
  i:[['lamb_shoulder',800,'g'],['lamb_fat',200,'g'],['cumin',40,'g'],['chili_powder',30,'g'],['onion',2,'pc'],['coarse_salt',20,'g'],['flatbread',6,'pc'],['black_peppercorns',10,'g']],
  s:{fr:["Coupez la viande et le gras en cubes de deux centimètres et enfilez-les en alternant, quatre maigres pour un gras.","Faites mariner deux heures avec l'oignon râpé seulement : les épices se mettent au grill, jamais avant.","Le cumin brûle sur la braise s'il est mis dans la marinade ; il se saupoudre pendant la cuisson, en trois fois.","Employez un brasero étroit sur lequel les brochettes reposent par leurs extrémités, la viande suspendue au-dessus des braises.","Retournez toutes les trente secondes, huit minutes en tout, en saupoudrant de cumin et de piment à chaque tour."],
     en:["Cut the meat and fat into two-centimetre cubes and thread them alternately, four lean to one fat.","Marinate two hours with grated onion alone: the spices go on at the grill, never before.","Cumin burns on the coals if put in the marinade; it is dusted on during cooking, in three stages.","Use a narrow brazier on which the skewers rest by their ends, the meat suspended above the coals.","Turn every thirty seconds, eight minutes in all, dusting with cumin and chilli at each turn."]} },

{ id:'laghman', c:'as', lat:43.826, lon:87.617, base:4, prep:180, cook:30, diff:3, tags:['noodles','lamb','comfort'],
  art:{v:'bowl',bg:'#33291f',plate:'#f0e4c8',style:'noodle',food:['#f2dfa8','#c9302a','#7fae5a','#8f5a3a'],garnish:'#7fae6a'},
  n:{fr:'Laghman',en:'Laghman'},
  p:{fr:'Urumqi, Xinjiang, Chine',en:'Urumqi, Xinjiang, China'},
  d:{fr:"Des nouilles étirées à la main, couvertes d'un sauté d'agneau et de légumes. Les nouilles ne sont ni coupées ni pressées : la pâte est huilée, enroulée en spirale et repose des heures, puis étirée en un seul fil qui peut atteindre plusieurs mètres.",
     en:"Hand-pulled noodles under a stir-fry of lamb and vegetables. The noodles are neither cut nor extruded: the dough is oiled, coiled and rested for hours, then pulled into a single strand that can run several metres."},
  i:[['flour',500,'g'],['water',250,'ml'],['sunflower_oil',80,'ml'],['lamb_shoulder',400,'g'],['bell_pepper',2,'pc'],['ripe_tomato',300,'g'],['green_beans',150,'g'],['onion',2,'pc'],['garlic',8,'clove'],['cumin',15,'g'],['chili_powder',15,'g'],['soy_sauce',30,'ml'],['salt',null,'']],
  s:{fr:["Pétrissez une pâte souple et salée, laissez-la reposer une heure, puis roulez-la en boudins que vous huilez généreusement.","Enroulez les boudins en spirale dans un plat huilé et laissez reposer trois heures au moins, couverts.","Ce long repos détend le gluten au point que la pâte s'étire sans jamais rompre : sans lui, elle casse à la première traction.","Étirez chaque boudin en le faisant claquer sur le plan de travail, en le repliant sur lui-même à chaque passe.","Cuisez deux minutes à l'eau bouillante et couvrez du sauté d'agneau et de légumes, préparé à part au wok."],
     en:["Knead a soft salted dough, rest it an hour, then roll it into ropes and oil them generously.","Coil the ropes in an oiled dish and rest them at least three hours, covered.","That long rest relaxes the gluten to the point where the dough stretches without ever breaking: without it, it snaps at the first pull.","Pull each rope, slapping it on the worktop and folding it back on itself at each pass.","Cook two minutes in boiling water and top with the lamb and vegetable stir-fry, made separately in the wok."]} },

{ id:'polo-xinjiang', c:'as', lat:39.470, lon:75.995, base:6, prep:60, cook:90, diff:2, tags:['rice','lamb','festive'],
  art:{v:'pot',bg:'#33291f',plate:'#f0e4c8',style:'rice',food:['#e8a032','#8f5a3a','#e8c46a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Polo du Xinjiang',en:'Xinjiang polo'},
  p:{fr:'Kashgar, Xinjiang, Chine',en:'Kashgar, Xinjiang, China'},
  d:{fr:"Un riz à l'agneau, aux carottes jaunes et aux raisins secs, cuit en une seule marmite. Les carottes jaunes du Xinjiang sont plus sucrées et moins aqueuses que les orange ; elles fondent en donnant sa couleur au riz, et les remplacer change le plat.",
     en:"Rice with lamb, yellow carrots and raisins, cooked in one pot. Xinjiang's yellow carrots are sweeter and less watery than orange ones; they melt away giving the rice its colour, and substituting changes the dish."},
  i:[['lamb_shoulder',800,'g'],['long_grain_rice',600,'g'],['yellow_carrot',600,'g'],['onion',3,'pc'],['raisins',100,'g'],['cumin',20,'g'],['lamb_fat',100,'g'],['garlic',2,'pc'],['chickpeas',100,'g'],['salt',null,'']],
  s:{fr:["Faites fondre la graisse d'agneau en premier et retirez les cretons : c'est dans ce gras que tout le reste cuira.","Faites dorer la viande, puis les oignons, puis les carottes en gros bâtonnets, sans jamais remuer une fois posées.","Les carottes forment une couche qui isole le riz de la viande : remuées, elles se défont et le riz devient une bouillie.","Versez le riz rincé par-dessus sans mélanger, ajoutez l'eau bouillante à deux centimètres au-dessus, et enfoncez les têtes d'ail entières.","Cuisez trente minutes à couvert, puis mêlez seulement au moment de servir, en retournant du fond vers le haut."],
     en:["Render the lamb fat first and lift out the cracklings: everything else will cook in that fat.","Brown the meat, then the onions, then the carrots in thick batons, never stirring once they are in.","The carrots form a layer that insulates the rice from the meat: stirred, they collapse and the rice turns to porridge.","Pour the rinsed rice over without mixing, add boiling water two centimetres above, and push in the whole garlic heads.","Cook thirty minutes covered, then mix only as you serve, turning from the bottom upwards."]} },

{ id:'nang-xinjiang', c:'as', lat:42.951, lon:89.190, base:6, prep:180, cook:20, diff:2, tags:['bread','bake','comfort'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'flat',food:['#c9924a','#e8c46a','#f2dfa8','#8f7a5a'],garnish:'#7fae6a'},
  n:{fr:'Pain nang',en:'Nang bread'},
  p:{fr:'Turpan, Xinjiang, Chine',en:'Turpan, Xinjiang, China'},
  d:{fr:"Un grand pain plat cuit contre la paroi d'un four d'argile, creusé au centre. Le motif imprimé au tampon à clous n'est pas décoratif : les creux empêchent le centre de gonfler, et le pain cuit ainsi régulièrement du centre au bord.",
     en:"A large flatbread baked against the wall of a clay oven, dimpled at the centre. The pattern stamped with a nail tool is not decorative: the dimples stop the centre puffing, so the bread bakes evenly from centre to rim."},
  i:[['flour',600,'g'],['water',350,'ml'],['fresh_yeast',10,'g'],['lamb_fat',60,'g'],['onion',1,'pc'],['sesame_seeds',40,'g'],['nigella_seeds',10,'g'],['egg',1,'pc'],['salt',null,'']],
  s:{fr:["Pétrissez une pâte ferme à la graisse d'agneau fondue et laissez-la lever deux heures.","Abaissez en disques de trente centimètres en laissant le bord deux fois plus épais que le centre.","Marquez le centre au tampon à clous, ou à défaut à la fourchette, en piquant jusqu'au plan de travail.","Badigeonnez d'eau salée à l'oignon et parsemez de sésame et de nigelle, en pressant pour les faire adhérer.","Collez le disque contre la paroi brûlante du four à 250 °C. Cinq minutes suffisent ; le bord gonfle, le centre reste plat."],
     en:["Knead a firm dough with melted lamb fat and prove it two hours.","Roll into thirty-centimetre discs leaving the rim twice as thick as the centre.","Stamp the centre with a nail tool, or failing that a fork, pricking right through to the worktop.","Brush with salted onion water and scatter sesame and nigella, pressing them to make them stick.","Slap the disc onto the scalding wall of a 250°C oven. Five minutes is enough; the rim puffs, the centre stays flat."]} },

{ id:'tsampa', c:'as', lat:29.652, lon:91.172, base:4, prep:20, cook:30, diff:1, tags:['breakfast','comfort','fast'],
  art:{v:'bowl',bg:'#33291f',plate:'#f4ead4',style:'other',food:['#c9a878','#e8dcb8','#f2dfa8','#8f7a5a'],garnish:'#7fae6a'},
  n:{fr:'Tsampa',en:'Tsampa'},
  p:{fr:'Lhassa, Tibet, Chine',en:'Lhasa, Tibet, China'},
  d:{fr:"De la farine d'orge grillée pétrie à la main dans le thé au beurre, formée en boulettes. C'est l'aliment de base du plateau tibétain depuis des siècles : l'orge est la seule céréale qui mûrisse à quatre mille mètres, et le grillage préalable permet de la manger sans cuisson.",
     en:"Roasted barley flour kneaded by hand into butter tea and shaped into balls. It has been the staple of the Tibetan plateau for centuries: barley is the only grain that ripens at four thousand metres, and the prior roasting allows it to be eaten uncooked."},
  i:[['barley_flour',300,'g'],['yak_butter',80,'g'],['black_tea',20,'g'],['whole_milk',200,'ml'],['water',800,'ml'],['salt',null,'']],
  s:{fr:["Grillez l'orge en grains dans du sable chaud jusqu'à ce qu'elle éclate, puis tamisez et moulez : c'est le grillage qui la rend comestible crue.","Préparez le thé au beurre en battant thé noir fort, beurre de yak et sel dans une baratte, plusieurs minutes.","Le battage émulsionne le beurre dans le thé : simplement mélangé, il remonte en flaque et le breuvage est immangeable.","Versez du thé chaud dans le bol, ajoutez la farine peu à peu et pétrissez du bout des doigts, directement dans le bol.","Formez une boule ferme qui se tient dans la paume. La proportion se juge à la main, jamais à la mesure."],
     en:["Roast the barley grains in hot sand until they pop, then sieve and mill: roasting is what makes it edible uncooked.","Make the butter tea by churning strong black tea, yak butter and salt in a churn for several minutes.","Churning emulsifies the butter into the tea: merely stirred, it rises in a pool and the drink is undrinkable.","Pour hot tea into the bowl, add the flour little by little and knead with your fingertips, in the bowl itself.","Form a firm ball that holds in the palm. The proportion is judged by hand, never measured."]} },

{ id:'shou-zhua-rou', c:'as', lat:40.842, lon:111.750, base:6, prep:40, cook:120, diff:1, tags:['lamb','slow','festive'],
  art:{v:'board',bg:'#2b2419',plate:'#f0e4c8',style:'other',food:['#f4f0e6','#8f5a3a','#e8c46a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Viande à la main',en:'Hand-grabbed mutton'},
  p:{fr:'Hohhot, Mongolie-Intérieure, Chine',en:'Hohhot, Inner Mongolia, China'},
  d:{fr:"De l'agneau bouilli dans l'eau salée, sans épices, mangé à la main avec un couteau. L'absence totale d'assaisonnement est le principe : la cuisine mongole tient qu'un mouton de qualité n'a besoin de rien, et les épices y passent pour un aveu de faiblesse.",
     en:"Mutton boiled in salted water with no spices, eaten by hand with a knife. The total absence of seasoning is the principle: Mongolian cooking holds that good mutton needs nothing, and spices there pass for an admission of weakness."},
  i:[['lamb_ribs',2,'kg'],['coarse_salt',30,'g'],['scallion',1,'bunch'],['ginger',40,'g'],['garlic',10,'clove'],['chili_sauce',60,'g'],['water',4,'l'],['garlic_chives',60,'g']],
  s:{fr:["Employez un agneau de moins d'un an, en morceaux avec l'os : le plat repose entièrement sur la qualité de la bête.","Partez à l'eau froide et portez lentement à frémissement, en écumant sans relâche la première demi-heure.","N'ajoutez rien d'autre que du sel, et seulement à mi-cuisson. Ni laurier, ni anis étoilé, ni poivre.","Comptez une heure et demie à deux heures, jusqu'à ce que la chair se détache de l'os sous une simple traction.","Servez les morceaux entiers, avec un couteau. Chacun découpe le sien et le trempe dans une sauce à l'ail et au piment."],
     en:["Use lamb under a year old, in pieces on the bone: the dish rests entirely on the quality of the animal.","Start in cold water and bring slowly to a tremble, skimming relentlessly for the first half hour.","Add nothing but salt, and only halfway through. No bay, no star anise, no pepper.","Allow an hour and a half to two hours, until the flesh leaves the bone under a light pull.","Serve the pieces whole, with a knife. Each diner cuts their own and dips it in a garlic and chilli sauce."]} }
];
